ST.xhtml:
IF NOT VI_IsActivePLC THEN
    VO_Armed := FALSE;
    VO_Alarm_Active := FALSE;
    VO_Siren_Active := FALSE;
    VO_Send_Code_Req := FALSE;
    VO_Code_To_Send := '';
    VO_Status_Msg := 'Охрана: резервный ПЛК';
    L_Arming_In_Progress := FALSE;
    L_Disarm_Pending := FALSE;
    L_2FA_Required := FALSE;
    L_Reset_2FA := FALSE;
    RETURN;
END_IF;

// 1. Проверка PIN-кода или RFID-метки через менеджер кодов
fbAccessCode(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Code_To_Check := VI_PIN_Code,
    VI_RFID_To_Check := VI_RFID_Tag,
    VI_Access_Codes := GVL_RETAIN.G_Access_Codes,
    VI_RFID_Tags := GVL_RETAIN.G_RFID_Tags,
    VO_Code_Valid => L_Valid_PIN
);

// 2. Логика постановки на охрану (с задержкой на выход)
L_Auto_Arm_Trigger := FALSE;
IF VI_Config.auto_arm_enabled THEN
    IF VI_Current_TOD >= UDINT_TO_TOD(VI_Config.auto_arm_time_ms) THEN
        L_Auto_Arm_Trigger := TRUE;
    END_IF;
END_IF;
R_Trig_Auto_Arm(CLK := L_Auto_Arm_Trigger);

IF ((VI_Arm_Request AND L_Valid_PIN) OR R_Trig_Auto_Arm.Q) AND NOT VO_Armed AND NOT L_Arming_In_Progress THEN
    // Проверка, что все двери/окна закрыты перед постановкой (с учетом байпаса)
    L_Any_Sensor_Active := FALSE;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_DOOR_SENSORS DO IF VI_Door_Sensors[L_i] AND NOT VI_Bypass_Doors[L_i] THEN L_Any_Sensor_Active := TRUE; END_IF; END_FOR;
    FOR L_i := 1 TO 16 DO IF VI_Window_Sensors[L_i] AND NOT VI_Bypass_Windows[L_i] THEN L_Any_Sensor_Active := TRUE; END_IF; END_FOR;

    IF NOT L_Any_Sensor_Active THEN
        L_Arming_In_Progress := TRUE;
        VO_Status_Msg := 'Постановка на охрану. Покиньте помещение.';
    ELSE
        VO_Status_Msg := 'Ошибка постановки: Открыты двери или окна';
    END_IF;
END_IF;

L_Arm_Delay_Timer(IN := L_Arming_In_Progress, PT := TO_TIME(VI_Config.exit_delay_seconds * 1000), VI_System_Time_MS := VI_System_Time_MS);
IF L_Arm_Delay_Timer.Q THEN
    L_Arming_In_Progress := FALSE;
    VO_Armed := TRUE;
    VO_Status_Msg := 'Система под охраной';
END_IF;

// 3. Логика снятия с охраны с 2FA
IF VI_Disarm_Request AND L_Valid_PIN AND VO_Armed THEN
    IF VI_Config.enable_2fa THEN
        L_Disarm_Pending := TRUE;
        L_2FA_Required := TRUE;
        VO_Status_Msg := 'Ожидание 2FA для снятия с охраны';
    ELSE
        // Снятие без 2FA
        VO_Armed := FALSE;
        VO_Alarm_Active := FALSE;
        VO_Siren_Active := FALSE;
        L_Arming_In_Progress := FALSE;
        VO_Status_Msg := 'Система снята с охраны';
    END_IF;
END_IF;

fbTwoFactor(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Start_Auth := L_2FA_Required,
    VI_Method := E_TwoFactor_Method.TF_METHOD_TOTP, // Для примера
    VI_User_Code := VI_2FA_Code, // Используем отдельный вход для 2FA кода
    VI_Reset_Success := L_Reset_2FA
);

VO_Send_Code_Req := fbTwoFactor.VO_Send_Code_Req;
VO_Code_To_Send := fbTwoFactor.VO_Code_To_Send;

IF L_Disarm_Pending AND fbTwoFactor.VO_State.Is_Success THEN
    VO_Armed := FALSE;
    VO_Alarm_Active := FALSE;
    VO_Siren_Active := FALSE;
    L_Arming_In_Progress := FALSE;
    L_Disarm_Pending := FALSE;
    L_2FA_Required := FALSE;
    L_Reset_2FA := TRUE;
    VO_Status_Msg := 'Система снята с охраны';
ELSIF L_Disarm_Pending AND fbTwoFactor.VO_State.Is_Locked THEN
    L_Disarm_Pending := FALSE;
    L_2FA_Required := FALSE;
    L_Reset_2FA := FALSE;
    VO_Status_Msg := 'Ошибка 2FA: Превышено количество попыток';
ELSE
    L_Reset_2FA := FALSE;
END_IF;

// 4. Логика тревоги (с задержкой на вход)
IF VO_Armed THEN
    L_Any_Sensor_Active := FALSE;
    FOR L_i := 1 TO 16 DO IF VI_Motion_Sensors[L_i] AND NOT VI_Bypass_Motion[L_i] THEN L_Any_Sensor_Active := TRUE; END_IF; END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_DOOR_SENSORS DO IF VI_Door_Sensors[L_i] AND NOT VI_Bypass_Doors[L_i] THEN L_Any_Sensor_Active := TRUE; END_IF; END_FOR;
    FOR L_i := 1 TO 16 DO IF VI_Window_Sensors[L_i] AND NOT VI_Bypass_Windows[L_i] THEN L_Any_Sensor_Active := TRUE; END_IF; END_FOR;

    // Защелкиваем факт нарушения периметра, чтобы кратковременное срабатывание датчика не сбрасывало таймер
    IF L_Any_Sensor_Active THEN
        L_Alarm_Delay_Timer.IN := TRUE;
    END_IF;

    L_Alarm_Delay_Timer(PT := TO_TIME(VI_Config.entry_delay_seconds * 1000), VI_System_Time_MS := VI_System_Time_MS);

    IF L_Alarm_Delay_Timer.Q THEN
        VO_Alarm_Active := TRUE;
        VO_Siren_Active := TRUE;
        VO_Status_Msg := 'ТРЕВОГА! Нарушение периметра';
    ELSIF L_Alarm_Delay_Timer.IN THEN
        VO_Status_Msg := 'Внимание! Введите PIN-код для отмены тревоги';
    END_IF;
ELSE
    L_Alarm_Delay_Timer(IN := FALSE, PT := T#0s, VI_System_Time_MS := VI_System_Time_MS); // Сброс таймера при снятии с охраны
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Security_System_Manager <<<

// ==============================================================================
// System timebase helper
//
// Internal helper for PRG_System.
// Owns PLC runtime clock projection into GVL_STATUS:
// - monotonic system milliseconds
// - time-of-day milliseconds
// - day of week / day of year rollover
// - TOD representation
// ==============================================================================



GVL_STATUS.G_System_Time_MS := TIME_TO_UDINT(TIME());

L_Time_Diff := SEL(
    GVL_STATUS.G_System_Time_MS >= GVL_STATUS.G_Last_System_Time_MS,
    GVL_STATUS.G_System_Time_MS - GVL_STATUS.G_Last_System_Time_MS,
    (4294967295 - GVL_STATUS.G_Last_System_Time_MS) + GVL_STATUS.G_System_Time_MS + 1
);

GVL_STATUS.G_Time_Of_Day_MS := (GVL_STATUS.G_Time_Of_Day_MS + L_Time_Diff) MOD 86400000;

IF GVL_STATUS.G_Time_Of_Day_MS < L_Time_Diff THEN
    GVL_STATUS.G_Current_Day := (GVL_STATUS.G_Current_Day MOD 7) + 1;
    GVL_STATUS.G_Day_Of_Year := (GVL_STATUS.G_Day_Of_Year MOD 365) + 1;
END_IF;

GVL_STATUS.G_Last_System_Time_MS := GVL_STATUS.G_System_Time_MS;
GVL_STATUS.G_Current_TOD := UDINT_TO_TOD(GVL_STATUS.G_Time_Of_Day_MS);

// >>> BULK_SYNC_ANCHOR: FB_System_Timebase <<<

// ======================================================
// MODBUS RTU SYSCOM TRANSPORT BOUNDARY
// ======================================================
// Byte-level transport boundary between:
//   - project RTU frame runtime
//   - concrete SysCom backend
//
// This FB intentionally does NOT:
//   - open COM ports
//   - call SysCom APIs
//   - generate fake RX frames
//   - generate fake TX done
//
// It only transfers bytes between frame runtime and SysCom backend runtime.
// ======================================================

IF NOT VI_Enable THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Ready := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Error := FALSE;

    RETURN;
END_IF;

// ======================================================
// EXPORT TX FRAME
// ======================================================
IF GVL_MODBUS_RTU_FRAME.G_TX_Ready AND
   NOT GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Length :=
        GVL_MODBUS_RTU_FRAME.G_TX_Frame.Length;

    FOR L_i := 0 TO 255 DO
        GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Buffer[L_i] :=
            GVL_MODBUS_RTU_FRAME.G_TX_Frame.Data[L_i];
    END_FOR;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error_Code := 0;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request := TRUE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_TX_Request_MS :=
        VI_System_Time_MS;

END_IF;

// ======================================================
// CONFIRMED TX DONE - ONE SHOT CONSUME
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done THEN

    GVL_MODBUS_RTU_FRAME.G_TX_Ready := FALSE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done := FALSE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_TX_Done_MS :=
        VI_System_Time_MS;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_TX :=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_TX + 1;

END_IF;

// ======================================================
// IMPORT RX FRAME - ONE SHOT CONSUME
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Ready THEN

    GVL_MODBUS_RTU_FRAME.G_RX_Frame.Valid := TRUE;
    GVL_MODBUS_RTU_FRAME.G_RX_Frame.Length :=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Length;

    FOR L_i := 0 TO 255 DO
        GVL_MODBUS_RTU_FRAME.G_RX_Frame.Data[L_i] :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Buffer[L_i];
    END_FOR;

    GVL_MODBUS_RTU_FRAME.G_Last_RX_MS :=
        VI_System_Time_MS;

    GVL_MODBUS_RTU_FRAME.G_RX_Ready := TRUE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_RX_MS :=
        VI_System_Time_MS;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX :=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX + 1;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Ready := FALSE;

END_IF;

// ======================================================
// TRANSPORT ERRORS - ONE SHOT CONSUME
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error OR
   GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Error THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Errors :=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Errors + 1;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Error := FALSE;

END_IF;

// ==============================================================================
// Heating runtime state publication phase
// Owns publication of finalized runtime outputs into global state/status layers.
// Does NOT calculate heating logic and does NOT mutate outputs.
// ==============================================================================



VO_Executed := FALSE;
VO_Valid := FALSE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    GVL_STATE.G_Zone_Valves[L_i] := VI_Zone_Valves[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_STATE.G_Manifold_Pumps[L_i] := VI_Manifold_Pumps[L_i];
    GVL_STATE.G_Manifold_Valves[L_i] := VI_Manifold_Valves[L_i];
    GVL_STATUS.G_Manifold_Status[L_i] := VI_Manifold_Status[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    GVL_STATE.G_Boiler_OT_Enable[L_i] := VI_Boiler_OT_Enable[L_i];
    GVL_STATE.G_Boiler_OT_Setpoint[L_i] := VI_Boiler_OT_Setpoint[L_i];
    GVL_STATUS.G_Boiler_Status[L_i] := VI_Boiler_Status[L_i];
END_FOR;

GVL_STATE.G_Backup_Circulation_Pump := VI_Backup_Circulation_Pump;
GVL_STATE.G_Electric_Heater_Enable := VI_Electric_Heater_Enable;
GVL_STATE.G_Safety_Freeze_Risk := VI_Freeze_Risk_Status;
GVL_STATE.G_DHW_Heating_Pump := VI_DHW_Heating_Pump;
GVL_STATE.G_DHW_Circ_Pump := VI_DHW_Circ_Pump;
GVL_STATUS.G_DHW_Status := VI_DHW_Status;

VO_Executed := TRUE;
VO_Valid := TRUE;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_State_Publication_Phase <<<

// Check if command ID is already in history
L_Found := FALSE;
FOR L_i := 0 TO GVL_CONSTANTS.C_MAX_DEDUPLICATION_HISTORY-1 DO
    IF L_Processed_History[L_i] = VI_Command_ID AND VI_Command_ID <> 0 THEN
        // Check if the command is not too old (e.g., 1 hour = 3600000 ms)
        IF (VI_System_Time_MS - L_Processed_Times[L_i]) < 3600000 THEN
            L_Found := TRUE;
            EXIT;
        END_IF;
    END_IF;
END_FOR;

IF NOT L_Found AND VI_Command_ID <> 0 THEN
    // New command detected
    VO_Is_New_Command := TRUE;
    VO_Processed_ID := VI_Command_ID;

    // Add to history
    L_Processed_History[L_History_Index] := VI_Command_ID;
    L_Processed_Times[L_History_Index] := VI_System_Time_MS;
    L_History_Index := L_History_Index + 1;
    IF L_History_Index > GVL_CONSTANTS.C_MAX_DEDUPLICATION_HISTORY-1 THEN
        L_History_Index := 0;
    END_IF;
ELSE
    // Duplicate or empty command
    VO_Is_New_Command := FALSE;
    VO_Processed_ID := 0;
END_IF;

// ==============================================================================
// System persist manager helper
//
// Internal helper for PRG_System.
// Owns persistent snapshot packing, controlled NVRAM write gating,
// FB_NVRAM_Manager call, and last-written buffer tracking.
// ==============================================================================



// Pack persistent snapshot into compact byte buffer for controlled NVRAM mirroring
VIO_Persist_Buffer[0] := TO_BYTE(TO_INT(GVL_STATE.G_System_Mode));
IF GVL_PERSISTENT.P_Safety_Gas_Latched THEN
    VIO_Persist_Buffer[1] := BYTE#1;
ELSE
    VIO_Persist_Buffer[1] := BYTE#0;
END_IF;
IF GVL_PERSISTENT.P_Safety_Smoke_Latched THEN
    VIO_Persist_Buffer[2] := BYTE#1;
ELSE
    VIO_Persist_Buffer[2] := BYTE#0;
END_IF;
IF GVL_PERSISTENT.P_Safety_Leak_Latched THEN
    VIO_Persist_Buffer[3] := BYTE#1;
ELSE
    VIO_Persist_Buffer[3] := BYTE#0;
END_IF;
IF GVL_PERSISTENT.P_DHW_Heating_Active THEN
    VIO_Persist_Buffer[4] := BYTE#1;
ELSE
    VIO_Persist_Buffer[4] := BYTE#0;
END_IF;

VIO_Persist_Buffer_Changed :=
    (VIO_Persist_Buffer[0] <> VIO_Last_Written_Persist_Buffer[0]) OR
    (VIO_Persist_Buffer[1] <> VIO_Last_Written_Persist_Buffer[1]) OR
    (VIO_Persist_Buffer[2] <> VIO_Last_Written_Persist_Buffer[2]) OR
    (VIO_Persist_Buffer[3] <> VIO_Last_Written_Persist_Buffer[3]) OR
    (VIO_Persist_Buffer[4] <> VIO_Last_Written_Persist_Buffer[4]);

VIO_NVRAM_Cmd := 0;
VIO_NVRAM_Offset := 0;

IF GVL_CONFIG.G_HMI_Apply_Settings THEN
    // explicit config apply may request a controlled write
    VIO_NVRAM_Cmd := 1;
    GVL_CONFIG.G_HMI_Apply_Settings := FALSE;

ELSIF VIO_Persist_Buffer_Changed THEN
    // controlled write: no more often than once per 60 seconds
    IF (VIO_Last_Persist_Write_MS = 0) OR
       ((VI_System_Time_MS - VIO_Last_Persist_Write_MS) >= 60000) THEN
        VIO_NVRAM_Cmd := 1;
    END_IF;
END_IF;

fbNVRAMManager(
    VI_Command := VIO_NVRAM_Cmd,
    VI_Offset := VIO_NVRAM_Offset,
    VI_DataRef := VIO_Persist_Buffer[0],
    VI_DataSize := 5,
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Operator_ID := 'SYSTEM',
    VI_IsActivePLC := VI_IsActivePLC,
    VI_TwoPersonConfirmation := FALSE,
    VO_Done => VIO_NVRAM_Done,
    VO_Error => VIO_NVRAM_Err,
    VO_ErrorID => VIO_NVRAM_ErrID
);

IF (VIO_NVRAM_Cmd = 1) AND VIO_NVRAM_Done AND NOT VIO_NVRAM_Err THEN
    VIO_Last_Written_Persist_Buffer[0] := VIO_Persist_Buffer[0];
    VIO_Last_Written_Persist_Buffer[1] := VIO_Persist_Buffer[1];
    VIO_Last_Written_Persist_Buffer[2] := VIO_Persist_Buffer[2];
    VIO_Last_Written_Persist_Buffer[3] := VIO_Persist_Buffer[3];
    VIO_Last_Written_Persist_Buffer[4] := VIO_Persist_Buffer[4];
    VIO_Last_Persist_Write_MS := VI_System_Time_MS;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Persist_Manager <<<

// ==============================================================================
// Heating root-cause diagnostics observer
// Public diagnostics/explainability layer.
// Does NOT own control/runtime decisions.
// ==============================================================================



IF NOT VI_Enable THEN
    GVL_STATE.G_Heating_RootCause := E_Heating_RootCause.RC_NONE;
    GVL_STATE.G_Heating_RootConfidence := 0.0;
    GVL_STATE.G_Heating_Confidence := 0.0;
    GVL_STATE.G_Heating_Error_Score := 1.0;
    GVL_STATE.G_Heating_Confidence_Reason_Code := -1;
    GVL_STATE.G_Heating_Confidence_Reason_Text := 'Heating diagnostics disabled';
    RETURN;
END_IF;

// ======================================================
// DEMAND MAP
// ======================================================
fbDemandMap(
    VI_Zone_Valves := GVL_STATE.G_Zone_Valves,
    VI_Zone_Configs := GVL_CONFIG.G_HMI_FloorHeating_Configs,
    VO_Manifold_Demand_Map => L_Demand_Map
);

// ======================================================
// INTERNAL INFERENCE ENGINE
// ======================================================
fbRootCause(
    VI_Emergency_Stop := GVL_STATE.G_Safety_Emergency_Stop,
    VI_Gas_Safety := GVL_STATE.G_Safety_Gas_Latched,
    VI_IO_Failsafe := GVL_STATE.G_Heating_IO_Fault,

    VI_Cascade_Available := GVL_STATE.G_Heating_Cascade_Available,
    VI_Cascade_Degraded := GVL_STATE.G_Heating_Cascade_Degraded,
    VI_Cascade_Partial_Capacity := GVL_STATE.G_Heating_Cascade_Partial_Capacity,
    VI_Cascade_No_Flame := GVL_STATE.G_Heating_Cascade_No_Flame,
    VI_Cascade_Transport_Degraded := GVL_STATE.G_Heating_Cascade_Transport_Degraded,
    VI_Cascade_Ignition_Timeout := GVL_STATE.G_Heating_Cascade_Ignition_Timeout,
    VI_Cascade_Active_Boilers := GVL_STATE.G_Heating_Cascade_Active_Boilers,
    VI_Cascade_Available_Boilers := GVL_STATE.G_Heating_Cascade_Available_Boilers,

    VI_Boiler_OT_Online := GVL_STATE.G_Boiler_OT_Online,
    VI_Boiler_Error := GVL_STATE.G_Boiler_Error,
    VI_Boiler_Flame := GVL_STATE.G_Boiler_Flame,
    VI_Boiler_OT_Command_Timeout := GVL_STATE.G_Boiler_OT_Command_Timeout,
    VI_Boiler_OT_Heartbeat_Timeout := GVL_STATE.G_Boiler_OT_Heartbeat_Timeout,
    VI_Boiler_OT_Adapter_Error := GVL_STATE.G_Boiler_OT_Adapter_Error,

    VI_Manifold_Pumps := GVL_STATE.G_Manifold_Pumps,
    VI_Manifold_Valves := GVL_STATE.G_Manifold_Valves,

    VI_Sensor_Error := GVL_STATE.G_Heating_Sensor_Fault,
    VI_Supply_Temps := GVL_STATE.G_Manifold_T_Supply,
    VI_Target_Supply := GVL_STATE.G_Target_Temperature,
    VI_Demand_Map := L_Demand_Map
);

// ======================================================
// PUBLIC DIAGNOSTICS STATE
// ======================================================
GVL_STATE.G_Heating_RootCause := fbRootCause.VO_RootCause;
GVL_STATE.G_Heating_RootConfidence := fbRootCause.VO_Confidence;
GVL_STATE.G_Heating_Confidence := fbRootCause.VO_Confidence;
GVL_STATE.G_Heating_Error_Score := fbRootCause.VO_Error_Score;
GVL_STATE.G_Heating_Confidence_Reason_Code := fbRootCause.VO_Reason_Code;
GVL_STATE.G_Heating_Confidence_Reason_Text := fbRootCause.VO_Reason_Text;

// >>> BULK_SYNC_ANCHOR: FB_Heating_RootCause_Diagnostics <<<

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

GVL_STATE.G_Lighting_IO_Fault := FALSE;
GVL_STATE.G_Lighting_Subsystem_Degraded := FALSE;

L_Effective_Scenario := VI_Current_Scenario;
L_Effective_Simulation_Active := VI_Simulation_Active;

CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
            VO_Lighting_Levels[L_j] := 0;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
            VO_Blinds_Positions[L_j] := 100;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_WET_ZONES DO
            VO_Wet_Zone_Light_Active[L_j] := FALSE;
        END_FOR;
        RETURN;
    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        L_Effective_Scenario := E_SCENARIO_TYPE.SCENARIO_NONE;
        L_Effective_Simulation_Active := FALSE;
    E_System_Operating_Mode.MODE_DEGRADED:
        L_Effective_Simulation_Active := FALSE;
END_CASE;

L_Wet_Zone_Idx := 1;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WET_ZONES DO
    VO_Wet_Zone_Light_Active[L_i] := FALSE;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        GVL_STATE.G_Lighting_IO_Fault := TRUE;
        GVL_STATE.G_Lighting_Subsystem_Degraded := TRUE;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
            VO_Lighting_Levels[L_j] := 0;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
            VO_Blinds_Positions[L_j] := 100;
        END_FOR;
        RETURN;
    END_IF;
END_FOR;

IF L_Effective_Scenario >= 1 AND L_Effective_Scenario <= GVL_CONSTANTS.C_MAX_SCENARIOS THEN
    L_Target_Base_Light := VI_Scenario_Configs[L_Effective_Scenario].lighting_level_base;
    L_Target_Base_Blinds := VI_Scenario_Configs[L_Effective_Scenario].blinds_position_percent;
ELSE
    L_Target_Base_Light := 100;
    L_Target_Base_Blinds := 100;
END_IF;

IF VI_Is_Night AND L_Effective_Scenario <> E_SCENARIO_TYPE.SCENARIO_AWAY AND L_Effective_Scenario <> E_SCENARIO_TYPE.SCENARIO_SLEEP THEN
    L_Target_Base_Blinds := 0;
END_IF;

IF L_Effective_Scenario <> L_Prev_Scenario THEN
    L_Transition_Light(VI_System_Time := VI_System_Time_MS, VI_Start_Time := VI_System_Time_MS, VI_Duration := 5000, VI_Start_Value := TO_REAL(L_Base_Light), VI_End_Value := TO_REAL(L_Target_Base_Light));
    L_Transition_Blinds(VI_System_Time := VI_System_Time_MS, VI_Start_Time := VI_System_Time_MS, VI_Duration := 10000, VI_Start_Value := TO_REAL(L_Base_Blinds), VI_End_Value := TO_REAL(L_Target_Base_Blinds));
    L_Prev_Scenario := L_Effective_Scenario;
ELSE
    L_Transition_Light(VI_System_Time := VI_System_Time_MS, VI_Start_Time := L_Transition_Light.VI_Start_Time, VI_Duration := L_Transition_Light.VI_Duration, VI_Start_Value := L_Transition_Light.VI_Start_Value, VI_End_Value := TO_REAL(L_Target_Base_Light));
    L_Transition_Blinds(VI_System_Time := VI_System_Time_MS, VI_Start_Time := L_Transition_Blinds.VI_Start_Time, VI_Duration := L_Transition_Blinds.VI_Duration, VI_Start_Value := L_Transition_Blinds.VI_Start_Value, VI_End_Value := TO_REAL(L_Target_Base_Blinds));
END_IF;

L_Base_Light := TO_BYTE(L_Transition_Light.VO_Current_Value);
L_Base_Blinds := TO_BYTE(L_Transition_Blinds.VO_Current_Value);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    L_Rule_Light_Active := FALSE;
    L_Rule_Light_Val := 0;
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_LIGHTING_BASE THEN
                L_Rule_Light_Active := TRUE;
                L_Rule_Light_Val := REAL_TO_BYTE(VI_Rule_Actions[L_j].Value);
                L_Light_States[L_i] := (L_Rule_Light_Val > 0);
            ELSIF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_TOGGLE_LIGHTING AND VI_Rule_Actions[L_j].Triggered THEN
                L_Light_States[L_i] := NOT L_Light_States[L_i];
            END_IF;
        END_IF;
    END_FOR;

    IF VI_Physical_Switches[L_i] AND NOT L_Prev_Switches[L_i] THEN
        L_Light_States[L_i] := NOT L_Light_States[L_i];
        L_Manual_Override[L_i] := TRUE;
    END_IF;
    L_Prev_Switches[L_i] := VI_Physical_Switches[L_i];

    L_Motion_Timers[L_i](IN := VI_Motion_Sensors[L_i], PT := T#5m, VI_System_Time_MS := VI_System_Time_MS);

    IF L_Prev_Motion_Q[L_i] AND NOT L_Motion_Timers[L_i].Q THEN
        L_Manual_Override[L_i] := FALSE;
    END_IF;
    L_Prev_Motion_Q[L_i] := L_Motion_Timers[L_i].Q;

    IF L_Motion_Timers[L_i].Q THEN
        IF NOT L_Manual_Override[L_i] THEN
            L_Light_States[L_i] := TRUE;
        END_IF;
    ELSE
        IF NOT L_Manual_Override[L_i] THEN
            L_Light_States[L_i] := FALSE;
        END_IF;
    END_IF;

    IF L_Effective_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY AND L_Effective_Simulation_Active THEN
        L_Light_States[L_i] := VI_Simulation_Lights[L_i];
    END_IF;

    IF VI_Manual_Light_Override[L_i] > 0 THEN
        VO_Lighting_Levels[L_i] := VI_Manual_Light_Override[L_i];
    ELSIF L_Rule_Light_Active THEN
        VO_Lighting_Levels[L_i] := L_Rule_Light_Val;
    ELSE
        VO_Lighting_Levels[L_i] := SEL(L_Light_States[L_i], 0, L_Base_Light);
    END_IF;

    IF VI_Wet_Zone_Map[L_i] AND L_Wet_Zone_Idx <= GVL_CONSTANTS.C_MAX_WET_ZONES THEN
        VO_Wet_Zone_Light_Active[L_Wet_Zone_Idx] := (VO_Lighting_Levels[L_i] > 10);
        L_Wet_Zone_Idx := L_Wet_Zone_Idx + 1;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
    L_Rule_Blinds_Active := FALSE;
    L_Rule_Blinds_Val := 0;
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_BLINDS THEN
                L_Rule_Blinds_Active := TRUE;
                L_Rule_Blinds_Val := REAL_TO_BYTE(VI_Rule_Actions[L_j].Value);
            END_IF;
        END_IF;
    END_FOR;

    IF VI_Manual_Blinds_Override[L_i] > 0 THEN
        VO_Blinds_Positions[L_i] := VI_Manual_Blinds_Override[L_i];
    ELSIF L_Rule_Blinds_Active THEN
        VO_Blinds_Positions[L_i] := L_Rule_Blinds_Val;
    ELSE
        VO_Blinds_Positions[L_i] := L_Base_Blinds;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Lighting_Blinds_Manager <<<

// ==============================================================================
// Heating allocation filter
// Runtime decision gate between Demand_Map and Manifold_Control.
//
// IMPORTANT:
// This FB is NOT a second runtime owner.
// This FB is NOT an orchestration layer.
//
// Actual ownership remains in:
// PRG_Heating
// → FB_Heating_System_Manager
// → active subsystem owners.
//
// Current responsibility:
// - manifold availability gating;
// - service-state filtering;
// - freeze-mode exceptions;
// - bounded demand authorization.
//
// Optional responsibility when explicitly enabled:
// - priority-based allocation;
// - thermal budget limiting.
// ==============================================================================



// ======================================================
// DEFAULT STATE
// ======================================================
VO_Allocation_Degraded := FALSE;
VO_Thermal_Budget_Used := REAL#0.0;
L_AnyPolicyBlock := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Demand_Filtered[L_i] := VI_Manifold_Demand_Map[L_i];
    VO_Manifold_Allowed[L_i] := TRUE;
    VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.NONE;
    VO_Manifold_Priority_Effective[L_i] := VI_Manifold_Base_Priority[L_i];
END_FOR;

// ======================================================
// STRICT PASSTHROUGH MODE
// ======================================================
IF NOT VI_Enable THEN
    RETURN;
END_IF;

// ======================================================
// FREEZE EXCEPTION MODE
//
// Freeze protection has higher authority than
// service gating and policy throttling.
// ======================================================
IF VI_Freeze_Mode_Active THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF VI_Manifold_Demand_Map[L_i] THEN
            VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.FREEZE_BYPASS;
        END_IF;
    END_FOR;
    RETURN;
END_IF;

// ======================================================
// DHW PRIORITY GATE
//
// Manifold_Control already owns DHW shutdown.
// Keep this filter transparent during DHW hold to avoid
// creating duplicate DHW authority here.
// ======================================================
IF VI_DHW_Heating_Demand THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF VI_Manifold_Demand_Map[L_i] THEN
            VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.DHW_BYPASS;
        END_IF;
    END_FOR;
    RETURN;
END_IF;

// ======================================================
// MANIFOLD AUTHORIZATION FILTER
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO

    IF NOT VI_Manifold_Available[L_i] THEN
        VO_Manifold_Allowed[L_i] := FALSE;
        VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.PRESSURE_UNAVAILABLE;
    END_IF;

    IF NOT VI_Manifold_In_Service[L_i] THEN
        VO_Manifold_Allowed[L_i] := FALSE;
        VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.SERVICE_DISABLED;
    END_IF;

    IF VI_Manifold_Subsystem_Degraded[L_i] THEN
        VO_Manifold_Allowed[L_i] := FALSE;
        VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.PREDICTIVE_DEGRADED;
    END_IF;

    IF VI_Manifold_Demand_Map[L_i] AND NOT VO_Manifold_Allowed[L_i] THEN
        VO_Manifold_Demand_Filtered[L_i] := FALSE;
        VO_Allocation_Degraded := TRUE;
    END_IF;

END_FOR;

// ======================================================
// OPTIONAL POLICY LAYER
//
// This layer can only reduce demand that is already
// authorized by availability/service/degraded checks.
// It never creates new demand and never writes outputs.
// ======================================================
IF NOT VI_Enable_Policy_Allocation THEN
    RETURN;
END_IF;

// Invalid or unset budget means no policy throttling.
IF VI_Max_Thermal_Budget <= REAL#0.0 THEN
    RETURN;
END_IF;

// Rebuild output demand from allowed candidates only.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Demand_Filtered[L_i] := FALSE;
END_FOR;

L_MaxPriority := 0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VI_Manifold_Demand_Map[L_i] AND VO_Manifold_Allowed[L_i] THEN
        IF VO_Manifold_Priority_Effective[L_i] > L_MaxPriority THEN
            L_MaxPriority := VO_Manifold_Priority_Effective[L_i];
        END_IF;
    END_IF;
END_FOR;

L_Used := REAL#0.0;

FOR L_CurrentPriority := L_MaxPriority TO 0 BY -1 DO
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF VI_Manifold_Demand_Map[L_i]
           AND VO_Manifold_Allowed[L_i]
           AND (VO_Manifold_Priority_Effective[L_i] = L_CurrentPriority) THEN

            L_Weight := VI_Manifold_Thermal_Weight[L_i];
            IF L_Weight <= REAL#0.0 THEN
                L_Weight := REAL#1.0;
            END_IF;

            IF (L_Used + L_Weight) <= VI_Max_Thermal_Budget THEN
                VO_Manifold_Demand_Filtered[L_i] := TRUE;
                L_Used := L_Used + L_Weight;
            ELSE
                L_AnyPolicyBlock := TRUE;
                IF VO_Manifold_Block_Reason[L_i] = E_Heating_Allocation_Block_Reason.NONE THEN
                    VO_Manifold_Block_Reason[L_i] := E_Heating_Allocation_Block_Reason.POLICY_BUDGET_SHED;
                END_IF;
            END_IF;
        END_IF;
    END_FOR;
END_FOR;

VO_Thermal_Budget_Used := L_Used;

IF L_AnyPolicyBlock THEN
    VO_Allocation_Degraded := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Allocation_Filter <<<

VO_Water_Test_Timeout_Close_Required := FALSE;
VO_Gas_Test_Timeout_Close_Required := FALSE;

VO_Water_Selective_Recover_Edge := VI_Water_Selective_Recover AND NOT L_CMD_Water_Selective_Recover_Prev;
VO_Gas_Selective_Recover_Edge := VI_Gas_Selective_Recover AND NOT L_CMD_Gas_Selective_Recover_Prev;
VO_Water_Valve_Test_Open_Edge := VI_Water_Valve_Test_Open AND NOT L_CMD_Water_Valve_Test_Open_Prev;
VO_Water_Valve_Test_Close_Edge := VI_Water_Valve_Test_Close AND NOT L_CMD_Water_Valve_Test_Close_Prev;
VO_Water_Valve_Test_Confirm_Edge := VI_Water_Valve_Test_Confirm AND NOT L_CMD_Water_Valve_Test_Confirm_Prev;
VO_Gas_Valve_Test_Open_Edge := VI_Gas_Valve_Test_Open AND NOT L_CMD_Gas_Valve_Test_Open_Prev;
VO_Gas_Valve_Test_Close_Edge := VI_Gas_Valve_Test_Close AND NOT L_CMD_Gas_Valve_Test_Close_Prev;
VO_Gas_Valve_Test_Confirm_Edge := VI_Gas_Valve_Test_Confirm AND NOT L_CMD_Gas_Valve_Test_Confirm_Prev;

L_CMD_Water_Selective_Recover_Prev := VI_Water_Selective_Recover;
L_CMD_Gas_Selective_Recover_Prev := VI_Gas_Selective_Recover;
L_CMD_Water_Valve_Test_Open_Prev := VI_Water_Valve_Test_Open;
L_CMD_Water_Valve_Test_Close_Prev := VI_Water_Valve_Test_Close;
L_CMD_Water_Valve_Test_Confirm_Prev := VI_Water_Valve_Test_Confirm;
L_CMD_Gas_Valve_Test_Open_Prev := VI_Gas_Valve_Test_Open;
L_CMD_Gas_Valve_Test_Close_Prev := VI_Gas_Valve_Test_Close;
L_CMD_Gas_Valve_Test_Confirm_Prev := VI_Gas_Valve_Test_Confirm;

IF VO_Water_Valve_Test_Open_Edge THEN
    L_Water_Test_Active := TRUE;
    L_Water_Test_Deadline := VI_System_Time_MS + 60000;
END_IF;

IF L_Water_Test_Active THEN
    IF VI_System_Time_MS >= L_Water_Test_Deadline THEN
        L_Water_Test_Active := FALSE;
        VO_Water_Test_Timeout_Close_Required := TRUE;
    END_IF;
END_IF;

IF VO_Gas_Valve_Test_Open_Edge THEN
    L_Gas_Test_Active := TRUE;
    L_Gas_Test_Deadline := VI_System_Time_MS + 60000;
END_IF;

IF L_Gas_Test_Active THEN
    IF VI_System_Time_MS >= L_Gas_Test_Deadline THEN
        L_Gas_Test_Active := FALSE;
        VO_Gas_Test_Timeout_Close_Required := TRUE;
    END_IF;
END_IF;

VO_Water_Test_Active := L_Water_Test_Active;
VO_Gas_Test_Active := L_Gas_Test_Active;

// 1. Prepare K_ipad and K_opad
FOR i := 0 TO 63 DO
    IF i < KeyLength THEN
        K_ipad[i] := Key[i] XOR 16#36;
        K_opad[i] := Key[i] XOR 16#5C;
    ELSE
        K_ipad[i] := 16#36;
        K_opad[i] := 16#5C;
    END_IF;
END_FOR;

// 2. Inner Hash: SHA1(K_ipad || Message)
FOR i := 0 TO 63 DO
    InnerData[i] := K_ipad[i];
END_FOR;
FOR i := 0 TO MessageLength - 1 DO
    InnerData[64 + i] := Message[i];
END_FOR;

FB_SHA1_Inner(Data := InnerData, Length := 64 + MessageLength, Hash => InnerHash);

// 3. Outer Hash: SHA1(K_opad || InnerHash)
FOR i := 0 TO 63 DO
    OuterData[i] := K_opad[i];
END_FOR;
FOR i := 0 TO 19 DO
    OuterData[64 + i] := InnerHash[i];
END_FOR;

FB_SHA1_Outer(Data := OuterData, Length := 84, Hash => Hash);

Done := TRUE;

// ==============================================================================
// Heating runtime observability layer
//
// Projection/publication layer only.
//
// IMPORTANT:
// - does NOT own outputs;
// - does NOT control pumps/valves;
// - does NOT modify demand;
// - does NOT participate in runtime authority.
//
// Responsibility:
// - allocation snapshot publication;
// - policy diagnostics projection;
// - freeze/DHW bypass visibility;
// - runtime explainability;
// - bounded policy bridge visibility.
// ==============================================================================



GVL_STATE.G_Allocation_Policy_Active := VI_Policy_Active;
GVL_STATE.G_Allocation_Freeze_Bypass_Active := VI_Freeze_Bypass_Active;
GVL_STATE.G_Allocation_DHW_Bypass_Active := VI_DHW_Bypass_Active;

GVL_STATE.G_Allocation_Budget_Max := VI_Budget_Max;
GVL_STATE.G_Allocation_Budget_Used := VI_Budget_Used;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_STATE.G_Allocation_Requested[L_i] := VI_Requested[L_i];
    GVL_STATE.G_Allocation_Allowed[L_i] := VI_Allowed[L_i];
    GVL_STATE.G_Allocation_Filtered[L_i] := VI_Filtered[L_i];

    GVL_STATE.G_Allocation_Block_Reason[L_i] := VI_Block_Reason[L_i];
    GVL_STATE.G_Allocation_Effective_Priority[L_i] := VI_Effective_Priority[L_i];

    GVL_STATE.G_Policy_Priority_Bias_Applied[L_i] := VI_Priority_Bias_Applied[L_i];
    GVL_STATE.G_Policy_Priority_Effective[L_i] := VI_Priority_Effective[L_i];
END_FOR;

GVL_STATE.G_Policy_Priority_Bridge_Active := VI_Priority_Bridge_Active;

// Bounded policy target bridge visibility.
// Mirrors the same clamp used by FB_Heating_System_Manager.
L_Policy_Target_Adjustment := GVL_HEATING_POLICY.G_Policy_Target_Adjustment;
IF L_Policy_Target_Adjustment > REAL#5.0 THEN
    L_Policy_Target_Adjustment := REAL#5.0;
ELSIF L_Policy_Target_Adjustment < REAL#-3.0 THEN
    L_Policy_Target_Adjustment := REAL#-3.0;
END_IF;

L_Policy_Priority_Multiplier := GVL_HEATING_POLICY.G_Policy_Priority_Multiplier;
IF L_Policy_Priority_Multiplier < REAL#0.3 THEN
    L_Policy_Priority_Multiplier := REAL#0.3;
ELSIF L_Policy_Priority_Multiplier > REAL#1.0 THEN
    L_Policy_Priority_Multiplier := REAL#1.0;
END_IF;

GVL_STATE.G_Policy_Target_Adjustment_Applied := L_Policy_Target_Adjustment;
GVL_STATE.G_Policy_Target_Adjustment_Active := ABS(L_Policy_Target_Adjustment) > REAL#0.001;
GVL_STATE.G_Policy_Priority_Multiplier_Applied := L_Policy_Priority_Multiplier;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Observability <<<

GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Event_ID := GVL_EVENT.G_Event_ID_Counter;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Event_Type := VI_Event_Type;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Timestamp := VI_Timestamp;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Param1 := VI_Param1;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Param2 := VI_Param2;

GVL_EVENT.G_Event_ID_Counter := GVL_EVENT.G_Event_ID_Counter + 1;
GVL_EVENT.G_Event_Head := (GVL_EVENT.G_Event_Head + 1) MOD 64;

L_Event_Text := '';

IF (VI_Severity <> L_Last_Severity) OR (VI_RootCause <> L_Last_RootCause) THEN
    CASE VI_RootCause OF
        E_System_Root_Cause.ROOT_FIRE:
            L_Event_Text := 'EVENT: FIRE DETECTED';
        E_System_Root_Cause.ROOT_GAS_LEAK:
            L_Event_Text := 'EVENT: GAS LEAK';
        E_System_Root_Cause.ROOT_CO_CRITICAL:
            L_Event_Text := 'EVENT: CO CRITICAL';
        E_System_Root_Cause.ROOT_CO_WARNING:
            L_Event_Text := 'EVENT: CO WARNING';
        E_System_Root_Cause.ROOT_WATER_LEAK:
            L_Event_Text := 'EVENT: WATER LEAK';
        E_System_Root_Cause.ROOT_SENSOR_FAULT:
            L_Event_Text := 'EVENT: SENSOR FAULT';
        E_System_Root_Cause.ROOT_IO_OFFLINE:
            L_Event_Text := 'EVENT: IO OFFLINE';
        E_System_Root_Cause.ROOT_COMM_FAULT:
            L_Event_Text := 'EVENT: COMM FAULT';
        E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
            L_Event_Text := 'EVENT: WATCHDOG FAULT';
        E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT:
            L_Event_Text := 'EVENT: SUBSYSTEM FAULT';
        ELSE
            L_Event_Text := 'EVENT: SYSTEM STATE CHANGE';
    END_CASE;

    L_Write_Index := L_Write_Index + 1;
    IF L_Write_Index > 16 THEN
        L_Write_Index := 1;
    END_IF;

    VO_Event_Time_MS[L_Write_Index] := VI_Time_MS;
    VO_Event_Severity[L_Write_Index] := VI_Severity;
    VO_Event_RootCause[L_Write_Index] := VI_RootCause;
    VO_Event_Text[L_Write_Index] := L_Event_Text;

    VO_Last_Index := L_Write_Index;
    VO_Last_Event_Text := L_Event_Text;

    IF VO_Event_Count < 16 THEN
        VO_Event_Count := VO_Event_Count + 1;
    END_IF;
END_IF;

L_Last_Severity := VI_Severity;
L_Last_RootCause := VI_RootCause;
// >>> BULK_SYNC_ANCHOR: FB_Fault_Logger <<<

VO_Applied := VI_Block_Normal_Heating;
VO_Backup_Circulation_Pump := FALSE;
VO_Electric_Heater_Enable := FALSE;
VO_Freeze_Risk_Status := FALSE;

L_Freeze_Circulation_Required := VI_Freeze_Active AND (VI_IO_Failsafe_Active OR VI_Gas_Safety_Active);

IF NOT VI_Block_Normal_Heating THEN
    RETURN;
END_IF;

// =============================
// ZONE VALVES (FIXED)
// =============================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF L_Freeze_Circulation_Required THEN
        VO_Zone_Valves[L_i] := TRUE;
    ELSE
        VO_Zone_Valves[L_i] := FALSE;
    END_IF;
END_FOR;

// =============================
// MANIFOLD CONTROL
// =============================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF L_Freeze_Circulation_Required THEN
        VO_Manifold_Pumps[L_i] := TRUE;
        VO_Manifold_Valves[L_i] := REAL#35.0;
    ELSE
        VO_Manifold_Pumps[L_i] := FALSE;
        VO_Manifold_Valves[L_i] := REAL#0.0;
    END_IF;
END_FOR;

// =============================
// BOILERS OFF
// =============================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_OT_Enable[L_i] := FALSE;
    VO_Boiler_OT_Setpoint[L_i] := REAL#0.0;
    VO_Boiler_Status[L_i].Warning := FALSE;
    VO_Boiler_Status[L_i].Error := TRUE;
END_FOR;

// =============================
// FREEZE PROTECTION LOGIC
// =============================
IF VI_Gas_Safety_Active AND VI_Freeze_Active THEN
    VO_Backup_Circulation_Pump := TRUE;

    L_Min_Supply_Temp := REAL#1000.0;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF VI_Manifold_Temps_Supply[L_i] < L_Min_Supply_Temp THEN
            L_Min_Supply_Temp := VI_Manifold_Temps_Supply[L_i];
        END_IF;
    END_FOR;

    IF L_Min_Supply_Temp > REAL#900.0 THEN
        L_Min_Supply_Temp := REAL#0.0;
    END_IF;

    IF L_Min_Supply_Temp < (VI_Freeze_Target_Supply - REAL#1.0) THEN
        VO_Electric_Heater_Enable := TRUE;
    ELSIF L_Min_Supply_Temp > (VI_Freeze_Target_Supply + REAL#1.0) THEN
        VO_Electric_Heater_Enable := FALSE;
    END_IF;

    VO_Freeze_Risk_Status := TRUE;
END_IF;

// =============================
// IO FAILSAFE + FREEZE
// =============================
IF VI_IO_Failsafe_Active AND VI_Freeze_Active THEN
    IF VI_Boiler_OT_Online[1] AND NOT VI_Boiler_Error_Status[1] THEN
        VO_Boiler_OT_Enable[1] := TRUE;
        VO_Boiler_OT_Setpoint[1] := VI_Freeze_Target_Supply;
    END_IF;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Safe_State <<<

VO_HMI_Status_Text := VI_Status_Msg;

CASE VI_Severity OF
    E_System_Severity.SEV_NORMAL:
        VO_HMI_State_Code := 0;
    E_System_Severity.SEV_WARNING:
        VO_HMI_State_Code := 1;
    E_System_Severity.SEV_DEGRADED:
        VO_HMI_State_Code := 2;
    E_System_Severity.SEV_CRITICAL:
        VO_HMI_State_Code := 3;
ELSE
        // No fallback required
END_CASE;
// >>> BULK_SYNC_ANCHOR: FB_HMI_Interface <<<

// Debounce non-critical diagnostics: require 3 stable cycles to assert/clear
IF VI_IO_Offline THEN
    L_IO_Fault_Clear_Count := 0;
    IF L_IO_Fault_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Assert_Count := L_IO_Fault_Assert_Count + 1;
    END_IF;
    IF L_IO_Fault_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_IO_Fault_Assert_Count := 0;
    IF L_IO_Fault_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Clear_Count := L_IO_Fault_Clear_Count + 1;
    END_IF;
    IF L_IO_Fault_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Stable := FALSE;
    END_IF;
END_IF;

IF VI_Comm_Fault THEN
    L_Comm_Fault_Clear_Count := 0;
    IF L_Comm_Fault_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Assert_Count := L_Comm_Fault_Assert_Count + 1;
    END_IF;
    IF L_Comm_Fault_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_Comm_Fault_Assert_Count := 0;
    IF L_Comm_Fault_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Clear_Count := L_Comm_Fault_Clear_Count + 1;
    END_IF;
    IF L_Comm_Fault_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Stable := FALSE;
    END_IF;
END_IF;

IF VI_Sensor_Fault THEN
    L_Sensor_Fault_Clear_Count := 0;
    IF L_Sensor_Fault_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Assert_Count := L_Sensor_Fault_Assert_Count + 1;
    END_IF;
    IF L_Sensor_Fault_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_Sensor_Fault_Assert_Count := 0;
    IF L_Sensor_Fault_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Clear_Count := L_Sensor_Fault_Clear_Count + 1;
    END_IF;
    IF L_Sensor_Fault_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Stable := FALSE;
    END_IF;
END_IF;

IF VI_Subsystem_Fault THEN
    L_Subsystem_Clear_Count := 0;
    IF L_Subsystem_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Assert_Count := L_Subsystem_Assert_Count + 1;
    END_IF;
    IF L_Subsystem_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_Subsystem_Assert_Count := 0;
    IF L_Subsystem_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Clear_Count := L_Subsystem_Clear_Count + 1;
    END_IF;
    IF L_Subsystem_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Fault_Stable := FALSE;
    END_IF;
END_IF;

// Count confirmed fault events on rising edge of stable/critical conditions
IF L_IO_Fault_Stable AND NOT L_IO_Fault_Prev THEN
    VO_IO_Fault_Count := VO_IO_Fault_Count + 1;
END_IF;
L_IO_Fault_Prev := L_IO_Fault_Stable;

IF L_Comm_Fault_Stable AND NOT L_Comm_Fault_Prev THEN
    VO_Comm_Fault_Count := VO_Comm_Fault_Count + 1;
END_IF;
L_Comm_Fault_Prev := L_Comm_Fault_Stable;

IF L_Sensor_Fault_Stable AND NOT L_Sensor_Fault_Prev THEN
    VO_Sensor_Fault_Count := VO_Sensor_Fault_Count + 1;
END_IF;
L_Sensor_Fault_Prev := L_Sensor_Fault_Stable;

IF L_Subsystem_Fault_Stable AND NOT L_Subsystem_Fault_Prev THEN
    VO_Subsystem_Fault_Count := VO_Subsystem_Fault_Count + 1;
END_IF;
L_Subsystem_Fault_Prev := L_Subsystem_Fault_Stable;

IF VI_Watchdog_Fault AND NOT L_Watchdog_Fault_Prev THEN
    VO_Watchdog_Fault_Count := VO_Watchdog_Fault_Count + 1;
END_IF;
L_Watchdog_Fault_Prev := VI_Watchdog_Fault;

VO_Sensor_Fault := L_Sensor_Fault_Stable;
VO_IO_Fault := L_IO_Fault_Stable;
VO_Comm_Fault := L_Comm_Fault_Stable;
VO_Subsystem_Degraded := L_Subsystem_Fault_Stable;

VO_System_Severity := E_System_Severity.SEV_NORMAL;
VO_Root_Cause := E_System_Root_Cause.ROOT_NONE;
VO_First_Fault_Active := FALSE;
VO_First_Fault_Type := 0;
VO_First_Fault_Source := 0;

// Priority: FIRE > GAS > CO > WATER > diagnostics
IF VI_Smoke_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_FIRE;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 5;

ELSIF VI_Gas_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_GAS_LEAK;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 6;

ELSIF VI_CO_Alarm_Level THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_CO_CRITICAL;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 7;

ELSIF VI_CO_Warning_Level THEN
    VO_System_Severity := E_System_Severity.SEV_WARNING;
    VO_Root_Cause := E_System_Root_Cause.ROOT_CO_WARNING;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 7;

ELSIF VI_Leak_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_WARNING;
    VO_Root_Cause := E_System_Root_Cause.ROOT_WATER_LEAK;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 8;

ELSIF VI_Watchdog_Fault THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_WATCHDOG_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 9;

ELSIF L_IO_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_IO_OFFLINE;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 1;

ELSIF L_Comm_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_COMM_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 3;

ELSIF L_Sensor_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_SENSOR_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 2;

ELSIF L_Subsystem_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 4;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_System_Health <<<

// ==============================================================================
// Ownership note
// ------------------------------------------------------------------------------
// This block owns only global policy mode/adjustment and policy quality/self-tune
// diagnostics. It does NOT own per-zone thermal fields, per-zone target adjustment,
// preheat request, or optimization demand values.
//
// Field owners:
// - FB_Heating_Thermal_Model: thermal response/demand/time/model confidence;
// - FB_Heating_Predictive_Controller: preheat-needed prediction;
// - FB_Heating_Optimizer: optimization scores/load diagnostics;
// - FB_Heating_Policy_Observer / FB_Heating_Schedule_Preheat: zone target policy;
// - FB_Heating_Policy_Manager: global policy and quality/self-level diagnostics.
// ==============================================================================

L_Zone_Hold_MS := VI_Min_Hold_MS / 2;
IF L_Zone_Hold_MS < 60000 THEN
    L_Zone_Hold_MS := 60000;
END_IF;

IF NOT L_Quality_Initialized THEN
    L_Last_Room_Avg := VI_Room_Temp_Avg;
    L_Filtered_Trend := 0.0;
    L_Same_Cause_Since := VI_System_Time_MS;
    L_Last_Cause := VI_RootCause;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        L_Zone_Last_Level_Accept_MS[L_i] := VI_System_Time_MS;
        GVL_HEATING_POLICY.G_Zone_Quality[L_i] := 0.0;
        GVL_HEATING_POLICY.G_Zone_Improving[L_i] := FALSE;
        GVL_HEATING_POLICY.G_Zone_Stable[L_i] := TRUE;
        GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] := 0;
    END_FOR;

    L_Quality_Initialized := TRUE;
END_IF;

// ==============================================================================
// Global predictive adjustment based on aggregate room trend.
// ==============================================================================
L_Trend := VI_Room_Temp_Avg - L_Last_Room_Avg;
L_Last_Room_Avg := VI_Room_Temp_Avg;
L_Filtered_Trend := (L_Filtered_Trend * 0.8) + (L_Trend * 0.2);

L_Predictive_Adjustment := 0.0;
IF (L_Filtered_Trend < -0.03) AND (VI_Room_Temp_Avg < (VI_Target_Temp + 0.5)) THEN
    L_Predictive_Adjustment := 1.0;
ELSIF L_Filtered_Trend > 0.03 THEN
    L_Predictive_Adjustment := -0.5;
END_IF;

IF L_Predictive_Adjustment > 1.0 THEN
    L_Predictive_Adjustment := 1.0;
END_IF;
IF L_Predictive_Adjustment < -1.0 THEN
    L_Predictive_Adjustment := -1.0;
END_IF;

GVL_HEATING_POLICY.G_Policy_Predictive_Adjustment := L_Predictive_Adjustment;
GVL_HEATING_POLICY.G_Policy_Predictive_Active := ABS(L_Predictive_Adjustment) > 0.001;

// ==============================================================================
// Aggregate quality / feedback diagnostics.
// ==============================================================================
L_Room_Error := VI_Target_Temp - VI_Room_Temp_Avg;
L_Supply_Error := VI_Target_Temp - VI_Supply_Temp;
L_DeltaT := VI_Supply_Temp - VI_Return_Temp;
L_Quality := 0.0;

IF L_Room_Error > 1.0 THEN
    L_Quality := L_Quality + 2.0;
END_IF;
IF L_Supply_Error > 1.0 THEN
    L_Quality := L_Quality + 1.0;
END_IF;
IF L_DeltaT < 3.0 THEN
    L_Quality := L_Quality + 1.0;
END_IF;

L_Improving := L_Quality < L_Last_Quality;
L_Stable := L_Quality = 0.0;

// ==============================================================================
// Per-zone quality / self-level diagnostics only.
// Does not write target adjustment, thermal demand, time-to-heat, or preheat flags.
// ==============================================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Zone_Error := VI_Target_Temp - VI_Room_Temps[L_i];
    L_Zone_Quality := 0.0;

    IF L_Zone_Error > 1.0 THEN
        L_Zone_Quality := L_Zone_Quality + 2.0;
    END_IF;
    IF VI_Floor_Temps[L_i] < (VI_Target_Temp - 2.0) THEN
        L_Zone_Quality := L_Zone_Quality + 1.0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Improving[L_i] :=
        L_Zone_Quality < GVL_HEATING_POLICY.G_Zone_Quality[L_i];

    GVL_HEATING_POLICY.G_Zone_Stable[L_i] :=
        L_Zone_Quality = 0.0;

    L_Zone_Desired_Level := GVL_HEATING_POLICY.G_Zone_Self_Level[L_i];

    IF GVL_HEATING_POLICY.G_Zone_Stable[L_i] THEN
        L_Zone_Desired_Level := 0;
    ELSIF GVL_HEATING_POLICY.G_Zone_Improving[L_i] THEN
        L_Zone_Desired_Level := GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] - 1;
    ELSIF L_Zone_Quality >= 3.0 THEN
        L_Zone_Desired_Level := GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] + 1;
    END_IF;

    IF L_Zone_Desired_Level > 2 THEN
        L_Zone_Desired_Level := 2;
    END_IF;
    IF L_Zone_Desired_Level < 0 THEN
        L_Zone_Desired_Level := 0;
    END_IF;

    IF L_Zone_Desired_Level <> GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] THEN
        IF (VI_System_Time_MS - L_Zone_Last_Level_Accept_MS[L_i]) >= L_Zone_Hold_MS THEN
            GVL_HEATING_POLICY.G_Zone_Self_Level[L_i] := L_Zone_Desired_Level;
            L_Zone_Last_Level_Accept_MS[L_i] := VI_System_Time_MS;
        END_IF;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Quality[L_i] := L_Zone_Quality;
END_FOR;

// ==============================================================================
// Global self-level and policy mode.
// ==============================================================================
IF VI_RootCause <> L_Last_Cause THEN
    L_Same_Cause_Since := VI_System_Time_MS;
    L_Self_Level := 0;
END_IF;
L_Last_Cause := VI_RootCause;

IF L_Stable THEN
    L_Self_Level := 0;
ELSIF L_Improving THEN
    L_Self_Level := L_Self_Level - 1;
ELSIF (VI_System_Time_MS - L_Same_Cause_Since) > (VI_Min_Hold_MS * 2) AND (VI_RootConfidence > 0.8) AND (L_Quality >= 3.0) THEN
    L_Self_Level := L_Self_Level + 1;
END_IF;

IF L_Self_Level > 2 THEN
    L_Self_Level := 2;
END_IF;
IF L_Self_Level < 0 THEN
    L_Self_Level := 0;
END_IF;

L_Raw_Mode := E_Heating_Policy_Mode.HPM_NORMAL;
L_Raw_Block := FALSE;
L_Raw_Target_Adjustment := L_Predictive_Adjustment;
L_Raw_Priority_Multiplier := 1.0;
L_Force_Immediate := FALSE;

IF VI_Emergency_Stop OR VI_Gas_Safety THEN
    L_Raw_Mode := E_Heating_Policy_Mode.HPM_SAFETY_BLOCK;
    L_Raw_Block := TRUE;
    L_Raw_Target_Adjustment := 0.0;
    L_Raw_Priority_Multiplier := 1.0;
    L_Force_Immediate := TRUE;
ELSIF VI_RootCause = E_Heating_RootCause.RC_IO_OFFLINE THEN
    L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
    L_Raw_Block := TRUE;
    L_Raw_Target_Adjustment := 0.0;
    L_Raw_Priority_Multiplier := 1.0;
    L_Force_Immediate := TRUE;
ELSIF VI_RootConfidence >= 0.6 THEN
    CASE VI_RootCause OF
        E_Heating_RootCause.RC_NO_HEAT_TRANSFER:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
            L_Raw_Target_Adjustment := L_Raw_Target_Adjustment + 3.0 + TO_REAL(L_Self_Level);
        E_Heating_RootCause.RC_PUMP_FAILURE:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_FAULT_ISOLATION;
            L_Raw_Priority_Multiplier := 0.5 - (0.1 * TO_REAL(L_Self_Level));
        E_Heating_RootCause.RC_VALVES_CLOSED:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_FAULT_ISOLATION;
            L_Raw_Target_Adjustment := L_Raw_Target_Adjustment - 2.0;
        E_Heating_RootCause.RC_NO_FLAME,
        E_Heating_RootCause.RC_BOILER_ERROR:
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
            L_Raw_Priority_Multiplier := 0.7;
    ELSE
        IF VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
            L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
        END_IF;
    END_CASE;
ELSE
    IF VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
        L_Raw_Mode := E_Heating_Policy_Mode.HPM_DEGRADED;
    END_IF;
END_IF;

IF L_Raw_Target_Adjustment > 5.0 THEN
    L_Raw_Target_Adjustment := 5.0;
END_IF;
IF L_Raw_Target_Adjustment < -3.0 THEN
    L_Raw_Target_Adjustment := -3.0;
END_IF;
IF L_Raw_Priority_Multiplier < 0.3 THEN
    L_Raw_Priority_Multiplier := 0.3;
END_IF;
IF L_Raw_Priority_Multiplier > 1.0 THEN
    L_Raw_Priority_Multiplier := 1.0;
END_IF;

L_Effective_Hold_MS := VI_Min_Hold_MS;
IF VI_RootConfidence >= 0.9 THEN
    L_Effective_Hold_MS := VI_Min_Hold_MS / 2;
END_IF;

IF NOT L_Initialized THEN
    L_Held_Mode := L_Raw_Mode;
    L_Held_Block := L_Raw_Block;
    L_Held_Target_Adjustment := L_Raw_Target_Adjustment;
    L_Held_Priority_Multiplier := L_Raw_Priority_Multiplier;
    L_Last_Accept_MS := VI_System_Time_MS;
    L_Initialized := TRUE;
ELSIF L_Force_Immediate THEN
    L_Held_Mode := L_Raw_Mode;
    L_Held_Block := L_Raw_Block;
    L_Held_Target_Adjustment := L_Raw_Target_Adjustment;
    L_Held_Priority_Multiplier := L_Raw_Priority_Multiplier;
    L_Last_Accept_MS := VI_System_Time_MS;
ELSIF (L_Raw_Mode <> L_Held_Mode) OR (ABS(L_Raw_Target_Adjustment - L_Held_Target_Adjustment) > 0.001) OR (ABS(L_Raw_Priority_Multiplier - L_Held_Priority_Multiplier) > 0.001) OR (L_Raw_Block <> L_Held_Block) THEN
    IF (VI_System_Time_MS - L_Last_Accept_MS) >= L_Effective_Hold_MS THEN
        L_Held_Mode := L_Raw_Mode;
        L_Held_Block := L_Raw_Block;
        L_Held_Target_Adjustment := L_Raw_Target_Adjustment;
        L_Held_Priority_Multiplier := L_Raw_Priority_Multiplier;
        L_Last_Accept_MS := VI_System_Time_MS;
    END_IF;
END_IF;

VO_Policy_Mode := L_Held_Mode;
VO_Block_Heating := L_Held_Block;
VO_Target_Adjustment := L_Held_Target_Adjustment;
VO_Priority_Multiplier := L_Held_Priority_Multiplier;
VO_Self_Tune_Active := L_Self_Level > 0;
VO_Self_Tune_Level := L_Self_Level;
VO_Feedback_Stable := L_Stable;
VO_Feedback_Improving := L_Improving;
VO_Feedback_Quality := L_Quality;

L_Last_Quality := L_Quality;

// Упрощенная модель износа
IF VI_Nominal_Life > 0 THEN
    VO_Remaining_Percent := TO_BYTE(100 - (VI_Runtime_Hours * 100 / VI_Nominal_Life));
ELSE
    VO_Remaining_Percent := 0;
END_IF;

VO_Maintenance_Req := (VO_Remaining_Percent < 10);

// Normalize count to analyzer bounds
L_Count := UDINT_TO_INT(VI_Data.record_count);
IF L_Count < 0 THEN
    L_Count := 0;
END_IF;
IF L_Count > GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS THEN
    L_Count := GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS;
END_IF;

// Copy source values into analyzer-compatible buffer
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS DO
    L_Data_Copy[L_i] := 0.0;
END_FOR;

IF L_Count > 0 THEN
    FOR L_i := 1 TO L_Count DO
        L_Data_Copy[L_i] := VI_Data.values[L_i];
    END_FOR;
END_IF;

fbAnalyzer(
    VI_Count := L_Count,
    VI_Data := L_Data_Copy,
    VO_Average => VO_Average,
    VO_Max => VO_Max,
    VO_Min => VO_Min,
    VO_Trend_Up => VO_Trend_Up,
    VO_Trend_Down => VO_Trend_Down
);

// ==============================================================================
// System redundancy orchestrator helper
//
// Internal helper for PRG_System.
// Owns PLC role calculation, heartbeat output projection, and synced-state apply.
// ==============================================================================



// Build local state snapshot for replication.
VIO_Local_State.System_Time_MS := GVL_STATUS.G_System_Time_MS;
VIO_Local_State.Current_Scenario := GVL_STATUS.G_Current_Scenario;
VIO_Local_State.Security_Armed := GVL_ALARM.G_Security_Armed;
VIO_Local_State.Active_Alarms := GVL_ALARM.G_Active_Alarm_Count;
VIO_Local_State.Zone_Valves := GVL_STATE.G_Zone_Valves;
VIO_Local_State.Manifold_Pumps := GVL_STATE.G_Manifold_Pumps;
VIO_Local_State.Lighting_States := GVL_STATE.G_Lighting_Levels;
VIO_Local_State.Blinds_Positions := GVL_STATE.G_Blinds_Positions;
VIO_Local_State.Socket_States := GVL_STATE.G_Socket_States;
VIO_Local_State.Gas_Valve_Closed := GVL_COMMAND.G_Gas_Valve_Close;
VIO_Local_State.Water_Valves_Closed := GVL_COMMAND.G_Close_Valve_36;
VIO_Local_State.Version := VIO_Local_State.Version + 1;

fbRedundancy(
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_Local_PLC_ID := GVL_STATUS.G_PLC_ID,
    VI_Remote_Pulse := GVL_IO.DI_Partner_Pulse,
    VI_Remote_Is_Active := GVL_IO.DI_Partner_Active,
    VI_Gateway_Ping_OK := GVL_GATEWAY.G_Gateway_Ping_OK,
    VI_Local_State := VIO_Local_State,
    VI_Remote_State := VIO_Remote_State
);

GVL_STATUS.G_Is_Active_PLC := (fbRedundancy.VO_Local_Role = E_PLC_ROLE.ROLE_ACTIVE);
GVL_IO.DO_Heartbeat_Pulse := fbRedundancy.VO_Local_Pulse;
GVL_IO.DO_Active_Status := GVL_STATUS.G_Is_Active_PLC;

IF fbRedundancy.VO_State_Updated THEN
    GVL_STATUS.G_Current_Scenario := fbRedundancy.VO_Synced_State.Current_Scenario;
    GVL_ALARM.G_Security_Armed := fbRedundancy.VO_Synced_State.Security_Armed;
    GVL_STATE.G_Zone_Valves := fbRedundancy.VO_Synced_State.Zone_Valves;
    GVL_STATE.G_Manifold_Pumps := fbRedundancy.VO_Synced_State.Manifold_Pumps;
    GVL_STATE.G_Lighting_Levels := fbRedundancy.VO_Synced_State.Lighting_States;
    GVL_STATE.G_Blinds_Positions := fbRedundancy.VO_Synced_State.Blinds_Positions;
    GVL_STATE.G_Socket_States := fbRedundancy.VO_Synced_State.Socket_States;
    GVL_COMMAND.G_Gas_Valve_Close := fbRedundancy.VO_Synced_State.Gas_Valve_Closed;
    GVL_COMMAND.G_Close_Valve_36 := fbRedundancy.VO_Synced_State.Water_Valves_Closed;
    VIO_Local_State.Version := fbRedundancy.VO_Synced_State.Version;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Redundancy_Orchestrator <<<

L_Found_Index := 0;
L_Was_Active := FALSE;
FOR L_i := 1 TO 50 DO
    IF (VIO_Events[L_i].Code = VI_Code) AND (VIO_Events[L_i].Source = VI_Source) THEN
        L_Found_Index := L_i;
        L_Was_Active := VIO_Events[L_i].Active;
        EXIT;
    END_IF;
END_FOR;

L_Debounce_Index := 0;
L_Oldest_Time := 16#FFFFFFFF;
L_Oldest_Index := 1;

FOR L_i := 1 TO 50 DO
    IF L_Debounce_Used[L_i] THEN
        IF (L_Debounce_Code[L_i] = VI_Code) AND (L_Debounce_Source[L_i] = VI_Source) THEN
            L_Debounce_Index := L_i;
            EXIT;
        END_IF;
        IF L_Debounce_Last_Change_Time[L_i] < L_Oldest_Time THEN
            L_Oldest_Time := L_Debounce_Last_Change_Time[L_i];
            L_Oldest_Index := L_i;
        END_IF;
    ELSE
        L_Debounce_Index := L_i;
        EXIT;
    END_IF;
END_FOR;

IF L_Debounce_Index = 0 THEN
    L_Debounce_Index := L_Oldest_Index;
END_IF;

IF NOT L_Debounce_Used[L_Debounce_Index] OR
   (L_Debounce_Code[L_Debounce_Index] <> VI_Code) OR
   (L_Debounce_Source[L_Debounce_Index] <> VI_Source) THEN
    L_Debounce_Used[L_Debounce_Index] := TRUE;
    L_Debounce_Code[L_Debounce_Index] := VI_Code;
    L_Debounce_Source[L_Debounce_Index] := VI_Source;
    L_Debounce_Last_Input_State[L_Debounce_Index] := VI_Active;
    L_Debounce_Stable_State[L_Debounce_Index] := FALSE;
    L_Debounce_Last_Change_Time[L_Debounce_Index] := VI_Timestamp;
END_IF;

IF VI_Active <> L_Debounce_Last_Input_State[L_Debounce_Index] THEN
    L_Debounce_Last_Input_State[L_Debounce_Index] := VI_Active;
    L_Debounce_Last_Change_Time[L_Debounce_Index] := VI_Timestamp;
END_IF;

IF (VI_Timestamp - L_Debounce_Last_Change_Time[L_Debounce_Index]) > 2000 THEN
    L_Debounce_Stable_State[L_Debounce_Index] := L_Debounce_Last_Input_State[L_Debounce_Index];
END_IF;

L_Stable_State := L_Debounce_Stable_State[L_Debounce_Index];

IF L_Stable_State THEN
    IF NOT L_Was_Active THEN
        L_Index := (VIO_Count MOD 50) + 1;
        VIO_Events[L_Index].Code := VI_Code;
        VIO_Events[L_Index].Severity := VI_Severity;
        VIO_Events[L_Index].Active := TRUE;
        VIO_Events[L_Index].Timestamp := VI_Timestamp;
        VIO_Events[L_Index].Source := VI_Source;
        VIO_Count := VIO_Count + 1;
    ELSIF L_Found_Index > 0 THEN
        VIO_Events[L_Found_Index].Severity := VI_Severity;
    END_IF;
ELSE
    IF L_Found_Index > 0 THEN
        VIO_Events[L_Found_Index].Active := FALSE;
    END_IF;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Diagnostics_Event_Manager <<<

// Если ПЛК находится в режиме Standby (резерв), он не должен управлять выходами
IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

IF VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    VO_Gate_Open := FALSE;
    VO_Wicket_Open := FALSE;
    VO_Lock_1_Open := FALSE;
    VO_Lock_2_Open := FALSE;
    RETURN;
END_IF;

// 1. Логика автоматического закрытия замков при постановке на охрану (ТЗ 3.0)
// При переходе системы в режим "Охрана" принудительно блокируем все замки
IF VI_Armed AND NOT L_Prev_Armed THEN
    L_Auto_Lock_Req := TRUE;
END_IF;
L_Prev_Armed := VI_Armed;

// Детекторы фронта для команд
R_Trig_Gate(CLK := VI_Gate_Open_Req);
R_Trig_Wicket(CLK := VI_Wicket_Open_Req);
R_Trig_Lock_1_O(CLK := VI_Lock_1_Open_Req);
R_Trig_Lock_1_C(CLK := VI_Lock_1_Close_Req OR L_Auto_Lock_Req);
R_Trig_Lock_2_O(CLK := VI_Lock_2_Open_Req);
R_Trig_Lock_2_C(CLK := VI_Lock_2_Close_Req OR L_Auto_Lock_Req);

// Проверка PIN-кода или RFID-метки через менеджер кодов
fbAccessCode(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Code_To_Check := VI_PIN_Code,
    VI_RFID_To_Check := VI_RFID_Tag,
    VI_Access_Codes := VI_Access_Codes,
    VI_RFID_Tags := VI_RFID_Tags,
    VO_Code_Valid => L_Valid_PIN
);

// 2. Формирование импульсов управления исполнительными механизмами (Pulse Control)
// Открытие ворот и калитки требует валидного ПИН-кода или RFID-метки, если система под охраной
L_Gate_Timer(IN := R_Trig_Gate.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.gate_open_pulse_ms));
VO_Gate_Open := L_Gate_Timer.Q;

L_Wicket_Timer(IN := R_Trig_Wicket.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.wicket_open_pulse_ms));
VO_Wicket_Open := L_Wicket_Timer.Q;

L_Lock_1_Open_T(IN := R_Trig_Lock_1_O.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.lock_open_pulse_ms));
VO_Lock_1_Open := L_Lock_1_Open_T.Q;

L_Lock_1_Close_T(IN := R_Trig_Lock_1_C.Q, PT := TO_TIME(VI_Config.lock_close_pulse_ms));
VO_Lock_1_Close := L_Lock_1_Close_T.Q;

L_Lock_2_Open_T(IN := R_Trig_Lock_2_O.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.lock_open_pulse_ms));
VO_Lock_2_Open := L_Lock_2_Open_T.Q;

L_Lock_2_Close_T(IN := R_Trig_Lock_2_C.Q, PT := TO_TIME(VI_Config.lock_close_pulse_ms));
VO_Lock_2_Close := L_Lock_2_Close_T.Q;

// Сброс флага автоматического закрытия
IF L_Auto_Lock_Req THEN
    L_Auto_Lock_Req := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Access_Control <<<

IF NOT VI_Config.enabled THEN
    RETURN;
END_IF;

L_Deviation := ABS(VI_Current_Value - L_Last_Value);
L_Elapsed_Time := SEL(
    VI_System_Time_MS >= L_Last_Log_Time,
    VI_System_Time_MS - L_Last_Log_Time,
    (4294967295 - L_Last_Log_Time) + VI_System_Time_MS + 1
);

IF (L_Deviation >= (ABS(L_Last_Value) * VI_Config.deviation_threshold_percent / REAL#100.0)) OR
   (L_Elapsed_Time >= GVL_CONSTANTS.C_MS_IN_HOUR) THEN

    L_Write_Index := (VO_Data.record_count MOD 100) + 1;
    VO_Data.write_index := L_Write_Index;
    VO_Data.values[L_Write_Index] := VI_Current_Value;
    VO_Data.timestamps[L_Write_Index] := VI_System_Time_MS;
    VO_Data.record_count := VO_Data.record_count + 1;
    VO_Data.sum_values := VO_Data.sum_values + VI_Current_Value;
    VO_Data.config := VI_Config;

    L_Last_Value := VI_Current_Value;
    L_Last_Log_Time := VI_System_Time_MS;
END_IF;

IF (VI_Gas_Alarm <> L_Last_Gas) OR (VI_Leak_Alarm <> L_Last_Leak) THEN
    VO_Last_Change_Time := VI_System_Time;
END_IF;

L_Last_Gas := VI_Gas_Alarm;
L_Last_Leak := VI_Leak_Alarm;

// ======================================================
// MODBUS RESPONSE APPLY LAYER
// ======================================================
// Transfers validated parser result into bridge/master response.
//
// Safety principles:
//   - Only validated parser result may produce Done.
//   - Parser error produces Error response.
//   - No synthetic successful response.
// ======================================================

VO_Response_Applied := FALSE;

IF NOT VI_Request_Valid THEN
    RETURN;
END_IF;

IF (VI_Request_Index < 1) OR (VI_Request_Index > 16) THEN
    RETURN;
END_IF;

// ======================================================
// PARSER ERROR
// ======================================================
IF VI_Parser_Error THEN

    GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Done := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error := TRUE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code := VI_Parser_Error_Code;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Sequence := VI_Request_Sequence;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Update_MS := VI_System_Time_MS;

    VO_Response_Applied := TRUE;

    RETURN;
END_IF;

// ======================================================
// VALID PARSED RESPONSE
// ======================================================
IF VI_Parser_Valid THEN

    FOR L_i := 1 TO 32 DO
        GVL_MODBUS_RTU_BRIDGE.G_Response_Value[L_i] := 0;
    END_FOR;

    L_Count := UINT_TO_INT(VI_Register_Count);

    IF L_Count > 32 THEN
        L_Count := 32;
    END_IF;

    FOR L_i := 1 TO L_Count DO
        GVL_MODBUS_RTU_BRIDGE.G_Response_Value[L_i] :=
            VI_Register_Value[L_i];
    END_FOR;

    GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Done := TRUE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code := 0;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Sequence := VI_Request_Sequence;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Update_MS := VI_System_Time_MS;

    VO_Response_Applied := TRUE;

END_IF;

// ==============================================================================
// Блок таймера, привязанный к системному времени (System Timer)
// Назначение:
// - Замена стандартного TON для обеспечения точной выдержки времени,
//   независимой от времени цикла ПЛК, с использованием единого системного времени.
// ==============================================================================



IF IN THEN
    IF NOT L_Running THEN
        L_Start_Time := VI_System_Time_MS;
        L_Running := TRUE;
        ET := T#0s;
        Q := FALSE;
    ELSE
        // Обработка переполнения UDINT (примерно 49 дней)
        ET := TO_TIME((SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1)));

        IF ET >= PT THEN
            Q := TRUE;
            ET := PT;
        ELSE
            Q := FALSE;
        END_IF;
    END_IF;
ELSE
    L_Running := FALSE;
    ET := T#0s;
    Q := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_System_Timer <<<

// ==============================================================================
// Heating runtime output projection phase
// Final phase wrapper around physical output projection.
// Does NOT calculate heating logic and does NOT publish state/status.
// ==============================================================================



VO_Executed := FALSE;
VO_Valid := FALSE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

fbOutputProjection(
    VI_Zone_Valves := VI_Zone_Valves,
    VI_Manifold_Pumps := VI_Manifold_Pumps,
    VI_Manifold_Valves := VI_Manifold_Valves,
    VI_DHW_Heating_Pump := VI_DHW_Heating_Pump,
    VI_DHW_Circ_Pump := VI_DHW_Circ_Pump,
    VI_Backup_Circulation_Pump := VI_Backup_Circulation_Pump,
    VI_Electric_Heater_Enable := VI_Electric_Heater_Enable
);

VO_Executed := TRUE;
VO_Valid := TRUE;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Output_Projection_Phase <<<

// ==============================================================================
// Heating runtime service gating phase
// Applies service/out-of-service and freeze hardware gating to computed outputs.
// Does NOT calculate heating demand and does NOT publish final state.
// ==============================================================================



VO_Executed := FALSE;
VO_Valid := FALSE;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

GVL_STATUS.G_Diagnostics.Backup_Pump_Out_Of_Service := NOT GVL_CONFIG.G_Backup_Circulation_Pump_In_Service;
GVL_STATUS.G_Diagnostics.Electric_Heater_Out_Of_Service := NOT GVL_CONFIG.G_Electric_Heater_In_Service;

IF NOT GVL_CONFIG.G_Backup_Circulation_Pump_In_Service THEN
    VIO_Backup_Circulation_Pump := FALSE;
END_IF;

IF NOT GVL_CONFIG.G_Electric_Heater_In_Service THEN
    VIO_Electric_Heater_Enable := FALSE;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_STATUS.G_Diagnostics.Manifold_Pump_Out_Of_Service[L_i] := NOT GVL_CONFIG.G_Manifold_Pump_In_Service[L_i];
    IF NOT GVL_CONFIG.G_Manifold_Pump_In_Service[L_i] THEN
        VIO_Manifold_Pumps[L_i] := FALSE;
    END_IF;
END_FOR;

GVL_STATUS.G_Diagnostics.DHW_Heating_Pump_Out_Of_Service := NOT GVL_CONFIG.G_DHW_Heating_Pump_In_Service;
IF NOT GVL_CONFIG.G_DHW_Heating_Pump_In_Service THEN
    VIO_DHW_Heating_Pump := FALSE;
    VIO_DHW_Status.Heating_Pump_On := FALSE;
END_IF;

GVL_STATUS.G_Diagnostics.DHW_Circ_Pump_Out_Of_Service := NOT GVL_CONFIG.G_DHW_Circ_Pump_In_Service;
IF NOT GVL_CONFIG.G_DHW_Circ_Pump_In_Service THEN
    VIO_DHW_Circ_Pump := FALSE;
    VIO_DHW_Status.Circ_Pump_On := FALSE;
END_IF;

GVL_STATE.G_Freeze_Hardware_Degraded := GVL_STATUS.G_Diagnostics.Backup_Pump_Fault OR GVL_STATUS.G_Diagnostics.Electric_Heater_Fault;
GVL_STATE.G_Freeze_Hardware_Failed := GVL_STATUS.G_Diagnostics.Backup_Pump_Fault AND GVL_STATUS.G_Diagnostics.Electric_Heater_Fault;

IF GVL_STATE.G_Freeze_Hardware_Failed THEN
    VIO_Backup_Circulation_Pump := FALSE;
    VIO_Electric_Heater_Enable := FALSE;
    VIO_Freeze_Risk_Status := TRUE;
END_IF;

VO_Executed := TRUE;
VO_Valid := TRUE;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Service_Gating_Phase <<<

// Детекция фронта команды
L_cmd_rising := (VI_Command <> 0) AND (L_prev_Command = 0);
L_prev_Command := VI_Command;

IF L_cmd_rising THEN
    VO_Done := FALSE;
    VO_Error := FALSE;
    VO_ErrorID := 0;
    VO_HMI_Status_Message := '';

    // Валидация смещения
    IF VI_Offset >= C_MAX_NVRAM_SIZE THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#1501;
        VO_HMI_Status_Message := 'NVRAM: Неверное смещение';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    // Валидация указателя
    IF NOT __ISVALIDREF(VI_DataRef) THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#150A;
        VO_HMI_Status_Message := 'NVRAM: Недействительная ссылка на данные';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    L_pData := ADR(VI_DataRef);

    IF (VI_Offset + VI_DataSize) > C_MAX_NVRAM_SIZE THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#150B;
        VO_HMI_Status_Message := 'NVRAM: Размер данных превышает доступный объем';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    IF VI_Command = 2 THEN
    VO_Error := TRUE;
    VO_ErrorID := 16#150D;
    VO_HMI_Status_Message := 'NVRAM: READ not implemented';
    VO_Done := TRUE;
    RETURN;
END_IF;

IF VI_Command = 1 THEN // ЗАПИСЬ (WRITE)
        IF NOT VI_IsActivePLC THEN
            VO_Error := TRUE;
            VO_ErrorID := 16#1509;
            VO_HMI_Status_Message := 'NVRAM: Запись запрещена (STANDBY)';
        ELSE
            // Проверка на изменение данных перед записью
            L_Data_Changed := FALSE;
            FOR L_i := 0 TO VI_DataSize - 1 DO
                IF GVL_Retain.G_NVRAM_Data[VI_Offset + L_i] <> L_pData[L_i] THEN
                    L_Data_Changed := TRUE;
                    EXIT;
                END_IF;
            END_FOR;

            IF L_Data_Changed THEN
                // Безопасное копирование (WRITE)
                FOR L_i := 0 TO VI_DataSize - 1 DO
                    GVL_Retain.G_NVRAM_Data[VI_Offset + L_i] := L_pData[L_i];
                END_FOR;
                VO_HMI_Status_Message := 'NVRAM: Данные успешно сохранены в RETAIN';
            ELSE
                VO_HMI_Status_Message := 'NVRAM: Данные не изменились, запись пропущена';
            END_IF;
        END_IF;
        VO_Done := TRUE;
    END_IF;
END_IF;

IF VI_Command = 0 THEN
    VO_Done := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_NVRAM_Manager <<<

IF VI_Write_Event AND NOT L_Prev_Write_Event THEN
    GVL_Retain.G_History_Buffer[GVL_Retain.G_History_Write_Idx] := VI_Event;
    GVL_Retain.G_History_Buffer[GVL_Retain.G_History_Write_Idx].timestamp_ms := VI_System_Time_MS;

    GVL_Retain.G_History_Write_Idx := (GVL_Retain.G_History_Write_Idx MOD GVL_CONSTANTS.C_MAX_HISTORY_RECORDS) + 1;
    GVL_Retain.G_History_Total_Events := GVL_Retain.G_History_Total_Events + 1;
END_IF;
L_Prev_Write_Event := VI_Write_Event;

VO_Total_Events := GVL_Retain.G_History_Total_Events;
// >>> BULK_SYNC_ANCHOR: FB_History_Manager <<<

// ==============================================================================
// Ownership note
// ------------------------------------------------------------------------------
// This block calculates optimization diagnostics only.
// It does NOT modify thermal demand.
//
// Thermal demand ownership remains in:
// FB_Heating_Thermal_Model.
// ==============================================================================

L_Total_Demand := 0.0;

// Aggregate thermal load estimate.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Total_Demand := L_Total_Demand + ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i]);
END_FOR;

GVL_HEATING_POLICY.G_Optimization_Load_Index := L_Total_Demand;
GVL_HEATING_POLICY.G_Optimization_Energy_Saving_Active := FALSE;

// Zone optimization diagnostics.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    IF L_Total_Demand > 0.01 THEN
        L_Load := ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i]) / L_Total_Demand;
    ELSE
        L_Load := 0.0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Optimization_Score[L_i] :=
        L_Load +
        ((1.0 - GVL_HEATING_POLICY.G_Zone_Thermal_Model_Confidence[L_i]) * 0.2);

    // Advisory energy-saving indication only.
    IF L_Total_Demand > 5.0 THEN
        GVL_HEATING_POLICY.G_Optimization_Energy_Saving_Active := TRUE;
    END_IF;

END_FOR;

// ==============================================================================
// Heating manifold control helper
// Internal refactoring helper for FB_Heating_System_Manager.
// Valve test override remains in FB_Heating_System_Manager for now.
// ==============================================================================



FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_PID_Timer[L_i](IN := TRUE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS);
    IF L_PID_Timer[L_i].Q THEN
        L_PID_Timer[L_i](IN := FALSE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS);
        L_PID_Timer[L_i](IN := TRUE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS);

        L_PID_Valves[L_i](
            VI_SetPoint := VI_Target_Supply_Temp,
            VI_ProcessValue := VI_Manifold_Temps_Supply[L_i],
            VI_Kp := 2.0,
            VI_Tn := 120.0,
            VI_Tv := 0.0,
            VI_Y_Min := 0.0,
            VI_Y_Max := 100.0,
            VI_Cycle_Time_S := 1.0,
            VO_Output => VO_Manifold_Valves[L_i]
        );
    END_IF;

    L_Pump_Run_Timer[L_i](
        IN := VO_Manifold_Pumps[L_i] AND NOT L_Pump_In_Pause[L_i],
        PT := T#72h,
        VI_System_Time_MS := VI_System_Time_MS
    );
    IF L_Pump_Run_Timer[L_i].Q THEN
        L_Pump_In_Pause[L_i] := TRUE;
    END_IF;

    L_Pump_Pause_Timer[L_i](
        IN := L_Pump_In_Pause[L_i],
        PT := T#1h,
        VI_System_Time_MS := VI_System_Time_MS
    );
    IF L_Pump_Pause_Timer[L_i].Q THEN
        L_Pump_In_Pause[L_i] := FALSE;
    END_IF;

    IF VI_DHW_Heating_Demand THEN
        VO_Manifold_Pumps[L_i] := FALSE;
        VO_Manifold_Valves[L_i] := 0.0;
    ELSE
        VO_Manifold_Pumps[L_i] := VI_IsActivePLC AND VI_Any_Zone_Active[L_i] AND NOT L_Pump_In_Pause[L_i];
    END_IF;

    IF VI_Freeze_Mode_Active THEN
        VO_Manifold_Pumps[L_i] := TRUE;
        IF VO_Manifold_Valves[L_i] < 35.0 THEN
            VO_Manifold_Valves[L_i] := 35.0;
        END_IF;
    END_IF;

    VO_Status[L_i].Pump_On := VO_Manifold_Pumps[L_i];
    VO_Status[L_i].Pump_Current := VI_Manifold_Currents[L_i];
    VO_Status[L_i].Pressure := VI_Manifold_Pressures[L_i];
    VO_Status[L_i].Temp_Supply := VI_Manifold_Temps_Supply[L_i];
    VO_Status[L_i].Temp_Return := VI_Manifold_Temps_Return[L_i];
    VO_Status[L_i].Valve_Pos := VO_Manifold_Valves[L_i];

    L_Pump_Diag[L_i](
        VI_Current_Value := VI_Manifold_Currents[L_i],
        VI_Nominal_Value := 0.55,
        VI_Is_Running := VO_Manifold_Pumps[L_i],
        VI_Reset_Stats := FALSE,
        VI_System_Time_MS := VI_System_Time_MS,
        VIO_Health_Data := VO_Status[L_i].Health
    );

    IF VO_Manifold_Pumps[L_i] THEN
        L_Delta_T := VI_Manifold_Temps_Supply[L_i] - VI_Manifold_Temps_Return[L_i];

        VO_Status[L_i].Error := FALSE;
        VO_Status[L_i].Error_ID := 0;

        IF VI_Manifold_Currents[L_i] <= 0.01 THEN
            VO_Status[L_i].Error := TRUE;
            VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_NO_CURRENT);
        ELSIF VI_Manifold_Currents[L_i] < 0.3 THEN
            VO_Status[L_i].Error := TRUE;
            VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_UNDERCURRENT);
        ELSIF VI_Manifold_Currents[L_i] > 1.5 THEN
            VO_Status[L_i].Error := TRUE;
            VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_OVERCURRENT);
        END_IF;

        IF (NOT VO_Status[L_i].Error) AND ((VI_Manifold_Pressures[L_i] < 1.5) OR (VI_Manifold_Pressures[L_i] > 2.5)) THEN
            VO_Status[L_i].Error := TRUE;
            VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PRESSURE_OUT_OF_RANGE);
        END_IF;

        IF NOT VO_Status[L_i].Error THEN
            IF L_Delta_T < 5.0 THEN
                VO_Status[L_i].Error := TRUE;
                VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_DELTA_T_LOW);
            ELSIF L_Delta_T > 10.0 THEN
                VO_Status[L_i].Error := TRUE;
                VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_DELTA_T_HIGH);
            END_IF;
        END_IF;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Manifold_Control <<<

// Менеджер управления розетками.
// Обеспечивает работу по сценариям, правилам и аварийное отключение (без локальных выключателей розеток).


IF NOT VI_IsActivePLC THEN RETURN; END_IF;


// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        // Переход в безопасное состояние при потере связи (отключение всех розеток)
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
            VO_Socket_States[L_j] := FALSE;
        END_FOR;
        RETURN;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    L_Rule_Active := FALSE;
    L_Rule_State := FALSE;

    L_Manual_Trig[L_i](CLK := VI_Manual_Override[L_i]);

    // Ручное переключение
    IF L_Manual_Trig[L_i].Q THEN
        L_Internal_State[L_i] := NOT L_Internal_State[L_i];
    END_IF;

    // Проверка правил для текущей розетки
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_SOCKET THEN
                L_Rule_Active := TRUE;
                L_Rule_State := (VI_Rule_Actions[L_j].Value > 0.5);
                L_Internal_State[L_i] := L_Rule_State; // Синхронизация внутреннего состояния
            ELSIF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_TOGGLE_SOCKET AND VI_Rule_Actions[L_j].Triggered THEN
                L_Internal_State[L_i] := NOT L_Internal_State[L_i]; // Toggle
            END_IF;
        END_IF;
    END_FOR;

    // Аварийное отключение
    IF VI_Fire_Alarm OR VI_Flood_Alarm THEN
        // Розетки 1-4 неотключаемые (холодильник, сервер и т.д.)
        IF L_i > 4 THEN
            VO_Socket_States[L_i] := FALSE;
        ELSE
            // Критические розетки сохраняют свое текущее внутреннее состояние, а не форсируются в TRUE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    ELSIF VI_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY OR VI_Security_Armed THEN
        // Master Off
        IF L_i > 4 THEN
            VO_Socket_States[L_i] := FALSE;
        ELSE
            // Неотключаемые розетки могут управляться вручную
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    ELSE
        // Нормальный режим: состояние определяется внутренним состоянием (ручным или правилом)
        IF L_Rule_Active THEN
            VO_Socket_States[L_i] := L_Rule_State;
        ELSE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    END_IF;
END_FOR;

VO_Internal_States := L_Internal_State;

// >>> BULK_SYNC_ANCHOR: FB_Socket_Manager <<<

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

// Reset outputs
VO_Smoke_Detected := FALSE;
VO_Gas_Detected := FALSE;
VO_CO_Warning_Level := FALSE;
VO_CO_Alarm_Level := FALSE;
VO_Status_Msg := 'ОК';

// --- Methane ---
L_Methane_Max := 0.0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    IF VI_Methane_LEL[L_i] > L_Methane_Max THEN
        L_Methane_Max := VI_Methane_LEL[L_i];
    END_IF;
END_FOR;

IF L_Methane_Max >= 20.0 THEN
    VO_Gas_Detected := TRUE;
END_IF;

// --- CO ---
L_CO_Max := 0.0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_CO_SENSORS DO
    IF VI_CO_PPM[L_i] > L_CO_Max THEN
        L_CO_Max := VI_CO_PPM[L_i];
    END_IF;
END_FOR;

L_CO_Level_30 := (L_CO_Max >= 30.0);
L_CO_Level_70 := (L_CO_Max >= 70.0);
L_CO_Level_400 := (L_CO_Max >= 400.0);

L_CO_Timer_30ppm(IN := L_CO_Level_30, PT := T#8h, VI_System_Time_MS := VI_System_Time_MS);
L_CO_Timer_70ppm(IN := L_CO_Level_70, PT := T#1h, VI_System_Time_MS := VI_System_Time_MS);
L_CO_Timer_400ppm(IN := L_CO_Level_400, PT := T#15m, VI_System_Time_MS := VI_System_Time_MS);

IF L_CO_Timer_30ppm.Q THEN
    VO_CO_Warning_Level := TRUE;
END_IF;

IF L_CO_Timer_70ppm.Q OR L_CO_Timer_400ppm.Q THEN
    VO_CO_Alarm_Level := TRUE;
END_IF;

// --- Smoke ---
L_Smoke_Count := 0;
L_Smoke_Active := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SMOKE_SENSORS DO
    L_Smoke_Timer[L_i](IN := VI_Smoke_Sensors[L_i], PT := T#30s, VI_System_Time_MS := VI_System_Time_MS);

    IF VI_Smoke_Sensors[L_i] THEN
        L_Smoke_Count := L_Smoke_Count + 1;
    END_IF;

    IF L_Smoke_Timer[L_i].Q OR (L_Smoke_Count >= 2) THEN
        L_Smoke_Active := TRUE;
    END_IF;
END_FOR;

IF L_Smoke_Active THEN
    VO_Smoke_Detected := TRUE;
END_IF;

// Status
IF VO_Smoke_Detected THEN
    VO_Status_Msg := 'ПОЖАР';
ELSIF VO_Gas_Detected THEN
    VO_Status_Msg := 'УТЕЧКА ГАЗА';
ELSIF VO_CO_Alarm_Level THEN
    VO_Status_Msg := 'КРИТИЧЕСКИЙ CO';
ELSIF VO_CO_Warning_Level THEN
    VO_Status_Msg := 'ПОВЫШЕННЫЙ CO';
ELSE
    VO_Status_Msg := 'ОК';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Gas_Smoke_Manager <<<

// 1. Error checking and scaling based on sensor type
VO_Error := FALSE;
VO_Diag_Code := 0;

CASE VI_Sensor_Type OF
    0: // 4-20mA (NAMUR NE43: < 3.6mA or > 21mA)
        IF VI_Raw_Value < GVL_CONSTANTS.C_ANALOG_3_6MA_RAW THEN // < 3.6mA (Open circuit)
            VO_Error := TRUE;
            VO_Diag_Code := 1;
        ELSIF VI_Raw_Value > GVL_CONSTANTS.C_ANALOG_21MA_RAW THEN // > 21mA (Short circuit)
            VO_Error := TRUE;
            VO_Diag_Code := 2;
        ELSE
            // 4mA = 5529, 20mA = 27648
            L_Scaled := VI_Min_Scale + (TO_REAL(VI_Raw_Value - GVL_CONSTANTS.C_ANALOG_4MA_RAW) / TO_REAL(GVL_CONSTANTS.C_ANALOG_RAW_MAX - GVL_CONSTANTS.C_ANALOG_4MA_RAW)) * (VI_Max_Scale - VI_Min_Scale);
        END_IF;

    1: // 0-10V (0-27648)
        IF VI_Raw_Value > GVL_CONSTANTS.C_ANALOG_10V_MAX_RAW THEN // Out of range
            VO_Error := TRUE;
            VO_Diag_Code := 3;
        ELSE
            L_Scaled := VI_Min_Scale + (TO_REAL(VI_Raw_Value) / TO_REAL(GVL_CONSTANTS.C_ANALOG_RAW_MAX)) * (VI_Max_Scale - VI_Min_Scale);
        END_IF;

    2: // PT100/1000 (Direct temperature * 10, e.g., 255 = 25.5C)
        // Typically, 16-bit signed integer for temperature
        IF VI_Raw_Value = 16#7FFF OR VI_Raw_Value = 16#8000 THEN // Sensor error codes
            VO_Error := TRUE;
            VO_Diag_Code := 1;
        ELSE
            L_Scaled := TO_REAL(TO_INT(VI_Raw_Value)) / 10.0;
            IF L_Scaled < VI_Min_Scale OR L_Scaled > VI_Max_Scale THEN
                VO_Error := TRUE;
                VO_Diag_Code := 3;
            END_IF;
        END_IF;

    ELSE
        VO_Error := TRUE;
        VO_Diag_Code := 16#FFFF; // Unknown sensor type
END_CASE;

// 2. Fallback handling
IF VO_Error THEN
    IF VI_Fallback_Mode = 1 THEN
        VO_Value := VI_Default_Value;
    END_IF;
    // If VI_Fallback_Mode = 0, VO_Value retains its last good value (L_Filtered)
    RETURN;
END_IF;

// 3. Calibration
L_Scaled := (L_Scaled * VI_Multiplier) + VI_Offset;

// 4. Moving Average Filter (ТЗ 1.2)
IF L_First_Scan THEN
    L_Filtered := L_Scaled;
    L_First_Scan := FALSE;
    L_Last_Time := VI_System_Time_MS;

    // Инициализация массива истории
    FOR L_i := 0 TO 9 DO
        L_History[L_i] := L_Scaled;
    END_FOR;
    L_History_Sum := L_Scaled * 10.0;
    L_History_Count := 10;
    L_History_Idx := 0;
END_IF;

L_DT := (SEL(VI_System_Time_MS >= L_Last_Time, VI_System_Time_MS - L_Last_Time, (4294967295 - L_Last_Time) + VI_System_Time_MS + 1));
IF VI_Filter_Time_MS = 0 THEN
    L_Filtered := L_Scaled;
    L_Last_Time := VI_System_Time_MS;
ELSIF L_DT >= (VI_Filter_Time_MS / 10) THEN // Обновляем 10 раз за время фильтрации
    // Вычитаем старое значение
    L_History_Sum := L_History_Sum - L_History[L_History_Idx];

    // Добавляем новое значение
    L_History[L_History_Idx] := L_Scaled;
    L_History_Sum := L_History_Sum + L_Scaled;

    // Сдвигаем индекс
    L_History_Idx := (L_History_Idx + 1) MOD 10;

    // Вычисляем среднее
    L_Filtered := L_History_Sum / 10.0;

    L_Last_Time := VI_System_Time_MS;
END_IF;

VO_Value := L_Filtered;

// Вспомогательная функция для безопасного вычисления разницы времени
L_Elapsed_Time := (VI_System_Time - L_Last_Pulse_Time);

// 1. Мониторинг "сердцебиения" и расчет сетевых задержек (ТЗ 8.4)
IF VI_Remote_Pulse <> L_Last_Pulse THEN
    // Вычисляем время между изменениями сигнала
    VO_RTT_MS := L_Elapsed_Time;
    // Фиксируем пиковые задержки для диагностики сети
    IF VO_RTT_MS > VO_Max_RTT THEN VO_Max_RTT := VO_RTT_MS; END_IF;
    L_Last_Pulse := VI_Remote_Pulse;
    L_Last_Pulse_Time := VI_System_Time;
    L_Elapsed_Time := 0; // Сбрасываем после обновления
END_IF;

// Подсчет статистики потерь связи (ТЗ 8.4)
IF L_Elapsed_Time > L_Timeout THEN
    IF (VI_System_Time - L_Last_Loss_Time) >= 1000 THEN
        VO_Loss_Count := VO_Loss_Count + 1;
        L_Last_Loss_Time := VI_System_Time;
    END_IF;
ELSE
    L_Last_Loss_Time := VI_System_Time;
END_IF;

// 2. Логика определения роли (Active/Standby) и предотвращение Split-Brain (ТЗ 8.3)
// Уровень 1: Проверка наличия связи с партнером
IF L_Elapsed_Time < L_Timeout THEN
    // Связь есть: Договариваемся о ролях на основе приоритета ID
    IF VI_Local_ID = 1 THEN
        VO_Is_Active := TRUE; // ПЛК А всегда активен при наличии связи
    ELSE
        VO_Is_Active := NOT VI_Remote_Is_Active; // ПЛК B активен только если А не активен
    END_IF;
ELSE
    // Связи нет: Пытаемся определить, кто из нас "живее"
    // Уровень 3: Если связи с партнером нет, проверяем доступность внешнего шлюза
    IF VI_Local_ID = 1 THEN
        // ПЛК А становится активным всегда при потере связи с партнером (fallback)
        VO_Is_Active := TRUE;
    ELSE
        // ПЛК B ждет таймаут удержания роли (2 секунды), прежде чем стать активным
        IF L_Elapsed_Time >= 2000 THEN
            // ПЛК B берет управление если он видит шлюз, а связи с А нет.
            // Если шлюз недоступен, B ждет дольше (fallback).
            IF VI_Gateway_Ping_OK THEN
                VO_Is_Active := TRUE;
            ELSIF L_Elapsed_Time >= 5000 THEN
                VO_Is_Active := TRUE; // Fallback: ПЛК А мертв и шлюз мертв
            ELSE
                VO_Is_Active := FALSE;
            END_IF;
        ELSE
            VO_Is_Active := FALSE;
        END_IF;
    END_IF;
END_IF;

// ==============================================================================
// Ownership note
// ------------------------------------------------------------------------------
// This block owns predictive preheat decision only.
// It does NOT modify thermal demand. Thermal demand is owned by
// FB_Heating_Thermal_Model and may be interpreted by downstream advisory layers.
// ==============================================================================

L_Now_TOD := GVL_TIME_SERVICE.G_Time_Of_Day_MS;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    L_Time_To_Heat := GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i];
    L_Time_To_Comfort := GVL_HEATING_POLICY.G_Zone_Comfort_Time_MS[L_i];

    // Predictive preheat decision.
    IF GVL_HEATING_POLICY.G_Zone_Schedule_Enabled[L_i] THEN

        IF L_Time_To_Comfort > L_Now_TOD THEN
            IF (L_Time_To_Comfort - L_Now_TOD) <= L_Time_To_Heat THEN
                GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := TRUE;
            ELSE
                GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := FALSE;
            END_IF;
        END_IF;

    END_IF;

    // Confidence gating.
    IF GVL_HEATING_POLICY.G_Zone_Thermal_Model_Confidence[L_i] < 0.1 THEN
        GVL_HEATING_POLICY.G_Zone_Preheat_Needed[L_i] := FALSE;
    END_IF;

END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    GVL_HEATING_OUTPUT.DO_Zone_Valves[L_i] := VI_Zone_Valves[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_HEATING_OUTPUT.DO_Manifold_Pumps[L_i] := VI_Manifold_Pumps[L_i];
    GVL_HEATING_OUTPUT.AO_Manifold_Valves[L_i] := REAL_TO_UINT(VI_Manifold_Valves[L_i] * 1000.0);
END_FOR;

GVL_HEATING_OUTPUT.DO_DHW_Heating_Pump := VI_DHW_Heating_Pump;
GVL_HEATING_OUTPUT.DO_DHW_Circ_Pump := VI_DHW_Circ_Pump;
GVL_HEATING_OUTPUT.DO_Backup_Circulation_Pump := VI_Backup_Circulation_Pump;
GVL_HEATING_OUTPUT.DO_Electric_Heater_Enable := VI_Electric_Heater_Enable;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Output_Projection <<<

IF (NOT VI_IsActivePLC) THEN
    VO_Sim_Active := FALSE;
    FOR L_i := 1 TO 32 DO
        VO_Sim_Lights[L_i] := FALSE;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
        VO_Sim_Water_Leak[L_i] := FALSE;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
        VO_Sim_Gas_Leak[L_i] := REAL#0.0;
    END_FOR;
    RETURN;
END_IF;

IF (VI_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY) AND VI_Config.Presence_Simulation_Enabled THEN
    VO_Sim_Active := TRUE;

    IF (VI_System_Time_MS - L_Last_Toggle) >= (GVL_CONSTANTS.C_MS_IN_MINUTE * 30) THEN
        L_Last_Toggle := VI_System_Time_MS;
        L_Slot := (VI_System_Time_MS / GVL_CONSTANTS.C_MS_IN_MINUTE) MOD 32;

        FOR L_i := 1 TO 32 DO
            VO_Sim_Lights[L_i] := ((TO_UDINT(L_i) + L_Slot) MOD 5) = 0;
        END_FOR;
    END_IF;
ELSE
    VO_Sim_Active := FALSE;
    FOR L_i := 1 TO 32 DO
        VO_Sim_Lights[L_i] := FALSE;
    END_FOR;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    VO_Sim_Water_Leak[L_i] := FALSE;
END_FOR;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    VO_Sim_Gas_Leak[L_i] := REAL#0.0;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Simulation_Manager <<<

// ==============================================================================
// System health orchestrator helper
//
// Internal helper for PRG_System.
// Owns safety latch update, watchdog, system health aggregation,
// system mode calculation, HMI/fault publication, diagnostic exports,
// and human-readable mode/cause text projection.
// ==============================================================================



fbSafety(
    VI_Gas_Alarm := GVL_STATE.G_Safety_Gas_Alarm,
    VI_Leak_Alarm := GVL_STATE.G_Safety_Leak_Alarm,
    VI_Smoke_Alarm := GVL_STATE.G_Safety_Smoke_Alarm,
    VI_Reset := GVL_COMMAND.G_Reset_Errors,
    VO_Gas_Latched => GVL_STATE.G_Safety_Gas_Latched,
    VO_Leak_Latched => GVL_STATE.G_Safety_Leak_Latched,
    VO_Smoke_Latched => GVL_STATE.G_Safety_Smoke_Latched,
    VO_Emergency_Stop => GVL_STATE.G_Safety_Emergency_Stop
);

GVL_STATE.G_Freeze_Hardware_Degraded := GVL_STATUS.G_Diagnostics.Backup_Pump_Fault OR GVL_STATUS.G_Diagnostics.Electric_Heater_Fault;
GVL_STATE.G_Freeze_Hardware_Failed := GVL_STATUS.G_Diagnostics.Backup_Pump_Fault AND GVL_STATUS.G_Diagnostics.Electric_Heater_Fault;

fbWatchdog(
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

fbSystemHealth(
    VI_Smoke_Detected := GVL_HEALTH_BRIDGE.G_Smoke_Detected OR GVL_STATE.G_Safety_Smoke_Latched,
    VI_Gas_Detected := GVL_HEALTH_BRIDGE.G_Gas_Detected OR GVL_STATE.G_Safety_Gas_Latched,
    VI_CO_Warning_Level := GVL_HEALTH_BRIDGE.G_CO_Warning_Level,
    VI_CO_Alarm_Level := GVL_HEALTH_BRIDGE.G_CO_Alarm_Level,
    VI_Leak_Detected := GVL_HEALTH_BRIDGE.G_Leak_Detected OR GVL_STATE.G_Safety_Leak_Latched,
    VI_Sensor_Fault := GVL_STATE.G_Heating_Sensor_Fault OR GVL_STATE.G_DHW_Sensor_Fault OR GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active,
    VI_IO_Offline := GVL_STATE.G_Heating_IO_Fault OR GVL_STATE.G_DHW_IO_Fault OR GVL_STATE.G_Ventilation_IO_Fault OR GVL_STATE.G_Lighting_IO_Fault,
    VI_Comm_Fault := GVL_STATE.G_Access_Comm_Fault,
    VI_Watchdog_Fault := fbWatchdog.VO_Watchdog_Fault,
    VI_Subsystem_Fault := GVL_STATE.G_Heating_Subsystem_Degraded OR GVL_STATE.G_DHW_Subsystem_Degraded OR GVL_STATE.G_Ventilation_Subsystem_Degraded OR GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active
);

fbStateManager(
    VI_System_Severity := fbSystemHealth.VO_System_Severity,
    VI_Root_Cause := fbSystemHealth.VO_Root_Cause,
    VI_Freeze_Risk := GVL_STATE.G_Safety_Freeze_Risk
);

fbHMIInterface(
    VI_Severity := fbSystemHealth.VO_System_Severity,
    VI_RootCause := fbSystemHealth.VO_Root_Cause,
    VI_Status_Msg := fbStateManager.VO_Status_Msg
);

fbFaultLogger(
    VI_Severity := fbSystemHealth.VO_System_Severity,
    VI_RootCause := fbSystemHealth.VO_Root_Cause,
    VI_Time_MS := GVL_STATUS.G_System_Time_MS
);

GVL_STATUS.G_System_Mode_Msg := fbStateManager.VO_Status_Msg;

GVL_STATUS.G_Diagnostics.Sensor_Fault :=
    GVL_STATE.G_Heating_Sensor_Fault OR
    GVL_STATE.G_DHW_Sensor_Fault OR
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active;

GVL_STATUS.G_Diagnostics.IO_Offline :=
    GVL_STATE.G_Heating_IO_Fault OR
    GVL_STATE.G_DHW_IO_Fault OR
    GVL_STATE.G_Ventilation_IO_Fault OR
    GVL_STATE.G_Lighting_IO_Fault;

GVL_STATUS.G_Diagnostics.Subsystem_Degraded :=
    GVL_STATE.G_Heating_Subsystem_Degraded OR
    GVL_STATE.G_DHW_Subsystem_Degraded OR
    GVL_STATE.G_Ventilation_Subsystem_Degraded OR
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active;

GVL_GATEWAY.G_Gateway_HMI_Status_Message := fbHMIInterface.VO_HMI_Status_Text;
IF fbFaultLogger.VO_Last_Event_Text <> '' THEN
    GVL_HEALTH_BRIDGE.G_Last_Fault_Event_Text := fbFaultLogger.VO_Last_Event_Text;
END_IF;

GVL_STATE.G_System_Mode := fbStateManager.VO_System_Mode;

CASE GVL_STATE.G_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        GVL_STATE.G_System_Mode_Text := 'SAFE_STOP';

    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        GVL_STATE.G_System_Mode_Text := 'FREEZE_PROTECTION';

    E_System_Operating_Mode.MODE_DEGRADED:
        GVL_STATE.G_System_Mode_Text := 'DEGRADED';

    ELSE
        GVL_STATE.G_System_Mode_Text := 'NORMAL';
END_CASE;

CASE fbSystemHealth.VO_Root_Cause OF
    E_System_Root_Cause.ROOT_FIRE:
        GVL_STATUS.G_System_Mode_Cause := 'Пожар/дым';
    E_System_Root_Cause.ROOT_GAS_LEAK:
        GVL_STATUS.G_System_Mode_Cause := 'Утечка газа';
    E_System_Root_Cause.ROOT_CO_CRITICAL:
        GVL_STATUS.G_System_Mode_Cause := 'Критический CO';
    E_System_Root_Cause.ROOT_CO_WARNING:
        GVL_STATUS.G_System_Mode_Cause := 'Повышенный CO';
    E_System_Root_Cause.ROOT_WATER_LEAK:
        GVL_STATUS.G_System_Mode_Cause := 'Протечка воды';
    E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
        GVL_STATUS.G_System_Mode_Cause := 'Ошибка watchdog';
    E_System_Root_Cause.ROOT_IO_OFFLINE:
        GVL_STATUS.G_System_Mode_Cause := 'Недоступен модуль IO';
    E_System_Root_Cause.ROOT_COMM_FAULT:
        GVL_STATUS.G_System_Mode_Cause := 'Ошибка связи';
    E_System_Root_Cause.ROOT_SENSOR_FAULT:
        GVL_STATUS.G_System_Mode_Cause := 'Ошибка датчика';
    E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT:
        GVL_STATUS.G_System_Mode_Cause := 'Ошибка подсистемы';
    ELSE
        GVL_STATUS.G_System_Mode_Cause := 'Аварийные режимы отсутствуют';
END_CASE;

VO_First_Fault_Active := fbSystemHealth.VO_First_Fault_Active;
VO_First_Fault_Type := fbSystemHealth.VO_First_Fault_Type;
VO_First_Fault_Source := fbSystemHealth.VO_First_Fault_Source;
VO_System_Severity := fbSystemHealth.VO_System_Severity;
VO_Root_Cause := fbSystemHealth.VO_Root_Cause;
VO_Watchdog_Fault := fbWatchdog.VO_Watchdog_Fault;

GVL_STATUS.G_System_Mode_Msg := fbStateManager.VO_Status_Msg;

// >>> BULK_SYNC_ANCHOR: FB_System_Health_Orchestrator <<<

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO

    VO_OT_Enable[L_i] := FALSE;
    VO_OT_Setpoint[L_i] := 0.0;
    VO_OT_Command_Valid[L_i] := FALSE;

    L_Command_Enable := FALSE;
    L_Setpoint := 0.0;
    L_Setpoint_x10 := 0;

    // ======================================================
    // COMMAND VALIDATION
    // ======================================================
    IF VI_Enable[L_i] AND VI_OT_Online[L_i] AND NOT VI_OT_Error[L_i] THEN
        L_Command_Enable := TRUE;
        L_Setpoint := LIMIT(20.0, VI_Setpoint[L_i], 80.0);
        L_Setpoint_x10 := REAL_TO_UINT(L_Setpoint * 10.0);

        VO_OT_Enable[L_i] := TRUE;
        VO_OT_Setpoint[L_i] := L_Setpoint;
    END_IF;

    // ======================================================
    // PHYSICAL ADAPTER COMMAND IMAGE
    // ======================================================
    GVL_OPENTHERM_ADAPTER.G_Command[L_i].Enable := L_Command_Enable;
    GVL_OPENTHERM_ADAPTER.G_Command[L_i].Setpoint_x10 := L_Setpoint_x10;

    // Sequence is advanced only when the actual command image changes.
    // This keeps the command stable long enough for adapter ACK validation.
    L_Command_Changed :=
        (L_Command_Enable <> L_Last_Command_Enable[L_i]) OR
        (L_Setpoint_x10 <> L_Last_Command_Setpoint_x10[L_i]);

    IF L_Command_Changed THEN
        GVL_OPENTHERM_ADAPTER.G_Command[L_i].Sequence :=
            GVL_OPENTHERM_ADAPTER.G_Command[L_i].Sequence + 1;

        GVL_OPENTHERM_ADAPTER.G_Command[L_i].Last_Write_MS :=
            GVL_STATUS.G_System_Time_MS;

        L_Last_Command_Enable[L_i] := L_Command_Enable;
        L_Last_Command_Setpoint_x10[L_i] := L_Setpoint_x10;
    END_IF;

    // Command is valid only when the adapter confirms the current stable sequence.
    VO_OT_Command_Valid[L_i] :=
        L_Command_Enable AND
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Ack AND
        (NOT GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Error) AND
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Online;

END_FOR;

L_Cycle_Time_Safe := VI_Cycle_Time_S;
IF L_Cycle_Time_Safe <= REAL#0.0 THEN
    L_Cycle_Time_Safe := REAL#0.01;
END_IF;

VO_Error := VI_SetPoint - VI_ProcessValue;
IF ABS(VO_Error) < VI_Deadband THEN
    VO_Error := REAL#0.0;
END_IF;

IF VI_Reset THEN
    L_Integral_Sum := REAL#0.0;
    L_Prev_Error := REAL#0.0;
    VO_Output := LIMIT(VI_Y_Min, REAL#0.0, VI_Y_Max);
    VO_Limiting := FALSE;
    RETURN;
END_IF;

L_P_Term := VI_Kp * VO_Error;

IF VI_Tv > REAL#0.0 THEN
    L_Derivative := (VO_Error - L_Prev_Error) / L_Cycle_Time_Safe;
    L_D_Term := VI_Kp * VI_Tv * L_Derivative;
ELSE
    L_Derivative := REAL#0.0;
    L_D_Term := REAL#0.0;
END_IF;

IF VI_Manual_Mode THEN
    VO_Output := LIMIT(VI_Y_Min, VI_Manual_Value, VI_Y_Max);
    L_Integral_Sum := VO_Output - L_P_Term - L_D_Term;
    L_Prev_Error := VO_Error;
    VO_Limiting := (VO_Output <= VI_Y_Min) OR (VO_Output >= VI_Y_Max);
    RETURN;
END_IF;

IF VI_Tn > REAL#0.0 THEN
    L_I_Candidate := L_Integral_Sum + ((VI_Kp / VI_Tn) * VO_Error * L_Cycle_Time_Safe);
ELSE
    L_I_Candidate := L_Integral_Sum;
END_IF;

L_Output_Predicted := L_P_Term + L_I_Candidate + L_D_Term;

// Anti-windup: accept the new integral only if it does not push the output farther into saturation.
IF VI_Tn > REAL#0.0 THEN
    IF (L_Output_Predicted > VI_Y_Max) AND (VO_Error > REAL#0.0) THEN
        // hold integral
    ELSIF (L_Output_Predicted < VI_Y_Min) AND (VO_Error < REAL#0.0) THEN
        // hold integral
    ELSE
        L_Integral_Sum := L_I_Candidate;
    END_IF;
END_IF;

L_Output_Raw := L_P_Term + L_Integral_Sum + L_D_Term;
VO_Output := LIMIT(VI_Y_Min, L_Output_Raw, VI_Y_Max);
VO_Limiting := (L_Output_Raw > VI_Y_Max) OR (L_Output_Raw < VI_Y_Min);
L_Prev_Error := VO_Error;

// >>> BULK_SYNC_ANCHOR: FB_PID_Controller <<<

// Сброс выходов по умолчанию
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_Enable[L_i] := FALSE;
    VO_Boiler_Setpoint[L_i] := 0.0;
END_FOR;

// Инициализация ротации
IF NOT L_Rotation_Initialized THEN
    L_Last_Rotation_MS := VI_System_Time_MS;
    L_Rotation_Initialized := TRUE;
END_IF;

// Принудительная остановка
IF VI_Boiler_Stop THEN
    VO_Lead_Boiler := L_Lead_Boiler;
    RETURN;
END_IF;

// Ротация строго каждые 168 часов
IF (VI_System_Time_MS - L_Last_Rotation_MS) >= L_Rotation_Period_MS THEN
    IF GVL_CONSTANTS.C_MAX_BOILERS > 1 THEN
        L_Lead_Boiler := 3 - L_Lead_Boiler;
    END_IF;
    L_Last_Rotation_MS := VI_System_Time_MS;
END_IF;

L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);

L_Lead_Available :=
    VI_Boiler_OT_Online[L_Lead_Boiler] AND
    NOT VI_Boiler_Error_Status[L_Lead_Boiler];

L_Reserve_Available :=
    (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
    VI_Boiler_OT_Online[L_Reserve_Boiler] AND
    NOT VI_Boiler_Error_Status[L_Reserve_Boiler];

// Контроль "команда есть, пламени нет" для ведущего котла
L_Flame_Miss_Timer[L_Lead_Boiler](
    IN := VI_Enable AND L_Lead_Available AND NOT VI_DHW_Heating_Demand AND NOT VI_Boiler_Flame_Status[L_Lead_Boiler],
    PT := T#120s
);

IF L_Flame_Miss_Timer[L_Lead_Boiler].Q AND L_Reserve_Available THEN
    L_Lead_Boiler := L_Reserve_Boiler;
    L_Last_Rotation_MS := VI_System_Time_MS;
    L_Lead_Available :=
        VI_Boiler_OT_Online[L_Lead_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Lead_Boiler];
    L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);
    L_Reserve_Available :=
        (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
        VI_Boiler_OT_Online[L_Reserve_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Reserve_Boiler];
END_IF;

// Нет запроса тепла
IF NOT VI_Enable THEN
    VO_Lead_Boiler := L_Lead_Boiler;
    RETURN;
END_IF;

// Целевая уставка
IF VI_DHW_Heating_Demand THEN
    L_Target_Setpoint := LIMIT(20.0, VI_DHW_Target_Temp + 15.0, 85.0);
ELSE
    L_Target_Setpoint := LIMIT(20.0, VI_Target_Supply_Temp + 5.0, 80.0);
END_IF;

// Выбор ведущего по доступности
IF NOT L_Lead_Available AND L_Reserve_Available THEN
    L_Lead_Boiler := L_Reserve_Boiler;
    L_Lead_Available := TRUE;
    L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);
    L_Reserve_Available :=
        (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
        VI_Boiler_OT_Online[L_Reserve_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Reserve_Boiler];
END_IF;

// Основной котёл
IF L_Lead_Available THEN
    VO_Boiler_Enable[L_Lead_Boiler] := TRUE;
    VO_Boiler_Setpoint[L_Lead_Boiler] := L_Target_Setpoint;
END_IF;

// Резервный котёл: >80% или отказ основного
L_Start_Reserve :=
    L_Reserve_Available AND
    (
        (VI_Demand_Power > 80.0) OR
        (NOT L_Lead_Available)
    );

IF L_Start_Reserve THEN
    VO_Boiler_Enable[L_Reserve_Boiler] := TRUE;
    VO_Boiler_Setpoint[L_Reserve_Boiler] := L_Target_Setpoint;
END_IF;

VO_Lead_Boiler := L_Lead_Boiler;

VO_Ownership_Violation := FALSE;

// Gas: signal present, alarm disappeared
IF (VI_Gas_Level > 20.0) AND L_Last_Gas_Alarm AND (NOT VI_Gas_Alarm) THEN
    VO_Ownership_Violation := TRUE;
END_IF;

// Leak: once latched should not drop instantly
IF L_Last_Leak_Alarm AND (NOT VI_Leak_Alarm) THEN
    VO_Ownership_Violation := TRUE;
END_IF;

// Smoke: same rule
IF L_Last_Smoke_Alarm AND (NOT VI_Smoke_Alarm) THEN
    VO_Ownership_Violation := TRUE;
END_IF;

L_Last_Gas_Alarm := VI_Gas_Alarm;
L_Last_Leak_Alarm := VI_Leak_Alarm;
L_Last_Smoke_Alarm := VI_Smoke_Alarm;

// ==============================================================================
// System scenario arbitration helper
//
// Internal helper for PRG_System.
// Owns scenario request validation, priority resolution, fail-safe clamp,
// degraded-mode adaptation, policy logging, and FB_Scenario_Manager call.
// ==============================================================================



// === SCENARIO REQUEST VALIDATION ===
// Normalize invalid values to NONE to avoid corrupt inputs.
// Actual enum range in E_SCENARIO_TYPE is 0..7.
IF TO_USINT(VIO_Scenario_Req_Operator) > 7 THEN
    VIO_Scenario_Req_Operator := E_SCENARIO_TYPE.SCENARIO_NONE;
END_IF;

IF TO_USINT(VIO_Scenario_Req_Gateway) > 7 THEN
    VIO_Scenario_Req_Gateway := E_SCENARIO_TYPE.SCENARIO_NONE;
END_IF;

IF TO_USINT(VIO_Scenario_Req_Rule) > 7 THEN
    VIO_Scenario_Req_Rule := E_SCENARIO_TYPE.SCENARIO_NONE;
END_IF;

// === SCENARIO PRIORITY RESOLUTION ===
// Produces VIO_Scenario_Req_Final (TRACE ONLY, not executed directly)
IF VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    VIO_Scenario_Req_Final := 0;
    VIO_Scenario_Source := SRC_SAFETY;
ELSIF VIO_Scenario_Req_Operator <> 0 THEN
    VIO_Scenario_Req_Final := VIO_Scenario_Req_Operator;
    VIO_Scenario_Source := SRC_OPERATOR;
ELSIF VIO_Scenario_Req_Gateway <> 0 THEN
    VIO_Scenario_Req_Final := VIO_Scenario_Req_Gateway;
    VIO_Scenario_Source := SRC_GATEWAY;
ELSIF VIO_Scenario_Req_Rule <> 0 THEN
    VIO_Scenario_Req_Final := VIO_Scenario_Req_Rule;
    VIO_Scenario_Source := SRC_RULE;
ELSE
    VIO_Scenario_Req_Final := GVL_STATUS.G_Current_Scenario;
    VIO_Scenario_Source := SRC_NONE;
END_IF;

VIO_Scenario_Intent := VIO_Scenario_Req_Final;

// === FAIL-SAFE SCENARIO CLAMP ===
CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;

    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;

    E_System_Operating_Mode.MODE_DEGRADED:
        CASE VIO_Scenario_Intent OF
            E_SCENARIO_TYPE.SCENARIO_NONE,
            E_SCENARIO_TYPE.SCENARIO_PRESENCE,
            E_SCENARIO_TYPE.SCENARIO_AWAY,
            E_SCENARIO_TYPE.SCENARIO_SLEEP:
                ; // allowed in degraded
        ELSE
            VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        END_CASE;
END_CASE;

// === CONTEXT FAIL-SAFE AUTOMATION ===
// If security is armed and no explicit source is requesting another scenario,
// force safe occupancy context to AWAY while system remains in MODE_NORMAL.
IF VI_System_Mode = E_System_Operating_Mode.MODE_NORMAL THEN
    IF VI_Security_Armed AND
       (VIO_Scenario_Req_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY) THEN

        IF VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY THEN
            VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
            VIO_Scenario_Source := SRC_POLICY;

            fbLogEvent(
                VI_Event_Type := 5,
                VI_Timestamp := VI_System_Time_MS,
                VI_Param1 := TO_UDINT(VIO_Scenario_Source),
                VI_Param2 := TO_UDINT(E_SCENARIO_TYPE.SCENARIO_AWAY)
            );
        END_IF;
    END_IF;
END_IF;

// === DEGRADED-AWARE SCENARIO ADAPTATION ===
// Soft adaptation in degraded mode: keep explicit requests intact,
// but if no source is requesting a scenario, move behavior to a safer baseline.
IF VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
    IF (VIO_Scenario_Req_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (VIO_Scenario_Req_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) THEN

        IF VI_Security_Armed THEN
            IF VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY THEN
                VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
                VIO_Scenario_Source := SRC_POLICY;

                fbLogEvent(
                    VI_Event_Type := 6,
                    VI_Timestamp := VI_System_Time_MS,
                    VI_Param1 := TO_UDINT(VIO_Scenario_Source),
                    VI_Param2 := TO_UDINT(E_SCENARIO_TYPE.SCENARIO_AWAY)
                );
            END_IF;

        ELSIF VIO_Scenario_Intent = E_SCENARIO_TYPE.SCENARIO_PRESENCE THEN
            IF VIO_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_SLEEP THEN
                VIO_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_SLEEP;
                VIO_Scenario_Source := SRC_POLICY;

                fbLogEvent(
                    VI_Event_Type := 7,
                    VI_Timestamp := VI_System_Time_MS,
                    VI_Param1 := TO_UDINT(VIO_Scenario_Source),
                    VI_Param2 := TO_UDINT(E_SCENARIO_TYPE.SCENARIO_SLEEP)
                );
            END_IF;
        END_IF;
    END_IF;
END_IF;

fbScenarioManager(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Activate_Request := VIO_Scenario_Intent,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_System_Mode := VI_System_Mode,
    VO_Current_Scenario => GVL_STATUS.G_Current_Scenario
);

// >>> BULK_SYNC_ANCHOR: FB_System_Scenario_Arbitration <<<

// 1. Генерация собственного пульса (меандр 100 мс)
L_Pulse_Timer(IN := NOT L_Pulse_Timer.Q, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
IF L_Pulse_Timer.Q THEN
    L_Pulse_State := NOT L_Pulse_State;
END_IF;
VO_Local_Pulse := L_Pulse_State;

// 2. Определение роли через Heartbeat
L_Heartbeat(
    VI_Local_ID := VI_Local_PLC_ID,
    VI_System_Time := VI_System_Time_MS,
    VI_Remote_Pulse := VI_Remote_Pulse,
    VI_Remote_Is_Active := VI_Remote_Is_Active,
    VI_Gateway_Ping_OK := VI_Gateway_Ping_OK
);

IF L_Heartbeat.VO_Is_Active THEN
    VO_Local_Role := E_PLC_ROLE.ROLE_ACTIVE;
    VO_Status_Msg := 'ПЛК АКТИВЕН (ВЕДУЩИЙ)';
ELSE
    VO_Local_Role := E_PLC_ROLE.ROLE_STANDBY;
    VO_Status_Msg := 'ПЛК В РЕЗЕРВЕ (ВЕДОМЫЙ)';
END_IF;

// 3. Запрос на синхронизацию при переходе в ACTIVE
IF VO_Local_Role = E_PLC_ROLE.ROLE_ACTIVE AND L_Prev_Role = E_PLC_ROLE.ROLE_STANDBY THEN
    VO_Sync_Data_Req := TRUE;
ELSE
    VO_Sync_Data_Req := FALSE;
END_IF;

L_State_Replicator(
    VI_Local_Role := VO_Local_Role,
    VI_Sync_Req := VO_Sync_Data_Req,
    VI_Local_State := VI_Local_State,
    VI_Remote_State := VI_Remote_State,
    VI_System_Time_MS := VI_System_Time_MS
);
VO_Synced_State := L_State_Replicator.VO_Synced_State;
VO_State_Updated := L_State_Replicator.VO_State_Updated;

L_Prev_Role := VO_Local_Role;
// >>> BULK_SYNC_ANCHOR: FB_Redundancy_Manager <<<

// Отслеживание изменения сигнала
IF VI_Heartbeat_Signal <> L_Last_Heartbeat_State THEN
    L_Last_Heartbeat_Time := VI_System_Time_MS;
    L_Last_Heartbeat_State := VI_Heartbeat_Signal;
END_IF;

// Проверка таймаута
L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Last_Heartbeat_Time, VI_System_Time_MS - L_Last_Heartbeat_Time, (4294967295 - L_Last_Heartbeat_Time) + VI_System_Time_MS + 1));

IF L_Elapsed_Time > VI_Timeout_MS THEN
    VO_Module_Online := FALSE;
    VO_Error_Active := TRUE;
ELSE
    VO_Module_Online := TRUE;
    VO_Error_Active := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_IO_Module_Watchdog <<<

// ==============================================================================
// System evacuation helper
//
// Internal helper for PRG_System.
// Owns evacuation guidance, target/hazard zone name projection,
// and evacuation lighting activation.
// ==============================================================================



FOR L_i := 1 TO 32 DO
    GVL_STATE.G_Evac_Guidance[L_i] := 0;

    IF GVL_STATE.G_Evac_Hazard_Zone[L_i] THEN
        GVL_STATE.G_Evac_Guidance[L_i] := -1;
    END_IF;

    IF GVL_CONFIG.G_Evac_Exit_Zones[L_i] AND NOT GVL_STATE.G_Evac_Hazard_Zone[L_i] THEN
        GVL_STATE.G_Evac_Guidance[L_i] := 1;
    END_IF;
END_FOR;

GVL_STATUS.G_Evac_Target_Zone_Name := '';
GVL_STATUS.G_Evac_Hazard_Zone_Name := '';

FOR L_i := 1 TO 32 DO
    IF (GVL_STATUS.G_Evac_Hazard_Zone_Name = '') AND GVL_STATE.G_Evac_Hazard_Zone[L_i] THEN
        GVL_STATUS.G_Evac_Hazard_Zone_Name := GVL_CONFIG.G_Evac_Zone_Names[L_i];
        IF GVL_STATUS.G_Evac_Hazard_Zone_Name = '' THEN
            GVL_STATUS.G_Evac_Hazard_Zone_Name := CONCAT('Zone ', INT_TO_STRING(L_i));
        END_IF;
    END_IF;

    IF (GVL_STATUS.G_Evac_Target_Zone_Name = '') AND (GVL_STATE.G_Evac_Guidance[L_i] = 1) THEN
        GVL_STATUS.G_Evac_Target_Zone_Name := GVL_CONFIG.G_Evac_Zone_Names[L_i];
        IF GVL_STATUS.G_Evac_Target_Zone_Name = '' THEN
            GVL_STATUS.G_Evac_Target_Zone_Name := CONCAT('Zone ', INT_TO_STRING(L_i));
        END_IF;
    END_IF;
END_FOR;

IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP AND GVL_STATE.G_Safety_Smoke_Latched THEN
    GVL_STATE.G_Evacuation_Lighting_Active := TRUE;
ELSE
    GVL_STATE.G_Evacuation_Lighting_Active := FALSE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Evacuation <<<

// ==============================================================================
// Heating runtime observer phase
// Owns governed observer authorization and finalized-state observer publication.
// Does NOT own heating control or output decisions.
// ==============================================================================



VO_Authorization_Executed := FALSE;
VO_Finalization_Executed := FALSE;
VO_Observer_Valid := FALSE;

// ======================================================
// GOVERNED OBSERVER AUTHORIZATION EVALUATION
// ======================================================
IF VI_Authorization_Stage THEN

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
        E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_PENDING;
    GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
        E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_PENDING;
    GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 10;
    GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
        'Heating runtime observer authorization pending';
    GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Active :=
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Request;

    fbRuntimeObserverAuthorization(
        VI_Enable_Request := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Request,
        VI_Bootstrap_Mode := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Bootstrap_Mode,
        VI_Passive_Mode := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Passive_Mode,
        VI_ReadOnly_Mode := GVL_Heating_Runtime_Observer.G_Runtime_Observer_ReadOnly_Mode,
        VI_Governance_Locked := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Governance_Locked,
        VI_Runtime_Authority_Disabled := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Runtime_Authority_Disabled,
        VI_Writable_Exports_Disabled := GVL_Heating_Runtime_Observer.G_Runtime_Observer_Writable_Exports_Disabled
    );

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Authorized :=
        fbRuntimeObserverAuthorization.VO_Enable_Authorized;

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Effective :=
        fbRuntimeObserverAuthorization.VO_Enable_Effective;

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Authorization_Valid :=
        fbRuntimeObserverAuthorization.VO_Authorization_Valid;

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Authorization_Status_Code :=
        fbRuntimeObserverAuthorization.VO_Status_Code;

    GVL_Heating_Runtime_Observer.G_Runtime_Observer_Authorization_Status_Text :=
        fbRuntimeObserverAuthorization.VO_Status_Text;

    IF NOT GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Request THEN
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
            E_Runtime_Observer_Lifecycle_State.ROS_INACTIVE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
            E_Runtime_Observer_Lifecycle_State.ROS_INACTIVE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 0;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
            'Heating runtime observer inactive';
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Active := FALSE;
    ELSIF NOT GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Effective THEN
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
            E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_DENIED;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
            E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_DENIED;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 20;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
            'Heating runtime observer authorization denied';
    END_IF;

    VO_Authorization_Executed := TRUE;
END_IF;

// ======================================================
// GOVERNED FINALIZED-STATE RUNTIME OBSERVER
// ======================================================
IF VI_Finalization_Stage THEN

    IF GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Effective THEN

        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Rollback_Validated := FALSE;

        IF NOT L_Enable_Last THEN
            L_Activation_Stabilized := FALSE;

            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_STABILIZATION;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_STABILIZATION;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 30;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
                'Heating runtime observer stabilization active';

            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Required := TRUE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Active := TRUE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Complete := FALSE;

            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Publication_Valid := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Stabilization_Complete := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Operational := FALSE;

            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Valid := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Ready := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Fault := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Code := 100;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Text :=
                'Heating runtime observer stabilization cycle active';
        END_IF;

        fbRuntimeObserver(
            VI_Enable := TRUE,
            VI_Runtime_Context := VI_Runtime_Context,
            VI_Diagnostics_Valid := VI_Diagnostics_Valid
        );

        GVL_Heating_Runtime_Observation.G_Runtime_Observation :=
            fbRuntimeObserver.VO_Observation;

        IF L_Activation_Stabilized THEN
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_OPERATIONAL;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_OPERATIONAL;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 40;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
                'Heating runtime observer operational';

            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Required := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Active := FALSE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Complete := TRUE;

            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Publication_Valid := TRUE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Stabilization_Complete := TRUE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Operational := TRUE;

            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Valid := TRUE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Ready :=
                fbRuntimeObserver.VO_Observer_Ready;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Fault :=
                fbRuntimeObserver.VO_Observer_Fault;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Code :=
                fbRuntimeObserver.VO_Status_Code;
            GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Text :=
                fbRuntimeObserver.VO_Status_Text;

            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Activation_Validated := TRUE;
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Sequencing_Validated := TRUE;
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Publication_Validated := TRUE;
            VO_Observer_Valid := TRUE;
        ELSE
            L_Activation_Stabilized := TRUE;
        END_IF;

    ELSE
        L_Activation_Stabilized := FALSE;

        IF L_Enable_Last THEN
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_ROLLBACK;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_ROLLBACK;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 50;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
                'Heating runtime observer rollback cleanup completed';
        ELSIF GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Request THEN
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_DENIED;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_AUTHORIZATION_DENIED;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 20;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
                'Heating runtime observer authorization denied';
        ELSE
            GVL_Heating_Runtime_Observer.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_INACTIVE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_State :=
                E_Runtime_Observer_Lifecycle_State.ROS_INACTIVE;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Code := 0;
            GVL_Heating_Runtime_Observation.G_Runtime_Observer_Lifecycle_Text :=
                'Heating runtime observer inactive';
        END_IF;

        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Required := TRUE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Commissioning_Complete := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Runtime_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Runtime_Ready := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Runtime_Fault := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Current_Phase := E_Heating_Runtime_Phase.HRP_DISABLED;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.DHW_Demand_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.DHW_Heating_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.DHW_Circulation_Active := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Heating_Demand_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Heating_Runtime_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Heating_Output_Active := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Cascade_Available := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Cascade_Degraded := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Cascade_Active_Boilers := 0;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Cascade_Available_Boilers := 0;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.OpenTherm_Online := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.OpenTherm_Command_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.OpenTherm_Transport_Degraded := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Diagnostics_Active := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Explainability_Active := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.DHW_Before_Heating_Observed := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Diagnostics_After_Publication_Observed := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Output_Projection_Last_Observed := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Runtime_Ownership_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Diagnostics_Ownership_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.OpenTherm_Ownership_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Cascade_Ownership_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Safety_Ownership_Valid := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Observation_Status_Code := 0;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation.Observation_Status_Text :=
            'Heating runtime observation inactive';

        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Publication_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Stabilization_Complete := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Operational := FALSE;

        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Valid := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Ready := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observer_Fault := FALSE;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Code := 0;
        GVL_Heating_Runtime_Observation.G_Runtime_Observation_Status_Text :=
            'Heating runtime observation inactive';

        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Activation_Validated := FALSE;
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Sequencing_Validated := FALSE;
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Publication_Validated := FALSE;
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Rollback_Validated := TRUE;
    END_IF;

    L_Enable_Last :=
        GVL_Heating_Runtime_Observer.G_Runtime_Observer_Enable_Effective;

    VO_Finalization_Executed := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Observer_Phase <<<

R_Trig_Start(CLK := VI_Start_Auth);

IF VI_Reset_Success THEN
    VO_State.Is_Success := FALSE;
END_IF;

IF R_Trig_Start.Q AND NOT VO_State.is_pending AND NOT VO_State.Is_Locked THEN
    VO_State.is_pending := TRUE;
    VO_State.Auth_Method := VI_Method;
    L_Start_Time := VI_System_Time_MS;
    VO_State.Attempts_Left := 3;
    VO_State.Is_Success := FALSE;
    VO_State.Is_Locked := FALSE;
    L_Prev_User_Code := '';

    IF VI_Method <> E_TwoFactor_Method.TF_METHOD_TOTP THEN
        // Генерируем одноразовый код через HMAC (без упрощенного алгоритма "по времени")
        L_Time_Step := VI_System_Time_MS / 30000;
        L_Key[0] := 16#31; L_Key[1] := 16#32; L_Key[2] := 16#33; L_Key[3] := 16#34; // Секрет-шаблон, заменяется из конфигурации
        FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step + L_Start_Time, L_i * 8) AND 16#FF); END_FOR;
        fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
        L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
        L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
        L_Generated_Code := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
        WHILE LEN(L_Generated_Code) < 6 DO
            L_Generated_Code := CONCAT('0', L_Generated_Code);
        END_WHILE;

        VO_Code_To_Send := L_Generated_Code;
        VO_Send_Code_Req := TRUE;
    ELSE
        // Для TOTP код не отправляем
        VO_Code_To_Send := '';
        VO_Send_Code_Req := FALSE;
    END_IF;
ELSE
    VO_Send_Code_Req := FALSE;
END_IF;

IF VO_State.is_pending THEN
    L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1));

    IF L_Elapsed_Time < (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.Time_Left_S := TO_UINT(((GVL_CONSTANTS.C_MS_IN_MINUTE * 5) - L_Elapsed_Time) / 1000);
    ELSE
        VO_State.Time_Left_S := 0;
    END_IF;

    IF VI_User_Code <> '' AND VI_User_Code <> L_Prev_User_Code THEN
        L_Code_Valid := FALSE;

        IF VI_Method = E_TwoFactor_Method.TF_METHOD_TOTP THEN
            // Вычисляем TOTP для текущего шага времени (30 секунд)
            L_Time_Step := VI_System_Time_MS / 30000; 

            // Подготовка ключа (в реальном проекте берется из GVL_CONFIG)
            L_Key[0] := 16#31; L_Key[1] := 16#32; L_Key[2] := 16#33; L_Key[3] := 16#34; // '1234'

            // Проверка текущего шага
            FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step, L_i * 8) AND 16#FF); END_FOR;
            fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
            L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
            L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
            L_Current_TOTP := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
            WHILE LEN(L_Current_TOTP) < 6 DO L_Current_TOTP := CONCAT('0', L_Current_TOTP); END_WHILE;

            // Проверка предыдущего шага (для компенсации рассинхронизации)
            FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step - 1, L_i * 8) AND 16#FF); END_FOR;
            fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
            L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
            L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
            L_Prev_TOTP := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
            WHILE LEN(L_Prev_TOTP) < 6 DO L_Prev_TOTP := CONCAT('0', L_Prev_TOTP); END_WHILE;

            IF VI_User_Code = L_Current_TOTP OR VI_User_Code = L_Prev_TOTP THEN
                L_Code_Valid := TRUE;
            END_IF;
        ELSE
            IF VI_User_Code = L_Generated_Code THEN
                L_Code_Valid := TRUE;
            END_IF;
        END_IF;

        IF L_Code_Valid THEN
            VO_State.Is_Success := TRUE;
            VO_State.is_pending := FALSE;
        ELSE
            IF VO_State.Attempts_Left > 0 THEN
                VO_State.Attempts_Left := VO_State.Attempts_Left - 1;
            END_IF;

            IF VO_State.Attempts_Left = 0 THEN
                VO_State.Is_Locked := TRUE;
                VO_State.is_pending := FALSE;
                L_Lockout_Start_Time := VI_System_Time_MS; // Блокировка на 5 минут
            END_IF;
        END_IF;
    END_IF;
    L_Prev_User_Code := VI_User_Code;

    IF L_Elapsed_Time > (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.is_pending := FALSE; // Таймаут
    END_IF;
END_IF;

IF VO_State.Is_Locked THEN
    IF (SEL(VI_System_Time_MS >= L_Lockout_Start_Time, VI_System_Time_MS - L_Lockout_Start_Time, (4294967295 - L_Lockout_Start_Time) + VI_System_Time_MS + 1)) >= (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.Is_Locked := FALSE;
    END_IF;
END_IF;

fbGateway(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Local_PLC_Role := SEL(VI_IsActivePLC, E_PLC_ROLE.ROLE_STANDBY, E_PLC_ROLE.ROLE_ACTIVE),
    VI_Incoming_Command := GVL_GATEWAY.G_Gateway_Command,
    VI_Command_Received := GVL_GATEWAY.G_Gateway_Command_Received,
    VI_FloorHeating_Temps := VIO_FloorHeating_Temps,
    VI_Room_Temps := GVL_STATE.G_Room_Temps,
    VI_Zone_Valve_States := VIO_Zone_Valve_States,
    VI_Manifold_Pressures := GVL_STATE.G_Manifold_Pressures,
    VI_Manifold_Pump_States := GVL_STATE.G_Manifold_Pumps,
    VI_Outdoor_Temp := GVL_STATE.G_Outdoor_Temp,
    VI_Security_Armed := GVL_ALARM.G_Security_Armed,
    VI_Flood_Alarm_Active := GVL_ALARM.G_Flood_Alarm_Active,
    VI_Gas_Alarm_Active := GVL_ALARM.G_Gas_Alarm_Active,
    VI_Fire_Alarm_Active := GVL_ALARM.G_Fire_Alarm_Active,
    VI_Methane_Concentration := GVL_STATE.G_Methane_Sensors[1],
    VI_Lighting_Base_Levels := VIO_Lighting_Base_Levels,
    VI_Socket_States := GVL_STATE.G_Socket_States,
    VI_Blinds_Positions := GVL_STATE.G_Blinds_Positions,
    VI_Active_Scenario := GVL_STATUS.G_Current_Scenario,
    VI_Send_2FA_Req := GVL_COMMAND.G_Send_2FA_Req,
    VI_2FA_Code := GVL_COMMAND.G_2FA_Code_Out,
    VI_Allowed_IPs := GVL_CONFIG.G_Allowed_IPs,
    VO_Telegram_Msg => GVL_GATEWAY.G_Gateway_Telegram_Msg,
    VO_Send_Telegram => GVL_GATEWAY.G_Gateway_Send_Telegram,
    VO_HMI_Status_Message => GVL_GATEWAY.G_Gateway_HMI_Status_Message,
    VO_Data_Ready => GVL_GATEWAY.G_Gateway_Data_Ready,
    VO_Modbus_Registers => GVL_GATEWAY.G_Gateway_Modbus_Registers,
    VO_Arm_Req => GVL_COMMAND.G_Arm_Req,
    VO_Disarm_Req => GVL_COMMAND.G_Disarm_Req,
    VO_PIN_Code => GVL_COMMAND.G_PIN_Code,
    VO_RFID_Tag => GVL_COMMAND.G_RFID_Tag,
    VO_2FA_Code_In => GVL_COMMAND.G_2FA_Code_In,
    VO_Lighting_Override => GVL_COMMAND.G_Lighting_Override,
    VO_Blinds_Override => GVL_COMMAND.G_Blinds_Override,
    VO_Socket_Override => GVL_COMMAND.G_Socket_Override,
    VO_Reset_Errors_Req => GVL_COMMAND.G_Reset_Errors
);

GVL_INTENT_USER.I_Source_Valid := TRUE;
GVL_INTENT_USER.I_Last_Update_MS := VI_System_Time_MS;
GVL_INTENT_USER.I_Arm_Request := GVL_COMMAND.G_Arm_Req;
GVL_INTENT_USER.I_Disarm_Request := GVL_COMMAND.G_Disarm_Req;
GVL_INTENT_USER.I_PIN_Code := GVL_COMMAND.G_PIN_Code;
GVL_INTENT_USER.I_RFID_Tag := GVL_COMMAND.G_RFID_Tag;
GVL_INTENT_USER.I_2FA_Code_In := GVL_COMMAND.G_2FA_Code_In;
GVL_INTENT_USER.I_Lighting_Override_32 := GVL_COMMAND.G_Lighting_Override;
GVL_INTENT_USER.I_Blinds_Override_32 := GVL_COMMAND.G_Blinds_Override;
GVL_INTENT_USER.I_Socket_Override_32 := GVL_COMMAND.G_Socket_Override;
GVL_INTENT_USER.I_Reset_Errors := GVL_COMMAND.G_Reset_Errors;
GVL_INTENT_USER.I_Set_Temp_Req := fbGateway.VO_Set_Temp_Req;
GVL_INTENT_USER.I_Target_Zone := fbGateway.VO_Target_Zone;
GVL_INTENT_USER.I_Target_Temperature := fbGateway.VO_Target_Temp;
GVL_INTENT_USER.I_Set_Vent_Req := fbGateway.VO_Set_Vent_Req;
GVL_INTENT_USER.I_Target_Vent_Speed := fbGateway.VO_Target_Vent_Speed;
GVL_INTENT_USER.I_Set_Config_Req := fbGateway.VO_Set_Config_Req;
GVL_INTENT_USER.I_Time_Sync_Req := fbGateway.VO_Sync_Time_Req;
GVL_INTENT_USER.I_New_Time_MS := fbGateway.VO_New_Time_MS;

// >>> BULK_SYNC_ANCHOR: FB_System_Gateway_Intent <<<

// ==============================================================================
// Heating runtime observer
// Minimal observer-only runtime attachment.
// Read-only.
// Governance-locked.
// Finalized-state observation only.
// ==============================================================================



// ======================================================
// DEFAULTS
// ======================================================
VO_Observation.Runtime_Active := FALSE;
VO_Observation.Runtime_Ready := FALSE;
VO_Observation.Runtime_Fault := FALSE;
VO_Observation.Current_Phase := E_Heating_Runtime_Phase.HRP_DISABLED;

VO_Observation.DHW_Demand_Active := FALSE;
VO_Observation.DHW_Heating_Active := FALSE;
VO_Observation.DHW_Circulation_Active := FALSE;

VO_Observation.Heating_Demand_Active := FALSE;
VO_Observation.Heating_Runtime_Active := FALSE;
VO_Observation.Heating_Output_Active := FALSE;

VO_Observation.Cascade_Available := FALSE;
VO_Observation.Cascade_Degraded := FALSE;
VO_Observation.Cascade_Active_Boilers := 0;
VO_Observation.Cascade_Available_Boilers := 0;

VO_Observation.OpenTherm_Online := FALSE;
VO_Observation.OpenTherm_Command_Valid := FALSE;
VO_Observation.OpenTherm_Transport_Degraded := FALSE;

VO_Observation.Diagnostics_Active := FALSE;
VO_Observation.Explainability_Active := FALSE;

VO_Observation.DHW_Before_Heating_Observed := FALSE;
VO_Observation.Diagnostics_After_Publication_Observed := FALSE;
VO_Observation.Output_Projection_Last_Observed := FALSE;

VO_Observation.Runtime_Ownership_Valid := TRUE;
VO_Observation.Diagnostics_Ownership_Valid := TRUE;
VO_Observation.OpenTherm_Ownership_Valid := TRUE;
VO_Observation.Cascade_Ownership_Valid := TRUE;
VO_Observation.Safety_Ownership_Valid := TRUE;

VO_Observation.Observation_Status_Code := 0;
VO_Observation.Observation_Status_Text := 'Heating runtime observer disabled';

VO_Observer_Ready := FALSE;
VO_Observer_Fault := FALSE;
VO_Status_Code := 0;
VO_Status_Text := 'Heating runtime observer disabled';

IF NOT VI_Enable THEN
    RETURN;
END_IF;

// ======================================================
// FINALIZED-STATE OBSERVATION ONLY
// ======================================================
VO_Observation.Runtime_Active := VI_Runtime_Context.Runtime_Enabled;
VO_Observation.Runtime_Ready := VI_Runtime_Context.Runtime_Ready;
VO_Observation.Runtime_Fault := VI_Runtime_Context.Runtime_Fault;
VO_Observation.Current_Phase := VI_Runtime_Context.Current_Phase;

VO_Observation.Diagnostics_Active := VI_Diagnostics_Valid;
VO_Observation.Explainability_Active := VI_Runtime_Context.Explainability_Isolation_Valid;

VO_Observation.DHW_Before_Heating_Observed :=
    VI_Runtime_Context.DHW_Before_Heating_Valid;

VO_Observation.Diagnostics_After_Publication_Observed :=
    VI_Runtime_Context.State_Publication_Before_Diagnostics_Valid;

VO_Observation.Output_Projection_Last_Observed :=
    VI_Runtime_Context.Output_Projection_Last_Valid;

VO_Observation.Runtime_Ownership_Valid := TRUE;
VO_Observation.Diagnostics_Ownership_Valid :=
    VI_Runtime_Context.Diagnostics_Isolation_Valid;

VO_Observation.OpenTherm_Ownership_Valid :=
    VI_Runtime_Context.OpenTherm_Ownership_Valid;

VO_Observation.Cascade_Ownership_Valid :=
    VI_Runtime_Context.Cascade_Ownership_Valid;

VO_Observation.Safety_Ownership_Valid :=
    VI_Runtime_Context.Safety_Isolation_Valid;

// These domain-specific runtime values remain intentionally FALSE/0 here.
// They must be populated only by finalized publication contracts, not by internal runtime scans.
VO_Observation.DHW_Demand_Active := FALSE;
VO_Observation.DHW_Heating_Active := FALSE;
VO_Observation.DHW_Circulation_Active := FALSE;
VO_Observation.Heating_Demand_Active := FALSE;
VO_Observation.Heating_Runtime_Active := FALSE;
VO_Observation.Heating_Output_Active := FALSE;
VO_Observation.Cascade_Available := FALSE;
VO_Observation.Cascade_Degraded := FALSE;
VO_Observation.Cascade_Active_Boilers := 0;
VO_Observation.Cascade_Available_Boilers := 0;
VO_Observation.OpenTherm_Online := FALSE;
VO_Observation.OpenTherm_Command_Valid := FALSE;
VO_Observation.OpenTherm_Transport_Degraded := FALSE;

// ======================================================
// STATUS
// ======================================================
IF VI_Runtime_Context.Runtime_Fault THEN
    VO_Observation.Observation_Status_Code := 900;
    VO_Observation.Observation_Status_Text := 'Heating runtime observer detected runtime fault';

ELSIF NOT VI_Diagnostics_Valid THEN
    VO_Observation.Observation_Status_Code := 200;
    VO_Observation.Observation_Status_Text := 'Heating runtime diagnostics publication invalid';

ELSE
    VO_Observation.Observation_Status_Code := 1;
    VO_Observation.Observation_Status_Text := 'Heating runtime observer nominal';
END_IF;

VO_Observer_Ready := TRUE;
VO_Observer_Fault := FALSE;

VO_Status_Code := VO_Observation.Observation_Status_Code;
VO_Status_Text := VO_Observation.Observation_Status_Text;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Observer <<<

// ============================================================================== // System alarm orchestrator helper // // Internal helper for PRG_System. // Owns FB_Alarm_Manager call and alarm output projection. // ==============================================================================
fbAlarmManager( VI_System_Time_MS := GVL_STATUS.G_System_Time_MS, VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC, VI_Gas_Alarm := GVL_ALARM.G_Gas_Alarm_Active, VI_Fire_Alarm := GVL_ALARM.G_Fire_Alarm_Active, VI_Flood_Alarm := GVL_ALARM.G_Flood_Alarm_Active, VI_Security_Alarm := GVL_ALARM.G_Security_Alarm, VI_First_Fault_Active := VI_First_Fault_Active, VI_First_Fault_Type := VI_First_Fault_Type, VI_First_Fault_Source := VI_First_Fault_Source, VI_Boiler_Errors := GVL_STATE.G_Boiler_Error, VI_Security_Msg := GVL_STATUS.G_Security_Status_Msg, VI_Acknowledge_All := GVL_CONFIG.G_HMI_Ack_Alarms OR GVL_COMMAND.G_Reset_Errors, VI_Mute_Siren := GVL_CONFIG.G_HMI_Mute_Alarm, VIO_Next_Alarm_ID := GVL_ALARM.G_Next_Alarm_ID, VO_Global_Critical => GVL_ALARM.G_Global_Critical, VO_Global_Warning => GVL_ALARM.G_Global_Warning, VO_Siren_Active => GVL_ALARM.G_Global_Siren, VO_Active_Count => GVL_ALARM.G_Active_Alarm_Count, VO_Unacked_Count => GVL_ALARM.G_Unacked_Alarm_Count, VO_Event_Pulse => GVL_STATUS.G_Diagnostics.Alarm_Event_Pulse, VO_Event_Code => GVL_STATUS.G_Diagnostics.Alarm_Event_Code, VO_Event_Value => GVL_STATUS.G_Diagnostics.Alarm_Event_Value, VO_Alarm_List => GVL_ALARM.G_Alarm_List );
// >>> BULK_SYNC_ANCHOR: FB_System_Alarm_Orchestrator <<<

IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

L_Requested_Scenario := VI_Activate_Request;

CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP,
    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        IF VO_Current_Scenario <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
            VO_Current_Scenario := E_SCENARIO_TYPE.SCENARIO_NONE;
            VO_Status_Msg := 'Сценарии принудительно отключены режимом безопасности';
        END_IF;
        RETURN;

    E_System_Operating_Mode.MODE_DEGRADED:
        CASE L_Requested_Scenario OF
            E_SCENARIO_TYPE.SCENARIO_NONE,
            E_SCENARIO_TYPE.SCENARIO_AWAY,
            E_SCENARIO_TYPE.SCENARIO_SLEEP,
            E_SCENARIO_TYPE.SCENARIO_PRESENCE:
                VO_Status_Msg := 'Сценарии работают в ограниченном degraded-режиме';
        ELSE
                L_Requested_Scenario := E_SCENARIO_TYPE.SCENARIO_NONE;
                VO_Status_Msg := 'Небезопасный сценарий заблокирован degraded-режимом';
        END_CASE;
ELSE
        // Normal mode: no additional clamp required.
END_CASE;

IF L_Requested_Scenario <> VO_Current_Scenario THEN
    // Проверка минимального времени работы сценария
    IF (VI_System_Time_MS - L_Last_Scenario_Time) >= 60000 OR VO_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_NONE THEN
        // Логика переключения сценариев
        VO_Current_Scenario := L_Requested_Scenario;
        L_Last_Scenario_Time := VI_System_Time_MS;

        CASE VO_Current_Scenario OF
        E_SCENARIO_TYPE.SCENARIO_NONE:
            VO_Status_Msg := 'Сценарии отключены';
        E_SCENARIO_TYPE.SCENARIO_AWAY:
            VO_Status_Msg := 'Активирован сценарий: Вне дома (Охрана + Энергосбережение)';
        E_SCENARIO_TYPE.SCENARIO_SLEEP:
            VO_Status_Msg := 'Активирован сценарий: Сон (Ночное освещение + Климат)';
        E_SCENARIO_TYPE.SCENARIO_PRESENCE:
            VO_Status_Msg := 'Активирован сценарий: Имитация присутствия';
        ELSE
            VO_Status_Msg := 'Активирован сценарий';
        END_CASE;
    END_IF;
END_IF;

// --- PREHEAT SCENARIO INSERT ---
IF VI_Preheat_Request THEN
    // removed: direct heating write (moved to Heating Manager)
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Scenario_Manager <<<

// ==============================================================================
// Adaptive target calculation for heating supply temperature
// ==============================================================================



VO_Target_Supply_Temp := VI_Base_Target_Supply_Temp;
VO_Adaptive_Max_Delta := 0.0;
L_Adaptive_Weighted_Sum := 0.0;
L_Adaptive_Weight_Total := 0.0;
VO_Adaptive_Effective_Delta := 0.0;
VO_Adaptive_Correction := 0.0;

IF VI_Global_Target_Temperature > 0.0 THEN
    VO_Target_Supply_Temp := VI_Global_Target_Temperature;
END_IF;

FOR L_Adaptive_Zone_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    L_Zone_Index := VI_Zone_Configs[L_Adaptive_Zone_i].zone;

    IF (L_Zone_Index >= 1) AND (L_Zone_Index <= GVL_CONSTANTS.C_MAX_ZONES) THEN
        CASE VI_Zone_Configs[L_Adaptive_Zone_i].control_type OF
            0:
                L_Adaptive_Delta :=
                    VI_Zone_Configs[L_Adaptive_Zone_i].design_temp -
                    VI_Floor_Temps[L_Adaptive_Zone_i];
                L_Adaptive_Weight := 0.6;
            1, 2:
                L_Adaptive_Delta :=
                    VI_Zone_Configs[L_Adaptive_Zone_i].design_temp -
                    VI_Room_Temps[L_Zone_Index];
                L_Adaptive_Weight := 1.0;
            ELSE
                L_Adaptive_Delta :=
                    VI_Zone_Configs[L_Adaptive_Zone_i].design_temp -
                    VI_Room_Temps[L_Zone_Index];
                L_Adaptive_Weight := 0.8;
        END_CASE;

        IF L_Zone_Index <= 4 THEN
            L_Adaptive_Weight := L_Adaptive_Weight * 1.2;
        ELSIF L_Zone_Index >= 9 THEN
            L_Adaptive_Weight := L_Adaptive_Weight * 0.7;
        END_IF;

        IF L_Adaptive_Weight > 2.0 THEN
            L_Adaptive_Weight := 2.0;
        ELSIF L_Adaptive_Weight < 0.2 THEN
            L_Adaptive_Weight := 0.2;
        END_IF;

        IF L_Adaptive_Delta > VO_Adaptive_Max_Delta THEN
            VO_Adaptive_Max_Delta := L_Adaptive_Delta;
        END_IF;

        L_Adaptive_Weighted_Sum := L_Adaptive_Weighted_Sum + (L_Adaptive_Delta * L_Adaptive_Weight);
        L_Adaptive_Weight_Total := L_Adaptive_Weight_Total + L_Adaptive_Weight;
    END_IF;
END_FOR;

IF L_Adaptive_Weight_Total > 0.0 THEN
    VO_Adaptive_Effective_Delta := L_Adaptive_Weighted_Sum / L_Adaptive_Weight_Total;
END_IF;

IF VO_Adaptive_Effective_Delta > 1.5 THEN
    VO_Adaptive_Correction := 2.0;
ELSIF VO_Adaptive_Effective_Delta > 0.7 THEN
    VO_Adaptive_Correction := 1.0;
ELSIF VO_Adaptive_Effective_Delta < -1.5 THEN
    VO_Adaptive_Correction := -2.0;
ELSIF VO_Adaptive_Effective_Delta < -0.7 THEN
    VO_Adaptive_Correction := -1.0;
ELSE
    VO_Adaptive_Correction := 0.0;
END_IF;

IF VO_Adaptive_Max_Delta > 2.5 AND VO_Adaptive_Correction < 2.0 THEN
    VO_Adaptive_Correction := 2.0;
END_IF;

VO_Target_Supply_Temp := VO_Target_Supply_Temp + VO_Adaptive_Correction;

IF VO_Target_Supply_Temp < 20.0 THEN
    VO_Target_Supply_Temp := 20.0;
ELSIF VO_Target_Supply_Temp > 45.0 THEN
    VO_Target_Supply_Temp := 45.0;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Adaptive_Target <<<

// ==============================================================================
// Heating circuit control helper
//
// Internal refactoring helper for FB_Heating_System_Manager.
// Owns per-circuit sensor validation, temperature source fallback,
// floor-heating controller call, overheat shutdown, and rule action projection.
// ==============================================================================



VO_Heating_Sensor_Fault := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    fbFloorTempValidator[L_i](
        VI_Value := VI_Floor_Temps[L_i],
        VI_Min_Valid := -40.0,
        VI_Max_Valid := 120.0,
        VI_Fallback_Mode := 0
    );

    L_Climate_Zone_ID := VI_Zone_Configs[L_i].zone;
    IF L_Climate_Zone_ID >= 1 AND L_Climate_Zone_ID <= 16 THEN
        fbRoomTempValidator[L_Climate_Zone_ID](
            VI_Value := VI_Room_Temps[L_Climate_Zone_ID],
            VI_Min_Valid := -40.0,
            VI_Max_Valid := 120.0,
            VI_Fallback_Mode := 0
        );
    END_IF;

    // Floor overheat protection
    L_Overheat_Timer[L_i](
        IN := fbFloorTempValidator[L_i].VO_Value > VI_Config.Overheat_Threshold,
        PT := T#60s,
        VI_System_Time_MS := VI_System_Time_MS
    );

    L_Current_Temp := 0.0;
    L_Sensor_Error := FALSE;

    IF VI_Zone_Configs[L_i].control_type = 1 OR VI_Zone_Configs[L_i].control_type = 2 THEN
        // Primary: room air temperature
        IF (L_Climate_Zone_ID >= 1) AND (L_Climate_Zone_ID <= 16) AND (NOT fbRoomTempValidator[L_Climate_Zone_ID].VO_Error) THEN
            L_Current_Temp := fbRoomTempValidator[L_Climate_Zone_ID].VO_Value;
        ELSIF NOT fbFloorTempValidator[L_i].VO_Error THEN
            L_Current_Temp := fbFloorTempValidator[L_i].VO_Value;
        ELSE
            L_Sensor_Error := TRUE;
        END_IF;
    ELSE
        // Primary: floor temperature
        IF NOT fbFloorTempValidator[L_i].VO_Error THEN
            L_Current_Temp := fbFloorTempValidator[L_i].VO_Value;
        ELSIF (L_Climate_Zone_ID >= 1) AND (L_Climate_Zone_ID <= 16) AND (NOT fbRoomTempValidator[L_Climate_Zone_ID].VO_Error) THEN
            L_Current_Temp := fbRoomTempValidator[L_Climate_Zone_ID].VO_Value;
        ELSE
            L_Sensor_Error := TRUE;
        END_IF;
    END_IF;

    IF L_Sensor_Error THEN
        VO_Heating_Sensor_Fault := TRUE;
        VO_Zone_Valves[L_i] := FALSE;
    ELSE
        L_Zone_Config := VI_Zone_Configs[L_i];
        L_Zone_Config.design_temp := L_Zone_Config.design_temp + VI_Scenario_Adjust;

        L_Floor_Controllers[L_i](
            VI_Current_Temp := L_Current_Temp,
            VI_Config := L_Zone_Config,
            VI_Tariff := VI_Tariff,
            VI_Current_Hour := VI_Current_Hour,
            VI_IsActivePLC := VI_IsActivePLC,
            VI_System_Time_MS := VI_System_Time_MS,
            VO_Valve_Bool => VO_Zone_Valves[L_i]
        );
    END_IF;

    IF L_Overheat_Timer[L_i].Q THEN
        VO_Zone_Valves[L_i] := FALSE;
    END_IF;

    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_FLOOR_HEATING THEN
                VO_Zone_Valves[L_i] := (VI_Rule_Actions[L_j].Value > 0.5);
            END_IF;
        END_IF;
    END_FOR;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Circuit_Control <<<

IF NOT VI_IsActivePLC THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        VO_Actions[L_i].Active := FALSE;
        VO_Actions[L_i].Triggered := FALSE;
        VO_Actions[L_i].Action_Type := E_Rule_Action_Type.ACTION_NONE;
        VO_Actions[L_i].Target_ID := 0;
        VO_Actions[L_i].Value := 0.0;
    END_FOR;
    VO_Preheat_Request := FALSE;
    RETURN;
END_IF;

VO_Preheat_Request := FALSE;

L_Elapsed_Time := SEL(VI_System_Time_MS >= L_Last_Reset_Time, VI_System_Time_MS - L_Last_Reset_Time, (4294967295 - L_Last_Reset_Time) + VI_System_Time_MS + 1);

IF L_Elapsed_Time >= GVL_CONSTANTS.C_MS_IN_MINUTE THEN
    L_Last_Reset_Time := VI_System_Time_MS;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        L_Trigger_Count[L_i] := 0;
    END_FOR;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO

    // Full per-cycle action reset prevents stale Triggered/Action_Type/Target_ID/Value
    // from being observed by any downstream consumer when a rule is disabled or inactive.
    VO_Actions[L_i].Active := FALSE;
    VO_Actions[L_i].Triggered := FALSE;
    VO_Actions[L_i].Action_Type := E_Rule_Action_Type.ACTION_NONE;
    VO_Actions[L_i].Target_ID := 0;
    VO_Actions[L_i].Value := 0.0;

    IF VI_Rules[L_i].Enabled THEN
        L_Condition_Met := FALSE;
        L_Current_Value := 0.0;

        IF VI_Rules[L_i].Condition_Target_ID > 0 THEN
            CASE VI_Rules[L_i].Condition_Type OF
                E_Rule_Condition_Type.COND_AIR_TEMP: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := VI_Indoor_Temps[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_FLOOR_TEMP: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS THEN L_Current_Value := VI_Floor_Temps[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_HUMIDITY: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := VI_Humidities[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_CO2: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := VI_CO2_Levels[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_MOTION: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := SEL(VI_Motion_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_DOOR_WINDOW: 
                    IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_DOOR_SENSORS THEN
                        L_Current_Value := SEL(VI_Door_Sensors[VI_Rules[L_i].Condition_Target_ID] OR VI_Window_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    ELSIF VI_Rules[L_i].Condition_Target_ID <= 16 THEN
                        L_Current_Value := SEL(VI_Window_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    END_IF;
                E_Rule_Condition_Type.COND_FLOOD: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_FLOOD_SENSORS THEN L_Current_Value := SEL(VI_Water_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_SMOKE: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_SMOKE_SENSORS THEN L_Current_Value := SEL(VI_Smoke_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_METHANE: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_METHANE_SENSORS THEN L_Current_Value := VI_Methane_Sensors[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_CO: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_CO_SENSORS THEN L_Current_Value := VI_CO_Sensors[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_TIME_OF_DAY: L_Current_Value := TO_REAL(TOD_TO_UDINT(VI_Current_Time) / GVL_CONSTANTS.C_MS_IN_MINUTE);
                E_Rule_Condition_Type.COND_DAY_OF_WEEK: L_Current_Value := TO_REAL(VI_Day_Of_Week);
            END_CASE;
        ELSE
            IF VI_Rules[L_i].Condition_Type = E_Rule_Condition_Type.COND_TIME_OF_DAY THEN
                L_Current_Value := TO_REAL(TOD_TO_UDINT(VI_Current_Time) / GVL_CONSTANTS.C_MS_IN_MINUTE);
            ELSIF VI_Rules[L_i].Condition_Type = E_Rule_Condition_Type.COND_DAY_OF_WEEK THEN
                L_Current_Value := TO_REAL(VI_Day_Of_Week);
            END_IF;
        END_IF;

        CASE VI_Rules[L_i].Condition_Op OF
            E_Rule_Comparison.COMP_GT: L_Condition_Met := (L_Current_Value > VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_LT: L_Condition_Met := (L_Current_Value < VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_EQ: L_Condition_Met := (ABS(L_Current_Value - VI_Rules[L_i].Condition_Value) < 0.1);
            E_Rule_Comparison.COMP_GE: L_Condition_Met := (L_Current_Value >= VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_LE: L_Condition_Met := (L_Current_Value <= VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_IN_RANGE: L_Condition_Met := (L_Current_Value >= VI_Rules[L_i].Condition_Value) AND (L_Current_Value <= VI_Rules[L_i].Condition_Value_Max);
            E_Rule_Comparison.COMP_TRUE: L_Condition_Met := (L_Current_Value > 0.5);
            E_Rule_Comparison.COMP_FALSE: L_Condition_Met := (L_Current_Value < 0.5);
        END_CASE;

        L_Triggers[L_i](CLK := L_Condition_Met);

        IF L_Triggers[L_i].Q THEN
            L_Trigger_Count[L_i] := L_Trigger_Count[L_i] + 1;
            IF L_Trigger_Count[L_i] > 10 THEN
                CONTINUE;
            END_IF;
        END_IF;

        IF L_Condition_Met AND (L_Trigger_Count[L_i] <= 10) THEN
            VO_Actions[L_i].Active := TRUE;
            VO_Actions[L_i].Triggered := L_Triggers[L_i].Q;
            VO_Actions[L_i].Action_Type := VI_Rules[L_i].Action_Type;
            VO_Actions[L_i].Target_ID := VI_Rules[L_i].Action_Target_ID;
            VO_Actions[L_i].Value := VI_Rules[L_i].Action_Value;
        END_IF;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Rule_Engine <<<

IF VI_Count > 0 AND VI_Count <= GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS THEN
    VO_Max := VI_Data[1];
    VO_Min := VI_Data[1];
    L_Sum := 0.0;

    FOR L_i := 1 TO VI_Count DO
        IF VI_Data[L_i] > VO_Max THEN VO_Max := VI_Data[L_i]; END_IF;
        IF VI_Data[L_i] < VO_Min THEN VO_Min := VI_Data[L_i]; END_IF;
        L_Sum := L_Sum + VI_Data[L_i];
    END_FOR;

    VO_Average := L_Sum / INT_TO_REAL(VI_Count);

    IF VI_Count >= 2 THEN
        VO_Trend_Up := (VI_Data[VI_Count] > VI_Data[1]);
        VO_Trend_Down := (VI_Data[VI_Count] < VI_Data[1]);
    END_IF;
END_IF;

L_Outdoor := GVL_STATE.G_Outdoor_Temp;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    L_DeltaT := GVL_STATE.G_Room_Temps[L_i] - L_Outdoor;

    L_Loss := L_DeltaT * REAL#0.01 * GVL_HEATING_POLICY.G_Zone_Thermal_Inertia[L_i];

    L_Gain := (GVL_STATE.G_Floor_Temps[L_i] - GVL_STATE.G_Room_Temps[L_i]) * REAL#0.05;

    GVL_HEATING_POLICY.G_Zone_Heat_Loss_Rate[L_i] := L_Loss;
    GVL_HEATING_POLICY.G_Zone_Heat_Gain_Rate[L_i] := L_Gain;

    GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i] := L_Gain - L_Loss;

    GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] := 
        GVL_STATE.G_Target_Temperature - GVL_STATE.G_Room_Temps[L_i];

    IF ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i]) > REAL#0.01 THEN
        GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := 
            REAL_TO_UDINT(ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] /
                  GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i]) * REAL#60000.0);
    ELSE
        GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] := 0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Predicted_Temp_30m[L_i] :=
        GVL_STATE.G_Room_Temps[L_i] + 
        GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i] * REAL#30.0;

    GVL_HEATING_POLICY.G_Zone_Thermal_Model_Confidence[L_i] :=
        LIMIT(REAL#0.0, REAL#1.0, ABS(GVL_HEATING_POLICY.G_Zone_Thermal_Response[L_i]));

END_FOR;

// ==============================================================================
// Heating root-cause inference engine
// Internal diagnostics core.
// Does NOT own explainability publication or runtime control.
// ==============================================================================



// ======================================================
// DEFAULTS
// ======================================================
VO_RootCause := E_Heating_RootCause.RC_NONE;
VO_Confidence := 1.0;
VO_Error_Score := 0.0;
VO_Reason_Code := 0;
VO_Reason_Text := 'Heating inference OK';

// ======================================================
// SAFETY / GLOBAL BLOCKS
// ======================================================
IF VI_Emergency_Stop THEN
    VO_RootCause := E_Heating_RootCause.RC_EMERGENCY_STOP;
    VO_Confidence := 1.0;
    VO_Error_Score := 1.0;
    VO_Reason_Code := 10;
    VO_Reason_Text := 'Emergency stop active';
    RETURN;
END_IF;

IF VI_Gas_Safety THEN
    VO_RootCause := E_Heating_RootCause.RC_GAS_SAFETY;
    VO_Confidence := 1.0;
    VO_Error_Score := 1.0;
    VO_Reason_Code := 20;
    VO_Reason_Text := 'Gas safety active';
    RETURN;
END_IF;

IF VI_IO_Failsafe THEN
    VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
    VO_Confidence := 1.0;
    VO_Error_Score := 1.0;
    VO_Reason_Code := 30;
    VO_Reason_Text := 'Heating IO failsafe active';
    RETURN;
END_IF;

// ======================================================
// AGGREGATE LEGACY / LOW-LEVEL FLAGS
// ======================================================
L_AnyBoilerOnline := FALSE;
L_AnyBoilerError := FALSE;
L_AnyFlame := FALSE;
L_AnyCommandTimeout := FALSE;
L_AnyHeartbeatTimeout := FALSE;
L_AnyAdapterError := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF VI_Boiler_OT_Online[L_i] THEN
        L_AnyBoilerOnline := TRUE;
    END_IF;

    IF VI_Boiler_Error[L_i] THEN
        L_AnyBoilerError := TRUE;
    END_IF;

    IF VI_Boiler_Flame[L_i] THEN
        L_AnyFlame := TRUE;
    END_IF;

    IF VI_Boiler_OT_Command_Timeout[L_i] THEN
        L_AnyCommandTimeout := TRUE;
    END_IF;

    IF VI_Boiler_OT_Heartbeat_Timeout[L_i] THEN
        L_AnyHeartbeatTimeout := TRUE;
    END_IF;

    IF VI_Boiler_OT_Adapter_Error[L_i] THEN
        L_AnyAdapterError := TRUE;
    END_IF;
END_FOR;

L_AnyDemand := FALSE;
L_AnyPumpOn := FALSE;
L_AnyValveOpen := FALSE;
L_LowSupply := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VI_Demand_Map[L_i] THEN
        L_AnyDemand := TRUE;
    END_IF;

    IF VI_Manifold_Pumps[L_i] THEN
        L_AnyPumpOn := TRUE;
    END_IF;

    IF VI_Manifold_Valves[L_i] > 5.0 THEN
        L_AnyValveOpen := TRUE;
    END_IF;

    IF VI_Demand_Map[L_i] AND (VI_Supply_Temps[L_i] < (VI_Target_Supply - 2.0)) THEN
        L_LowSupply := TRUE;
    END_IF;
END_FOR;

L_CascadeSemanticKnown :=
    VI_Cascade_Available OR
    VI_Cascade_Degraded OR
    VI_Cascade_Partial_Capacity OR
    VI_Cascade_No_Flame OR
    VI_Cascade_Transport_Degraded OR
    VI_Cascade_Ignition_Timeout OR
    (VI_Cascade_Active_Boilers > 0) OR
    (VI_Cascade_Available_Boilers > 0);

// ======================================================
// MODERN CASCADE / OPENTHERM SEMANTICS
// ======================================================
IF L_CascadeSemanticKnown THEN

    IF NOT VI_Cascade_Available THEN
        VO_RootCause := E_Heating_RootCause.RC_BOILER_OFFLINE;
        VO_Confidence := 0.95;
        VO_Error_Score := 0.95;
        VO_Reason_Code := 100;
        VO_Reason_Text := 'Heating cascade unavailable';
        RETURN;
    END_IF;

    IF VI_Cascade_Transport_Degraded THEN
        IF L_AnyHeartbeatTimeout THEN
            VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
            VO_Confidence := 0.90;
            VO_Error_Score := 0.90;
            VO_Reason_Code := 210;
            VO_Reason_Text := 'OpenTherm heartbeat timeout';
            RETURN;
        END_IF;

        IF L_AnyCommandTimeout THEN
            VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
            VO_Confidence := 0.85;
            VO_Error_Score := 0.85;
            VO_Reason_Code := 220;
            VO_Reason_Text := 'OpenTherm command ACK timeout';
            RETURN;
        END_IF;

        IF L_AnyAdapterError THEN
            VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
            VO_Confidence := 0.85;
            VO_Error_Score := 0.85;
            VO_Reason_Code := 230;
            VO_Reason_Text := 'OpenTherm adapter error';
            RETURN;
        END_IF;

        VO_RootCause := E_Heating_RootCause.RC_IO_OFFLINE;
        VO_Confidence := 0.75;
        VO_Error_Score := 0.75;
        VO_Reason_Code := 200;
        VO_Reason_Text := 'OpenTherm transport degraded';
        RETURN;
    END_IF;

    IF VI_Cascade_Ignition_Timeout THEN
        VO_RootCause := E_Heating_RootCause.RC_NO_FLAME;
        VO_Confidence := 0.90;
        VO_Error_Score := 0.90;
        VO_Reason_Code := 300;
        VO_Reason_Text := 'Boiler ignition timeout';
        RETURN;
    END_IF;

    IF VI_Cascade_No_Flame THEN
        VO_RootCause := E_Heating_RootCause.RC_NO_FLAME;
        VO_Confidence := 0.80;
        VO_Error_Score := 0.80;
        VO_Reason_Code := 310;
        VO_Reason_Text := 'Cascade active but no flame';
        RETURN;
    END_IF;

    IF VI_Cascade_Partial_Capacity THEN
        VO_RootCause := E_Heating_RootCause.RC_LOW_SUPPLY_TEMP;
        VO_Confidence := 0.60;
        VO_Error_Score := 0.40;
        VO_Reason_Code := 500;
        VO_Reason_Text := 'Partial cascade capacity';
        RETURN;
    END_IF;
END_IF;

// ======================================================
// LEGACY BOILER / TRANSPORT FALLBACK
// ======================================================
IF NOT L_AnyBoilerOnline THEN
    VO_RootCause := E_Heating_RootCause.RC_BOILER_OFFLINE;
    VO_Confidence := 0.90;
    VO_Error_Score := 0.90;
    VO_Reason_Code := 110;
    VO_Reason_Text := 'No boiler online';
    RETURN;
END_IF;

IF L_AnyBoilerError THEN
    VO_RootCause := E_Heating_RootCause.RC_BOILER_ERROR;
    VO_Confidence := 0.90;
    VO_Error_Score := 0.90;
    VO_Reason_Code := 120;
    VO_Reason_Text := 'Boiler error active';
    RETURN;
END_IF;

IF L_AnyDemand AND NOT L_AnyFlame THEN
    VO_RootCause := E_Heating_RootCause.RC_NO_FLAME;
    VO_Confidence := 0.80;
    VO_Error_Score := 0.80;
    VO_Reason_Code := 130;
    VO_Reason_Text := 'Demand active but no flame';
    RETURN;
END_IF;

// ======================================================
// HYDRAULICS
// ======================================================
IF L_AnyDemand THEN
    IF NOT L_AnyPumpOn THEN
        VO_RootCause := E_Heating_RootCause.RC_PUMP_FAILURE;
        VO_Confidence := 0.80;
        VO_Error_Score := 0.80;
        VO_Reason_Code := 400;
        VO_Reason_Text := 'Demand active but manifold pumps are off';
        RETURN;
    END_IF;

    IF NOT L_AnyValveOpen THEN
        VO_RootCause := E_Heating_RootCause.RC_VALVES_CLOSED;
        VO_Confidence := 0.80;
        VO_Error_Score := 0.80;
        VO_Reason_Code := 410;
        VO_Reason_Text := 'Demand active but manifold valves are closed';
        RETURN;
    END_IF;
END_IF;

// ======================================================
// THERMAL TRANSFER
// ======================================================
IF L_AnyDemand AND L_LowSupply THEN
    VO_RootCause := E_Heating_RootCause.RC_NO_HEAT_TRANSFER;
    VO_Confidence := 0.70;
    VO_Error_Score := 0.70;
    VO_Reason_Code := 420;
    VO_Reason_Text := 'Supply temperature below target under demand';
    RETURN;
END_IF;

// ======================================================
// SENSORS
// ======================================================
IF VI_Sensor_Error THEN
    VO_RootCause := E_Heating_RootCause.RC_SENSOR_ERROR;
    VO_Confidence := 0.70;
    VO_Error_Score := 0.70;
    VO_Reason_Code := 450;
    VO_Reason_Text := 'Heating sensor error active';
    RETURN;
END_IF;

// ======================================================
// NORMAL
// ======================================================
VO_RootCause := E_Heating_RootCause.RC_NONE;
VO_Confidence := 1.0;
VO_Error_Score := 0.0;
VO_Reason_Code := 0;
VO_Reason_Text := 'Heating inference OK';

IF NOT L_Initialized THEN
    L_Write_Index := GVL_Retain.G_BlackBox_LastIndex;
    IF L_Write_Index < 0 OR L_Write_Index >= GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS THEN
        L_Write_Index := 0;
        GVL_Retain.G_BlackBox_LastIndex := 0;
    END_IF;
    L_Initialized := TRUE;
END_IF;

IF VI_Freeze THEN
    GVL_Retain.G_BlackBox_Frozen := TRUE;
END_IF;

VO_Frozen := GVL_Retain.G_BlackBox_Frozen;

IF NOT GVL_Retain.G_BlackBox_Frozen THEN
    GVL_Retain.G_BlackBox_Buffer[L_Write_Index] := VI_Current_Data;
    GVL_Retain.G_BlackBox_LastIndex := L_Write_Index;

    L_Write_Index := L_Write_Index + 1;
    IF L_Write_Index >= GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS THEN
        L_Write_Index := 0;
    END_IF;
END_IF;

VO_Records_Count := GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS; // Размер кольцевого буфера
// >>> BULK_SYNC_ANCHOR: FB_BlackBox_Recorder <<<

// ==============================================================================
// System init helper
//
// Internal helper for PRG_System.
// Owns first-boot initialization of RETAIN runtime state.
// ==============================================================================



IF NOT GVL_Retain.G_Initialized THEN
    FOR L_i := 0 TO GVL_CONSTANTS.C_MAX_PRESENCE_HISTORY - 1 DO
        GVL_Retain.G_Presence_History[L_i] := 0;
    END_FOR;

    GVL_Retain.G_History_Write_Idx := 1;
    GVL_Retain.G_History_Total_Events := 0;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        GVL_Retain.G_Boiler_Accumulated_MS[L_i] := 0;
        GVL_Retain.G_Boiler_Work_Seconds[L_i] := 0;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        GVL_Retain.G_Valve_Test_Results[L_i] := FALSE;
    END_FOR;

    VIO_Local_State.Version := 0;
    VIO_Remote_State.Version := 0;

    GVL_Retain.G_Initialized := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Init <<<

// Защёлкиваем аварии независимо друг от друга
IF VI_Gas_Alarm THEN
    VO_Gas_Latched := TRUE;
END_IF;

IF VI_Leak_Alarm THEN
    VO_Leak_Latched := TRUE;
END_IF;

IF VI_Smoke_Alarm THEN
    VO_Smoke_Latched := TRUE;
END_IF;

L_Any_Active := VI_Gas_Alarm OR VI_Leak_Alarm OR VI_Smoke_Alarm;

// Ручной сброс допустим только когда все входные аварийные сигналы уже исчезли
IF VI_Reset AND NOT L_Any_Active THEN
    VO_Gas_Latched := FALSE;
    VO_Leak_Latched := FALSE;
    VO_Smoke_Latched := FALSE;
END_IF;

// Агрегированный аварийный стоп = любая защёлкнутая safety-авария
VO_Emergency_Stop := VO_Gas_Latched OR VO_Leak_Latched OR VO_Smoke_Latched;

// >>> BULK_SYNC_ANCHOR: FB_Safety_Manager <<<

// ==============================================================================
// System recovery helper
//
// Internal helper for PRG_System.
// Owns one-shot recovery of persistent safety/system state after boot.
// ==============================================================================



IF NOT VIO_Recovery_Done THEN
    IF GVL_PERSISTENT.P_Valid THEN
        GVL_STATE.G_Safety_Gas_Latched := GVL_PERSISTENT.P_Safety_Gas_Latched;
        GVL_STATE.G_Safety_Smoke_Latched := GVL_PERSISTENT.P_Safety_Smoke_Latched;
        GVL_STATE.G_Safety_Leak_Latched := GVL_PERSISTENT.P_Safety_Leak_Latched;
        GVL_STATE.G_System_Mode := GVL_PERSISTENT.P_System_Mode;
    END_IF;

    VIO_Recovery_Done := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_System_Recovery <<<

// ======================================================
// MODBUS RTU TX FRAME BUILDER
// ======================================================
// Builds Modbus RTU request frames only.
// This FB does not send data and does not modify response state.
// ======================================================

VO_Error := FALSE;
VO_Error_Code := 0;
VO_Frame.Valid := FALSE;
VO_Frame.Length := 0;
VO_Frame.CRC := 0;
L_Function_Byte := 0;

FOR L_i := 0 TO 255 DO
    VO_Frame.Data[L_i] := 0;
END_FOR;

IF NOT VI_Request_Valid THEN
    RETURN;
END_IF;

IF VI_Slave_ID = 0 THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0101;
    RETURN;
END_IF;

IF (VI_Register_Count = 0) OR (VI_Register_Count > 32) THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0102;
    RETURN;
END_IF;

CASE VI_Function_Code OF
    MB_FC03_READ_HOLDING_REGISTERS:
        L_Function_Byte := 3;
    MB_FC04_READ_INPUT_REGISTERS:
        L_Function_Byte := 4;
    MB_FC06_WRITE_SINGLE_REGISTER:
        L_Function_Byte := 6;
    MB_FC16_WRITE_MULTIPLE_REGISTERS:
        L_Function_Byte := 16;
ELSE
    VO_Error := TRUE;
    VO_Error_Code := 16#0104;
    RETURN;
END_CASE;

VO_Frame.Data[0] := VI_Slave_ID;
VO_Frame.Data[1] := L_Function_Byte;
VO_Frame.Data[2] := WORD_TO_BYTE(SHR(UINT_TO_WORD(VI_Start_Register), 8));
VO_Frame.Data[3] := WORD_TO_BYTE(UINT_TO_WORD(VI_Start_Register) AND 16#00FF);

CASE VI_Function_Code OF

    MB_FC03_READ_HOLDING_REGISTERS,
    MB_FC04_READ_INPUT_REGISTERS:

        VO_Frame.Data[4] := WORD_TO_BYTE(SHR(UINT_TO_WORD(VI_Register_Count), 8));
        VO_Frame.Data[5] := WORD_TO_BYTE(UINT_TO_WORD(VI_Register_Count) AND 16#00FF);
        VO_Frame.Length := 6;

    MB_FC06_WRITE_SINGLE_REGISTER:

        VO_Frame.Data[4] := WORD_TO_BYTE(SHR(VI_Write_Value[1], 8));
        VO_Frame.Data[5] := WORD_TO_BYTE(VI_Write_Value[1] AND 16#00FF);
        VO_Frame.Length := 6;

    MB_FC16_WRITE_MULTIPLE_REGISTERS:

        L_Byte_Count := VI_Register_Count * 2;

        IF L_Byte_Count > 64 THEN
            VO_Error := TRUE;
            VO_Error_Code := 16#0103;
            RETURN;
        END_IF;

        VO_Frame.Data[4] := WORD_TO_BYTE(SHR(UINT_TO_WORD(VI_Register_Count), 8));
        VO_Frame.Data[5] := WORD_TO_BYTE(UINT_TO_WORD(VI_Register_Count) AND 16#00FF);
        VO_Frame.Data[6] := UINT_TO_BYTE(L_Byte_Count);

        L_Pos := 7;

        FOR L_i := 1 TO UINT_TO_INT(VI_Register_Count) DO
            VO_Frame.Data[L_Pos] := WORD_TO_BYTE(SHR(VI_Write_Value[L_i], 8));
            VO_Frame.Data[L_Pos + 1] := WORD_TO_BYTE(VI_Write_Value[L_i] AND 16#00FF);
            L_Pos := L_Pos + 2;
        END_FOR;

        VO_Frame.Length := 7 + L_Byte_Count;

ELSE
    VO_Error := TRUE;
    VO_Error_Code := 16#0104;
    RETURN;
END_CASE;

// ======================================================
// INLINE MODBUS RTU CRC16
// ======================================================
L_CRC := 16#FFFF;

FOR L_i := 0 TO (UINT_TO_INT(VO_Frame.Length) - 1) DO

    L_CRC := L_CRC XOR BYTE_TO_WORD(VO_Frame.Data[L_i]);

    FOR L_j := 0 TO 7 DO
        IF (L_CRC AND 16#0001) <> 0 THEN
            L_CRC := SHR(L_CRC, 1);
            L_CRC := L_CRC XOR 16#A001;
        ELSE
            L_CRC := SHR(L_CRC, 1);
        END_IF;
    END_FOR;

END_FOR;

VO_Frame.CRC := L_CRC;
VO_Frame.Data[VO_Frame.Length] := WORD_TO_BYTE(L_CRC AND 16#00FF);
VO_Frame.Data[VO_Frame.Length + 1] := WORD_TO_BYTE(SHR(L_CRC, 8));
VO_Frame.Length := VO_Frame.Length + 2;
VO_Frame.Valid := TRUE;

// reset
VO_Block_Heating := FALSE;
VO_Block_Ventilation := FALSE;
VO_Block_Lighting := FALSE;
VO_Block_Sockets := FALSE;
VO_System_Degraded := FALSE;
VO_Code := 0;

// FIRE has highest priority. Safety-stop ownership remains in PRG_Safety.
IF VI_Fire_Latched THEN
    VO_Block_Heating := TRUE;
    VO_Block_Ventilation := TRUE;
    VO_Block_Sockets := TRUE;
    VO_Code := 100;
    RETURN;
END_IF;

// GAS has higher priority than behavior mode.
IF VI_Gas_Latched THEN
    VO_Block_Heating := TRUE;
    VO_Block_Lighting := TRUE;
    VO_Block_Sockets := TRUE;
    VO_Code := 200;
    RETURN;
END_IF;

// LEAK blocks heating but does not suppress later degradation/mode overlays.
IF VI_Leak_Latched THEN
    VO_Block_Heating := TRUE;
    VO_Code := 300;
END_IF;

// IO degraded blocks heating and marks system degraded.
IF VI_IO_Degraded THEN
    VO_System_Degraded := TRUE;
    VO_Block_Heating := TRUE;
    IF VO_Code = 0 THEN
        VO_Code := 400;
    END_IF;
END_IF;

// Ownership violation marks system degraded. Test/result handler owns any safe-stop reaction.
IF VI_Ownership_Violation THEN
    VO_System_Degraded := TRUE;
    IF VO_Code = 0 THEN
        VO_Code := 500;
    END_IF;
END_IF;

// Behavior mode overlays. These are lower priority than safety/system faults.
CASE VI_Behavior_Mode OF
    BEHAVIOR_AWAY:
        VO_Block_Lighting := TRUE;
        VO_Block_Sockets := TRUE;
        IF VO_Code = 0 THEN
            VO_Code := 600;
        END_IF;

    BEHAVIOR_NIGHT:
        VO_Block_Lighting := TRUE;
        IF VO_Code = 0 THEN
            VO_Code := 700;
        END_IF;

    BEHAVIOR_MAINTENANCE:
        VO_Block_Heating := TRUE;
        VO_Block_Ventilation := TRUE;
        IF VO_Code = 0 THEN
            VO_Code := 800;
        END_IF;
ELSE
        // No fallback required
END_CASE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Demand_Map[L_i] := FALSE;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VI_Zone_Valves[L_i] THEN
        L_Manifold_ID := VI_Zone_Configs[L_i].manifold_id;
        IF L_Manifold_ID >= 1 AND L_Manifold_ID <= GVL_CONSTANTS.C_MAX_MANIFOLDS THEN
            VO_Manifold_Demand_Map[L_Manifold_ID] := TRUE;
        END_IF;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Demand_Map <<<

// ======================================================
// MODBUS RTU SYSCOM BACKEND
// ======================================================
// Industrial transport runtime:
//   - serial open/configure
//   - RX assembler
//   - CRC validation
//   - watchdog supervision
//   - reconnect supervision
// ======================================================

IF NOT VI_Enable THEN

    IF L_Handle <> 16#FFFFFFFF THEN
        SysCom.SysComClose(hCom := L_Handle);
        L_Handle := 16#FFFFFFFF;
    END_IF;

    L_Open_Done := FALSE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Transport_Attached := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Online := FALSE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
        MB_SYSCOM_CLOSED;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
        MB_RTU_RX_IDLE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active := FALSE;
    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length := 0;

    RETURN;
END_IF;

// ======================================================
// WATCHDOGS
// ======================================================
GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Watchdog_Timeout := FALSE;
GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Watchdog_Timeout := FALSE;
GVL_MODBUS_SYSCOM_TRANSPORT.G_Bus_Silent := FALSE;

IF GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request THEN

    IF (VI_System_Time_MS -
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_TX_Request_MS) >
        (GVL_CONFIG.G_Modbus_RTU_Request_Timeout_MS * 2) THEN

        GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Watchdog_Timeout := TRUE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_TX_Watchdog :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_TX_Watchdog + 1;

    END_IF;

END_IF;

IF GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Online THEN

    IF (VI_System_Time_MS -
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_RX_MS) > 30000 THEN

        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Watchdog_Timeout := TRUE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Watchdog :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Watchdog + 1;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Bus_Silent := TRUE;

    END_IF;

END_IF;

// ======================================================
// RECONNECT WAIT STATE
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State =
   MB_SYSCOM_RECONNECT_WAIT THEN

    IF (VI_System_Time_MS -
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Last_Error_MS) >=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Reconnect_Delay_MS THEN

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
            MB_SYSCOM_OPENING;

    ELSE

        RETURN;

    END_IF;

END_IF;

// ======================================================
// OPEN + CONFIGURE
// ======================================================
IF NOT L_Open_Done THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
        MB_SYSCOM_OPENING;

    L_Baudrate := GVL_CONFIG.G_Modbus_RTU_Baudrate;

    IF L_Baudrate <= 9600 THEN
        L_Interframe_MS := 5;
    ELSIF L_Baudrate <= 19200 THEN
        L_Interframe_MS := 3;
    ELSE
        L_Interframe_MS := 2;
    END_IF;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_InterFrame_MS :=
        L_Interframe_MS;

    CASE GVL_CONFIG.G_Modbus_RTU_Port_Number OF
        1:
            L_Settings.sPort := SysCom.SYS_COMPORT1;
        2:
            L_Settings.sPort := SysCom.SYS_COMPORT2;
        3:
            L_Settings.sPort := SysCom.SYS_COMPORT3;
        4:
            L_Settings.sPort := SysCom.SYS_COMPORT4;
    ELSE
        L_Settings.sPort := SysCom.SYS_COMPORT1;
    END_CASE;

    CASE GVL_CONFIG.G_Modbus_RTU_Baudrate OF
        4800:
            L_Settings.ulBaudrate := SysCom.SYS_BR_4800;
        9600:
            L_Settings.ulBaudrate := SysCom.SYS_BR_9600;
        19200:
            L_Settings.ulBaudrate := SysCom.SYS_BR_19200;
        38400:
            L_Settings.ulBaudrate := SysCom.SYS_BR_38400;
        57600:
            L_Settings.ulBaudrate := SysCom.SYS_BR_57600;
        115200:
            L_Settings.ulBaudrate := SysCom.SYS_BR_115200;
    ELSE
        L_Settings.ulBaudrate := SysCom.SYS_BR_9600;
    END_CASE;

    CASE GVL_CONFIG.G_Modbus_RTU_Parity OF
        0:
            L_Settings.byParity := SysCom.SYS_NOPARITY;
        1:
            L_Settings.byParity := SysCom.SYS_EVENPARITY;
        2:
            L_Settings.byParity := SysCom.SYS_ODDPARITY;
    ELSE
        L_Settings.byParity := SysCom.SYS_EVENPARITY;
    END_CASE;

    CASE GVL_CONFIG.G_Modbus_RTU_Stop_Bits OF
        1:
            L_Settings.byStopBits := SysCom.SYS_ONESTOPBIT;
        2:
            L_Settings.byStopBits := SysCom.SYS_TWOSTOPBITS;
    ELSE
        L_Settings.byStopBits := SysCom.SYS_ONESTOPBIT;
    END_CASE;

    L_Settings.ulTimeout := GVL_CONFIG.G_Modbus_RTU_Request_Timeout_MS;
    L_Settings.ulBufferSize := 512;

    IF GVL_CONFIG.G_Modbus_RTU_Data_Bits < 7 THEN
        L_SettingsEx2.byByteSize := 8;
    ELSIF GVL_CONFIG.G_Modbus_RTU_Data_Bits > 8 THEN
        L_SettingsEx2.byByteSize := 8;
    ELSE
        L_SettingsEx2.byByteSize := GVL_CONFIG.G_Modbus_RTU_Data_Bits;
    END_IF;

    L_SettingsEx2.bBinary := TRUE;
    L_SettingsEx2.bOutxCtsFlow := FALSE;
    L_SettingsEx2.bOutxDsrFlow := FALSE;
    L_SettingsEx2.byDtrControl := 0;
    L_SettingsEx2.bDsrSensitivity := FALSE;
    L_SettingsEx2.byRtsControl := 0;
    L_SettingsEx2.bTXContinueOnXoff := FALSE;
    L_SettingsEx2.bOutX := FALSE;
    L_SettingsEx2.bInX := FALSE;
    L_SettingsEx2.byXonChar := 0;
    L_SettingsEx2.byXoffChar := 0;
    L_SettingsEx2.wXonLim := 0;
    L_SettingsEx2.wXoffLim := 0;

    L_Handle := SysCom.SysComOpen3(
        pSettings := ADR(L_Settings),
        pSettingsEx2 := ADR(L_SettingsEx2),
        pResult := ADR(L_Result)
    );

    IF L_Handle <> 16#FFFFFFFF THEN

        SysCom.SysComPurge(hCom := L_Handle);

        L_Open_Done := TRUE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Transport_Attached := TRUE;
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Online := TRUE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
            MB_SYSCOM_ONLINE;

    ELSE

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Transport_Attached := FALSE;
        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Online := FALSE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
            MB_SYSCOM_RECONNECT_WAIT;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Last_Error_MS :=
            VI_System_Time_MS;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Reconnect_Attempts :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_Reconnect_Attempts + 1;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Reconnects :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Reconnects + 1;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Errors :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_Errors + 1;

    END_IF;

    RETURN;
END_IF;

GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
    MB_SYSCOM_ONLINE;

// ======================================================
// TX WRITE
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Request AND
   NOT GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done THEN

    L_Bytes_Written := SysCom.SysComWrite(
        hCom := L_Handle,
        pbyBuffer := ADR(GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Buffer),
        ulSize := GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Length,
        ulTimeout := GVL_CONFIG.G_Modbus_RTU_Request_Timeout_MS,
        pResult := ADR(L_Result)
    );

    IF L_Bytes_Written = GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Length THEN

        GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Done := TRUE;

    ELSE

        GVL_MODBUS_SYSCOM_TRANSPORT.G_TX_Error := TRUE;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_Backend_State :=
            MB_SYSCOM_ERROR;

    END_IF;

END_IF;

// ======================================================
// RX STREAM READ
// ======================================================
L_Bytes_Read := SysCom.SysComRead(
    hCom := L_Handle,
    pbyBuffer := ADR(L_RX_Buffer),
    ulSize := 256,
    ulTimeout := SysCom.SYS_NOWAIT,
    pResult := ADR(L_Result)
);

IF L_Bytes_Read > 0 THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
        MB_RTU_RX_RECEIVING;

    IF L_Bytes_Read > 256 THEN
        L_Read_Count := 256;
    ELSE
        L_Read_Count := UDINT_TO_INT(L_Bytes_Read);
    END_IF;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active := TRUE;

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Last_Byte_MS :=
        VI_System_Time_MS;

    FOR L_i := 0 TO (L_Read_Count - 1) DO

        L_Target_Index :=
            UINT_TO_INT(GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length);

        IF L_Target_Index >= 256 THEN

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
                MB_RTU_RX_OVERFLOW;

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Overflow := TRUE;

            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Overflow :=
                GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Overflow + 1;

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active := FALSE;
            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length := 0;

            EXIT;

        END_IF;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Buffer[L_Target_Index] :=
            L_RX_Buffer[L_i];

        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length :=
            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length + 1;

    END_FOR;

END_IF;

// ======================================================
// INTER-FRAME FINALIZATION
// ======================================================
IF GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active THEN

    IF (VI_System_Time_MS -
        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Last_Byte_MS) >=
        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_InterFrame_MS THEN

        L_Frame_Length :=
            UINT_TO_INT(GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length);

        IF L_Frame_Length >= 4 THEN

            L_CRC := 16#FFFF;

            FOR L_i := 0 TO (L_Frame_Length - 3) DO

                L_CRC := L_CRC XOR
                    BYTE_TO_WORD(
                        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Buffer[L_i]
                    );

                FOR L_j := 0 TO 7 DO

                    IF (L_CRC AND 16#0001) <> 0 THEN
                        L_CRC := SHR(L_CRC, 1);
                        L_CRC := L_CRC XOR 16#A001;
                    ELSE
                        L_CRC := SHR(L_CRC, 1);
                    END_IF;

                END_FOR;

            END_FOR;

            L_CRC_Frame :=
                BYTE_TO_WORD(
                    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Buffer[L_Frame_Length - 2]
                );

            L_CRC_Frame :=
                L_CRC_Frame OR
                SHL(
                    BYTE_TO_WORD(
                        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Buffer[L_Frame_Length - 1]
                    ),
                    8
                );

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_CRC_Calc :=
                L_CRC;

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_CRC_Frame :=
                L_CRC_Frame;

            IF L_CRC = L_CRC_Frame THEN

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
                    MB_RTU_RX_FRAME_READY;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_CRC_OK := TRUE;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Length :=
                    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Ready := TRUE;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX :=
                    GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX + 1;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_Last_RX_MS :=
                    VI_System_Time_MS;

            ELSE

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
                    MB_RTU_RX_CRC_ERROR;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_CRC_OK := FALSE;

                GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_CRC_Error :=
                    GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_CRC_Error + 1;

            END_IF;

        ELSE

            GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
                MB_RTU_RX_SHORT_FRAME;

            GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Short_Frame :=
                GVL_MODBUS_SYSCOM_TRANSPORT.G_Total_RX_Short_Frame + 1;

        END_IF;

        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active := FALSE;
        GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Length := 0;

    END_IF;

END_IF;

IF NOT GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Assembler_Active AND
   NOT GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_Ready AND
   (GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State = MB_RTU_RX_FRAME_READY) THEN

    GVL_MODBUS_SYSCOM_TRANSPORT.G_RX_State :=
        MB_RTU_RX_IDLE;

END_IF;

// ==============================================================================
// System diagnostics helper
//
// Internal helper for PRG_System.
// Owns diagnostic flag export into GVL_STATUS.G_Diagnostics.
// ==============================================================================


GVL_STATUS.G_Diagnostics.Sensor_Fault :=
    GVL_STATE.G_Heating_Sensor_Fault OR
    GVL_STATE.G_DHW_Sensor_Fault OR
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active;

GVL_STATUS.G_Diagnostics.IO_Offline :=
    GVL_STATE.G_Heating_IO_Fault OR
    GVL_STATE.G_DHW_IO_Fault OR
    GVL_STATE.G_Ventilation_IO_Fault OR
    GVL_STATE.G_Lighting_IO_Fault;

GVL_STATUS.G_Diagnostics.Subsystem_Degraded :=
    GVL_STATE.G_Heating_Subsystem_Degraded OR
    GVL_STATE.G_DHW_Subsystem_Degraded OR
    GVL_STATE.G_Ventilation_Subsystem_Degraded OR
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active OR
    GVL_STATUS.G_Diagnostics.Manifold_Return_Temp_Fault_Active;

// >>> BULK_SYNC_ANCHOR: FB_System_Diagnostics <<<

L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);

GVL_STATE.G_Heating_IO_Fault := FALSE;
GVL_STATE.G_Heating_Sensor_Fault := FALSE;
GVL_STATE.G_Heating_Subsystem_Degraded := FALSE;
L_Sensor_Error := FALSE;
L_Subsys_Degraded := FALSE;
L_Allocation_Degraded := FALSE;

L_IO_Failsafe_Active := FALSE;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        L_IO_Failsafe_Active := TRUE;
        GVL_STATE.G_Heating_IO_Fault := TRUE;
        GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
        EXIT;
    END_IF;
END_FOR;

fbSafetyGate(
    VI_System_Mode := VI_System_Mode,
    VI_Emergency_Stop := VI_Emergency_Stop,
    VI_Gas_Safety_Stop := VI_Gas_Safety_Stop,
    VI_IO_Failsafe_Active := L_IO_Failsafe_Active,
    VI_Outdoor_Temp := VI_Outdoor_Temp,
    VI_Freeze_Threshold := VI_Config.Freeze_Threshold,
    VI_Floor_Temps := VI_Floor_Temps,
    VO_Freeze_Mode_Active => L_Freeze_Active,
    VO_Freeze_Target_Supply => L_Freeze_Target_Supply
);

fbSafeState(
    VI_Block_Normal_Heating := fbSafetyGate.VO_Block_Normal_Heating,
    VI_IO_Failsafe_Active := fbSafetyGate.VO_IO_Failsafe_Active,
    VI_Gas_Safety_Active := fbSafetyGate.VO_Gas_Safety_Active,
    VI_Freeze_Active := L_Freeze_Active,
    VI_Freeze_Target_Supply := L_Freeze_Target_Supply,
    VI_Manifold_Temps_Supply := VI_Manifold_Temps_Supply,
    VI_Boiler_Error_Status := VI_Boiler_Error_Status,
    VI_Boiler_OT_Online := VI_Boiler_OT_Online
);

IF fbSafeState.VO_Applied THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        VO_Zone_Valves[L_i] := fbSafeState.VO_Zone_Valves[L_i];
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        VO_Manifold_Pumps[L_i] := fbSafeState.VO_Manifold_Pumps[L_i];
        VO_Manifold_Valves[L_i] := fbSafeState.VO_Manifold_Valves[L_i];
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Boiler_OT_Enable[L_i] := fbSafeState.VO_Boiler_OT_Enable[L_i];
        VO_Boiler_OT_Setpoint[L_i] := fbSafeState.VO_Boiler_OT_Setpoint[L_i];
        VO_Boiler_Status[L_i] := fbSafeState.VO_Boiler_Status[L_i];
    END_FOR;

    VO_Backup_Circulation_Pump := fbSafeState.VO_Backup_Circulation_Pump;
    VO_Electric_Heater_Enable := fbSafeState.VO_Electric_Heater_Enable;
    VO_Freeze_Risk_Status := fbSafeState.VO_Freeze_Risk_Status;
    RETURN;
END_IF;

VO_Backup_Circulation_Pump := FALSE;
VO_Electric_Heater_Enable := FALSE;
VO_Freeze_Risk_Status := FALSE;

IF L_Freeze_Active THEN
    L_Target_Supply_Temp := L_Freeze_Target_Supply;
ELSE
    L_Target_Supply_Temp := VI_Config.Target_Floor_Temp;
END_IF;

fbAdaptiveTarget(
    VI_Base_Target_Supply_Temp := L_Target_Supply_Temp,
    VI_Global_Target_Temperature := GVL_STATE.G_Target_Temperature,
    VI_Zone_Configs := VI_Zone_Configs,
    VI_Floor_Temps := VI_Floor_Temps,
    VI_Room_Temps := VI_Room_Temps,
    VO_Target_Supply_Temp => L_Target_Supply_Temp
);

L_Policy_Target_Adjustment := GVL_HEATING_POLICY.G_Policy_Target_Adjustment;

IF L_Policy_Target_Adjustment > REAL#5.0 THEN
    L_Policy_Target_Adjustment := REAL#5.0;
ELSIF L_Policy_Target_Adjustment < REAL#-3.0 THEN
    L_Policy_Target_Adjustment := REAL#-3.0;
END_IF;

L_Target_Supply_Temp :=
    LIMIT(
        GVL_CONSTANTS.C_BOILER_SETPOINT_MIN,
        L_Target_Supply_Temp + L_Policy_Target_Adjustment,
        GVL_CONSTANTS.C_BOILER_SETPOINT_MAX
    );

fbCircuitControl(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Current_Hour := VI_Current_Hour,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Config := VI_Config,
    VI_Tariff := VI_Tariff,
    VI_Scenario_Adjust := REAL#0.0,
    VI_Zone_Configs := VI_Zone_Configs,
    VI_Floor_Temps := VI_Floor_Temps,
    VI_Room_Temps := VI_Room_Temps,
    VI_Rule_Actions := VI_Rule_Actions,
    VO_Zone_Valves => VO_Zone_Valves,
    VO_Heating_Sensor_Fault => L_Sensor_Error
);

GVL_STATE.G_Heating_Sensor_Fault := L_Sensor_Error;

fbDemandMap(
    VI_Zone_Valves := VO_Zone_Valves,
    VI_Zone_Configs := VI_Zone_Configs,
    VO_Manifold_Demand_Map => L_Manifold_Demand_Map
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_Manifold_Available[L_i] := VI_Manifold_Pressures[L_i] >= GVL_CONSTANTS.C_MIN_HEATING_MANIFOLD_PRESSURE;
    L_Manifold_In_Service[L_i] := GVL_CONFIG.G_Manifold_Pump_In_Service[L_i];
    L_Manifold_Subsystem_Degraded[L_i] :=
        GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i]
        OR GVL_STATE.G_Predictive_Pump_Current_Rise[L_i];

    L_Manifold_Base_Priority[L_i] := GVL_CONFIG.G_Manifold_Priority[L_i];
    L_Manifold_Thermal_Weight[L_i] := GVL_CONFIG.G_Manifold_Thermal_Weight[L_i];
END_FOR;

fbPolicyPriorityBridge(
    VI_Enable := (GVL_CONFIG.G_Max_Thermal_Budget > REAL#0.0),
    VI_Zone_Valves := VO_Zone_Valves,
    VI_Zone_Configs := VI_Zone_Configs,
    VI_Manifold_Base_Priority := L_Manifold_Base_Priority,
    VI_Zone_Priority_Bias := GVL_HEATING_POLICY.G_Zone_Priority_Bias,
    VI_Policy_Priority_Multiplier := GVL_HEATING_POLICY.G_Policy_Priority_Multiplier,
    VO_Manifold_Effective_Priority => L_Manifold_Effective_Priority
);

fbAllocationFilter(
    VI_Enable := TRUE,
    VI_Enable_Policy_Allocation := (GVL_CONFIG.G_Max_Thermal_Budget > REAL#0.0),
    VI_Freeze_Mode_Active := L_Freeze_Active,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_Manifold_Demand_Map := L_Manifold_Demand_Map,
    VI_Manifold_Available := L_Manifold_Available,
    VI_Manifold_In_Service := L_Manifold_In_Service,
    VI_Manifold_Subsystem_Degraded := L_Manifold_Subsystem_Degraded,
    VI_Manifold_Base_Priority := L_Manifold_Effective_Priority,
    VI_Manifold_Thermal_Weight := L_Manifold_Thermal_Weight,
    VI_Max_Thermal_Budget := GVL_CONFIG.G_Max_Thermal_Budget,
    VO_Manifold_Demand_Filtered => L_Manifold_Demand_Filtered,
    VO_Allocation_Degraded => L_Allocation_Degraded
);

fbRuntimeObservability(
    VI_Policy_Active := (GVL_CONFIG.G_Max_Thermal_Budget > REAL#0.0),
    VI_Freeze_Bypass_Active := L_Freeze_Active,
    VI_DHW_Bypass_Active := VI_DHW_Heating_Demand,
    VI_Budget_Max := GVL_CONFIG.G_Max_Thermal_Budget,
    VI_Budget_Used := fbAllocationFilter.VO_Thermal_Budget_Used,
    VI_Requested := L_Manifold_Demand_Map,
    VI_Allowed := fbAllocationFilter.VO_Manifold_Allowed,
    VI_Filtered := L_Manifold_Demand_Filtered,
    VI_Block_Reason := fbAllocationFilter.VO_Manifold_Block_Reason,
    VI_Effective_Priority := fbAllocationFilter.VO_Manifold_Priority_Effective,
    VI_Priority_Bridge_Active := fbPolicyPriorityBridge.VO_Bridge_Active,
    VI_Priority_Bias_Applied := fbPolicyPriorityBridge.VO_Manifold_Priority_Bias_Applied,
    VI_Priority_Effective := L_Manifold_Effective_Priority
);

IF L_Allocation_Degraded THEN
    GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
END_IF;

fbManifoldControl(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_Freeze_Mode_Active := L_Freeze_Active,
    VI_Target_Supply_Temp := L_Target_Supply_Temp,
    VI_Any_Zone_Active := L_Manifold_Demand_Filtered,
    VI_Manifold_Pressures := VI_Manifold_Pressures,
    VI_Manifold_Currents := VI_Manifold_Currents,
    VI_Manifold_Temps_Supply := VI_Manifold_Temps_Supply,
    VI_Manifold_Temps_Return := VI_Manifold_Temps_Return,
    VO_Manifold_Pumps => VO_Manifold_Pumps,
    VO_Manifold_Valves => VO_Manifold_Valves,
    VO_Status => VO_Status
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_Pressure_OK := VI_Manifold_Pressures[L_i] >= GVL_CONSTANTS.C_MIN_HEATING_MANIFOLD_PRESSURE;

    IF VO_Manifold_Pumps[L_i] AND NOT L_Pressure_OK THEN
        VO_Manifold_Pumps[L_i] := FALSE;
        GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
    END_IF;

    IF (L_Prev_Pressure[L_i] > REAL#0.0) AND ((L_Prev_Pressure[L_i] - VI_Manifold_Pressures[L_i]) > REAL#0.2) THEN
        GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i] := TRUE;
    ELSE
        GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i] := FALSE;
    END_IF;

    IF (L_Prev_Current[L_i] > REAL#0.0) AND (VI_Manifold_Currents[L_i] > (L_Prev_Current[L_i] * REAL#1.2)) THEN
        GVL_STATE.G_Predictive_Pump_Current_Rise[L_i] := TRUE;
    ELSE
        GVL_STATE.G_Predictive_Pump_Current_Rise[L_i] := FALSE;
    END_IF;

    IF GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i] OR GVL_STATE.G_Predictive_Pump_Current_Rise[L_i] THEN
        GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
    END_IF;

    L_Prev_Pressure[L_i] := VI_Manifold_Pressures[L_i];
    L_Prev_Current[L_i] := VI_Manifold_Currents[L_i];
END_FOR;

L_Error_Instant := REAL#0.0;

IF GVL_STATE.G_Heating_Sensor_Fault THEN
    L_Error_Instant := L_Error_Instant + REAL#0.2;
END_IF;

IF GVL_STATE.G_Heating_IO_Fault THEN
    L_Error_Instant := L_Error_Instant + REAL#0.2;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VI_Manifold_Pressures[L_i] < GVL_CONSTANTS.C_MIN_HEATING_MANIFOLD_PRESSURE THEN
        L_Error_Instant := L_Error_Instant + REAL#0.1;
        EXIT;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i] OR GVL_STATE.G_Predictive_Pump_Current_Rise[L_i] THEN
        L_Error_Instant := L_Error_Instant + REAL#0.2;
        EXIT;
    END_IF;
END_FOR;

GVL_STATE.G_Heating_Error_Score := (GVL_STATE.G_Heating_Error_Score * REAL#0.98) + L_Error_Instant;
L_Confidence := REAL#1.0 - GVL_STATE.G_Heating_Error_Score;

IF L_Confidence < REAL#0.0 THEN
    L_Confidence := REAL#0.0;
ELSIF L_Confidence > REAL#1.0 THEN
    L_Confidence := REAL#1.0;
END_IF;

GVL_STATE.G_Heating_Confidence := L_Confidence;

GVL_STATE.G_Heating_Confidence_Reason_Code := 0;
GVL_STATE.G_Heating_Confidence_Reason_Text := 'OK';

IF GVL_STATE.G_Heating_IO_Fault THEN
    GVL_STATE.G_Heating_Confidence_Reason_Code := 2;
    GVL_STATE.G_Heating_Confidence_Reason_Text := 'IO fault detected';
ELSIF GVL_STATE.G_Heating_Sensor_Fault THEN
    GVL_STATE.G_Heating_Confidence_Reason_Code := 1;
    GVL_STATE.G_Heating_Confidence_Reason_Text := 'Sensor fault detected';
ELSE
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF VI_Manifold_Pressures[L_i] < GVL_CONSTANTS.C_MIN_HEATING_MANIFOLD_PRESSURE THEN
            GVL_STATE.G_Heating_Confidence_Reason_Code := 3;
            GVL_STATE.G_Heating_Confidence_Reason_Text := 'Low manifold pressure';
            EXIT;
        END_IF;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i] OR GVL_STATE.G_Predictive_Pump_Current_Rise[L_i] THEN
            GVL_STATE.G_Heating_Confidence_Reason_Code := 4;
            GVL_STATE.G_Heating_Confidence_Reason_Text := 'Predictive pump degradation';
            EXIT;
        END_IF;
    END_FOR;
END_IF;

IF GVL_STATE.G_Heating_Confidence < REAL#0.5 THEN
    L_Target_Supply_Temp := L_Target_Supply_Temp - REAL#3.0;
END_IF;

CASE GVL_STATE.G_Heating_Confidence_Reason_Code OF
    1:
        L_Target_Supply_Temp := LIMIT(GVL_CONSTANTS.C_BOILER_SETPOINT_MIN, REAL#40.0, GVL_CONSTANTS.C_BOILER_SETPOINT_MAX);
    2:
        VO_Backup_Circulation_Pump := TRUE;
    3:
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            VO_Manifold_Pumps[L_i] := FALSE;
        END_FOR;
    4:
        L_Target_Supply_Temp := LIMIT(GVL_CONSTANTS.C_BOILER_SETPOINT_MIN, L_Target_Supply_Temp - REAL#5.0, GVL_CONSTANTS.C_BOILER_SETPOINT_MAX);
ELSE
    // no auto-recovery action
END_CASE;

fbValveTestManager(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Valve_Currents := VI_Manifold_Currents,
    VI_Valve_End_Switches := VI_Manifold_End_Switches,
    VI_Config := VI_Valve_Test_Config
);

IF fbValveTestManager.VO_Test_Active THEN
    L_i := fbValveTestManager.VO_Current_Valve;
    IF L_i >= 1 AND L_i <= GVL_CONSTANTS.C_MAX_MANIFOLDS THEN
        IF fbValveTestManager.VO_Valve_Cmd[L_i] THEN
            VO_Manifold_Valves[L_i] := REAL#100.0;
        ELSE
            VO_Manifold_Valves[L_i] := REAL#0.0;
        END_IF;
        VO_Manifold_Pumps[L_i] := FALSE;
    END_IF;
END_IF;

fbBoilerControl(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_DHW_Target_Temp := VI_DHW_Target_Temp,
    VI_Target_Supply_Temp := L_Target_Supply_Temp,
    VI_Freeze_Mode_Active := L_Freeze_Active,
    VI_Policy_Degraded := L_Policy_Degraded,
    VI_Manifold_Pumps := VO_Manifold_Pumps,
    VI_Manifold_Valves := VO_Manifold_Valves,
    VI_Boiler_Flame_Status := VI_Boiler_Flame_Status,
    VI_Boiler_Error_Status := VI_Boiler_Error_Status,
    VI_Boiler_OT_Online := VI_Boiler_OT_Online,
    VI_Boiler_Modulation := VI_Boiler_Modulation,
    VO_Boiler_OT_Enable => VO_Boiler_OT_Enable,
    VO_Boiler_OT_Setpoint => VO_Boiler_OT_Setpoint,
    VO_Boiler_Status => VO_Boiler_Status,
    VO_Any_Subsystem_Degraded => L_Subsys_Degraded
);

GVL_STATE.G_Heating_Subsystem_Degraded := GVL_STATE.G_Heating_Subsystem_Degraded OR L_Subsys_Degraded;

// >>> BULK_SYNC_ANCHOR: FB_Heating_System_Manager <<<

// default
VO_Mode := BEHAVIOR_HOME;
VO_Mode_Code := 0;

// priority-based transitions
IF VI_Maintenance_Request THEN
    VO_Mode := BEHAVIOR_MAINTENANCE;
    VO_Mode_Code := 300;
ELSIF VI_Away_Request THEN
    VO_Mode := BEHAVIOR_AWAY;
    VO_Mode_Code := 200;
ELSIF VI_Is_Night THEN
    VO_Mode := BEHAVIOR_NIGHT;
    VO_Mode_Code := 100;
END_IF;

// ==============================================================================
// Config simulation / validation function block
// Service/commissioning validation utility.
// Does NOT own runtime control and does NOT participate in heating phase runtime.
// ==============================================================================



VO_Executed := FALSE;
VO_Result_OK := GVL_CONFIG_SIMULATION.G_Simulation_Result_OK;
VO_Error_Text := GVL_CONFIG_SIMULATION.G_Simulation_Error_Text;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

IF VI_Request AND VI_Confirm THEN

    L_Error := FALSE;
    VO_Result_OK := TRUE;
    VO_Error_Text := '';

    // Simulate INPUT constraints
    IF (GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate < 0.0) OR (GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate > 1.0) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Invalid learning rate';
        L_Error := TRUE;
    END_IF;

    // Simulate SCENARIO logic
    IF GVL_CONFIG_CONTROL.STG_Night_Start_Hour = GVL_CONFIG_CONTROL.STG_Night_End_Hour THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Night window invalid';
        L_Error := TRUE;
    END_IF;

    // Simulate SAFETY
    IF GVL_CONFIG_CONTROL.STG_Stabilization_Delay_MS < 1000 THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Recovery delay too small';
        L_Error := TRUE;
    END_IF;

    // Simulate FAIL-SAFE policy
    IF NOT (
        GVL_CONFIG_CONTROL.STG_PLC_Inactive_Close_Gas OR
        GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Boiler OR
        GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Heating OR
        GVL_CONFIG_CONTROL.STG_PLC_Inactive_Stop_Vent OR
        GVL_CONFIG_CONTROL.STG_PLC_Inactive_Block_Water
    ) THEN
        VO_Result_OK := FALSE;
        VO_Error_Text := 'Fail-safe disabled';
        L_Error := TRUE;
    END_IF;

    GVL_CONFIG_SIMULATION.G_Simulation_Result_OK := NOT L_Error;
    GVL_CONFIG_SIMULATION.G_Simulation_Error_Text := VO_Error_Text;
    GVL_CONFIG_SIMULATION.G_Simulation_Last_Run_MS := GVL_TIME_SERVICE.G_Now_MS;
    VO_Executed := TRUE;

END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Config_Simulation <<<

VO_System_OK := FALSE;
VO_System_Warning := FALSE;
VO_System_Critical := FALSE;
VO_Status_Msg := '';
VO_System_Mode := E_System_Operating_Mode.MODE_NORMAL;

CASE VI_System_Severity OF
    E_System_Severity.SEV_NORMAL:
        VO_System_OK := TRUE;
        VO_Status_Msg := 'Система в норме';
        VO_System_Mode := E_System_Operating_Mode.MODE_NORMAL;

    E_System_Severity.SEV_WARNING:
        VO_System_Warning := TRUE;
        VO_System_Mode := E_System_Operating_Mode.MODE_DEGRADED;
        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_WATER_LEAK:
                VO_Status_Msg := 'Предупреждение: протечка воды';
            E_System_Root_Cause.ROOT_CO_WARNING:
                VO_Status_Msg := 'Предупреждение: повышенный CO';
            ELSE
                VO_Status_Msg := 'Предупреждение системы';
        END_CASE;

    E_System_Severity.SEV_DEGRADED:
        VO_System_Warning := TRUE;
        VO_System_Mode := E_System_Operating_Mode.MODE_DEGRADED;
        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_SENSOR_FAULT:
                VO_Status_Msg := 'Деградация: ошибка датчика';
            E_System_Root_Cause.ROOT_IO_OFFLINE:
                VO_Status_Msg := 'Деградация: модуль IO недоступен';
            E_System_Root_Cause.ROOT_COMM_FAULT:
                VO_Status_Msg := 'Деградация: ошибка связи';
            E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
                VO_Status_Msg := 'Деградация: watchdog fault';
            E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT:
                VO_Status_Msg := 'Деградация: ошибка подсистемы';
            ELSE
                VO_Status_Msg := 'Деградация системы';
        END_CASE;

    E_System_Severity.SEV_CRITICAL:
        VO_System_Critical := TRUE;

        IF (VI_Root_Cause = E_System_Root_Cause.ROOT_GAS_LEAK OR
            VI_Root_Cause = E_System_Root_Cause.ROOT_CO_CRITICAL) AND
            VI_Freeze_Risk THEN
            VO_System_Mode := E_System_Operating_Mode.MODE_FREEZE_PROTECTION;
        ELSE
            VO_System_Mode := E_System_Operating_Mode.MODE_SAFE_STOP;
        END_IF;

        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_FIRE:
                VO_Status_Msg := 'АВАРИЯ: ПОЖАР';
            E_System_Root_Cause.ROOT_GAS_LEAK:
                VO_Status_Msg := 'АВАРИЯ: УТЕЧКА ГАЗА';
            E_System_Root_Cause.ROOT_CO_CRITICAL:
                VO_Status_Msg := 'АВАРИЯ: КРИТИЧЕСКИЙ CO';
            E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
                VO_Status_Msg := 'АВАРИЯ: WATCHDOG';
            ELSE
                VO_Status_Msg := 'АВАРИЯ СИСТЕМЫ';
        END_CASE;
END_CASE;
// >>> BULK_SYNC_ANCHOR: FB_State_Manager <<<

// ==============================================================================
// Heating safety gate helper
// ==============================================================================



VO_Gas_Safety_Active := VI_Gas_Safety_Stop;
VO_Emergency_Safe_Stop_Active := VI_Emergency_Stop OR (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
VO_IO_Failsafe_Active := VI_IO_Failsafe_Active;

// REAL validity guard: NaN fails self-equality; extreme values are rejected as sensor faults.
VO_Outdoor_Temp_Valid := (VI_Outdoor_Temp = VI_Outdoor_Temp) AND (VI_Outdoor_Temp > -80.0) AND (VI_Outdoor_Temp < 80.0);
IF VO_Outdoor_Temp_Valid THEN
    L_Outdoor_Temp_Safe := VI_Outdoor_Temp;
ELSE
    L_Outdoor_Temp_Safe := 20.0;
    GVL_STATE.G_Heating_Sensor_Fault := TRUE;
END_IF;

VO_Block_Normal_Heating := VO_Gas_Safety_Active OR VO_Emergency_Safe_Stop_Active OR VO_IO_Failsafe_Active;
VO_Freeze_Mode_Active := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION) OR (L_Outdoor_Temp_Safe < -5.0);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VI_Floor_Temps[L_i] < 7.0 THEN
        VO_Freeze_Mode_Active := TRUE;
    END_IF;
END_FOR;

IF VO_Freeze_Mode_Active THEN
    VO_Freeze_Target_Supply := LIMIT(20.0, VI_Freeze_Threshold + 2.0, 35.0);
ELSE
    VO_Freeze_Target_Supply := 0.0;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Safety_Gate <<<

VO_Event_Pulse := FALSE;
VO_Event_Code := 0;
VO_Event_Value := 0.0;

// 1. Детекция новых тревог (антидребезг + передний фронт)
T_Debounce_Gas(IN := VI_Gas_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Fire(IN := VI_Fire_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Flood(IN := VI_Flood_Alarm, PT := T#500ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Security(IN := VI_Security_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);

R_Trig_Gas(CLK := T_Debounce_Gas.Q);
R_Trig_Fire(CLK := T_Debounce_Fire.Q);
R_Trig_Flood(CLK := T_Debounce_Flood.Q);
R_Trig_Security(CLK := T_Debounce_Security.Q);
R_Trig_First_Fault(CLK := VI_First_Fault_Active);
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    R_Trig_Boiler[L_i](CLK := VI_Boiler_Errors[L_i]);
END_FOR;

// 2. Добавление новых тревог в список (Кольцевой буфер)
L_Pending_Count := 0;
L_Event_Pulse_Latched := FALSE;

IF R_Trig_Gas.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Gas';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Критическая концентрация газа!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Fire.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Fire';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Обнаружено задымление!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Flood.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Flood';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Обнаружена протечка воды!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Security.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Security';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := VI_Security_Msg;
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_First_Fault.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Diagnostics';
    L_Pending_Alarms[L_Pending_Count].Source_ID := TO_BYTE(VI_First_Fault_Source);

    CASE VI_First_Fault_Type OF
        1: L_First_Fault_Type_Text := 'IO';
        2: L_First_Fault_Type_Text := 'Sensor';
        3: L_First_Fault_Type_Text := 'Comm';
        4: L_First_Fault_Type_Text := 'Subsystem';
        ELSE L_First_Fault_Type_Text := 'Unknown';
    END_CASE;

    CASE VI_First_Fault_Source OF
        1: L_First_Fault_Source_Text := 'Heating';
        2: L_First_Fault_Source_Text := 'DHW';
        3: L_First_Fault_Source_Text := 'Ventilation';
        4: L_First_Fault_Source_Text := 'Lighting';
        5: L_First_Fault_Source_Text := 'Access';
        ELSE L_First_Fault_Source_Text := 'Unknown';
    END_CASE;

    L_Pending_Alarms[L_Pending_Count].Message := CONCAT('Diagnostics root cause: ', CONCAT(L_First_Fault_Source_Text, CONCAT(' / ', L_First_Fault_Type_Text)));
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF R_Trig_Boiler[L_j].Q AND L_Pending_Count < 10 THEN
        L_Pending_Count := L_Pending_Count + 1;
        L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
        L_Pending_Alarms[L_Pending_Count].Source := 'Boiler';
        L_Pending_Alarms[L_Pending_Count].Source_ID := TO_BYTE(L_j);
        L_Pending_Alarms[L_Pending_Count].Message := CONCAT('Авария котла №', INT_TO_STRING(L_j));
        L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
        L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
        L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
    END_IF;
END_FOR;



// Обработка очереди новых тревог с учетом приоритетов
FOR L_i := 1 TO L_Pending_Count DO

    L_Target_Slot := 0;

    // 1. Ищем пустой слот
    FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF VO_Alarm_List[L_k].ID = 0 THEN
            L_Target_Slot := L_k;
            EXIT;
        END_IF;
    END_FOR;

    // 2. Ищем квитированную тревогу с наименьшим приоритетом
    IF L_Target_Slot = 0 THEN
        L_Min_Pri := 999;
        FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
            IF VO_Alarm_List[L_k].Is_Acknowledged AND TO_INT(VO_Alarm_List[L_k].Severity) < L_Min_Pri THEN
                L_Min_Pri := TO_INT(VO_Alarm_List[L_k].Severity);
                L_Target_Slot := L_k;
            END_IF;
        END_FOR;
    END_IF;

    // 3. Ищем неквитированную тревогу с наименьшим приоритетом (если он ниже добавляемой)
    IF L_Target_Slot = 0 THEN
        L_Min_Pri := 999;
        FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
            IF TO_INT(VO_Alarm_List[L_k].Severity) < L_Min_Pri AND TO_INT(VO_Alarm_List[L_k].Severity) < TO_INT(L_Pending_Alarms[L_i].Severity) THEN
                L_Min_Pri := TO_INT(VO_Alarm_List[L_k].Severity);
                L_Target_Slot := L_k;
            END_IF;
        END_FOR;
    END_IF;

    IF L_Target_Slot = 0 THEN 
        // Буфер полон критических неквитированных тревог. Не затираем!
        CONTINUE; 
    END_IF;

    VO_Alarm_List[L_Target_Slot] := L_Pending_Alarms[L_i];
    VO_Alarm_List[L_Target_Slot].ID := VIO_Next_Alarm_ID;
    VIO_Next_Alarm_ID := VIO_Next_Alarm_ID + 1;
    IF VIO_Next_Alarm_ID = 0 THEN VIO_Next_Alarm_ID := 1; END_IF;
    IF NOT L_Event_Pulse_Latched THEN
        VO_Event_Pulse := TRUE;
        VO_Event_Code := 1203;
        VO_Event_Value := TO_REAL(VO_Alarm_List[L_Target_Slot].Severity);
        L_Event_Pulse_Latched := TRUE;
    END_IF;
END_FOR;

// 3. Обновление статуса существующих тревог (ушли ли они?)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 THEN
        IF VO_Alarm_List[L_i].Source = 'Gas' THEN VO_Alarm_List[L_i].Is_Active := VI_Gas_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Fire' THEN VO_Alarm_List[L_i].Is_Active := VI_Fire_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Flood' THEN VO_Alarm_List[L_i].Is_Active := VI_Flood_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Security' THEN VO_Alarm_List[L_i].Is_Active := VI_Security_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Diagnostics' THEN VO_Alarm_List[L_i].Is_Active := VI_First_Fault_Active;
        ELSIF VO_Alarm_List[L_i].Source = 'Boiler' THEN 
            IF TO_INT(VO_Alarm_List[L_i].Source_ID) >= 1 AND TO_INT(VO_Alarm_List[L_i].Source_ID) <= GVL_CONSTANTS.C_MAX_BOILERS THEN
                VO_Alarm_List[L_i].Is_Active := VI_Boiler_Errors[TO_INT(VO_Alarm_List[L_i].Source_ID)];
            END_IF;
        END_IF;
    END_IF;
END_FOR;

// 4. Квитирование тревог
IF VI_Acknowledge_All THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF VO_Alarm_List[L_i].ID <> 0 THEN
            VO_Alarm_List[L_i].Is_Acknowledged := TRUE;
        END_IF;
    END_FOR;

    IF NOT L_Event_Pulse_Latched THEN
        VO_Event_Pulse := TRUE;
        VO_Event_Code := 1201;
        VO_Event_Value := TO_REAL(VO_Unacked_Count);
        L_Event_Pulse_Latched := TRUE;
    END_IF;
END_IF;

// 4.5 Автоквитирование некритичных тревог, если они больше не активны
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 AND NOT VO_Alarm_List[L_i].Is_Active AND NOT VO_Alarm_List[L_i].Is_Acknowledged THEN
        IF VO_Alarm_List[L_i].Severity <> E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL THEN
            VO_Alarm_List[L_i].Is_Acknowledged := TRUE;
        END_IF;
    END_IF;
END_FOR;

// 5. Очистка списка (удаление неактивных И квитированных тревог)
// В кольцевом буфере мы просто помечаем слот как пустой (ID = 0), без сдвига массива
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 AND NOT VO_Alarm_List[L_i].Is_Active AND VO_Alarm_List[L_i].Is_Acknowledged THEN
        // Удаляем тревогу
        VO_Alarm_List[L_i].ID := 0;
        IF NOT L_Event_Pulse_Latched THEN
            VO_Event_Pulse := TRUE;
            VO_Event_Code := 1202;
            VO_Event_Value := 0.0;
            L_Event_Pulse_Latched := TRUE;
        END_IF;
    END_IF;
END_FOR;


// 6. Подсчет статистики и формирование глобальных флагов
VO_Global_Critical := FALSE;
VO_Global_Warning := FALSE;
VO_Siren_Active := FALSE;
VO_Active_Count := 0;
VO_Unacked_Count := 0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 THEN
        IF VO_Alarm_List[L_i].Is_Active THEN
            VO_Active_Count := VO_Active_Count + 1;
        END_IF;

        IF NOT VO_Alarm_List[L_i].Is_Acknowledged THEN
            VO_Unacked_Count := VO_Unacked_Count + 1;

            IF VO_Alarm_List[L_i].Severity = E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL THEN
                VO_Global_Critical := TRUE;
                // Сирена работает только для неквитированных критических тревог, если не включен Mute
                IF NOT VI_Mute_Siren THEN
                    VO_Siren_Active := TRUE;
                END_IF;
            ELSIF VO_Alarm_List[L_i].Severity = E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH THEN
                VO_Global_Warning := TRUE;
            END_IF;
        END_IF;
    END_IF;
END_FOR;
// >>> BULK_SYNC_ANCHOR: FB_Alarm_Manager <<<

L_Current_Slot := (VI_Time_Index / (GVL_CONSTANTS.C_MS_IN_MINUTE * 10)) MOD TO_UDINT(GVL_CONSTANTS.C_MAX_PRESENCE_HISTORY);

IF VI_Mode_Record THEN
    GVL_Retain.G_Presence_History[L_Current_Slot] := 0;
    FOR L_i := 1 TO 32 DO
        IF VI_Light_Inputs[L_i] THEN
            GVL_Retain.G_Presence_History[L_Current_Slot] := GVL_Retain.G_Presence_History[L_Current_Slot] OR SHL(WORD#1, L_i-1);
        END_IF;
    END_FOR;
ELSE
    FOR L_i := 1 TO 32 DO
        VO_Light_Outputs[L_i] := (GVL_Retain.G_Presence_History[L_Current_Slot] AND SHL(WORD#1, L_i-1)) <> 0;
    END_FOR;
END_IF;

// ========================================
// Ventilation policy layer
// ========================================
VO_Ventilation_IO_Fault := FALSE;
VO_Ventilation_Subsystem_Degraded := FALSE;
L_Policy_Normal := (VI_System_Mode = E_System_Operating_Mode.MODE_NORMAL);
L_Policy_Safe_Stop := (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
L_Policy_Freeze_Protection := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);

IF NOT VI_IsActivePLC THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
        IF L_i <= GVL_CONSTANTS.C_MAX_SUPPLY_TEMPS THEN
            VO_Heater_Power[L_i] := 0.0;
        END_IF;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 0;
    END_FOR;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: РЕЗЕРВНЫЙ ПЛК';
    RETURN;
END_IF;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        VO_Ventilation_IO_Fault := TRUE;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
            VO_Supply_Fans[L_j] := 0;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
            VO_Exhaust_Fans[L_j] := 0;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
            VO_Heater_Power[L_j] := 0.0;
        END_FOR;
        VO_Status_Msg := 'ОШИБКА: Потеря связи с модулями ввода-вывода';
        RETURN;
    END_IF;
END_FOR;

// =========================
// SYSTEM MODE / HARD REQUEST OVERRIDES
// =========================
IF L_Policy_Safe_Stop OR VI_Vent_Stop THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Heater_Power[L_i] := 0.0;
    END_FOR;
    IF VI_Vent_Stop THEN
        VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: ОСТАНОВЛЕНА ПО КОМАНДЕ';
    ELSE
        VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: ОСТАНОВЛЕНА POLICY SAFE_STOP';
    END_IF;
    RETURN;
END_IF;

IF L_Policy_Degraded THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Heater_Power[L_i] := 0.0;
    END_FOR;
    VO_Ventilation_Subsystem_Degraded := TRUE;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: DEGRADED POLICY';
END_IF;

IF L_Policy_Freeze_Protection THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Heater_Power[L_i] := 0.0;
    END_FOR;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: FREEZE_PROTECTION POLICY (stop)';
    RETURN;
END_IF;

// 1. Определение базовой скорости и целевой температуры по сценарию (ТЗ 7.1)
CASE VI_Current_Scenario OF
    E_SCENARIO_TYPE.SCENARIO_AWAY:
        L_Base_Speed := VI_Config.Scenario_Modes[3].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[3].Target_Temp;
    E_SCENARIO_TYPE.SCENARIO_SLEEP:
        L_Base_Speed := VI_Config.Scenario_Modes[2].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[2].Target_Temp;
    ELSE // PRESENCE, MORNING, EVENING
        L_Base_Speed := VI_Config.Scenario_Modes[1].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[1].Target_Temp;
END_CASE;

// 2. Логика управления приточными установками (П-1, П-2, П-3)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    IF L_i <= GVL_CONSTANTS.C_MAX_SUPPLY_TEMPS THEN
        L_PID_Heaters[L_i](
            VI_SetPoint := L_Target_Temp,
            VI_ProcessValue := VI_Supply_Temps[L_i],
            VI_Kp := 4.0, VI_Tn := 120.0, VI_Tv := 0.0,
            VI_Y_Min := 0.0, VI_Y_Max := 100.0, VI_Cycle_Time_S := 1.0,
            VO_Output => VO_Heater_Power[L_i]
        );
    END_IF;

    VO_Supply_Fans[L_i] := L_Base_Speed;

    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_VENTILATION THEN
                VO_Supply_Fans[L_i] := REAL_TO_BYTE(VI_Rule_Actions[L_j].Value);
            END_IF;
        END_IF;
    END_FOR;
END_FOR;

// 3. Логика управления вытяжными установками (В-1 .. В-5)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    VO_Exhaust_Fans[L_i] := L_Base_Speed;

    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_WET_ZONES DO
        IF VI_Config.wet_zone_to_exhaust_map[L_j] = L_i THEN
            L_Wet_Zone_Timers[L_j](IN := VI_Wet_Zone_Active[L_j], PT := T#5m, VI_System_Time_MS := VI_System_Time_MS);
            IF VI_Wet_Zone_Active[L_j] THEN
                VO_Exhaust_Fans[L_i] := 80;
            ELSIF L_Wet_Zone_Timers[L_j].Q THEN
                VO_Exhaust_Fans[L_i] := 50;
            END_IF;
        END_IF;
    END_FOR;
END_FOR;

// ========================================
// OPERATIONAL REQUEST OVERRIDES
// ========================================
IF VI_Supply_100_Req THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 100;
    END_FOR;
ELSIF VI_Supply_80_Req THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        IF VO_Supply_Fans[L_i] < 80 THEN
            VO_Supply_Fans[L_i] := 80;
        END_IF;
    END_FOR;
END_IF;

IF VI_PV3_Boost_Req THEN
    IF GVL_CONSTANTS.C_MAX_SUPPLY_FANS >= 3 THEN
        VO_Supply_Fans[3] := 100;
    END_IF;
END_IF;

IF VI_Exhaust_100_Req THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 100;
    END_FOR;
END_IF;

// ========================================
// VENT_FINAL_CLAMP
// ========================================
IF L_Policy_Degraded THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := MIN(VO_Exhaust_Fans[L_i], VI_Config.Degraded_Exhaust_Limit);
    END_FOR;
END_IF;

// 4. Формирование статусного сообщения
IF L_Policy_Degraded THEN
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: DEGRADED POLICY';
ELSIF VI_PV3_Boost_Req OR VI_Supply_100_Req OR VI_Exhaust_100_Req OR VI_Supply_80_Req THEN
    VO_Status_Msg := 'Вентиляция: активен операционный boost/request';
ELSE
    VO_Status_Msg := 'Вентиляция работает в штатном режиме';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Ventilation_System_Manager <<<

// 0. Сброс статистики
IF VI_Reset_Stats THEN
    VIO_Health_Data.Starts_Count := 0;
    VIO_Health_Data.Sample_Count := 0;
    VIO_Health_Data.Current_Sum := 0.0;
    VIO_Health_Data.Avg_Start_Current := 0.0;
    VIO_Health_Data.Health_Score := 100;
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := '';
    VIO_Health_Data.Last_Start_Current := 0.0;
    VIO_Health_Data.Total_Runtime_Hours := 0;
    L_Accumulated_MS := 0;
END_IF;

// 1. Счётчик пусков и замер пускового тока
IF VI_Is_Running AND NOT L_Prev_Running THEN
    VIO_Health_Data.Starts_Count := VIO_Health_Data.Starts_Count + 1;
    VIO_Health_Data.Last_Start_Current := VI_Current_Value;
    L_Start_Time := VI_System_Time_MS;
    L_Last_Calc_Time := VI_System_Time_MS;

    // Обновление среднего пускового тока
    VIO_Health_Data.Sample_Count := VIO_Health_Data.Sample_Count + 1;
    VIO_Health_Data.Current_Sum := VIO_Health_Data.Current_Sum + VI_Current_Value;
    VIO_Health_Data.Avg_Start_Current := VIO_Health_Data.Current_Sum / UDINT_TO_REAL(VIO_Health_Data.Sample_Count);

    // 2. Анализ отклонения пускового тока (п. 12.1 ТЗ)
    IF VI_Current_Value > (VI_Nominal_Value * 1.5) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 5, 100));
    ELSIF VI_Current_Value > (VI_Nominal_Value * 1.2) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
    ELSIF VI_Current_Value < (VI_Nominal_Value * 0.5) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 2, 100));
    END_IF;
END_IF;

// 3. Анализ рабочего тока и наработки
IF VI_Is_Running THEN
    L_Elapsed_MS := (VI_System_Time_MS - L_Last_Calc_Time);
    L_Accumulated_MS := L_Accumulated_MS + L_Elapsed_MS;
    L_Last_Calc_Time := VI_System_Time_MS;

    // Обновляем наработку каждый час (3600000 мс)
    IF L_Accumulated_MS >= 3600000 THEN
        VIO_Health_Data.Total_Runtime_Hours := VIO_Health_Data.Total_Runtime_Hours + 1;
        L_Accumulated_MS := L_Accumulated_MS - 3600000;

        // Естественный износ: -1% здоровья каждые 1000 часов
        IF (VIO_Health_Data.Total_Runtime_Hours MOD 1000) = 0 THEN
            VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
        END_IF;

        // Анализ рабочего тока (после пускового режима)
        IF (VI_System_Time_MS - L_Start_Time) > 10000 THEN // 10 секунд после пуска
            IF VI_Current_Value > (VI_Nominal_Value * 1.1) THEN
                // Повышенный рабочий ток - ускоренный износ (-1% в час)
                VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
            END_IF;
        END_IF;
    END_IF;
END_IF;

// 4. Генерация предупреждения
IF VIO_Health_Data.Health_Score < 20 THEN
    VIO_Health_Data.Maintenance_Required := TRUE;
    VIO_Health_Data.Warning_Message := 'Критический износ: проверьте механику';
ELSIF VIO_Health_Data.Health_Score < 60 THEN
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := 'Предупреждение: повышенное трение';
ELSE
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := 'В норме';
END_IF;

L_Prev_Running := VI_Is_Running;

// read real time
L_Real_Now := GVL_STATUS.G_System_Time_MS;

// wrap-safe delta (real time base)
IF L_Real_Now >= GVL_TIME_SERVICE.G_Last_Now_MS THEN
    L_Elapsed := L_Real_Now - GVL_TIME_SERVICE.G_Last_Now_MS;
    GVL_TIME_SERVICE.G_Wrap_Detected := FALSE;
ELSE
    L_Elapsed := (16#FFFFFFFF - GVL_TIME_SERVICE.G_Last_Now_MS) + L_Real_Now + 1;
    GVL_TIME_SERVICE.G_Wrap_Detected := TRUE;
END_IF;

GVL_TIME_SERVICE.G_Last_Now_MS := L_Real_Now;

// --- SIMULATION MODE ---
IF GVL_TIME_SERVICE.G_Sim_Enabled THEN

    IF NOT GVL_TIME_SERVICE.G_Sim_Frozen THEN
        L_Scaled_Delta := REAL_TO_UDINT(TO_REAL(L_Elapsed) * GVL_TIME_SERVICE.G_Sim_Time_Scale);

        GVL_TIME_SERVICE.G_Sim_Now_MS := GVL_TIME_SERVICE.G_Sim_Now_MS + L_Scaled_Delta;

        GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS + L_Scaled_Delta;

        IF GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS >= 86400000 THEN
            GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS MOD 86400000;
            GVL_TIME_SERVICE.G_Sim_Day_Of_Week := GVL_TIME_SERVICE.G_Sim_Day_Of_Week + 1;
            IF GVL_TIME_SERVICE.G_Sim_Day_Of_Week > 7 THEN
                GVL_TIME_SERVICE.G_Sim_Day_Of_Week := 1;
            END_IF;
        END_IF;
    END_IF;

    GVL_TIME_SERVICE.G_Now_MS := GVL_TIME_SERVICE.G_Sim_Now_MS;
    GVL_TIME_SERVICE.G_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Sim_Time_Of_Day_MS;
    GVL_TIME_SERVICE.G_Day_Of_Week := GVL_TIME_SERVICE.G_Sim_Day_Of_Week;

ELSE
    GVL_TIME_SERVICE.G_Now_MS := L_Real_Now;
    GVL_TIME_SERVICE.G_Time_Of_Day_MS := GVL_STATUS.G_Time_Of_Day_MS;
    GVL_TIME_SERVICE.G_Day_Of_Week := TO_INT(GVL_STATUS.G_Current_Day);
END_IF;

// TOD unified
GVL_TIME_SERVICE.G_Current_TOD := UDINT_TO_TOD(GVL_TIME_SERVICE.G_Time_Of_Day_MS);

GVL_TIME_SERVICE.G_Delta_MS := L_Elapsed;

// ======================================================
// MODBUS RTU DRIVER ORCHESTRATION
// ======================================================
// Responsibilities:
//   1. Detect active request.
//   2. Build TX frame.
//   3. Wait for physical RX frame.
//   4. Validate/parse RX frame.
//   5. Apply validated response.
//
// IMPORTANT:
//   Real serial exchange is still external.
//   Concrete RTU/COM implementation must:
//      - send G_TX_Frame
//      - fill G_RX_Frame
//      - set G_RX_Ready
// ======================================================

VO_Driver_Online := FALSE;
VO_Driver_Error := FALSE;
VO_Driver_Error_Code := 0;

GVL_MODBUS_RTU_BRIDGE.G_Driver_Online := FALSE;
GVL_MODBUS_RTU_BRIDGE.G_Driver_Error := FALSE;
GVL_MODBUS_RTU_BRIDGE.G_Driver_Error_Code := 0;

IF NOT VI_Enable THEN

    GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Done := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error := FALSE;
    GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code := 0;

    GVL_MODBUS_RTU_FRAME.G_TX_Ready := FALSE;
    GVL_MODBUS_RTU_FRAME.G_RX_Ready := FALSE;

    L_Exchange_In_Progress := FALSE;

    RETURN;
END_IF;

IF NOT VI_Driver_Attached THEN

    VO_Driver_Error := TRUE;
    VO_Driver_Error_Code := 16#0002;

    GVL_MODBUS_RTU_BRIDGE.G_Driver_Error := TRUE;
    GVL_MODBUS_RTU_BRIDGE.G_Driver_Error_Code := VO_Driver_Error_Code;

    IF GVL_MODBUS_RTU_BRIDGE.G_Request_Valid THEN

        GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Done := FALSE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Error := TRUE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code := VO_Driver_Error_Code;

        GVL_MODBUS_RTU_BRIDGE.G_Response_Sequence :=
            GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence;

        GVL_MODBUS_RTU_BRIDGE.G_Response_Update_MS :=
            VI_System_Time_MS;

    END_IF;

    L_Exchange_In_Progress := FALSE;

    RETURN;
END_IF;

// ======================================================
// REQUEST DETECTION
// ======================================================
L_Request_Active := GVL_MODBUS_RTU_BRIDGE.G_Request_Valid;

IF L_Request_Active THEN

    IF GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence <> L_Last_Sequence THEN

        L_Last_Sequence :=
            GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence;

        L_Exchange_In_Progress := TRUE;

        GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := TRUE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Done := FALSE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Error := FALSE;
        GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code := 0;

        // ==============================================
        // BUILD TX FRAME
        // ==============================================
        FB_TX_Builder(
            VI_Request_Valid := TRUE,
            VI_Slave_ID := GVL_MODBUS_RTU_BRIDGE.G_Request_Slave_ID,
            VI_Function_Code := GVL_MODBUS_RTU_BRIDGE.G_Request_Function_Code,
            VI_Start_Register := GVL_MODBUS_RTU_BRIDGE.G_Request_Start_Register,
            VI_Register_Count := GVL_MODBUS_RTU_BRIDGE.G_Request_Register_Count,
            VI_Write_Value := GVL_MODBUS_RTU_BRIDGE.G_Request_Write_Value
        );

        IF FB_TX_Builder.VO_Error THEN

            GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;
            GVL_MODBUS_RTU_BRIDGE.G_Response_Done := FALSE;
            GVL_MODBUS_RTU_BRIDGE.G_Response_Error := TRUE;
            GVL_MODBUS_RTU_BRIDGE.G_Response_Error_Code :=
                FB_TX_Builder.VO_Error_Code;

            GVL_MODBUS_RTU_BRIDGE.G_Response_Sequence :=
                GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence;

            GVL_MODBUS_RTU_BRIDGE.G_Response_Update_MS :=
                VI_System_Time_MS;

            L_Exchange_In_Progress := FALSE;

            RETURN;

        END_IF;

        GVL_MODBUS_RTU_FRAME.G_TX_Frame :=
            FB_TX_Builder.VO_Frame;

        GVL_MODBUS_RTU_FRAME.G_TX_Ready := TRUE;
        GVL_MODBUS_RTU_FRAME.G_Last_TX_MS := VI_System_Time_MS;

    END_IF;

END_IF;

// ======================================================
// RX FRAME AVAILABLE
// ======================================================
IF L_Exchange_In_Progress AND
   GVL_MODBUS_RTU_FRAME.G_RX_Ready THEN

    // ==================================================
    // PARSE RX FRAME
    // ==================================================
    FB_RX_Parser(
        VI_Frame := GVL_MODBUS_RTU_FRAME.G_RX_Frame,
        VI_Expected_Slave_ID :=
            GVL_MODBUS_RTU_BRIDGE.G_Request_Slave_ID,
        VI_Expected_Function :=
            GVL_MODBUS_RTU_BRIDGE.G_Request_Function_Code
    );

    // ==================================================
    // APPLY RESPONSE
    // ==================================================
    FB_Response_Apply(
        VI_Request_Valid := TRUE,
        VI_Request_Index := GVL_MODBUS_RTU_BRIDGE.G_Request_Index,
        VI_Request_Sequence :=
            GVL_MODBUS_RTU_BRIDGE.G_Request_Sequence,
        VI_Parser_Valid := FB_RX_Parser.VO_Valid,
        VI_Parser_Error := FB_RX_Parser.VO_Error,
        VI_Parser_Error_Code := FB_RX_Parser.VO_Error_Code,
        VI_Register_Count := FB_RX_Parser.VO_Register_Count,
        VI_Register_Value := FB_RX_Parser.VO_Register_Value,
        VI_System_Time_MS := VI_System_Time_MS
    );

    IF FB_Response_Apply.VO_Response_Applied THEN

        L_Last_Success_MS := VI_System_Time_MS;

        GVL_MODBUS_RTU_FRAME.G_RX_Ready := FALSE;

        L_Exchange_In_Progress := FALSE;

    END_IF;

END_IF;

// ======================================================
// DRIVER ONLINE STATE
// ======================================================
IF (L_Last_Success_MS > 0) AND
   ((VI_System_Time_MS - L_Last_Success_MS) <
    GVL_CONFIG.G_OpenTherm_Heartbeat_Timeout_MS) THEN

    VO_Driver_Online := TRUE;

    GVL_MODBUS_RTU_BRIDGE.G_Driver_Online := TRUE;

END_IF;

// ======================================================
// CLEAR IDLE BUSY STATE
// ======================================================
IF NOT L_Request_Active THEN

    GVL_MODBUS_RTU_BRIDGE.G_Response_Busy := FALSE;

    L_Exchange_In_Progress := FALSE;

END_IF;

IF VI_Value >= VI_Min_Valid AND VI_Value <= VI_Max_Valid THEN
    VO_Error := FALSE;
    VO_Value := VI_Value;
    L_Last_Good_Value := VI_Value;
    L_First_Valid := TRUE;
ELSE
    VO_Error := TRUE;
    IF VI_Fallback_Mode = 1 OR NOT L_First_Valid THEN
        VO_Value := VI_Default_Value;
    ELSE
        VO_Value := L_Last_Good_Value;
    END_IF;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Analog_Validator <<<

// Вычисление времени цикла
IF L_Last_Time = 0 THEN
    L_Last_Time := VI_System_Time_MS;
    L_Cycle_Time_S := 1.0;
ELSE
    L_Cycle_Time_S := UDINT_TO_REAL((SEL(VI_System_Time_MS >= L_Last_Time, VI_System_Time_MS - L_Last_Time, (4294967295 - L_Last_Time) + VI_System_Time_MS + 1))) / 1000.0;
    L_Last_Time := VI_System_Time_MS;
END_IF;
IF L_Cycle_Time_S <= 0.0 THEN L_Cycle_Time_S := 0.01; END_IF;

// 1. Определение активного тарифа
IF VI_Tariff.Enabled THEN
    IF VI_Tariff.Night_Start_Hour > VI_Tariff.Night_End_Hour THEN
        // Переход через полночь (например, 23:00 - 07:00)
        L_Is_Night := (VI_Current_Hour >= VI_Tariff.Night_Start_Hour) OR (VI_Current_Hour < VI_Tariff.Night_End_Hour);
    ELSE
        // В пределах одного дня
        L_Is_Night := (VI_Current_Hour >= VI_Tariff.Night_Start_Hour) AND (VI_Current_Hour < VI_Tariff.Night_End_Hour);
    END_IF;
ELSE
    L_Is_Night := FALSE;
END_IF;

// 2. Расчет эффективной уставки
VO_Effective_Setpoint := VI_Config.design_temp;
IF L_Is_Night THEN
    VO_Effective_Setpoint := VO_Effective_Setpoint + VI_Tariff.Boost_Delta;
END_IF;

// 3. ПИД-регулирование
L_PID(
    VI_SetPoint := VO_Effective_Setpoint,
    VI_ProcessValue := VI_Current_Temp,
    VI_Kp := VI_Config.pid_kp,
    VI_Tn := 300.0,
    VI_Tv := 0.0,
    VI_Y_Min := 0.0,
    VI_Y_Max := 100.0,
    VI_Cycle_Time_S := L_Cycle_Time_S,
    VO_Output => VO_Valve_Pos
);

// 4. ШИМ-модуляция для термоэлектрического привода
IF VI_Config.pwm_period_s > 0 THEN
    L_PWM_Period_MS := TO_UDINT(VI_Config.pwm_period_s) * 1000;
ELSE
    L_PWM_Period_MS := 600000; // 10 минут
END_IF;

L_Current_Phase_MS := (SEL(VI_System_Time_MS >= L_PWM_Start_Time, VI_System_Time_MS - L_PWM_Start_Time, (4294967295 - L_PWM_Start_Time) + VI_System_Time_MS + 1));
IF L_Current_Phase_MS >= L_PWM_Period_MS THEN
    L_PWM_Start_Time := VI_System_Time_MS - (L_Current_Phase_MS - L_PWM_Period_MS); // Сохраняем остаток для точности
    L_Current_Phase_MS := (SEL(VI_System_Time_MS >= L_PWM_Start_Time, VI_System_Time_MS - L_PWM_Start_Time, (4294967295 - L_PWM_Start_Time) + VI_System_Time_MS + 1));
END_IF;

L_PWM_Duty_MS := TO_UDINT((VO_Valve_Pos / 100.0) * TO_REAL(L_PWM_Period_MS));

IF VI_IsActivePLC THEN
    VO_Pump_Run := (VO_Valve_Pos > 5.0);

    IF VO_Valve_Pos >= 100.0 THEN
        VO_Valve_Bool := TRUE;
    ELSIF VO_Valve_Pos <= 0.0 THEN
        VO_Valve_Bool := FALSE;
    ELSE
        VO_Valve_Bool := (L_Current_Phase_MS <= L_PWM_Duty_MS);
    END_IF;
ELSE
    VO_Pump_Run := FALSE;
    VO_Valve_Bool := FALSE;
END_IF;

// ==============================================================================
// Heating runtime observer authorization
// Governed passive-bootstrap authorization only.
// Read-only.
// Deterministic.
// ==============================================================================



// ======================================================
// DEFAULTS
// ======================================================
VO_Enable_Authorized := FALSE;
VO_Enable_Effective := FALSE;
VO_Authorization_Valid := FALSE;

VO_Status_Code := 0;
VO_Status_Text := 'Heating runtime observer authorization inactive';

// ======================================================
// REQUEST VALIDATION
// ======================================================
IF NOT VI_Enable_Request THEN
    RETURN;
END_IF;

// ======================================================
// GOVERNANCE VALIDATION
// ======================================================
IF NOT VI_Bootstrap_Mode THEN
    VO_Status_Code := 100;
    VO_Status_Text := 'Bootstrap mode required for observer authorization';
    RETURN;
END_IF;

IF NOT VI_Passive_Mode THEN
    VO_Status_Code := 110;
    VO_Status_Text := 'Passive mode required for observer authorization';
    RETURN;
END_IF;

IF NOT VI_ReadOnly_Mode THEN
    VO_Status_Code := 120;
    VO_Status_Text := 'Read-only mode required for observer authorization';
    RETURN;
END_IF;

IF NOT VI_Governance_Locked THEN
    VO_Status_Code := 130;
    VO_Status_Text := 'Governance lock required for observer authorization';
    RETURN;
END_IF;

IF NOT VI_Runtime_Authority_Disabled THEN
    VO_Status_Code := 140;
    VO_Status_Text := 'Runtime authority isolation required';
    RETURN;
END_IF;

IF NOT VI_Writable_Exports_Disabled THEN
    VO_Status_Code := 150;
    VO_Status_Text := 'Writable exports must remain disabled';
    RETURN;
END_IF;

// ======================================================
// AUTHORIZED PASSIVE BOOTSTRAP ACTIVATION
// ======================================================
VO_Enable_Authorized := TRUE;
VO_Enable_Effective := TRUE;
VO_Authorization_Valid := TRUE;

VO_Status_Code := 1;
VO_Status_Text := 'Heating runtime observer authorization granted';

// >>> BULK_SYNC_ANCHOR: FB_Heating_Runtime_Observer_Authorization <<<

// ==============================================================================
// Heating boiler control helper
// ==============================================================================



VO_Any_Subsystem_Degraded := FALSE;
VO_Demand_Power := 0.0;

L_Available_Count := 0;
L_Active_Count := 0;
L_Any_Transport_Degraded := FALSE;
L_Any_Ignition_Timeout := FALSE;
L_Any_Flame := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VI_Manifold_Pumps[L_i] THEN
        VO_Demand_Power := VO_Demand_Power + VI_Manifold_Valves[L_i];
    END_IF;
END_FOR;

IF VI_Freeze_Mode_Active AND VO_Demand_Power < 20.0 THEN
    VO_Demand_Power := 20.0;
END_IF;

IF VI_Policy_Degraded THEN
    IF VO_Demand_Power > 60.0 THEN
        VO_Demand_Power := 60.0;
    END_IF;
END_IF;

fbBoilerCascade(
    VI_Enable := VI_IsActivePLC AND ((VO_Demand_Power > GVL_CONSTANTS.C_BOILER_CASCADE_MIN_DEMAND) OR VI_Freeze_Mode_Active OR VI_DHW_Heating_Demand),
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Boiler_Stop := FALSE,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_DHW_Target_Temp := VI_DHW_Target_Temp,
    VI_Target_Supply_Temp := VI_Target_Supply_Temp,
    VI_Demand_Power := VO_Demand_Power,
    VI_Boiler_Flame_Status := VI_Boiler_Flame_Status,
    VI_Boiler_Error_Status := VI_Boiler_Error_Status,
    VI_Boiler_OT_Online := VI_Boiler_OT_Online,
    VI_Boiler_Modulation := VI_Boiler_Modulation,
    VO_Boiler_Enable => L_Boiler_Request_Enable,
    VO_Boiler_Setpoint => L_Boiler_Request_Setpoint,
    VO_Lead_Boiler => VO_Lead_Boiler
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF L_Boiler_Request_Enable[L_i] THEN
        L_Boiler_Request_Setpoint[L_i] := LIMIT(
            GVL_CONSTANTS.C_BOILER_SETPOINT_MIN,
            L_Boiler_Request_Setpoint[L_i],
            80.0
        );
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF NOT VI_Boiler_OT_Online[L_i] OR VI_Boiler_Error_Status[L_i] THEN
        L_Boiler_Request_Enable[L_i] := FALSE;
        L_Boiler_Request_Setpoint[L_i] := 0.0;
    END_IF;
END_FOR;

fbBoilerOpenTherm(
    VI_Enable := L_Boiler_Request_Enable,
    VI_Setpoint := L_Boiler_Request_Setpoint,
    VI_OT_Online := VI_Boiler_OT_Online,
    VI_OT_Error := VI_Boiler_Error_Status,
    VO_OT_Enable => VO_Boiler_OT_Enable,
    VO_OT_Setpoint => VO_Boiler_OT_Setpoint,
    VO_OT_Command_Valid => L_Boiler_OT_Command_Valid
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO

    L_Transport_Degraded :=
        L_Boiler_Request_Enable[L_i] AND
        (
            NOT L_Boiler_OT_Command_Valid[L_i] OR
            NOT VI_Boiler_OT_Online[L_i] OR
            VI_Boiler_Error_Status[L_i]
        );

    VO_Boiler_Status[L_i].OT_Online := VI_Boiler_OT_Online[L_i];
    VO_Boiler_Status[L_i].OT_Command_Valid := L_Boiler_OT_Command_Valid[L_i];
    VO_Boiler_Status[L_i].OT_Transport_Degraded := L_Transport_Degraded;
    VO_Boiler_Status[L_i].OT_Adapter_Error :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Error;

    VO_Boiler_Status[L_i].Active := L_Boiler_Request_Enable[L_i];
    VO_Boiler_Status[L_i].Running := VI_Boiler_Flame_Status[L_i];
    VO_Boiler_Status[L_i].Warning := L_Transport_Degraded;
    VO_Boiler_Status[L_i].Error := VI_Boiler_Error_Status[L_i];

    VO_Boiler_Status[L_i].Available :=
        VI_Boiler_OT_Online[L_i] AND
        NOT VI_Boiler_Error_Status[L_i] AND
        NOT L_Transport_Degraded;

    VO_Boiler_Status[L_i].Selected_By_Cascade :=
        L_Boiler_Request_Enable[L_i];

    VO_Boiler_Status[L_i].Transport_Missing :=
        NOT VI_Boiler_OT_Online[L_i];

    VO_Boiler_Status[L_i].Flame_Missing :=
        L_Boiler_Request_Enable[L_i] AND
        NOT VI_Boiler_Flame_Status[L_i] AND
        NOT L_Transport_Degraded;

    VO_Boiler_Status[L_i].Ignition_Timeout :=
        VO_Boiler_Status[L_i].Flame_Missing AND
        (GVL_STATE.G_Boiler_OT_Command_Age_MS[L_i] > 30000);

    VO_Boiler_Status[L_i].Degraded :=
        L_Transport_Degraded OR
        VO_Boiler_Status[L_i].Ignition_Timeout;

    // ======================================================
    // CASCADE AGGREGATION
    // ======================================================
    IF VO_Boiler_Status[L_i].Available THEN
        L_Available_Count := L_Available_Count + 1;
    END_IF;

    IF VO_Boiler_Status[L_i].Selected_By_Cascade THEN
        L_Active_Count := L_Active_Count + 1;
    END_IF;

    IF VI_Boiler_Flame_Status[L_i] THEN
        L_Any_Flame := TRUE;
    END_IF;

    IF L_Transport_Degraded THEN
        L_Any_Transport_Degraded := TRUE;
    END_IF;

    IF VO_Boiler_Status[L_i].Ignition_Timeout THEN
        L_Any_Ignition_Timeout := TRUE;
    END_IF;

    IF VO_Boiler_Status[L_i].Degraded THEN
        VO_Any_Subsystem_Degraded := TRUE;
    END_IF;

END_FOR;

// ======================================================
// GLOBAL CASCADE SEMANTIC STATE
// ======================================================
GVL_STATE.G_Heating_Cascade_Active_Boilers := L_Active_Count;
GVL_STATE.G_Heating_Cascade_Available_Boilers := L_Available_Count;

GVL_STATE.G_Heating_Cascade_Available :=
    (L_Available_Count > 0);

GVL_STATE.G_Heating_Cascade_Partial_Capacity :=
    (L_Available_Count > 0) AND
    (L_Available_Count < GVL_CONSTANTS.C_MAX_BOILERS);

GVL_STATE.G_Heating_Cascade_Transport_Degraded :=
    L_Any_Transport_Degraded;

GVL_STATE.G_Heating_Cascade_Ignition_Timeout :=
    L_Any_Ignition_Timeout;

GVL_STATE.G_Heating_Cascade_No_Flame :=
    (L_Active_Count > 0) AND
    NOT L_Any_Flame;

GVL_STATE.G_Heating_Cascade_Degraded :=
    GVL_STATE.G_Heating_Cascade_Transport_Degraded OR
    GVL_STATE.G_Heating_Cascade_Ignition_Timeout OR
    GVL_STATE.G_Heating_Cascade_Partial_Capacity;

IF NOT L_Initialized THEN
    L_Initialized := TRUE;
    L_Last_Call_MS := VI_System_Time_MS;
    VO_Cycle_DT_MS := 0;
    VO_Watchdog_Fault := FALSE;
    VO_Alive := TRUE;
    RETURN;
END_IF;

// Measure real time gap between successive calls
L_DT_MS := (SEL(VI_System_Time_MS >= L_Last_Call_MS, VI_System_Time_MS - L_Last_Call_MS, (4294967295 - L_Last_Call_MS) + VI_System_Time_MS + 1));
VO_Cycle_DT_MS := L_DT_MS;

// Fault if the task/cycle resumed after an abnormal pause
VO_Watchdog_Fault := (L_DT_MS > VI_Timeout_MS);
VO_Alive := NOT VO_Watchdog_Fault;

// Store current timestamp for next cycle
L_Last_Call_MS := VI_System_Time_MS;
// >>> BULK_SYNC_ANCHOR: FB_Watchdog <<<

FOR L_i := 1 TO 32 DO
    GVL_WATER_OUTPUT.DO_Water_Zone_Enable[L_i] := VI_Zone_Enable[L_i];
END_FOR;

GVL_WATER_OUTPUT.DO_Water_Valve_35_Close := VI_Valve_35_Close;
GVL_WATER_OUTPUT.DO_Water_Valve_36_Close := VI_Valve_36_Close;

// >>> BULK_SYNC_ANCHOR: FB_Water_Output_Projection <<<

// >>> SYNC_TEST_MARKER_001 <<<


IF NOT VI_IsActivePLC THEN RETURN; END_IF;


GVL_STATE.G_DHW_IO_Fault := FALSE;
GVL_STATE.G_DHW_Sensor_Fault := FALSE;
GVL_STATE.G_DHW_Subsystem_Degraded := FALSE;

IF VI_Emergency_Stop THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    VO_Status.Warning := FALSE;
    VO_Status.Error := TRUE;
    VO_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_DHW_IO_OFFLINE); // временно используем общий аварийный код до детализации safety-кодов
    VO_Status.Heating_Pump_On := FALSE;
    VO_Status.Circ_Pump_On := FALSE;
    RETURN;
END_IF;

// Фиксация текущего времени
L_Current_TOD := VI_Current_TOD;

// ========================================
// DHW POLICY LAYER
// ========================================
L_Policy_Safe_Stop := (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
L_Policy_Freeze_Protection := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);
L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
L_Target_Temp_Adjusted := VI_Config.Target_Temp;
IF L_Policy_Degraded THEN
    L_Target_Temp_Adjusted := VI_Config.Target_Temp - VI_Config.Degraded_Target_Delta;
END_IF;

// ========================================
// DHW POLICY OVERRIDE
// ========================================
IF L_Policy_Safe_Stop THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    RETURN;
END_IF;

IF L_Policy_Freeze_Protection THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    RETURN;
END_IF;

// Сброс признака выполнения термодезинфекции при смене дня.
IF L_Last_Legionella_Day <> VI_Current_Day_Of_Week THEN
    L_Legionella_Done_Today := FALSE;
    L_Last_Legionella_Day := VI_Current_Day_Of_Week;
END_IF;

// Базовый сброс незащёлкнутых статусных флагов на текущий цикл.
// Критические ошибки ниже могут зафиксироваться и завершить выполнение через RETURN.
VO_Status.Warning := FALSE;
VO_Status.Error := FALSE;
VO_Status.Error_ID := 0;

// Сброс ошибок
IF VI_Reset_Errors THEN
    L_Error_Latched := FALSE;
    L_Error_ID_Latched := 0;
END_IF;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        L_Error_Latched := TRUE;
        GVL_STATE.G_DHW_IO_Fault := TRUE;
        L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_IO_OFFLINE); // Потеря связи с модулями ввода-вывода
    END_IF;
END_FOR;

// 1. Обработка неисправностей датчиков и сервисных режимов (ТЗ 7.0)
fbTempValidator(
    VI_Value := VI_Temp,
    VI_Min_Valid := 0.0,
    VI_Max_Valid := 100.0,
    VI_Fallback_Mode := 0,
    VI_Default_Value := 55.0
);

fbPressValidator(
    VI_Value := VI_Pressure,
    VI_Min_Valid := 0.0,
    VI_Max_Valid := 10.0,
    VI_Fallback_Mode := 0
);

VO_Status.Temp := fbTempValidator.VO_Value;
VO_Status.Pressure := fbPressValidator.VO_Value;

// Сохраняем последнее достоверное значение температуры ГВС.
// Используется только для диагностики/сервиса, не для fallback-управления.
IF NOT fbTempValidator.VO_Error THEN
    L_Last_Good_Temp := VO_Status.Temp;
END_IF;

IF fbTempValidator.VO_Error THEN
    GVL_STATE.G_DHW_Sensor_Fault := TRUE;
    L_Error_Latched := TRUE;
    L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_TEMP_SENSOR_FAULT); // Критическая ошибка датчика температуры
ELSIF (VO_Status.Pressure < 1.0 OR VO_Status.Pressure > 4.0) AND NOT fbPressValidator.VO_Error THEN
    L_Error_Latched := TRUE;
    L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_PRESSURE_OUT_OF_RANGE); // Давление вне нормы
END_IF;

IF L_Error_Latched THEN
    // Критическая ошибка: переход в безопасное состояние с полной остановкой насосов.
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    VO_Status.Warning := FALSE;
    VO_Status.Error := TRUE;
    VO_Status.Error_ID := L_Error_ID_Latched;
    VO_Status.Heating_Pump_On := FALSE;
    VO_Status.Circ_Pump_On := FALSE;
    RETURN;
END_IF;

// Ошибка датчика давления не останавливает ГВС,
// но переводит подсистему в режим предупреждения (degraded mode).
IF fbPressValidator.VO_Error THEN
    GVL_STATE.G_DHW_Sensor_Fault := TRUE;
    GVL_STATE.G_DHW_Subsystem_Degraded := TRUE;
    VO_Status.Warning := TRUE;
    VO_Status.Error := FALSE;
    VO_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_DHW_PRESSURE_SENSOR_FAULT);
END_IF;

// 2. Логика поддержания температуры воды в бойлере (Нагрев)
// На этом этапе FB уже выполняется только на активном ПЛК.

// Термическая дезинфекция (Легионелла)
IF VI_Config.Anti_Legionella_Enabled
   AND (VI_Current_Day_Of_Week = VI_Config.Anti_Legionella_Day)
   AND (L_Current_TOD >= TOD#02:00)
   AND (L_Current_TOD <= TOD#04:00)
   AND NOT L_Legionella_Done_Today THEN
    L_Legionella_Active := TRUE;
ELSE
    L_Legionella_Active := FALSE;
END_IF;

L_Legionella_Timer(IN := L_Legionella_Active AND VO_Status.Temp >= 70.0, PT := T#30m, VI_System_Time_MS := VI_System_Time_MS);
IF L_Legionella_Timer.Q THEN
    L_Legionella_Active := FALSE; // Дезинфекция завершена
    L_Legionella_Done_Today := TRUE; // Повторно в те же сутки не запускать
END_IF;

// Двухпозиционное регулирование с гистерезисом
IF L_Legionella_Active THEN
    IF VO_Status.Temp < 70.0 THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > 72.0 THEN
        VO_Heating_Pump := FALSE;
    END_IF;
ELSE
    IF VO_Status.Temp < (L_Target_Temp_Adjusted - VI_Config.Hysteresis) THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > (L_Target_Temp_Adjusted + VI_Config.Hysteresis) THEN
        VO_Heating_Pump := FALSE;
    END_IF;
END_IF;

// 3. Управление циркуляционным насосом ГВС по расписанию
// Рециркуляция обеспечивает мгновенное наличие горячей воды у потребителя
VO_Circ_Pump := SEL(VI_Config.Circulation_Schedule_Enabled AND NOT (VI_Config.Night_Mode_Enabled AND (L_Current_TOD < VI_Config.Circulation_Start OR L_Current_TOD > VI_Config.Circulation_End)), FALSE, TRUE);

// Формирование статусных данных для визуализации.
// К этому моменту статус уже консистентен:
// - Error = критическая ошибка с остановкой ГВС
// - Warning = деградация без остановки
VO_Status.Heating_Pump_On := VO_Heating_Pump;
VO_Status.Circ_Pump_On := VO_Circ_Pump;

// >>> BULK_SYNC_ANCHOR: FB_DHW_Manager <<<

// ======================================================
// MODBUS RTU RX FRAME PARSER
// ======================================================

VO_Valid := FALSE;
VO_Error := FALSE;
VO_Error_Code := 0;
VO_Exception_Response := FALSE;
VO_Register_Count := 0;

FOR L_i := 1 TO 32 DO
    VO_Register_Value[L_i] := 0;
END_FOR;

IF NOT VI_Frame.Valid THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0201;
    RETURN;
END_IF;

IF VI_Frame.Length < 5 THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0202;
    RETURN;
END_IF;

CASE VI_Expected_Function OF
    MB_FC03_READ_HOLDING_REGISTERS:
        L_Expected_Function := 3;
    MB_FC04_READ_INPUT_REGISTERS:
        L_Expected_Function := 4;
    MB_FC06_WRITE_SINGLE_REGISTER:
        L_Expected_Function := 6;
    MB_FC16_WRITE_MULTIPLE_REGISTERS:
        L_Expected_Function := 16;
ELSE
    VO_Error := TRUE;
    VO_Error_Code := 16#0203;
    RETURN;
END_CASE;

// ======================================================
// CRC VALIDATION
// ======================================================
L_CRC_Frame :=
    BYTE_TO_WORD(VI_Frame.Data[VI_Frame.Length - 2]) OR
    SHL(BYTE_TO_WORD(VI_Frame.Data[VI_Frame.Length - 1]), 8);

L_CRC_Calc := 16#FFFF;

FOR L_i := 0 TO (VI_Frame.Length - UINT#3) DO

    L_CRC_Calc := L_CRC_Calc XOR BYTE_TO_WORD(VI_Frame.Data[L_i]);

    FOR L_j := 0 TO 7 DO
        IF (L_CRC_Calc AND 16#0001) <> 0 THEN
            L_CRC_Calc := SHR(L_CRC_Calc, 1);
            L_CRC_Calc := L_CRC_Calc XOR 16#A001;
        ELSE
            L_CRC_Calc := SHR(L_CRC_Calc, 1);
        END_IF;
    END_FOR;

END_FOR;

IF L_CRC_Calc <> L_CRC_Frame THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0204;
    RETURN;
END_IF;

IF VI_Frame.Data[0] <> VI_Expected_Slave_ID THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0205;
    RETURN;
END_IF;

L_Function_Byte := VI_Frame.Data[1];

IF L_Function_Byte = (L_Expected_Function OR 16#80) THEN
    VO_Exception_Response := TRUE;
    VO_Error := TRUE;
    VO_Error_Code := 16#0206;
    RETURN;
END_IF;

IF L_Function_Byte <> L_Expected_Function THEN
    VO_Error := TRUE;
    VO_Error_Code := 16#0207;
    RETURN;
END_IF;

CASE VI_Expected_Function OF

    MB_FC03_READ_HOLDING_REGISTERS,
    MB_FC04_READ_INPUT_REGISTERS:

        L_Byte_Count := VI_Frame.Data[2];

        IF (L_Byte_Count = 0) OR ((L_Byte_Count MOD 2) <> 0) THEN
            VO_Error := TRUE;
            VO_Error_Code := 16#0208;
            RETURN;
        END_IF;

        VO_Register_Count := L_Byte_Count / 2;

        IF VO_Register_Count > 32 THEN
            VO_Error := TRUE;
            VO_Error_Code := 16#0209;
            RETURN;
        END_IF;

        L_Data_Index := 3;

        FOR L_i := 1 TO VO_Register_Count DO

            VO_Register_Value[L_i] :=
                SHL(BYTE_TO_WORD(VI_Frame.Data[L_Data_Index]), 8) OR
                BYTE_TO_WORD(VI_Frame.Data[L_Data_Index + 1]);

            L_Data_Index := L_Data_Index + 2;

        END_FOR;

    MB_FC06_WRITE_SINGLE_REGISTER,
    MB_FC16_WRITE_MULTIPLE_REGISTERS:

        VO_Register_Count := 0;

ELSE
    VO_Error := TRUE;
    VO_Error_Code := 16#020A;
    RETURN;
END_CASE;

VO_Valid := TRUE;

IF NOT GVL_BEHAVIOR_ADAPT.G_Adapt_Enabled THEN RETURN; END_IF;

idx := USINT_TO_INT(iScenario);

L_Stats := GVL_BEHAVIOR_ADAPT.G_Scenario_Stats[idx];
L_Stats.Activations := L_Stats.Activations + 1;

IF iSuccess THEN
    L_Stats.Success_Count := L_Stats.Success_Count + 1;
ELSE
    L_Stats.Failure_Count := L_Stats.Failure_Count + 1;
END_IF;

IF L_Stats.Activations > 0 THEN
    L_Stats.Success_Rate := UDINT_TO_REAL(L_Stats.Success_Count) / UDINT_TO_REAL(L_Stats.Activations);
END_IF;

IF (iScenario = REASON_SCENARIO_VENT_BOOST) AND (iZone >= 1) AND (iZone <= GVL_CONSTANTS.C_MAX_ZONES) THEN

    L_Zone := GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[iZone];

    IF L_Zone.Zone_Weight = 0.0 THEN
        L_Zone.Zone_Weight := GVL_BEHAVIOR_ADAPT.G_Adapt_Default_Zone_Weight;
    END_IF;

    L_Decay := GVL_BEHAVIOR_ADAPT.G_Decay_Factor;
    L_Zone.Zone_Weight := L_Zone.Zone_Weight * L_Decay;
    L_Zone.Confidence := L_Zone.Confidence * L_Decay;

    L_Zone.Activations := L_Zone.Activations + 1;

    IF iSuccess THEN
        L_Zone.Success_Count := L_Zone.Success_Count + 1;
    ELSE
        L_Zone.Failure_Count := L_Zone.Failure_Count + 1;
    END_IF;

    IF L_Zone.Activations > 0 THEN
        L_Zone.Success_Rate := UDINT_TO_REAL(L_Zone.Success_Count) / UDINT_TO_REAL(L_Zone.Activations);
    END_IF;

    IF iConfidence >= GVL_BEHAVIOR_ADAPT.G_Adapt_Min_Confidence THEN
        L_Zone.Confidence := L_Zone.Confidence +
            (iConfidence - L_Zone.Confidence) * GVL_BEHAVIOR_ADAPT.G_Confidence_Learning_Rate;
    END_IF;

    IF (GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold > 0) AND
       ((L_Zone.Activations MOD INT_TO_UDINT(GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold)) = 0) THEN

        L_Adjustment :=
            (L_Zone.Success_Rate - 0.5)
            * GVL_BEHAVIOR_ADAPT.G_Adapt_Learning_Rate
            * L_Zone.Confidence;

        L_Zone.Zone_Weight := LIMIT(0.5, L_Zone.Zone_Weight + L_Adjustment, 2.0);

    END_IF;

    L_Zone.Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

    GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[iZone] := L_Zone;

END_IF;

GVL_BEHAVIOR_ADAPT.G_Scenario_Stats[idx] := L_Stats;

