// ==============================================================================
// System intent publisher helper
//
// Internal helper for PRG_System.
// Owns publication of system-mode gates into GVL_INTENT_SYSTEM.
// ==============================================================================



GVL_INTENT_SYSTEM.I_Source_Valid := TRUE;
GVL_INTENT_SYSTEM.I_Last_Update_MS := VI_System_Time_MS;
GVL_INTENT_SYSTEM.I_Mode_Safe_Stop_Active := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Mode_Degraded_Active := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
GVL_INTENT_SYSTEM.I_Mode_Freeze_Protection_Active := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);
GVL_INTENT_SYSTEM.I_Operator_Scenario_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Lighting_Overrides_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Blinds_Overrides_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Socket_Overrides_Block := (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
GVL_INTENT_SYSTEM.I_Gateway_Writes_Allowed := VI_Gateway_Writes_Allowed;
GVL_INTENT_SYSTEM.I_Scenario_Request_Allowed := (GVL_STATE.G_System_Mode <> E_System_Operating_Mode.MODE_SAFE_STOP);

// >>> BULK_SYNC_ANCHOR: FB_System_Intent_Publisher <<<

// ==============================================================================
// Heating policy priority bridge
//
// Bounded mapper from advisory zone policy to manifold allocation priority.
//
// IMPORTANT:
// - does NOT own demand;
// - does NOT create demand;
// - does NOT control pumps/valves;
// - does NOT write outputs;
// - does NOT bypass safety or service gates.
//
// Responsibility:
// - map circuit->zone policy bias into manifold effective priority;
// - keep the result bounded and deterministic;
// - provide a safe input for FB_Heating_Allocation_Filter.
// ==============================================================================



// Default passthrough state.
VO_Bridge_Active := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    VO_Manifold_Effective_Priority[L_i] := VI_Manifold_Base_Priority[L_i];
    VO_Manifold_Priority_Bias_Applied[L_i] := REAL#1.0;
    L_MaxScore[L_i] := REAL#0.0;
    L_HasActiveCircuit[L_i] := FALSE;
END_FOR;

IF NOT VI_Enable THEN
    RETURN;
END_IF;

L_Multiplier := VI_Policy_Priority_Multiplier;
IF L_Multiplier <= REAL#0.0 THEN
    L_Multiplier := REAL#1.0;
ELSIF L_Multiplier < REAL#0.3 THEN
    L_Multiplier := REAL#0.3;
ELSIF L_Multiplier > REAL#1.0 THEN
    L_Multiplier := REAL#1.0;
END_IF;

IF ABS(L_Multiplier - REAL#1.0) > REAL#0.001 THEN
    VO_Bridge_Active := TRUE;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VI_Zone_Valves[L_i] THEN
        L_Manifold_ID := TO_INT(VI_Zone_Configs[L_i].manifold_id);
        L_Zone_ID := TO_INT(VI_Zone_Configs[L_i].zone);

        IF (L_Manifold_ID >= 1)
           AND (L_Manifold_ID <= GVL_CONSTANTS.C_MAX_MANIFOLDS)
           AND (L_Zone_ID >= 1)
           AND (L_Zone_ID <= GVL_CONSTANTS.C_MAX_ZONES) THEN

            L_Bias := VI_Zone_Priority_Bias[L_Zone_ID];
            IF L_Bias <= REAL#0.0 THEN
                // Uninitialized advisory bias is treated as neutral.
                L_Bias := REAL#1.0;
            ELSIF L_Bias < REAL#0.3 THEN
                L_Bias := REAL#0.3;
            ELSIF L_Bias > REAL#1.5 THEN
                L_Bias := REAL#1.5;
            END_IF;

            IF ABS(L_Bias - REAL#1.0) > REAL#0.001 THEN
                VO_Bridge_Active := TRUE;
            END_IF;

            IF L_Bias > VO_Manifold_Priority_Bias_Applied[L_Manifold_ID] THEN
                VO_Manifold_Priority_Bias_Applied[L_Manifold_ID] := L_Bias;
            END_IF;

            L_Score := TO_REAL(VI_Manifold_Base_Priority[L_Manifold_ID]) * L_Multiplier * L_Bias;

            IF L_Score > L_MaxScore[L_Manifold_ID] THEN
                L_MaxScore[L_Manifold_ID] := L_Score;
            END_IF;

            L_HasActiveCircuit[L_Manifold_ID] := TRUE;
        END_IF;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF L_HasActiveCircuit[L_i] THEN
        IF L_MaxScore[L_i] >= REAL#3.5 THEN
            VO_Manifold_Effective_Priority[L_i] := 4;
        ELSIF L_MaxScore[L_i] >= REAL#2.5 THEN
            VO_Manifold_Effective_Priority[L_i] := 3;
        ELSIF L_MaxScore[L_i] >= REAL#1.5 THEN
            VO_Manifold_Effective_Priority[L_i] := 2;
        ELSIF L_MaxScore[L_i] >= REAL#0.5 THEN
            VO_Manifold_Effective_Priority[L_i] := 1;
        ELSE
            VO_Manifold_Effective_Priority[L_i] := 0;
        END_IF;
    ELSE
        VO_Manifold_Effective_Priority[L_i] := VI_Manifold_Base_Priority[L_i];
        VO_Manifold_Priority_Bias_Applied[L_i] := REAL#1.0;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Heating_Policy_Priority_Bridge <<<

// Initialize variables
H0 := 16#67452301;
H1 := 16#EFCDAB89;
H2 := 16#98BADCFE;
H3 := 16#10325476;
H4 := 16#C3D2E1F0;

// Pre-processing
FOR i := 0 TO Length - 1 DO
    PaddedData[i] := Data[i];
END_FOR;

// Append the bit '1' to the message
PaddedData[Length] := 16#80;

// Append 0 <= k < 512 bits '0', such that the resulting message length in bits
// is congruent to -64 ≡ 448 (mod 512)
PaddedLength := Length + 1;
WHILE (PaddedLength MOD 64) <> 56 DO
    PaddedData[PaddedLength] := 0;
    PaddedLength := PaddedLength + 1;
END_WHILE;

// Append length of message (before pre-processing), in bits, as 64-bit big-endian integer
// Since our message is small (max 127 bytes), we only need the lower 32 bits
Temp := TO_DWORD(Length * 8);
PaddedData[PaddedLength] := 0;
PaddedData[PaddedLength+1] := 0;
PaddedData[PaddedLength+2] := 0;
PaddedData[PaddedLength+3] := 0;
PaddedData[PaddedLength+4] := TO_BYTE(SHR(Temp, 24));
PaddedData[PaddedLength+5] := TO_BYTE(SHR(Temp, 16));
PaddedData[PaddedLength+6] := TO_BYTE(SHR(Temp, 8));
PaddedData[PaddedLength+7] := TO_BYTE(Temp);
PaddedLength := PaddedLength + 8;

NumBlocks := PaddedLength / 64;

// Process the message in successive 512-bit chunks
FOR i := 0 TO NumBlocks - 1 DO
    BlockOffset := i * 64;

    // Break chunk into sixteen 32-bit big-endian words w[i], 0 <= i <= 15
    FOR j := 0 TO 15 DO
        W[j] := SHL(TO_DWORD(PaddedData[BlockOffset + j*4]), 24) OR
                SHL(TO_DWORD(PaddedData[BlockOffset + j*4 + 1]), 16) OR
                SHL(TO_DWORD(PaddedData[BlockOffset + j*4 + 2]), 8) OR
                TO_DWORD(PaddedData[BlockOffset + j*4 + 3]);
    END_FOR;

    // Message schedule: extend the sixteen 32-bit words into eighty 32-bit words
    FOR j := 16 TO 79 DO
        Temp := W[j-3] XOR W[j-8] XOR W[j-14] XOR W[j-16];
        W[j] := SHL(Temp, 1) OR SHR(Temp, 31); // Left rotate by 1
    END_FOR;

    // Initialize hash value for this chunk
    A := H0;
    B := H1;
    C := H2;
    D := H3;
    E := H4;

    // Main loop
    FOR j := 0 TO 79 DO
        IF j <= 19 THEN
            F := (B AND C) OR ((NOT B) AND D);
            K := 16#5A827999;
        ELSIF j <= 39 THEN
            F := B XOR C XOR D;
            K := 16#6ED9EBA1;
        ELSIF j <= 59 THEN
            F := (B AND C) OR (B AND D) OR (C AND D);
            K := 16#8F1BBCDC;
        ELSE
            F := B XOR C XOR D;
            K := 16#CA62C1D6;
        END_IF;

        Temp := (SHL(A, 5) OR SHR(A, 27)) + F + E + K + W[j];
        E := D;
        D := C;
        C := SHL(B, 30) OR SHR(B, 2);
        B := A;
        A := Temp;
    END_FOR;

    // Add this chunk's hash to result so far
    H0 := H0 + A;
    H1 := H1 + B;
    H2 := H2 + C;
    H3 := H3 + D;
    H4 := H4 + E;
END_FOR;

// Produce the final hash value (big-endian)
Hash[0] := TO_BYTE(SHR(H0, 24)); Hash[1] := TO_BYTE(SHR(H0, 16)); Hash[2] := TO_BYTE(SHR(H0, 8)); Hash[3] := TO_BYTE(H0);
Hash[4] := TO_BYTE(SHR(H1, 24)); Hash[5] := TO_BYTE(SHR(H1, 16)); Hash[6] := TO_BYTE(SHR(H1, 8)); Hash[7] := TO_BYTE(H1);
Hash[8] := TO_BYTE(SHR(H2, 24)); Hash[9] := TO_BYTE(SHR(H2, 16)); Hash[10] := TO_BYTE(SHR(H2, 8)); Hash[11] := TO_BYTE(H2);
Hash[12] := TO_BYTE(SHR(H3, 24)); Hash[13] := TO_BYTE(SHR(H3, 16)); Hash[14] := TO_BYTE(SHR(H3, 8)); Hash[15] := TO_BYTE(H3);
Hash[16] := TO_BYTE(SHR(H4, 24)); Hash[17] := TO_BYTE(SHR(H4, 16)); Hash[18] := TO_BYTE(SHR(H4, 8)); Hash[19] := TO_BYTE(H4);

// Compatibility placeholder.
// Previous METHOD Calculate returned DWORD#0.
// Keep same behaviour without METHOD syntax for this CODESYS project format.
IF VI_Enable THEN
    VO_CRC := DWORD#0;
END_IF;

L_Away_Mode := (VI_Behavior_Mode = BEHAVIOR_AWAY);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    // compute empty duration
    IF VI_Zone_Occupied[L_i] THEN
        VO_Zone_Empty_Duration_MS[L_i] := 0;
    ELSE
        VO_Zone_Empty_Duration_MS[L_i] := VI_System_Time_MS - VI_Zone_Last_Motion_TS[L_i];
    END_IF;

    // policy classification
    // Guest/preheat has priority even in AWAY mode.
    IF VI_Zone_Guest_Preheat[L_i] THEN
        VO_Zone_Policy_Class[L_i] := 3; // guest

    ELSIF VI_Zone_Occupied[L_i] THEN
        VO_Zone_Policy_Class[L_i] := 0; // comfort

    ELSIF VI_Zone_Permanent_Use[L_i] AND (NOT L_Away_Mode) THEN
        VO_Zone_Policy_Class[L_i] := 4; // permanent mild eco

    ELSIF VO_Zone_Empty_Duration_MS[L_i] >= L_Long_Threshold THEN
        VO_Zone_Policy_Class[L_i] := 2; // deep eco

    ELSE
        VO_Zone_Policy_Class[L_i] := 1; // mild eco
    END_IF;

    // observe-only target adjustment (no effect yet)
    CASE VO_Zone_Policy_Class[L_i] OF
        0: // comfort
            VO_Zone_Target_Adjustment[L_i] := 0.0;
            VO_Zone_Priority_Bias[L_i] := 1.0;

        1: // mild eco
            VO_Zone_Target_Adjustment[L_i] := -1.0;
            VO_Zone_Priority_Bias[L_i] := 0.8;

        2: // deep eco
            VO_Zone_Target_Adjustment[L_i] := -3.0;
            VO_Zone_Priority_Bias[L_i] := 0.5;

        3: // guest preheat
            VO_Zone_Target_Adjustment[L_i] := 0.0;
            VO_Zone_Priority_Bias[L_i] := 1.5;

        4: // permanent-use mild eco
            VO_Zone_Target_Adjustment[L_i] := -0.5;
            VO_Zone_Priority_Bias[L_i] := 0.9;

    END_CASE;

END_FOR;

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

CASE L_State OF
    0: // Ожидание
        VO_Test_Active := FALSE;
        L_Need_Test := FALSE;

        // Поиск клапана, которому нужен тест (раз в неделю)
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            IF VI_Config[L_i].enabled AND ((VI_System_Time_MS - L_Last_Test_Time[L_i]) > (VI_Config[L_i].test_interval_days * 86400000)) THEN
                L_Current_Valve := L_i;
                L_Need_Test := TRUE;
                EXIT;
            END_IF;
        END_FOR;

        IF L_Need_Test THEN
            L_State := 1;
            L_Test_Start_Time := VI_System_Time_MS;
            VO_Test_Active := TRUE;
            VO_Current_Valve := L_Current_Valve;
            VO_Valve_Cmd[L_Current_Valve] := TRUE; // Открываем
            VO_Status_Msg := CONCAT('ТЕСТ КЛАПАНА ', INT_TO_STRING(L_Current_Valve));
            VO_Test_Results[L_Current_Valve] := TRUE; // Сброс результата
        END_IF;

    1: // Тестирование (ожидание открытия)
        L_Elapsed_Time := (VI_System_Time_MS - L_Test_Start_Time);

        IF VI_Valve_End_Switches[L_Current_Valve] THEN
            // Концевик сработал до истечения таймаута
            // Проверка тока
            IF ABS(VI_Valve_Currents[L_Current_Valve] - VI_Config[L_Current_Valve].Nominal_Current) > (VI_Config[L_Current_Valve].Nominal_Current * 0.2) THEN
                VO_Test_Results[L_Current_Valve] := FALSE; // Ошибка по току
            END_IF;

            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := VO_Test_Results[L_Current_Valve];

            VO_Valve_Cmd[L_Current_Valve] := FALSE; // Закрываем
            L_Test_Start_Time := VI_System_Time_MS; // Перезапускаем таймер для проверки закрытия
            L_State := 2;
        ELSIF L_Elapsed_Time > TO_UDINT(VI_Config[L_Current_Valve].nominal_close_time_sec * 1000.0) THEN
            // Таймаут открытия (заклинивание)
            VO_Test_Results[L_Current_Valve] := FALSE; 
            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := FALSE;
            VO_Status_Msg := CONCAT('ОШИБКА: ЗАКЛИНИВАНИЕ КЛАПАНА ', INT_TO_STRING(L_Current_Valve));

            VO_Valve_Cmd[L_Current_Valve] := FALSE; // Закрываем
            L_Test_Start_Time := VI_System_Time_MS; // Перезапускаем таймер
            L_State := 2;
        END_IF;

    2: // Ожидание закрытия
        L_Elapsed_Time := (VI_System_Time_MS - L_Test_Start_Time);

        IF NOT VI_Valve_End_Switches[L_Current_Valve] THEN
            // Концевик разомкнулся (клапан закрыт)
            L_Last_Test_Time[L_Current_Valve] := VI_System_Time_MS;
            L_State := 0;
            IF VO_Test_Results[L_Current_Valve] THEN
                VO_Status_Msg := 'ТЕСТ ЗАВЕРШЕН УСПЕШНО';
            END_IF;
        ELSIF L_Elapsed_Time > TO_UDINT(VI_Config[L_Current_Valve].nominal_close_time_sec * 1000.0) THEN
            // Таймаут закрытия (заклинивание)
            VO_Test_Results[L_Current_Valve] := FALSE; 
            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := FALSE;
            VO_Status_Msg := CONCAT('ОШИБКА: НЕ ЗАКРЫЛСЯ КЛАПАН ', INT_TO_STRING(L_Current_Valve));

            L_Last_Test_Time[L_Current_Valve] := VI_System_Time_MS;
            L_State := 0;
        END_IF;
ELSE
        // No fallback required
END_CASE;

IF NOT GVL_TRACE.G_Trace_Enabled THEN RETURN; END_IF;

L_Index := GVL_TRACE.G_Trace_Write_Index;

GVL_TRACE.G_Trace_Buffer[L_Index].Timestamp_MS := GVL_TIME_SERVICE.G_Now_MS;
GVL_TRACE.G_Trace_Buffer[L_Index].Layer := iLayer;
GVL_TRACE.G_Trace_Buffer[L_Index].Source := iSource;
GVL_TRACE.G_Trace_Buffer[L_Index].Reason_Code := iReason;
GVL_TRACE.G_Trace_Buffer[L_Index].Value_Bool := iValueBool;
GVL_TRACE.G_Trace_Buffer[L_Index].Value_Real := iValueReal;
GVL_TRACE.G_Trace_Buffer[L_Index].Text := iText;

L_Index := L_Index + 1;
IF L_Index > 200 THEN L_Index := 1; END_IF;

GVL_TRACE.G_Trace_Write_Index := L_Index;

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

L_Any_Leak := FALSE;
L_Any_Warning := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    L_Sensor_Timers[L_i](
        IN := VI_Sensors[L_i],
        PT := TO_TIME(VI_Config.min_duration_ms + VI_Config.warning_duration_ms),
        VI_System_Time_MS := VI_System_Time_MS
    );

    IF L_Sensor_Timers[L_i].ET >= TO_TIME(VI_Config.min_duration_ms) THEN
        L_Any_Warning := TRUE;

        IF L_Sensor_Timers[L_i].Q THEN
            L_Any_Leak := TRUE;
        END_IF;
    END_IF;
END_FOR;

// Manual latch instead of RS
IF GVL_INTENT_USER.I_Reset_Errors THEN
    VO_Leak_Detected := FALSE;
ELSIF L_Any_Leak THEN
    VO_Leak_Detected := TRUE;
END_IF;

VO_Leak_Warning_Level := L_Any_Warning;

IF VO_Leak_Detected THEN
    VO_Status_Msg := 'АВАРИЯ: ПРОТЕЧКА ВОДЫ.';
ELSIF L_Any_Warning THEN
    VO_Status_Msg := 'ПРЕДУПРЕЖДЕНИЕ: ОБНАРУЖЕНА ВОДА.';
ELSE
    VO_Status_Msg := 'Система контроля протечек в норме';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Water_Leakage_Manager <<<

// Convert ventilation manager BYTE outputs directly into IO-ready projection.
// PRG_Ventilation no longer needs to publish fan actuator values through GVL_STATE.

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    GVL_VENT_OUTPUT.AO_Supply_Fans[L_i] := BYTE_TO_UINT(VI_Supply_Fans[L_i]) * 10;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    GVL_VENT_OUTPUT.AO_Exhaust_Fans[L_i] := BYTE_TO_UINT(VI_Exhaust_Fans[L_i]) * 10;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Vent_Output_Projection <<<

IF NOT VI_Enable THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        GVL_HEATING_POLICY.G_Zone_Schedule_Preheat_Active[L_i] := FALSE;
    END_FOR;
    RETURN;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Active := FALSE;
    L_Max_Boost := 0.0;

    FOR L_e := 1 TO 3 DO
        L_Event := GVL_HEATING_POLICY_CONFIG.G_Zone_Schedule[L_i, L_e];

        IF L_Event.Enabled THEN
            IF (L_Event.Weekday_Mask AND SHL(1, VI_Day_Of_Week - 1)) <> 0 THEN

                IF L_Event.Comfort_Time_MS >= VI_Time_Of_Day_MS THEN
                    L_Time_To_Comfort_MS := L_Event.Comfort_Time_MS - VI_Time_Of_Day_MS;
                ELSE
                    L_Time_To_Comfort_MS := (86400000 - VI_Time_Of_Day_MS) + L_Event.Comfort_Time_MS;
                END_IF;

                IF L_Event.Adaptive_Enabled THEN
                    IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] > L_Event.Adaptive_Max_Offset_MS THEN
                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] := L_Event.Adaptive_Max_Offset_MS;
                    END_IF;
                    L_Time_To_Comfort_MS := L_Time_To_Comfort_MS + GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e];
                END_IF;

                IF (GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] >= L_Time_To_Comfort_MS)
                   AND (GVL_HEATING_POLICY.G_Zone_Time_To_Heat_MS[L_i] > 0) THEN

                    IF L_Event.Preheat_Boost > L_Max_Boost THEN
                        L_Max_Boost := L_Event.Preheat_Boost;
                    END_IF;

                    L_Active := TRUE;
                END_IF;

                IF L_Event.Adaptive_Enabled THEN
                    IF L_Time_To_Comfort_MS < L_Learn_Window_MS THEN

                        IF GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] > 1.0 THEN
                            L_Cold_Confirm[L_i, L_e] := L_Cold_Confirm[L_i, L_e] + 1;
                            L_Hot_Confirm[L_i, L_e] := 0;
                        ELSIF GVL_HEATING_POLICY.G_Zone_Thermal_Demand[L_i] < -0.5 THEN
                            L_Hot_Confirm[L_i, L_e] := L_Hot_Confirm[L_i, L_e] + 1;
                            L_Cold_Confirm[L_i, L_e] := 0;
                        ELSE
                            L_Cold_Confirm[L_i, L_e] := 0;
                            L_Hot_Confirm[L_i, L_e] := 0;
                        END_IF;

                        // UDINT wrap-safe elapsed time; unsigned subtraction is valid modulo 2^32.
                        L_Elapsed_MS := VI_System_Time_MS - L_Last_Learn_MS[L_i, L_e];

                        IF L_Elapsed_MS >= L_Learn_Cooldown_MS THEN

                            IF L_Cold_Confirm[L_i, L_e] >= 2 THEN
                                IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] < L_Event.Adaptive_Max_Offset_MS THEN
                                    GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] :=
                                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] + L_Event.Adaptive_Step_MS;
                                    IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] > L_Event.Adaptive_Max_Offset_MS THEN
                                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] := L_Event.Adaptive_Max_Offset_MS;
                                    END_IF;
                                    L_Last_Learn_MS[L_i, L_e] := VI_System_Time_MS;
                                END_IF;
                                L_Cold_Confirm[L_i, L_e] := 0;
                            END_IF;

                            IF L_Hot_Confirm[L_i, L_e] >= 2 THEN
                                IF GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] > L_Event.Adaptive_Step_MS THEN
                                    GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] :=
                                        GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] - L_Event.Adaptive_Step_MS;
                                ELSE
                                    GVL_HEATING_POLICY.G_Zone_Schedule_Learned_Offset_MS[L_i, L_e] := 0;
                                END_IF;
                                L_Last_Learn_MS[L_i, L_e] := VI_System_Time_MS;
                                L_Hot_Confirm[L_i, L_e] := 0;
                            END_IF;

                        END_IF;
                    ELSE
                        L_Cold_Confirm[L_i, L_e] := 0;
                        L_Hot_Confirm[L_i, L_e] := 0;
                    END_IF;
                END_IF;

            END_IF;
        END_IF;
    END_FOR;

    L_Adjustment := GVL_HEATING_POLICY.G_Zone_Target_Adjustment[L_i];

    IF L_Active AND (L_Adjustment < L_Max_Boost) THEN
        L_Adjustment := L_Max_Boost;
    END_IF;

    IF L_Adjustment > 1.0 THEN
        L_Adjustment := 1.0;
    ELSIF L_Adjustment < -1.0 THEN
        L_Adjustment := -1.0;
    END_IF;

    GVL_HEATING_POLICY.G_Zone_Target_Adjustment[L_i] := L_Adjustment;
    GVL_HEATING_POLICY.G_Zone_Schedule_Preheat_Active[L_i] := L_Active;
END_FOR;

L_Elapsed := (SEL(VI_System_Time >= VI_Start_Time, VI_System_Time - VI_Start_Time, (4294967295 - VI_Start_Time) + VI_System_Time + 1));

IF L_Elapsed >= VI_Duration OR VI_Duration = 0 THEN
    VO_Current_Value := VI_End_Value;
    VO_Transition_Done := TRUE;
ELSE
    L_Progress := UDINT_TO_REAL(L_Elapsed) / UDINT_TO_REAL(VI_Duration);
    VO_Current_Value := VI_Start_Value + (VI_End_Value - VI_Start_Value) * L_Progress;
    VO_Transition_Done := FALSE;
END_IF;

// ==============================================================================
// Блок таймера задержки выключения (System Timer TOF)
// Назначение:
// - Замена стандартного TOF для обеспечения точной выдержки времени,
//   независимой от времени цикла ПЛК, с использованием единого системного времени.
// ==============================================================================



IF IN THEN
    Q := TRUE;
    ET := T#0s;
    L_Running := FALSE;
ELSE
    IF L_Prev_IN THEN
        L_Start_Time := VI_System_Time_MS;
        L_Running := TRUE;
        ET := T#0s;
    END_IF;

    IF L_Running THEN
        // Обработка переполнения UDINT (примерно 49 дней)
        ET := TO_TIME((SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1)));

        IF ET >= PT THEN
            Q := FALSE;
            ET := PT;
            L_Running := FALSE;
        ELSE
            Q := TRUE;
        END_IF;
    END_IF;
END_IF;

L_Prev_IN := IN;

// Периодическая синхронизация (каждые 5 секунд)
L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Last_Sync_Time, VI_System_Time_MS - L_Last_Sync_Time, (4294967295 - L_Last_Sync_Time) + VI_System_Time_MS + 1));

IF L_Elapsed_Time > 5000 THEN
    L_Periodic_Sync_Req := TRUE;
    L_Last_Sync_Time := VI_System_Time_MS;
ELSE
    L_Periodic_Sync_Req := FALSE;
END_IF;

// State Replication Logic
// Синхронизация состояния между ПЛК (ТЗ 8.2)
IF (VI_Sync_Req OR L_Periodic_Sync_Req) AND NOT L_Sync_In_Progress THEN
    L_Sync_In_Progress := TRUE;

    // Разрешение конфликтов на основе версии состояния
    IF VI_Remote_State.Version > VI_Local_State.Version THEN
        VO_Synced_State := VI_Remote_State;
        VO_State_Updated := TRUE;
    ELSIF VI_Remote_State.Version = VI_Local_State.Version THEN
        // Если версии равны, приоритет у ведущего ПЛК
        IF VI_Local_Role = E_PLC_ROLE.ROLE_STANDBY THEN
            VO_Synced_State := VI_Remote_State;
            VO_State_Updated := TRUE;
        ELSE
            VO_Synced_State := VI_Local_State;
            VO_State_Updated := FALSE;
        END_IF;
    ELSE
        VO_Synced_State := VI_Local_State;
        VO_State_Updated := FALSE;
    END_IF;
ELSIF NOT (VI_Sync_Req OR L_Periodic_Sync_Req) THEN
    L_Sync_In_Progress := FALSE;
    VO_State_Updated := FALSE;
    VO_Synced_State := VI_Local_State;
END_IF;

VO_Send_Telegram := FALSE;
IF VI_Fire_Alarm_Active AND NOT L_Prev_Fire THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! ПОЖАРНАЯ ТРЕВОГА!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Gas_Alarm_Active AND NOT L_Prev_Gas THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! УТЕЧКА ГАЗА!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Flood_Alarm_Active AND NOT L_Prev_Flood THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! ПРОТЕЧКА ВОДЫ!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Security_Armed AND NOT L_Prev_Security THEN
    VO_Telegram_Msg := 'ОХРАНА ВКЛЮЧЕНА';
    VO_Send_Telegram := TRUE;
ELSIF NOT VI_Security_Armed AND L_Prev_Security THEN
    VO_Telegram_Msg := 'ОХРАНА ОТКЛЮЧЕНА';
    VO_Send_Telegram := TRUE;
END_IF;

L_Prev_Fire := VI_Fire_Alarm_Active;
L_Prev_Gas := VI_Gas_Alarm_Active;
L_Prev_Flood := VI_Flood_Alarm_Active;
L_Prev_Security := VI_Security_Armed;

IF (VI_System_Time_MS - L_last_update_time) >= GVL_CONSTANTS.C_MS_IN_SECOND THEN
    L_last_update_time := VI_System_Time_MS;
    L_tmp_word := 0;
    IF VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE THEN L_tmp_word := L_tmp_word OR 1; END_IF;
    IF VI_Security_Armed THEN L_tmp_word := L_tmp_word OR 2; END_IF;
    IF VI_Flood_Alarm_Active THEN L_tmp_word := L_tmp_word OR 4; END_IF;
    IF VI_Gas_Alarm_Active THEN L_tmp_word := L_tmp_word OR 8; END_IF;
    IF VI_Fire_Alarm_Active THEN L_tmp_word := L_tmp_word OR 16; END_IF;
    VO_Modbus_Registers[0] := L_tmp_word;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        VO_Modbus_Registers[L_i] := TO_WORD(TO_INT(VI_FloorHeating_Temps[L_i] * REAL#10.0));
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
        VO_Modbus_Registers[16 + L_i] := TO_WORD(TO_INT(VI_Room_Temps[L_i] * REAL#10.0));
    END_FOR;

    L_tmp_word := 0;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        IF VI_Zone_Valve_States[L_i] THEN
            L_tmp_word := L_tmp_word OR SHL(TO_WORD(1), L_i - 1);
        END_IF;
    END_FOR;
    VO_Modbus_Registers[33] := L_tmp_word;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        VO_Modbus_Registers[33 + L_i] := TO_WORD(TO_INT(VI_Manifold_Pressures[L_i] * REAL#100.0));
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        VO_Modbus_Registers[39 + L_i] := TO_WORD(VI_Lighting_Base_Levels[L_i]);
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
        VO_Modbus_Registers[71 + L_i] := TO_WORD(VI_Blinds_Positions[L_i]);
    END_FOR;

    FOR L_i := 0 TO (GVL_CONSTANTS.C_MAX_SOCKETS - 1) / 16 DO
        L_tmp_word := 0;
        FOR L_j := 1 TO 16 DO
            L_idx := (L_i * 16) + L_j;
            IF L_idx <= GVL_CONSTANTS.C_MAX_SOCKETS THEN
                IF VI_Socket_States[L_idx] THEN
                    L_tmp_word := L_tmp_word OR SHL(TO_WORD(1), L_j - 1);
                END_IF;
            END_IF;
        END_FOR;
        VO_Modbus_Registers[92 + L_i] := L_tmp_word;
    END_FOR;

    VO_Modbus_Registers[100] := SEL(VI_Send_2FA_Req, 0, 1);
    IF VI_Send_2FA_Req THEN
        L_Code_UDINT := STRING_TO_UDINT(VI_2FA_Code);
        VO_Modbus_Registers[101] := TO_WORD(L_Code_UDINT AND 16#FFFF);
        VO_Modbus_Registers[102] := TO_WORD(SHR(L_Code_UDINT, 16));
    ELSE
        VO_Modbus_Registers[101] := 0;
        VO_Modbus_Registers[102] := 0;
    END_IF;

    VO_Data_Ready := TRUE;
END_IF;

VO_Arm_Req := FALSE;
VO_Disarm_Req := FALSE;
VO_Set_Scenario_Req := FALSE;
VO_Set_Temp_Req := FALSE;
VO_Set_Vent_Req := FALSE;
VO_Reset_Errors_Req := FALSE;
VO_Set_Config_Req := FALSE;
VO_Sync_Time_Req := FALSE;
L_Has_Command_To_Process := FALSE;

IF VI_Command_Received THEN
    IF VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE THEN
        L_Process_Command := VI_Incoming_Command;
        L_Has_Command_To_Process := TRUE;
    ELSE
        IF L_Buffer_Count < GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN
            L_Command_Buffer[L_Buffer_Head] := VI_Incoming_Command;
            L_Buffer_Head := L_Buffer_Head + 1;
            IF L_Buffer_Head > GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN L_Buffer_Head := 1; END_IF;
            L_Buffer_Count := L_Buffer_Count + 1;
        END_IF;
    END_IF;
END_IF;

IF NOT L_Has_Command_To_Process AND (VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE) AND (L_Buffer_Count > 0) THEN
    L_Process_Command := L_Command_Buffer[L_Buffer_Tail];
    L_Buffer_Tail := L_Buffer_Tail + 1;
    IF L_Buffer_Tail > GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN L_Buffer_Tail := 1; END_IF;
    L_Buffer_Count := L_Buffer_Count - 1;
    L_Has_Command_To_Process := TRUE;
END_IF;

IF L_Has_Command_To_Process THEN
    L_IP_Allowed := FALSE;
    IF L_Process_Command.source_ip = '' THEN
        L_IP_Allowed := TRUE;
    ELSE
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALLOWED_IPS DO
            IF VI_Allowed_IPs[L_i] = L_Process_Command.source_ip THEN
                L_IP_Allowed := TRUE;
                EXIT;
            END_IF;
        END_FOR;
    END_IF;

    IF NOT L_IP_Allowed THEN
        VO_HMI_Status_Message := 'Gateway: Ошибка безопасности (Неизвестный IP)';
        RETURN;
    END_IF;

    L_CRC_Calc();
    L_Calculated_CRC := L_CRC_Calc.VO_CRC;

    IF L_Calculated_CRC = L_Process_Command.crc32 THEN
        L_Deduplicator(VI_Command_ID := L_Process_Command.command_id, VI_Command_Type := L_Process_Command.command_type, VI_Command_Value := L_Process_Command.target_value, VI_System_Time_MS := VI_System_Time_MS);

        IF L_Deduplicator.VO_Is_New_Command THEN
            CASE L_Process_Command.command_type OF
                E_Gateway_Command_Type.CMD_SET_SCENARIO:
                    VO_Set_Scenario_Req := TRUE;
                    VO_Target_Scenario := L_Process_Command.target_scenario;
                    VO_HMI_Status_Message := 'Gateway: Сценарий изменен';
                E_Gateway_Command_Type.CMD_SET_LIGHT:
                    IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_LIGHT_ZONES) THEN
                        VO_Lighting_Override[L_Process_Command.target_zone] := TO_BYTE(L_Process_Command.target_value);
                        VO_HMI_Status_Message := 'Gateway: Команда освещения принята';
                    END_IF;
                E_Gateway_Command_Type.CMD_SET_BLINDS:
                    IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_BLINDS) THEN
                        VO_Blinds_Override[L_Process_Command.target_zone] := TO_BYTE(L_Process_Command.target_value);
                        VO_HMI_Status_Message := 'Gateway: Команда штор принята';
                    END_IF;
                E_Gateway_Command_Type.CMD_SET_SOCKET:
                    IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_SOCKETS) THEN
                        VO_Socket_Override[L_Process_Command.target_zone] := L_Process_Command.target_on_off;
                        VO_HMI_Status_Message := 'Gateway: Команда розетки принята';
                    END_IF;
                E_Gateway_Command_Type.CMD_SET_SECURITY:
                    IF L_Process_Command.target_armed THEN VO_Arm_Req := TRUE; ELSE VO_Disarm_Req := TRUE; END_IF;
                    VO_PIN_Code := L_Process_Command.target_pin;
                    VO_2FA_Code_In := L_Process_Command.target_2fa_code;
                    VO_HMI_Status_Message := 'Gateway: Запрос охраны принят';
                E_Gateway_Command_Type.CMD_SET_TEMP:
                    IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS) THEN
                        VO_Set_Temp_Req := TRUE;
                        VO_Target_Zone := L_Process_Command.target_zone;
                        VO_Target_Temp := L_Process_Command.target_value;
                        VO_HMI_Status_Message := 'Gateway: Уставка температуры изменена';
                    END_IF;
                E_Gateway_Command_Type.CMD_SET_VENT:
                    VO_Set_Vent_Req := TRUE;
                    VO_Target_Vent_Speed := TO_BYTE(L_Process_Command.target_value);
                    VO_HMI_Status_Message := 'Gateway: Уставка вентиляции изменена';
                E_Gateway_Command_Type.CMD_TELEGRAM_MSG:
                    VO_Telegram_Msg := L_Process_Command.telegram_msg;
                    VO_Send_Telegram := TRUE;
                    VO_HMI_Status_Message := 'Gateway: Сообщение Telegram отправлено';
                E_Gateway_Command_Type.CMD_SYNC_TIME:
                    VO_Sync_Time_Req := TRUE;
                    VO_New_Time_MS := REAL_TO_UDINT(L_Process_Command.target_value);
                    VO_HMI_Status_Message := 'Gateway: Время синхронизировано';
                E_Gateway_Command_Type.CMD_RESET_ERRORS:
                    VO_Reset_Errors_Req := TRUE;
                    VO_HMI_Status_Message := 'Gateway: Запрос на сброс ошибок принят';
                E_Gateway_Command_Type.CMD_SET_CONFIG:
                    VO_Set_Config_Req := TRUE;
                    VO_HMI_Status_Message := 'Gateway: Запрос на применение конфигурации принят';
            END_CASE;
        END_IF;
    ELSE
        VO_HMI_Status_Message := 'Gateway: Ошибка CRC команды';
    END_IF;
END_IF;

// >>> BULK_SYNC_ANCHOR: FB_Gateway_Interface <<<

GVL_ACCESS_OUTPUT.DO_Lock_1_Open := VI_Lock_1_Open;
GVL_ACCESS_OUTPUT.DO_Lock_1_Close := VI_Lock_1_Close;
GVL_ACCESS_OUTPUT.DO_Lock_2_Open := VI_Lock_2_Open;
GVL_ACCESS_OUTPUT.DO_Lock_2_Close := VI_Lock_2_Close;
GVL_ACCESS_OUTPUT.DO_Gate_Open := VI_Gate_Open;
GVL_ACCESS_OUTPUT.DO_Wicket_Open := VI_Wicket_Open;

// >>> BULK_SYNC_ANCHOR: FB_Access_Output_Projection <<<

VO_Code_Valid := FALSE;

// Вычисляем хэш введенного кода
IF LEN(VI_Code_To_Check) > 0 THEN
    pCode := ADR(VI_Code_To_Check);
    L_Input_Hash := 0;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ACCESS_CODES DO
        IF VI_Access_Codes[L_i] <> 0 AND VI_Access_Codes[L_i] = L_Input_Hash THEN
            VO_Code_Valid := TRUE;
            RETURN;
        END_IF;
    END_FOR;
END_IF;

// Проверяем RFID метку
IF LEN(VI_RFID_To_Check) > 0 THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ACCESS_CODES DO
        IF VI_RFID_Tags[L_i] <> '' AND VI_RFID_Tags[L_i] = VI_RFID_To_Check THEN
            VO_Code_Valid := TRUE;
            RETURN;
        END_IF;
    END_FOR;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_AccessCode_Manager <<<

// detect any motion
VO_Any_Motion := FALSE;
FOR L_i := 1 TO 32 DO
    IF VI_Motion_Sensors[L_i] THEN
        VO_Any_Motion := TRUE;
    END_IF;
END_FOR;

// init protection (avoid instant AWAY at boot)
IF NOT L_Initialized THEN
    L_Last_Motion_TS := VI_System_Time_MS;
    L_Initialized := TRUE;
END_IF;

// fast return: any motion immediately updates timestamp
IF VO_Any_Motion THEN
    L_Last_Motion_TS := VI_System_Time_MS;
END_IF;

// hysteresis logic:
// stay OCCUPIED until timeout expires
IF (VI_System_Time_MS - L_Last_Motion_TS) < L_Timeout_MS THEN
    VO_Occupied := TRUE;
ELSE
    VO_Occupied := FALSE;
END_IF;

VO_Auto_Away := NOT VO_Occupied;
VO_Last_Motion_TS := L_Last_Motion_TS;

// Input degraded forces safe stop first
IF GVL_INPUT.IN_Input_Degraded THEN
    L_Mode := GLOBAL_STOP;
ELSE

    // Priority: FIRE > GAS > WATER > GLOBAL_STOP > NORMAL

    IF GVL_INTENT_SAFETY.I_Fire_Alarm_Active THEN
        L_Mode := FIRE;
    ELSIF GVL_INTENT_SAFETY.I_Gas_Close_Required OR GVL_INTENT_SAFETY.I_Test_Timeout_Gas_Close THEN
        L_Mode := GAS;
    ELSIF GVL_INTENT_SAFETY.I_Water_Main_Close_Required OR GVL_INTENT_SAFETY.I_Test_Timeout_Water_Close THEN
        L_Mode := WATER_LEAK;
    ELSIF GVL_INTENT_SAFETY.I_System_Safe_Stop_Required THEN
        L_Mode := GLOBAL_STOP;
    ELSE
        L_Mode := NORMAL;
    END_IF;

END_IF;

GVL_SAFETY_SHUTDOWN.G_Safety_Mode := L_Mode;
GVL_SAFETY_SHUTDOWN.G_Safety_Active := (L_Mode <> NORMAL);

// >>> BULK_SYNC_ANCHOR: PRG_Safety_Shutdown <<<

fbTime();
fbThermal();
fbPredictive();
fbOptimizer();

L_Room_Avg := 0.0;
L_Floor_Avg := 0.0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Room_Avg := L_Room_Avg + GVL_STATE.G_Room_Temps[L_i];
    L_Floor_Avg := L_Floor_Avg + GVL_STATE.G_Floor_Temps[L_i];
END_FOR;

L_Room_Avg := L_Room_Avg / TO_REAL(GVL_CONSTANTS.C_MAX_ZONES);
L_Floor_Avg := L_Floor_Avg / TO_REAL(GVL_CONSTANTS.C_MAX_ZONES);

fbPolicyManager(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_System_Mode := GVL_STATE.G_System_Mode,
    VI_RootCause := GVL_STATE.G_Heating_RootCause,
    VI_RootConfidence := GVL_STATE.G_Heating_RootConfidence,
    VI_Min_Hold_MS := GVL_CONFIG.G_Policy_Min_Hold_MS,
    VI_Emergency_Stop := GVL_STATE.G_Safety_Emergency_Stop,
    VI_Gas_Safety := GVL_STATE.G_Safety_Gas_Latched,
    VI_Room_Temp_Avg := L_Room_Avg,
    VI_Floor_Temp_Avg := L_Floor_Avg,
    VI_Supply_Temp := GVL_STATE.G_Manifold_T_Supply[1],
    VI_Return_Temp := GVL_STATE.G_Manifold_T_Return[1],
    VI_Target_Temp := GVL_STATE.G_Target_Temperature,
    VI_Room_Temps := GVL_STATE.G_Room_Temps,
    VI_Floor_Temps := GVL_STATE.G_Floor_Temps
);

fbSchedule(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Time_Of_Day_MS := GVL_TIME_SERVICE.G_Time_Of_Day_MS,
    VI_Day_Of_Week := GVL_TIME_SERVICE.G_Day_Of_Week,
    VI_Enable := TRUE
);

GVL_HEATING_POLICY.G_Policy_Mode := fbPolicyManager.VO_Policy_Mode;
GVL_HEATING_POLICY.G_Policy_Block_Heating_Request := fbPolicyManager.VO_Block_Heating;
GVL_HEATING_POLICY.G_Policy_Target_Adjustment := fbPolicyManager.VO_Target_Adjustment;
GVL_HEATING_POLICY.G_Policy_Priority_Multiplier := fbPolicyManager.VO_Priority_Multiplier;
GVL_HEATING_POLICY.G_Policy_Self_Tune_Active := fbPolicyManager.VO_Self_Tune_Active;
GVL_HEATING_POLICY.G_Policy_Self_Tune_Level := fbPolicyManager.VO_Self_Tune_Level;
GVL_HEATING_POLICY.G_Policy_Feedback_Stable := fbPolicyManager.VO_Feedback_Stable;
GVL_HEATING_POLICY.G_Policy_Feedback_Improving := fbPolicyManager.VO_Feedback_Improving;
GVL_HEATING_POLICY.G_Policy_Feedback_Quality := fbPolicyManager.VO_Feedback_Quality;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Distributed_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// DISTRIBUTED EPOCH GOVERNOR
// ======================================================
// Governs peer epoch reconciliation foundation.
// Prevents distributed stale authority continuity.
//
// Current implementation mode:
// peer-optional foundation mode.
//
// Missing peer topology is NOT treated as divergence.
// Peer validation activates only after real peer
// synchronization state exists.
// ======================================================

GVL_DISTRIBUTED_EPOCH.Peer_Lease_Expired := FALSE;
GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Stale := FALSE;
GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Stale := FALSE;
GVL_DISTRIBUTED_EPOCH.Peer_Boot_Mismatch := FALSE;
GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Conflict := FALSE;
GVL_DISTRIBUTED_EPOCH.Peer_Semantic_Continuity_Lost := FALSE;

// ------------------------------------------------------
// Local authority projection.
// ------------------------------------------------------

GVL_DISTRIBUTED_EPOCH.Local_Runtime_Epoch := GVL_RUNTIME_EPOCH.Runtime_Epoch;
GVL_DISTRIBUTED_EPOCH.Local_Snapshot_Epoch := GVL_RUNTIME_SNAPSHOT.Snapshot_Epoch;
GVL_DISTRIBUTED_EPOCH.Local_Boot_Generation := GVL_TIME_MONOTONIC.Boot_Generation_ID;
GVL_DISTRIBUTED_EPOCH.Local_Fencing_Token := GVL_PLC_FENCING.PLC_Fencing_Token;

// ------------------------------------------------------
// Peer session detection.
// ------------------------------------------------------
// Peer validation becomes authoritative only after
// real peer epoch continuity exists.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_EPOCH.Peer_Boot_Generation > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Token > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

// ------------------------------------------------------
// Peer lease validation foundation.
// ------------------------------------------------------

IF L_Peer_Session_Active THEN
    L_Delta_MS := L_Now_MS - GVL_DISTRIBUTED_EPOCH.Peer_Last_Refresh_MS;

    IF GVL_DISTRIBUTED_EPOCH.Peer_Lease_Active THEN
        IF L_Delta_MS > GVL_DISTRIBUTED_EPOCH.Peer_Lease_Timeout_MS THEN
            GVL_DISTRIBUTED_EPOCH.Peer_Lease_Expired := TRUE;

            L_Distributed_Valid := FALSE;
            L_Error_Code := 13000;
            L_Error_Text := 'Peer lease expired';
        END_IF;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer runtime continuity foundation.
// ------------------------------------------------------

IF L_Distributed_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Epoch < GVL_DISTRIBUTED_EPOCH.Local_Runtime_Epoch THEN
        GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Stale := TRUE;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer snapshot continuity foundation.
// ------------------------------------------------------

IF L_Distributed_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Epoch < GVL_DISTRIBUTED_EPOCH.Local_Snapshot_Epoch THEN
        GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Stale := TRUE;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer boot generation continuity foundation.
// ------------------------------------------------------

IF L_Distributed_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_EPOCH.Peer_Boot_Generation <> GVL_DISTRIBUTED_EPOCH.Local_Boot_Generation THEN
        GVL_DISTRIBUTED_EPOCH.Peer_Boot_Mismatch := TRUE;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer fencing continuity foundation.
// ------------------------------------------------------

IF L_Distributed_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Token = GVL_DISTRIBUTED_EPOCH.Local_Fencing_Token THEN
        GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Conflict := TRUE;

        L_Distributed_Valid := FALSE;
        L_Error_Code := 13001;
        L_Error_Text := 'Peer fencing conflict detected';
    END_IF;
END_IF;

// ------------------------------------------------------
// Distributed semantic continuity.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Stale
OR GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Stale
OR GVL_DISTRIBUTED_EPOCH.Peer_Boot_Mismatch
OR GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Conflict
THEN
    GVL_DISTRIBUTED_EPOCH.Peer_Semantic_Continuity_Lost := TRUE;
END_IF;

// ------------------------------------------------------
// Publish distributed epoch state.
// ------------------------------------------------------

IF L_Distributed_Valid THEN
    GVL_DISTRIBUTED_EPOCH.Distributed_Epoch := GVL_DISTRIBUTED_EPOCH.Distributed_Epoch + 1;
    GVL_DISTRIBUTED_EPOCH.Distributed_Reconciliation_Epoch := GVL_DISTRIBUTED_EPOCH.Distributed_Reconciliation_Epoch + 1;

    GVL_DISTRIBUTED_EPOCH.Distributed_Epoch_Consistent := TRUE;
    GVL_DISTRIBUTED_EPOCH.Distributed_Reconciliation_Valid := TRUE;
    GVL_DISTRIBUTED_EPOCH.Distributed_Publication_Allowed := TRUE;

    GVL_DISTRIBUTED_EPOCH.Distributed_Quarantine_Active := FALSE;

    GVL_DISTRIBUTED_EPOCH.Peer_Last_Reconciliation_MS := L_Now_MS;

    GVL_DISTRIBUTED_EPOCH.Distributed_Last_Error_Code := 0;
    GVL_DISTRIBUTED_EPOCH.Distributed_Last_Error_Text := '';
ELSE
    GVL_DISTRIBUTED_EPOCH.Distributed_Epoch_Consistent := FALSE;
    GVL_DISTRIBUTED_EPOCH.Distributed_Reconciliation_Valid := FALSE;
    GVL_DISTRIBUTED_EPOCH.Distributed_Publication_Allowed := FALSE;

    GVL_DISTRIBUTED_EPOCH.Distributed_Quarantine_Active := TRUE;

    GVL_DISTRIBUTED_EPOCH.Distributed_Last_Error_Code := L_Error_Code;
    GVL_DISTRIBUTED_EPOCH.Distributed_Last_Error_Text := L_Error_Text;
END_IF;

// ============================================================
// CONFIGURATION SAFETY CLAMP
// ============================================================
// Configuration validation is diagnostic-only; policy owns the decision
// to degrade the system when invalid configuration is detected.
// Do not override active safety modes such as SAFE_STOP or FREEZE_PROTECTION.
IF GVL_CONFIG_VALIDATION.G_Config_Force_Safe_Mode AND
   (NOT GVL_CONFIG_VALIDATION.G_Config_Valid) AND
   (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_NORMAL) THEN
    GVL_STATE.G_System_Mode := E_System_Operating_Mode.MODE_DEGRADED;
    GVL_STATUS.G_Diagnostics.Subsystem_Degraded := TRUE;
    GVL_STATUS.G_System_Mode_Text := 'CONFIG DEGRADED';
END_IF;

// ============================================================
// SCENARIO POLICY OWNER
// ============================================================

// 1. Base priority resolution
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
    GVL_POLICY.G_Scenario_Source := SRC_SAFETY;

ELSIF GVL_POLICY.G_Scenario_Request_Operator <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Operator;
    GVL_POLICY.G_Scenario_Source := SRC_OPERATOR;

ELSIF GVL_POLICY.G_Scenario_Request_Gateway <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Gateway;
    GVL_POLICY.G_Scenario_Source := SRC_GATEWAY;

ELSIF GVL_POLICY.G_Scenario_Request_Rule <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Rule;
    GVL_POLICY.G_Scenario_Source := SRC_RULE;

ELSE
    GVL_POLICY.G_Scenario_Intent := GVL_STATUS.G_Current_Scenario;
    GVL_POLICY.G_Scenario_Source := SRC_NONE;
END_IF;

// 2. Fail-safe clamp
CASE GVL_STATE.G_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        GVL_POLICY.G_Scenario_Source := SRC_SAFETY;

    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        GVL_POLICY.G_Scenario_Source := SRC_POLICY;

    E_System_Operating_Mode.MODE_DEGRADED:
        CASE GVL_POLICY.G_Scenario_Intent OF
            E_SCENARIO_TYPE.SCENARIO_NONE,
            E_SCENARIO_TYPE.SCENARIO_PRESENCE,
            E_SCENARIO_TYPE.SCENARIO_AWAY,
            E_SCENARIO_TYPE.SCENARIO_SLEEP:
                ;
        ELSE
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;
        END_CASE;
END_CASE;

// 3. Context automation
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_NORMAL THEN
    IF GVL_ALARM.G_Security_Armed AND
       (GVL_POLICY.G_Scenario_Request_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY) THEN
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
        GVL_POLICY.G_Scenario_Source := SRC_POLICY;
    END_IF;
END_IF;

// 4. Degraded adaptation
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
    IF (GVL_POLICY.G_Scenario_Request_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) THEN

        IF GVL_ALARM.G_Security_Armed THEN
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;

        ELSIF GVL_POLICY.G_Scenario_Intent = E_SCENARIO_TYPE.SCENARIO_PRESENCE THEN
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_SLEEP;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;
        END_IF;
    END_IF;
END_IF;

// 5. Heating bridge
GVL_STATE.G_Preheat_Request := GVL_POLICY.G_Rule_Preheat_Request;
GVL_STATE.G_Freeze_Request :=
    (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);

// Minimal production trend channel: room temperature 1.
L_TrendConfig.enabled := TRUE;
L_TrendConfig.param_type := 1;
L_TrendConfig.zone_id := 1;
L_TrendConfig.deviation_threshold_percent := REAL#1.0;
L_TrendConfig.history_days := 7;

fbTrendLogger(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Config := L_TrendConfig,
    VI_Current_Value := GVL_STATE.G_Room_Temps[1],
    VO_Data => L_TrendData
);

fbTrendAdapter(
    VI_Data := L_TrendData,
    VO_Average => L_Average,
    VO_Min => L_Min,
    VO_Max => L_Max,
    VO_Trend_Up => L_Trend_Up,
    VO_Trend_Down => L_Trend_Down
);

// ======================================================
// SAFE READ-ONLY MODBUS REGISTER SCAN
// ======================================================
// Safety rules:
//   - FC03/FC04 only.
//   - Never write registers.
//   - Manual enable only.
//   - Limited scan range.
// ======================================================

IF NOT GVL_MODBUS_SCAN.G_Scan_Enable THEN
    GVL_MODBUS_SCAN.G_Scan_Active := FALSE;
    GVL_MODBUS_SCAN.G_Scan_Done := FALSE;
    RETURN;
END_IF;

GVL_MODBUS_SCAN.G_Scan_Active := TRUE;
GVL_MODBUS_SCAN.G_Scan_Error := FALSE;

IF GVL_MODBUS_SCAN.G_Current_Register < GVL_MODBUS_SCAN.G_Start_Register THEN
    GVL_MODBUS_SCAN.G_Current_Register :=
        GVL_MODBUS_SCAN.G_Start_Register;
END_IF;

IF GVL_MODBUS_SCAN.G_Current_Register > GVL_MODBUS_SCAN.G_End_Register THEN
    GVL_MODBUS_SCAN.G_Scan_Active := FALSE;
    GVL_MODBUS_SCAN.G_Scan_Done := TRUE;
    RETURN;
END_IF;

L_Register := GVL_MODBUS_SCAN.G_Current_Register;

// ======================================================
// Issue read-only FC03 request
// ======================================================
GVL_MODBUS_MASTER.G_Request[16].Enable := TRUE;
GVL_MODBUS_MASTER.G_Request[16].Slave_ID := GVL_MODBUS_SCAN.G_Slave_ID;
GVL_MODBUS_MASTER.G_Request[16].Function_Code := MB_FC03_READ_HOLDING_REGISTERS;
GVL_MODBUS_MASTER.G_Request[16].Start_Register := L_Register;
GVL_MODBUS_MASTER.G_Request[16].Register_Count := 1;
GVL_MODBUS_MASTER.G_Request[16].Sequence :=
    GVL_MODBUS_MASTER.G_Request[16].Sequence + 1;
GVL_MODBUS_MASTER.G_Request[16].Timeout_MS := 250;

// ======================================================
// Process response
// ======================================================
IF GVL_MODBUS_MASTER.G_Response[16].Done THEN

    GVL_MODBUS_SCAN.G_Found_Register[L_Register] := TRUE;

    GVL_MODBUS_SCAN.G_Found_Value[L_Register] :=
        GVL_MODBUS_MASTER.G_Response[16].Read_Value[1];

    GVL_MODBUS_SCAN.G_Last_Scan_MS := GVL_STATUS.G_System_Time_MS;

    GVL_MODBUS_SCAN.G_Current_Register :=
        GVL_MODBUS_SCAN.G_Current_Register + 1;

ELSIF GVL_MODBUS_MASTER.G_Response[16].Error THEN

    GVL_MODBUS_SCAN.G_Found_Register[L_Register] := FALSE;

    GVL_MODBUS_SCAN.G_Current_Register :=
        GVL_MODBUS_SCAN.G_Current_Register + 1;

END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Time_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// MONOTONIC TIME GOVERNOR
// ======================================================
// Creates monotonic time authority semantics.
// Prevents rollback/reboot resurrection.
// ======================================================

// First initialization.
IF NOT GVL_TIME_MONOTONIC.Monotonic_Time_Initialized THEN
    GVL_TIME_MONOTONIC.Monotonic_Time_Initialized := TRUE;
    GVL_TIME_MONOTONIC.Boot_Generation_ID := GVL_TIME_MONOTONIC.Boot_Generation_ID + 1;
    GVL_TIME_MONOTONIC.Startup_Quarantine_Active := TRUE;
    GVL_TIME_MONOTONIC.Startup_Quarantine_Start_MS := L_Now_MS;
    GVL_TIME_MONOTONIC.Last_Monotonic_Time_MS := L_Now_MS;
END_IF;

GVL_TIME_MONOTONIC.Time_Rollback_Detected := FALSE;
GVL_TIME_MONOTONIC.Time_Overflow_Detected := FALSE;
GVL_TIME_MONOTONIC.Retained_Time_Invalid := FALSE;
GVL_TIME_MONOTONIC.Startup_Quarantine_Release_Allowed := FALSE;

// Rollback detection.
IF L_Now_MS < GVL_TIME_MONOTONIC.Last_Monotonic_Time_MS THEN
    L_Time_Valid := FALSE;
    L_Error_Code := 8000;
    L_Error_Text := 'Monotonic rollback detected';

    GVL_TIME_MONOTONIC.Time_Rollback_Detected := TRUE;
    GVL_TIME_MONOTONIC.Retained_Time_Invalid := TRUE;
END_IF;

// Overflow / invalid delta detection.
L_Delta_MS := L_Now_MS - GVL_TIME_MONOTONIC.Last_Monotonic_Time_MS;

IF L_Time_Valid AND (L_Delta_MS > 60000) THEN
    L_Time_Valid := FALSE;
    L_Error_Code := 8001;
    L_Error_Text := 'Monotonic delta overflow';

    GVL_TIME_MONOTONIC.Time_Overflow_Detected := TRUE;
END_IF;

// Startup quarantine governance.
IF GVL_TIME_MONOTONIC.Startup_Quarantine_Active THEN
    IF (L_Now_MS - GVL_TIME_MONOTONIC.Startup_Quarantine_Start_MS) >= GVL_TIME_MONOTONIC.Startup_Quarantine_Timeout_MS THEN
        GVL_TIME_MONOTONIC.Startup_Quarantine_Active := FALSE;
        GVL_TIME_MONOTONIC.Startup_Quarantine_Release_Allowed := TRUE;
    ELSE
        L_Time_Valid := FALSE;

        IF L_Error_Code = 0 THEN
            L_Error_Code := 8002;
            L_Error_Text := 'Startup quarantine active';
        END_IF;
    END_IF;
END_IF;

// Publish monotonic authority state.
IF L_Time_Valid THEN
    GVL_TIME_MONOTONIC.Monotonic_Epoch := GVL_TIME_MONOTONIC.Monotonic_Epoch + 1;
    GVL_TIME_MONOTONIC.Monotonic_Time_Valid := TRUE;
    GVL_TIME_MONOTONIC.Last_Validated_Time_MS := L_Now_MS;
    GVL_TIME_MONOTONIC.Last_Monotonic_Time_MS := L_Now_MS;

    GVL_TIME_MONOTONIC.Monotonic_Last_Error_Code := 0;
    GVL_TIME_MONOTONIC.Monotonic_Last_Error_Text := '';
ELSE
    GVL_TIME_MONOTONIC.Monotonic_Time_Valid := FALSE;
    GVL_TIME_MONOTONIC.Monotonic_Last_Error_Code := L_Error_Code;
    GVL_TIME_MONOTONIC.Monotonic_Last_Error_Text := L_Error_Text;

    GVL_TIME_MONOTONIC.Monotonic_Invalidation_Count := GVL_TIME_MONOTONIC.Monotonic_Invalidation_Count + 1;
END_IF;

// ======================================================
// MODBUS MASTER RUNTIME SCHEDULER
// ======================================================
// Library-independent Modbus master scheduler.
// ======================================================

IF NOT GVL_CONFIG.G_OpenTherm_Enabled THEN

    GVL_MODBUS_MASTER.G_Master_Online := FALSE;
    GVL_MODBUS_MASTER.G_Master_Error := FALSE;

    GVL_MODBUS_MASTER.G_Active := FALSE;
    GVL_MODBUS_MASTER.G_Active_Index := 0;
    GVL_MODBUS_MASTER.G_Active_Sequence := 0;
    GVL_MODBUS_MASTER.G_Active_Start_MS := 0;
    GVL_MODBUS_MASTER.G_Active_Retry_Count := 0;

    FOR L_i := 1 TO 16 DO
        GVL_MODBUS_MASTER.G_Response[L_i].Busy := FALSE;
        GVL_MODBUS_MASTER.G_Response[L_i].Done := FALSE;
        GVL_MODBUS_MASTER.G_Response[L_i].Error := FALSE;
        GVL_MODBUS_MASTER.G_Response[L_i].Error_Code := 0;
    END_FOR;

    RETURN;
END_IF;

GVL_MODBUS_MASTER.G_Master_Online :=
    GVL_MODBUS_RTU_BRIDGE.G_Driver_Online;

GVL_MODBUS_MASTER.G_Master_Error :=
    GVL_MODBUS_RTU_BRIDGE.G_Driver_Error;

// ======================================================
// START NEW TRANSACTION
// ======================================================
IF NOT GVL_MODBUS_MASTER.G_Active THEN

    FOR L_i := 1 TO 16 DO

        IF GVL_MODBUS_MASTER.G_Request[L_i].Enable THEN

            GVL_MODBUS_MASTER.G_Active := TRUE;
            GVL_MODBUS_MASTER.G_Active_Index := L_i;
            GVL_MODBUS_MASTER.G_Active_Sequence :=
                GVL_MODBUS_MASTER.G_Request[L_i].Sequence;

            GVL_MODBUS_MASTER.G_Active_Start_MS :=
                GVL_STATUS.G_System_Time_MS;

            GVL_MODBUS_MASTER.G_Active_Retry_Count := 0;

            GVL_MODBUS_MASTER.G_Response[L_i].Busy := TRUE;
            GVL_MODBUS_MASTER.G_Response[L_i].Done := FALSE;
            GVL_MODBUS_MASTER.G_Response[L_i].Error := FALSE;
            GVL_MODBUS_MASTER.G_Response[L_i].Error_Code := 0;

            EXIT;

        END_IF;

    END_FOR;

END_IF;

// ======================================================
// ACTIVE TRANSACTION SUPERVISION
// ======================================================
IF GVL_MODBUS_MASTER.G_Active THEN

    L_i := GVL_MODBUS_MASTER.G_Active_Index;

    L_Elapsed_MS :=
        GVL_STATUS.G_System_Time_MS -
        GVL_MODBUS_MASTER.G_Active_Start_MS;

    IF GVL_MODBUS_MASTER.G_Response[L_i].Done OR
       GVL_MODBUS_MASTER.G_Response[L_i].Error THEN

        GVL_MODBUS_MASTER.G_Response[L_i].Busy := FALSE;

        GVL_MODBUS_MASTER.G_Active := FALSE;
        GVL_MODBUS_MASTER.G_Last_Transaction_MS :=
            GVL_STATUS.G_System_Time_MS;

        GVL_MODBUS_MASTER.G_Total_Transactions :=
            GVL_MODBUS_MASTER.G_Total_Transactions + 1;

        IF GVL_MODBUS_MASTER.G_Response[L_i].Error THEN
            GVL_MODBUS_MASTER.G_Total_Errors :=
                GVL_MODBUS_MASTER.G_Total_Errors + 1;
        END_IF;

    ELSIF L_Elapsed_MS > GVL_MODBUS_MASTER.G_Request[L_i].Timeout_MS THEN

        GVL_MODBUS_MASTER.G_Active_Retry_Count :=
            GVL_MODBUS_MASTER.G_Active_Retry_Count + 1;

        IF GVL_MODBUS_MASTER.G_Active_Retry_Count >
           GVL_CONFIG.G_Modbus_RTU_Retry_Count THEN

            GVL_MODBUS_MASTER.G_Response[L_i].Busy := FALSE;
            GVL_MODBUS_MASTER.G_Response[L_i].Done := FALSE;
            GVL_MODBUS_MASTER.G_Response[L_i].Error := TRUE;
            GVL_MODBUS_MASTER.G_Response[L_i].Error_Code := 16#0003;

            GVL_MODBUS_MASTER.G_Response[L_i].Last_Sequence :=
                GVL_MODBUS_MASTER.G_Active_Sequence;

            GVL_MODBUS_MASTER.G_Response[L_i].Last_Update_MS :=
                GVL_STATUS.G_System_Time_MS;

            GVL_MODBUS_MASTER.G_Active := FALSE;

            GVL_MODBUS_MASTER.G_Total_Timeouts :=
                GVL_MODBUS_MASTER.G_Total_Timeouts + 1;

            GVL_MODBUS_MASTER.G_Total_Errors :=
                GVL_MODBUS_MASTER.G_Total_Errors + 1;

        ELSE

            GVL_MODBUS_MASTER.G_Active_Start_MS :=
                GVL_STATUS.G_System_Time_MS;

        END_IF;

    END_IF;

END_IF;

// ======================================================
// REAL TRANSPORT LAYER CONTRACT
// ======================================================
// This layer converts high-level command/status structures
// into transport-safe wire images.
//
// Real Modbus RTU/TCP or serial IO code must:
//   1. Write G_Wire_Image command fields to adapter registers.
//   2. Read adapter status registers into G_Wire_Image status fields.
//
// This program keeps protocol encoding/decoding centralized.
// It does not claim transport online unless OpenTherm is enabled.
// ======================================================

IF NOT GVL_CONFIG.G_OpenTherm_Enabled THEN
    GVL_OPENTHERM_ADAPTER.G_Transport_Online := FALSE;
    GVL_OPENTHERM_ADAPTER.G_Transport_Error := FALSE;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Enable := 0;
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Setpoint_x10 := 0;
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Seq_Lo := 0;
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Seq_Hi := 0;

        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Online := FALSE;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Error := FALSE;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Flame := FALSE;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Status_Word := 0;
    END_FOR;

    RETURN;
END_IF;

GVL_OPENTHERM_ADAPTER.G_Transport_Online := TRUE;
GVL_OPENTHERM_ADAPTER.G_Transport_Error := FALSE;
GVL_OPENTHERM_ADAPTER.G_Last_Transport_Update_MS := GVL_STATUS.G_System_Time_MS;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO

    // ======================================================
    // COMMAND → WIRE IMAGE
    // ======================================================
    IF GVL_OPENTHERM_ADAPTER.G_Command[L_i].Enable THEN
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Enable := 1;
    ELSE
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Enable := 0;
    END_IF;

    GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Setpoint_x10 :=
        GVL_OPENTHERM_ADAPTER.G_Command[L_i].Setpoint_x10;

    GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Seq_Lo :=
        UDINT_TO_WORD(GVL_OPENTHERM_ADAPTER.G_Command[L_i].Sequence AND 16#FFFF);

    GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Cmd_Seq_Hi :=
        UDINT_TO_WORD(SHR(GVL_OPENTHERM_ADAPTER.G_Command[L_i].Sequence, 16));

    // ======================================================
    // WIRE IMAGE → STATUS
    // ======================================================
    L_Heartbeat :=
        WORD_TO_UDINT(GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Status_Heartbeat_Lo)
        OR SHL(
            WORD_TO_UDINT(GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Status_Heartbeat_Hi),
            16
        );

    L_Ack_Seq :=
        WORD_TO_UDINT(GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Status_Ack_Seq_Lo)
        OR SHL(
            WORD_TO_UDINT(GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Status_Ack_Seq_Hi),
            16
        );

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Heartbeat := L_Heartbeat;
    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Ack_Seq := L_Ack_Seq;

    L_Status_Word :=
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Status_Word;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Online :=
        (L_Status_Word AND 16#0001) <> 0;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Error :=
        (L_Status_Word AND 16#0002) <> 0;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Flame :=
        (L_Status_Word AND 16#0004) <> 0;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Status_Word :=
        L_Status_Word;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Error_Code :=
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Error_Code;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Modulation_x10 :=
        GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Modulation_x10;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Boiler_Temp_x10 :=
        WORD_TO_INT(GVL_OPENTHERM_ADAPTER.G_Wire_Image[L_i].Boiler_Temp_x10);

END_FOR;

// Вызов основной программы
PRG_System();
// >>> BULK_SYNC_ANCHOR: PRG_PLC_B <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Distributed_Snapshot_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// DISTRIBUTED IMMUTABLE SNAPSHOT GOVERNOR
// ======================================================
// Governs immutable peer publication snapshot exchange.
// Publication-authoritative only.
// Does not invalidate runtime barrier, PLC fencing
// or local immutable snapshot freeze.
//
// Current implementation mode:
// peer-optional foundation mode.
//
// Missing peer topology is NOT treated as divergence.
// Peer validation activates only after real peer
// synchronization state exists.
// ======================================================

GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Stale := FALSE;
GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Not_Immutable := FALSE;
GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Divergence := FALSE;
GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Reconciliation_Lost := FALSE;
GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Lease_Expired := FALSE;

// ------------------------------------------------------
// Local immutable publication projection.
// ------------------------------------------------------
// Distributed snapshot is upstream of output freshness in MAIN.
// Therefore local publication baseline must not read GVL_OUTPUT_EPOCH.
// It uses the already-frozen runtime snapshot epoch instead.
// ------------------------------------------------------

GVL_DISTRIBUTED_SNAPSHOT.Local_Distributed_Snapshot_Epoch := GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Epoch;
GVL_DISTRIBUTED_SNAPSHOT.Local_Runtime_Snapshot_Epoch := GVL_RUNTIME_SNAPSHOT.Snapshot_Epoch;
GVL_DISTRIBUTED_SNAPSHOT.Local_Publication_Epoch := GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Epoch;

// ------------------------------------------------------
// Local immutable publication freeze semantics.
// ------------------------------------------------------

IF GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen
AND GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed
AND GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid
AND GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid
THEN
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Frozen := TRUE;
ELSE
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Frozen := FALSE;

    L_Distributed_Snapshot_Valid := FALSE;
    L_Error_Code := 14000;
    L_Error_Text := 'Local immutable snapshot not frozen';
END_IF;

// ------------------------------------------------------
// Peer session detection.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Runtime_Snapshot_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Distributed_Snapshot_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Immutable THEN
    L_Peer_Session_Active := TRUE;
END_IF;

// ------------------------------------------------------
// Peer snapshot lease validation.
// ------------------------------------------------------

IF L_Distributed_Snapshot_Valid AND L_Peer_Session_Active THEN
    L_Delta_MS := L_Now_MS - GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Last_Refresh_MS;

    IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Lease_Active THEN
        IF L_Delta_MS > GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Lease_Timeout_MS THEN
            GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Lease_Expired := TRUE;

            L_Distributed_Snapshot_Valid := FALSE;
            L_Error_Code := 14001;
            L_Error_Text := 'Peer snapshot lease expired';
        END_IF;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer immutable snapshot semantics.
// ------------------------------------------------------

IF L_Distributed_Snapshot_Valid AND L_Peer_Session_Active THEN
    IF NOT GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Immutable THEN
        GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Not_Immutable := TRUE;

        L_Distributed_Snapshot_Valid := FALSE;
        L_Error_Code := 14002;
        L_Error_Text := 'Peer snapshot not immutable';
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer publication continuity.
// ------------------------------------------------------

IF L_Distributed_Snapshot_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Epoch < GVL_DISTRIBUTED_SNAPSHOT.Local_Publication_Epoch THEN
        GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Stale := TRUE;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer publication reconciliation continuity.
// ------------------------------------------------------

IF L_Distributed_Snapshot_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Runtime_Snapshot_Epoch <> GVL_DISTRIBUTED_SNAPSHOT.Local_Runtime_Snapshot_Epoch THEN
        GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Divergence := TRUE;
    END_IF;
END_IF;

IF GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Stale
OR GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Divergence
OR GVL_DISTRIBUTED_SNAPSHOT.Peer_Snapshot_Not_Immutable
THEN
    GVL_DISTRIBUTED_SNAPSHOT.Peer_Publication_Reconciliation_Lost := TRUE;
END_IF;

// ------------------------------------------------------
// Publish authoritative distributed snapshot state.
// ------------------------------------------------------

IF L_Distributed_Snapshot_Valid THEN
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Epoch := GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Epoch + 1;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Reconciliation_Epoch := GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Reconciliation_Epoch + 1;

    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled := TRUE;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid := TRUE;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent := TRUE;

    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Quarantine_Active := FALSE;

    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Last_Error_Code := 0;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Last_Error_Text := '';
ELSE
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled := FALSE;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid := FALSE;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent := FALSE;

    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Quarantine_Active := TRUE;

    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Last_Error_Code := L_Error_Code;
    GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Last_Error_Text := L_Error_Text;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Output_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay := FALSE;
GVL_OUTPUT_EPOCH.Output_Stale_Detected := FALSE;

IF NOT GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6000;
    L_Error_Text := 'Output runtime authority invalid';
END_IF;

IF L_Output_Valid AND (NOT GVL_RUNTIME_EPOCH.Runtime_IO_Publication_Allowed) THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6001;
    L_Error_Text := 'Output publication not allowed';
END_IF;

IF L_Output_Valid AND (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen) THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6100;
    L_Error_Text := 'Runtime snapshot not frozen';
END_IF;

IF L_Output_Valid AND (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed) THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6101;
    L_Error_Text := 'Snapshot publication blocked';
END_IF;

IF L_Output_Valid AND (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid) THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6102;
    L_Error_Text := 'Snapshot copy invalid';
END_IF;

IF L_Output_Valid AND (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid) THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6103;
    L_Error_Text := 'Snapshot isolation invalid';
END_IF;

IF L_Output_Valid AND GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6104;
    L_Error_Text := 'Snapshot mutation detected';
END_IF;

// Distributed epoch is the aggregate reconciliation authority.
// Peer-detail fields remain observability, not additional hard-stop fanout.
IF L_Output_Valid AND GVL_DISTRIBUTED_EPOCH.Distributed_Quarantine_Active THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6200;
    L_Error_Text := 'Distributed reconciliation quarantine active';
END_IF;

// Distributed snapshot aggregate publication authority.
IF L_Output_Valid AND (NOT GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled) THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6300;
    L_Error_Text := 'Distributed publication reconciliation invalid';
END_IF;

IF L_Output_Valid AND (NOT GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid) THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6301;
    L_Error_Text := 'Distributed publication freeze invalid';
END_IF;

IF L_Output_Valid AND (NOT GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent) THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6302;
    L_Error_Text := 'Distributed immutable snapshot inconsistent';
END_IF;

IF L_Output_Valid AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Quarantine_Active THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6306;
    L_Error_Text := 'Distributed immutable snapshot quarantine active';
END_IF;

// Distributed commit aggregate publication-continuity authority.
IF L_Output_Valid AND (NOT GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid) THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6400;
    L_Error_Text := 'Distributed commit invalid';
END_IF;

IF L_Output_Valid AND GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Quarantine_Active THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6401;
    L_Error_Text := 'Distributed commit quarantine active';
END_IF;

IF L_Output_Valid AND GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired THEN
    L_Output_Valid := FALSE;
    L_Error_Code := 6405;
    L_Error_Text := 'Distributed commit lease expired';
END_IF;

// Semantic continuity is advisory-only.
GVL_OUTPUT_EPOCH.Output_Semantic_Continuity_Warning :=
    (NOT GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid)
    OR (NOT GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK)
    OR GVL_SEMANTIC_PROGRESS.Semantic_Stagnation_Detected
    OR GVL_SEMANTIC_PROGRESS.Semantic_Replay_Suspected
    OR GVL_SEMANTIC_PROGRESS.Semantic_Livelock_Suspected
    OR GVL_SEMANTIC_PROGRESS.Semantic_Deadlock_Suspected
    OR GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired
    OR GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active;

IF L_Output_Valid THEN
    IF GVL_OUTPUT_EPOCH.Output_Runtime_Epoch > GVL_RUNTIME_EPOCH.Runtime_Epoch THEN
        L_Output_Valid := FALSE;
        L_Error_Code := 6002;
        L_Error_Text := 'Output epoch ahead of runtime epoch';
    END_IF;
END_IF;

L_Delta_MS := L_Now_MS - GVL_OUTPUT_EPOCH.Output_Last_Refresh_MS;

IF L_Output_Valid AND GVL_OUTPUT_EPOCH.Output_Lease_Active THEN
    IF L_Delta_MS > GVL_OUTPUT_EPOCH.Output_Lease_Timeout_MS THEN
        L_Output_Valid := FALSE;
        L_Error_Code := 6003;
        L_Error_Text := 'Output lease expired';
    END_IF;
END_IF;

IF L_Output_Valid THEN
    GVL_OUTPUT_EPOCH.Output_Publication_Epoch := GVL_OUTPUT_EPOCH.Output_Publication_Epoch + 1;

    GVL_OUTPUT_EPOCH.Output_Publication_Valid := TRUE;
    GVL_OUTPUT_EPOCH.Output_Lease_Active := TRUE;
    GVL_OUTPUT_EPOCH.Output_Lease_Expired := FALSE;

    GVL_OUTPUT_EPOCH.Output_Runtime_Epoch := GVL_RUNTIME_EPOCH.Runtime_Epoch;
    GVL_OUTPUT_EPOCH.Output_Runtime_Epoch_Valid := TRUE;

    GVL_OUTPUT_EPOCH.Output_Last_Publication_MS := L_Now_MS;
    GVL_OUTPUT_EPOCH.Output_Last_Refresh_MS := L_Now_MS;

    GVL_OUTPUT_EPOCH.Output_Last_Error_Code := 0;
    GVL_OUTPUT_EPOCH.Output_Last_Error_Text := '';
ELSE
    GVL_OUTPUT_EPOCH.Output_Publication_Valid := FALSE;
    GVL_OUTPUT_EPOCH.Output_Lease_Expired := TRUE;
    GVL_OUTPUT_EPOCH.Output_Stale_Detected := TRUE;
    GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay := TRUE;

    GVL_OUTPUT_EPOCH.Output_Last_Invalidation_MS := L_Now_MS;
    GVL_OUTPUT_EPOCH.Output_Last_Error_Code := L_Error_Code;
    GVL_OUTPUT_EPOCH.Output_Last_Error_Text := L_Error_Text;
END_IF;

fbCoord(
    VI_Fire_Latched := GVL_STATE.G_Safety_Smoke_Latched,
    VI_Gas_Latched := GVL_STATE.G_Safety_Gas_Latched,
    VI_Leak_Latched := GVL_STATE.G_Safety_Leak_Latched,
    VI_IO_Degraded := NOT GVL_STATUS.G_IO_Modules_Online[1],
    VI_Ownership_Violation := FALSE,
    VI_Behavior_Mode := GVL_MODE.G_Current_Behavior_Mode
);

GVL_SYSTEM_COORDINATION.G_Block_Heating := fbCoord.VO_Block_Heating OR GVL_HEATING_POLICY.G_Policy_Block_Heating_Request;
GVL_SYSTEM_COORDINATION.G_Block_Ventilation := fbCoord.VO_Block_Ventilation;
GVL_SYSTEM_COORDINATION.G_Block_Lighting_Override := fbCoord.VO_Block_Lighting;
GVL_SYSTEM_COORDINATION.G_Block_Sockets_Override := fbCoord.VO_Block_Sockets;

GVL_SYSTEM_COORDINATION.G_System_Degraded := fbCoord.VO_System_Degraded;
GVL_SYSTEM_COORDINATION.G_Coordination_Code := fbCoord.VO_Code;

// Update heartbeat
IF GVL_STATUS.G_Remote_PLC_Pulse THEN
    GVL_STATUS.G_Remote_PLC_Last_Seen_MS := GVL_TIME_SERVICE.G_Now_MS;
END_IF;

// Alive check (3s)
GVL_STATUS.G_Remote_PLC_Alive :=
    (GVL_TIME_SERVICE.G_Now_MS - GVL_STATUS.G_Remote_PLC_Last_Seen_MS) < 3000;

// Deterministic arbitration.
// If remote is not alive, local PLC owns runtime.
// If remote is alive, the lowest PLC ID wins; equality keeps local active
// because G_Active_PLC_ID defaults to the configured local owner ID.
IF NOT GVL_STATUS.G_Remote_PLC_Alive THEN
    GVL_STATUS.G_Is_Active_PLC := TRUE;
    GVL_STATUS.G_Active_PLC_ID := GVL_STATUS.G_Local_PLC_ID;
ELSE
    IF GVL_STATUS.G_Local_PLC_ID <= GVL_STATUS.G_Active_PLC_ID THEN
        GVL_STATUS.G_Is_Active_PLC := TRUE;
        GVL_STATUS.G_Active_PLC_ID := GVL_STATUS.G_Local_PLC_ID;
    ELSE
        GVL_STATUS.G_Is_Active_PLC := FALSE;
    END_IF;
END_IF;

GVL_STATUS.G_Other_PLC_Is_Active :=
    GVL_STATUS.G_Remote_PLC_Alive AND NOT GVL_STATUS.G_Is_Active_PLC;

// >>> BULK_SYNC_ANCHOR: PRG_PLC_Arbitration <<<

L_Mode := GVL_SAFETY_SHUTDOWN.G_Safety_Mode;
L_Recovery := GVL_SAFETY_RECOVERY.G_Recovery_Phase;

GVL_EXPLAINABILITY.G_Last_Safety_Mode := L_Mode;
GVL_EXPLAINABILITY.G_Last_Recovery_Phase := L_Recovery;
GVL_EXPLAINABILITY.G_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

// SAFETY LEVEL
CASE L_Mode OF
    FIRE: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'FIRE';
    GAS: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'GAS';
    WATER_LEAK: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'WATER';
    GLOBAL_STOP: GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'GLOBAL_STOP';
    ELSE
        IF GVL_SAFETY_RECOVERY.G_Recovery_Active THEN
            GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'RECOVERY';
        ELSE
            GVL_EXPLAINABILITY.G_Reason_Chain_Safety := 'NORMAL';
        END_IF;
END_CASE;

// BEHAVIOR LEVEL
GVL_EXPLAINABILITY.G_Reason_Chain_Behavior := GVL_INTENT_BEHAVIOR.I_Reason_Text;

// COMMAND LEVEL
IF GVL_COMMAND_SHADOW.G_Heating_Block THEN
    L_Command := 'Heating Blocked';
ELSIF GVL_COMMAND_SHADOW.G_Vent_Stop THEN
    L_Command := 'Vent Stopped';
ELSIF GVL_COMMAND_SHADOW.G_Water_Block THEN
    L_Command := 'Water Blocked';
ELSE
    L_Command := 'Command OK';
END_IF;
GVL_EXPLAINABILITY.G_Reason_Chain_Command := L_Command;

// HEATING DOMAIN EXPLAINABILITY
IF GVL_STATE.G_Heating_RootCause <> E_Heating_RootCause.RC_NONE THEN
    L_Heating := GVL_STATE.G_Heating_Confidence_Reason_Text;
ELSIF GVL_STATE.G_Heating_Cascade_Degraded THEN
    L_Heating := 'Heating cascade degraded';
ELSE
    L_Heating := 'Heating OK';
END_IF;
GVL_EXPLAINABILITY.G_Heating_Why_Blocked := L_Heating;

// OUTPUT LEVEL
GVL_EXPLAINABILITY.G_Reason_Chain_Output := 'Outputs Applied';

// FULL CHAIN
GVL_EXPLAINABILITY.G_Reason_Chain_Full := CONCAT(
    CONCAT(
        CONCAT(
            GVL_EXPLAINABILITY.G_Reason_Chain_Safety,
            ' -> '
        ),
        CONCAT(
            GVL_EXPLAINABILITY.G_Reason_Chain_Behavior,
            ' -> '
        )
    ),
    CONCAT(
        CONCAT(
            GVL_EXPLAINABILITY.G_Reason_Chain_Command,
            ' -> '
        ),
        CONCAT(
            L_Heating,
            ' -> Outputs Applied'
        )
    )
);

// KEEP OLD FIELDS
GVL_EXPLAINABILITY.G_Behavior_Why_Active := GVL_INTENT_BEHAVIOR.I_Reason_Text;

fbMode(
    VI_Is_Night := GVL_STATUS.G_Is_Night,
    VI_Away_Request := GVL_MODE.G_Away_Request OR GVL_PRESENCE.G_Auto_Away_Request,
    VI_Maintenance_Request := GVL_MODE.G_Maintenance_Request,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

GVL_MODE.G_Current_Behavior_Mode := fbMode.VO_Mode;
GVL_MODE.G_Mode_Code := fbMode.VO_Mode_Code;

IF L_Last_Mode <> fbMode.VO_Mode THEN
    GVL_MODE.G_Mode_Last_Change_TS := GVL_STATUS.G_System_Time_MS;
    L_Last_Mode := fbMode.VO_Mode;
END_IF;

L_Mode := GVL_SAFETY_SHUTDOWN.G_Safety_Mode;
L_Now_MS := GVL_STATUS.G_System_Time_MS;

// Load pulse duration from config with safety clamp
L_Pulse_MS := GVL_CONFIG.G_Access_Pulse_MS;
IF L_Pulse_MS < 100 THEN
    L_Pulse_MS := 100;
ELSIF L_Pulse_MS > 5000 THEN
    L_Pulse_MS := 5000;
END_IF;

L_Lock_1_Open := FALSE;
L_Lock_1_Close := FALSE;
L_Lock_2_Open := FALSE;
L_Lock_2_Close := FALSE;
L_Gate_Open := FALSE;
L_Wicket_Open := FALSE;

CASE L_Mode OF
    FIRE:
        L_Lock_1_Open := GVL_COMMAND_SHADOW.G_Lock_1_Open;
        L_Lock_2_Open := GVL_COMMAND_SHADOW.G_Lock_2_Open;
        L_Gate_Open := GVL_COMMAND_SHADOW.G_Gate_Open;
        L_Wicket_Open := GVL_COMMAND_SHADOW.G_Wicket_Open;

        L_Pulse_Lock_1_Open := FALSE;
        L_Pulse_Lock_1_Close := FALSE;
        L_Pulse_Lock_2_Open := FALSE;
        L_Pulse_Lock_2_Close := FALSE;
        L_Pulse_Gate_Open := FALSE;
        L_Pulse_Wicket_Open := FALSE;

        L_Prev_Lock_1_Open := GVL_COMMAND_SHADOW.G_Lock_1_Open;
        L_Prev_Lock_1_Close := GVL_COMMAND_SHADOW.G_Lock_1_Close;
        L_Prev_Lock_2_Open := GVL_COMMAND_SHADOW.G_Lock_2_Open;
        L_Prev_Lock_2_Close := GVL_COMMAND_SHADOW.G_Lock_2_Close;
        L_Prev_Gate_Open := GVL_COMMAND_SHADOW.G_Gate_Open;
        L_Prev_Wicket_Open := GVL_COMMAND_SHADOW.G_Wicket_Open;

    GAS:
        L_Gate_Open := GVL_COMMAND_SHADOW.G_Gate_Open;

        IF GVL_COMMAND_SHADOW.G_Lock_1_Open AND NOT L_Prev_Lock_1_Open THEN
            L_Pulse_Lock_1_Open := TRUE;
            L_Start_Lock_1_Open_MS := L_Now_MS;
        END_IF;
        IF GVL_COMMAND_SHADOW.G_Lock_2_Open AND NOT L_Prev_Lock_2_Open THEN
            L_Pulse_Lock_2_Open := TRUE;
            L_Start_Lock_2_Open_MS := L_Now_MS;
        END_IF;
        IF GVL_COMMAND_SHADOW.G_Wicket_Open AND NOT L_Prev_Wicket_Open THEN
            L_Pulse_Wicket_Open := TRUE;
            L_Start_Wicket_Open_MS := L_Now_MS;
        END_IF;

        IF L_Pulse_Lock_1_Open THEN
            L_Elapsed_MS := SEL(L_Now_MS >= L_Start_Lock_1_Open_MS, L_Now_MS - L_Start_Lock_1_Open_MS, (4294967295 - L_Start_Lock_1_Open_MS) + L_Now_MS + 1);
            IF L_Elapsed_MS < L_Pulse_MS THEN
                L_Lock_1_Open := TRUE;
            ELSE
                L_Pulse_Lock_1_Open := FALSE;
            END_IF;
        END_IF;

        IF L_Pulse_Lock_2_Open THEN
            L_Elapsed_MS := SEL(L_Now_MS >= L_Start_Lock_2_Open_MS, L_Now_MS - L_Start_Lock_2_Open_MS, (4294967295 - L_Start_Lock_2_Open_MS) + L_Now_MS + 1);
            IF L_Elapsed_MS < L_Pulse_MS THEN
                L_Lock_2_Open := TRUE;
            ELSE
                L_Pulse_Lock_2_Open := FALSE;
            END_IF;
        END_IF;

        IF L_Pulse_Wicket_Open THEN
            L_Elapsed_MS := SEL(L_Now_MS >= L_Start_Wicket_Open_MS, L_Now_MS - L_Start_Wicket_Open_MS, (4294967295 - L_Start_Wicket_Open_MS) + L_Now_MS + 1);
            IF L_Elapsed_MS < L_Pulse_MS THEN
                L_Wicket_Open := TRUE;
            ELSE
                L_Pulse_Wicket_Open := FALSE;
            END_IF;
        END_IF;

        L_Prev_Lock_1_Open := GVL_COMMAND_SHADOW.G_Lock_1_Open;
        L_Prev_Lock_1_Close := GVL_COMMAND_SHADOW.G_Lock_1_Close;
        L_Prev_Lock_2_Open := GVL_COMMAND_SHADOW.G_Lock_2_Open;
        L_Prev_Lock_2_Close := GVL_COMMAND_SHADOW.G_Lock_2_Close;
        L_Prev_Gate_Open := GVL_COMMAND_SHADOW.G_Gate_Open;
        L_Prev_Wicket_Open := GVL_COMMAND_SHADOW.G_Wicket_Open;

ELSE
        IF GVL_COMMAND_SHADOW.G_Lock_1_Open AND NOT L_Prev_Lock_1_Open THEN
            L_Pulse_Lock_1_Open := TRUE;
            L_Start_Lock_1_Open_MS := L_Now_MS;
        END_IF;
        IF GVL_COMMAND_SHADOW.G_Lock_1_Close AND NOT L_Prev_Lock_1_Close THEN
            L_Pulse_Lock_1_Close := TRUE;
            L_Start_Lock_1_Close_MS := L_Now_MS;
        END_IF;
        IF GVL_COMMAND_SHADOW.G_Lock_2_Open AND NOT L_Prev_Lock_2_Open THEN
            L_Pulse_Lock_2_Open := TRUE;
            L_Start_Lock_2_Open_MS := L_Now_MS;
        END_IF;
        IF GVL_COMMAND_SHADOW.G_Lock_2_Close AND NOT L_Prev_Lock_2_Close THEN
            L_Pulse_Lock_2_Close := TRUE;
            L_Start_Lock_2_Close_MS := L_Now_MS;
        END_IF;
        IF GVL_COMMAND_SHADOW.G_Gate_Open AND NOT L_Prev_Gate_Open THEN
            L_Pulse_Gate_Open := TRUE;
            L_Start_Gate_Open_MS := L_Now_MS;
        END_IF;
        IF GVL_COMMAND_SHADOW.G_Wicket_Open AND NOT L_Prev_Wicket_Open THEN
            L_Pulse_Wicket_Open := TRUE;
            L_Start_Wicket_Open_MS := L_Now_MS;
        END_IF;

        IF L_Pulse_Lock_1_Open THEN
            L_Elapsed_MS := SEL(L_Now_MS >= L_Start_Lock_1_Open_MS, L_Now_MS - L_Start_Lock_1_Open_MS, (4294967295 - L_Start_Lock_1_Open_MS) + L_Now_MS + 1);
            IF L_Elapsed_MS < L_Pulse_MS THEN
                L_Lock_1_Open := TRUE;
            ELSE
                L_Pulse_Lock_1_Open := FALSE;
            END_IF;
        END_IF;

        IF L_Pulse_Lock_1_Close THEN
            L_Elapsed_MS := SEL(L_Now_MS >= L_Start_Lock_1_Close_MS, L_Now_MS - L_Start_Lock_1_Close_MS, (4294967295 - L_Start_Lock_1_Close_MS) + L_Now_MS + 1);
            IF L_Elapsed_MS < L_Pulse_MS THEN
                L_Lock_1_Close := TRUE;
            ELSE
                L_Pulse_Lock_1_Close := FALSE;
            END_IF;
        END_IF;

        IF L_Pulse_Lock_2_Open THEN
            L_Elapsed_MS := SEL(L_Now_MS >= L_Start_Lock_2_Open_MS, L_Now_MS - L_Start_Lock_2_Open_MS, (4294967295 - L_Start_Lock_2_Open_MS) + L_Now_MS + 1);
            IF L_Elapsed_MS < L_Pulse_MS THEN
                L_Lock_2_Open := TRUE;
            ELSE
                L_Pulse_Lock_2_Open := FALSE;
            END_IF;
        END_IF;

        IF L_Pulse_Lock_2_Close THEN
            L_Elapsed_MS := SEL(L_Now_MS >= L_Start_Lock_2_Close_MS, L_Now_MS - L_Start_Lock_2_Close_MS, (4294967295 - L_Start_Lock_2_Close_MS) + L_Now_MS + 1);
            IF L_Elapsed_MS < L_Pulse_MS THEN
                L_Lock_2_Close := TRUE;
            ELSE
                L_Pulse_Lock_2_Close := FALSE;
            END_IF;
        END_IF;

        IF L_Pulse_Gate_Open THEN
            L_Elapsed_MS := SEL(L_Now_MS >= L_Start_Gate_Open_MS, L_Now_MS - L_Start_Gate_Open_MS, (4294967295 - L_Start_Gate_Open_MS) + L_Now_MS + 1);
            IF L_Elapsed_MS < L_Pulse_MS THEN
                L_Gate_Open := TRUE;
            ELSE
                L_Pulse_Gate_Open := FALSE;
            END_IF;
        END_IF;

        IF L_Pulse_Wicket_Open THEN
            L_Elapsed_MS := SEL(L_Now_MS >= L_Start_Wicket_Open_MS, L_Now_MS - L_Start_Wicket_Open_MS, (4294967295 - L_Start_Wicket_Open_MS) + L_Now_MS + 1);
            IF L_Elapsed_MS < L_Pulse_MS THEN
                L_Wicket_Open := TRUE;
            ELSE
                L_Pulse_Wicket_Open := FALSE;
            END_IF;
        END_IF;

        L_Prev_Lock_1_Open := GVL_COMMAND_SHADOW.G_Lock_1_Open;
        L_Prev_Lock_1_Close := GVL_COMMAND_SHADOW.G_Lock_1_Close;
        L_Prev_Lock_2_Open := GVL_COMMAND_SHADOW.G_Lock_2_Open;
        L_Prev_Lock_2_Close := GVL_COMMAND_SHADOW.G_Lock_2_Close;
        L_Prev_Gate_Open := GVL_COMMAND_SHADOW.G_Gate_Open;
        L_Prev_Wicket_Open := GVL_COMMAND_SHADOW.G_Wicket_Open;
END_CASE;

fbProjection(
    VI_Lock_1_Open := L_Lock_1_Open,
    VI_Lock_1_Close := L_Lock_1_Close,
    VI_Lock_2_Open := L_Lock_2_Open,
    VI_Lock_2_Close := L_Lock_2_Close,
    VI_Gate_Open := L_Gate_Open,
    VI_Wicket_Open := L_Wicket_Open
);

// >>> BULK_SYNC_ANCHOR: PRG_Access <<<

FOR L_i := 1 TO 4 DO
    L_Pumps_4[L_i] := GVL_HEATING_OUTPUT.DO_Manifold_Pumps[L_i];
END_FOR;

fbSystemDiagnostics();

fbStateTraceLog(
    VI_System_Time := GVL_TIME_SERVICE.G_Now_MS,
    VI_Gas_Alarm := GVL_ALARM.G_Gas_Alarm_Active,
    VI_Leak_Alarm := GVL_ALARM.G_Flood_Alarm_Active,
    VI_Pumps := L_Pumps_4,
    VO_Last_Change_Time => L_Last_State_Trace_MS
);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO

    L_Hum := 0.0;

    IF GVL_BEHAVIOR_ADAPT.G_Prev_Valid[L_i] THEN
        L_PrevHum := GVL_BEHAVIOR_ADAPT.G_Prev_Humidity[L_i];
    ELSE
        L_PrevHum := L_Hum;
    END_IF;

    L_DeltaHum := L_PrevHum - L_Hum;

    IF ABS(L_DeltaHum) < 0.5 THEN
        L_Confidence := 0.2;
    ELSE
        L_Confidence := 1.0;
    END_IF;

    IF GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost THEN
        fbAdapt(
            iScenario := REASON_SCENARIO_VENT_BOOST,
            iSuccess := (L_DeltaHum > 5.0),
            iMeasuredValue := L_Hum,
            iZone := L_i,
            iConfidence := L_Confidence
        );
    END_IF;

    GVL_BEHAVIOR_ADAPT.G_Prev_Humidity[L_i] := L_Hum;
    GVL_BEHAVIOR_ADAPT.G_Prev_Valid[L_i] := TRUE;

END_FOR;

IF GVL_INTENT_BEHAVIOR.I_Request_Night_Mode THEN
    fbAdapt(
        iScenario := REASON_SCENARIO_NIGHT,
        iSuccess := TRUE,
        iMeasuredValue := 0.0,
        iZone := 0,
        iConfidence := 1.0
    );
END_IF;

// Extracted from PRG_System (Phase 5A).
// Idempotent projection: safe to run while legacy call still exists.
L_Gateway_Writes_Allowed :=
    NOT GVL_STATUS.G_Diagnostics.Dangerous_Action_Pending_Confirm AND
    NOT GVL_STATUS.G_Diagnostics.Operator_Action_Blocked AND
    NOT GVL_STATUS.G_Diagnostics.User_Access_Denied;

fbSystemIntentPublisher(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Gateway_Writes_Allowed := L_Gateway_Writes_Allowed
);

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Commit_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// SEMANTIC PUBLICATION COMMIT GOVERNOR
// ======================================================
// Governs semantic publication checkpoint coherence.
// Downstream/publication continuity only.
// Does not invalidate runtime barrier, PLC fencing,
// immutable snapshots, distributed commit or IO authority.
// ======================================================

GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Mismatch := FALSE;
GVL_SEMANTIC_COMMIT.Semantic_Commit_Mismatch := FALSE;
GVL_SEMANTIC_COMMIT.Semantic_Rollback_Detected := FALSE;
GVL_SEMANTIC_COMMIT.Semantic_Replay_Fenced := FALSE;
GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Missing := FALSE;
GVL_SEMANTIC_COMMIT.Semantic_Commit_Lease_Expired := FALSE;

// ------------------------------------------------------
// Semantic checkpoint epoch progression.
// ------------------------------------------------------

GVL_SEMANTIC_COMMIT.Local_Semantic_Checkpoint_Epoch :=
    GVL_SEMANTIC_COMMIT.Local_Semantic_Checkpoint_Epoch + 1;

GVL_SEMANTIC_COMMIT.Local_Semantic_Commit_Epoch :=
    GVL_SEMANTIC_COMMIT.Local_Semantic_Commit_Epoch + 1;

// ------------------------------------------------------
// Rollback/replay fencing foundation.
// ------------------------------------------------------

IF GVL_SEMANTIC_COMMIT.Peer_Semantic_Checkpoint_Epoch
< GVL_SEMANTIC_COMMIT.Local_Semantic_Checkpoint_Epoch THEN
    GVL_SEMANTIC_COMMIT.Semantic_Rollback_Detected := TRUE;
    GVL_SEMANTIC_COMMIT.Semantic_Replay_Fenced := TRUE;

    L_Commit_Valid := FALSE;
    L_Error_Code := 18000;
    L_Error_Text := 'Semantic rollback detected';
END_IF;

// ------------------------------------------------------
// Checkpoint acknowledgement foundation.
// ------------------------------------------------------

IF L_Commit_Valid THEN
    IF NOT GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Ack_Valid THEN
        GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Missing := TRUE;

        L_Commit_Valid := FALSE;
        L_Error_Code := 18001;
        L_Error_Text := 'Semantic checkpoint acknowledgement missing';
    END_IF;
END_IF;

// ------------------------------------------------------
// Semantic checkpoint mismatch foundation.
// ------------------------------------------------------

IF L_Commit_Valid THEN
    IF GVL_SEMANTIC_COMMIT.Peer_Semantic_Commit_Epoch
    <> GVL_SEMANTIC_COMMIT.Local_Semantic_Commit_Epoch THEN
        GVL_SEMANTIC_COMMIT.Semantic_Commit_Mismatch := TRUE;

        L_Commit_Valid := FALSE;
        L_Error_Code := 18002;
        L_Error_Text := 'Semantic commit mismatch detected';
    END_IF;
END_IF;

// ------------------------------------------------------
// Semantic commit lease freshness.
// ------------------------------------------------------

L_Delta_MS :=
    L_Now_MS - GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Refresh_MS;

IF L_Commit_Valid
AND GVL_SEMANTIC_COMMIT.Semantic_Commit_Lease_Active THEN
    IF L_Delta_MS > GVL_SEMANTIC_COMMIT.Semantic_Commit_Timeout_MS THEN
        GVL_SEMANTIC_COMMIT.Semantic_Commit_Lease_Expired := TRUE;

        L_Commit_Valid := FALSE;
        L_Error_Code := 18003;
        L_Error_Text := 'Semantic commit lease expired';
    END_IF;
END_IF;

// ------------------------------------------------------
// Publish semantic commit coherence foundation.
// ------------------------------------------------------

IF L_Commit_Valid THEN
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Epoch :=
        GVL_SEMANTIC_COMMIT.Semantic_Commit_Epoch + 1;

    GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Epoch :=
        GVL_SEMANTIC_COMMIT.Semantic_Checkpoint_Epoch + 1;

    GVL_SEMANTIC_COMMIT.Semantic_Publication_Commit_Epoch :=
        GVL_SEMANTIC_COMMIT.Semantic_Publication_Commit_Epoch + 1;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Valid := TRUE;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Lease_Active := TRUE;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Lease_Expired := FALSE;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Quarantine_Active := FALSE;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Forced_Safe_Mode := FALSE;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Refresh_MS := L_Now_MS;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Error_Code := 0;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Error_Text := '';
ELSE
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Valid := FALSE;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Quarantine_Active := TRUE;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Forced_Safe_Mode := TRUE;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Error_Code := L_Error_Code;
    GVL_SEMANTIC_COMMIT.Semantic_Commit_Last_Error_Text := L_Error_Text;

    GVL_SEMANTIC_COMMIT.Semantic_Commit_Invalidation_Count :=
        GVL_SEMANTIC_COMMIT.Semantic_Commit_Invalidation_Count + 1;
END_IF;

L_Fire_Alarm_Active := GVL_ALARM.G_Fire_Alarm_Active OR GVL_STATE.G_Safety_Smoke_Latched;
L_Security_Armed := GVL_ALARM.G_Security_Armed;
L_Security_Alarm := GVL_ALARM.G_Security_Alarm;
L_Evac_Blink_Phase := (GVL_STATUS.G_System_Time_MS / 500) MOD 2;
L_Evac_Blink_On := (L_Evac_Blink_Phase = 0);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    IF GVL_INTENT_SYSTEM.I_Lighting_Overrides_Block OR GVL_SYSTEM_COORDINATION.G_Block_Lighting_Override THEN
        L_Manual_Light_Override[L_i] := 0;
    ELSE
        L_Manual_Light_Override[L_i] := GVL_INTENT_USER.I_Lighting_Override_32[L_i];
    END_IF;

    L_Sim_Lights[L_i] := GVL_STATE.G_Sim_Lights[L_i];
    L_Physical_Switches[L_i] := GVL_STATE.G_Physical_Switches[L_i];
    L_Motion_Sensors[L_i] := GVL_STATE.G_Motion_Sensors[L_i];

    IF GVL_INTENT_SYSTEM.I_Blinds_Overrides_Block THEN
        L_Manual_Blinds_Override[L_i] := 0;
    ELSE
        L_Manual_Blinds_Override[L_i] := GVL_INTENT_USER.I_Blinds_Override_32[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
    L_Blinds_Override[L_i] := L_Manual_Blinds_Override[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    IF GVL_INTENT_SYSTEM.I_Socket_Overrides_Block OR GVL_SYSTEM_COORDINATION.G_Block_Sockets_Override THEN
        L_Manual_Socket_Override[L_i] := FALSE;
    ELSE
        L_Manual_Socket_Override[L_i] := GVL_INTENT_USER.I_Socket_Override_32[L_i];
    END_IF;
    L_Socket_Override[L_i] := L_Manual_Socket_Override[L_i];
END_FOR;

fbLightingManager(
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_Current_Scenario := GVL_STATUS.G_Current_Scenario,
    VI_Away_Level := 1,
    VI_Simulation_Active := GVL_STATUS.G_Sim_Active,
    VI_Is_Night := GVL_STATUS.G_Is_Night,
    VI_System_Mode := GVL_STATE.G_System_Mode,
    VI_Manual_Light_Override := L_Manual_Light_Override,
    VI_Manual_Blinds_Override := L_Blinds_Override,
    VI_Simulation_Lights := L_Sim_Lights,
    VI_Physical_Switches := L_Physical_Switches,
    VI_Motion_Sensors := L_Motion_Sensors,
    VI_Rule_Actions := GVL_STATE.G_Rule_Actions,
    VI_IO_Modules_Online := GVL_STATUS.G_IO_Modules_Online,
    VI_Wet_Zone_Map := GVL_CONFIG.G_Wet_Zone_Map,
    VI_Scenario_Configs := GVL_CONFIG.G_HMI_Scenario_Configs,
    VO_Lighting_Levels => GVL_STATE.G_Lighting_Levels,
    VO_Blinds_Positions => GVL_STATE.G_Blinds_Positions,
    VO_Wet_Zone_Light_Active => L_Wet_Zone_Light_Active
);

fbSocketManager(
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_Scenario := GVL_STATUS.G_Current_Scenario,
    VI_Manual_Override := L_Socket_Override,
    VI_Physical_Switches := GVL_STATE.G_Socket_Switches,
    VI_Rule_Actions := GVL_STATE.G_Rule_Actions,
    VI_Fire_Alarm := GVL_ALARM.G_Fire_Alarm_Active,
    VI_Flood_Alarm := GVL_ALARM.G_Flood_Alarm_Active,
    VI_Security_Armed := GVL_ALARM.G_Security_Armed,
    VI_IO_Modules_Online := GVL_STATUS.G_IO_Modules_Online,
    VO_Socket_States => GVL_STATE.G_Socket_States
);

// Priority overrides after normal manager calculation:
// Evacuation > Fire > Security Alarm > Security Armed > Normal
IF GVL_STATE.G_Evacuation_Lighting_Active THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        CASE GVL_STATE.G_Evac_Guidance[L_i] OF
            -1:
                GVL_STATE.G_Lighting_Levels[L_i] := 0;
            1:
                GVL_STATE.G_Lighting_Levels[L_i] := 100;
        ELSE
            IF L_Evac_Blink_On THEN
                GVL_STATE.G_Lighting_Levels[L_i] := 100;
            ELSE
                GVL_STATE.G_Lighting_Levels[L_i] := 0;
            END_IF;
        END_CASE;
    END_FOR;
ELSIF L_Fire_Alarm_Active THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        GVL_STATE.G_Lighting_Levels[L_i] := 100;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
        GVL_STATE.G_Blinds_Positions[L_i] := 100;
    END_FOR;
ELSIF L_Security_Alarm THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        GVL_STATE.G_Lighting_Levels[L_i] := 100;
    END_FOR;
ELSIF L_Security_Armed THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        GVL_STATE.G_Lighting_Levels[L_i] := 0;
    END_FOR;
END_IF;

// Publish wet-zone activity from the final lighting state seen by IO_Write.
L_Wet_Zone_Any_Active := FALSE;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    IF GVL_CONFIG.G_Wet_Zone_Map[L_i] AND (GVL_STATE.G_Lighting_Levels[L_i] > 10) THEN
        L_Wet_Zone_Any_Active := TRUE;
    END_IF;
END_FOR;
GVL_STATUS.G_Wet_Zone_Light_Active := L_Wet_Zone_Any_Active;

// ======================================================
// DOMAIN OUTPUT PROJECTION
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    GVL_LIGHTING_OUTPUT.AO_Lighting_Levels[L_i] := BYTE_TO_UINT(GVL_STATE.G_Lighting_Levels[L_i]) * 10;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
    GVL_LIGHTING_OUTPUT.AO_Blinds_Positions[L_i] := BYTE_TO_UINT(GVL_STATE.G_Blinds_Positions[L_i]) * 10;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    GVL_LIGHTING_OUTPUT.DO_Sockets[L_i] := GVL_STATE.G_Socket_States[L_i];
END_FOR;

// >>> BULK_SYNC_ANCHOR: PRG_Lighting <<<

// Alarm orchestration based on global health snapshot
fbSystemAlarmOrchestrator(
    VI_First_Fault_Active := GVL_SYSTEM_HEALTH.G_First_Fault_Active,
    VI_First_Fault_Type := GVL_SYSTEM_HEALTH.G_First_Fault_Type,
    VI_First_Fault_Source := GVL_SYSTEM_HEALTH.G_First_Fault_Source
);

// Gateway intent execution
fbSystemGatewayIntent(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_Gateway_Writes_Allowed := NOT GVL_STATUS.G_Diagnostics.Operator_Action_Blocked,
    VIO_FloorHeating_Temps := GVL_STATE.G_Floor_Temps,
    VIO_Zone_Valve_States := GVL_STATE.G_Zone_Valves,
    VIO_Lighting_Base_Levels := GVL_STATE.G_Lighting_Levels,
    VIO_Scenario_Req_Gateway := L_Scenario_Req_Gateway
);

GVL_INTENT_USER.I_Scenario_Request := L_Scenario_Req_Gateway;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Block_IO := FALSE;
L_Error_Code := 0;
L_Error_Text := '';
L_Any_Manifold_Pump_On := FALSE;
L_Prev_Block_IO := GVL_COMMAND_VERIFY.PreOutput_Block_IO;

// ======================================================
// PRE-OUTPUT SAFETY BARRIER
// ======================================================
// This PRG executes after domain output projection and before PRG_IO_Write.
// It validates current-cycle command/domain-output semantics before any
// final physical IO projection can be published by PRG_IO_Write.
//
// RISK coverage:
//   - RISK-015 command/execution divergence
//   - RISK-037 scan-cycle visibility gap
//   - RISK-038 post-arbitration mutation window
//   - RISK-040 verifier-after-IO physical unsafe window
//   - RISK-047 stale/unsafe output survivability foundation
// ======================================================

// PLC inactive must never continue toward normal IO projection.
IF (NOT L_Block_IO) AND (NOT GVL_STATUS.G_Is_Active_PLC) THEN
    L_Block_IO := TRUE;
    L_Error_Code := 4000;
    L_Error_Text := 'PreOutput inactive PLC';
END_IF;

// Command mismatch must be blocked before IO projection.
IF (NOT L_Block_IO) AND (GVL_COMMAND.G_Gas_Valve_Close <> GVL_COMMAND_SHADOW.G_Gas_Valve_Close) THEN
    L_Block_IO := TRUE;
    L_Error_Code := 4001;
    L_Error_Text := 'PreOutput gas command mismatch';
END_IF;

IF (NOT L_Block_IO) AND (GVL_COMMAND.G_Boiler_Stop <> GVL_COMMAND_SHADOW.G_Boiler_Stop) THEN
    L_Block_IO := TRUE;
    L_Error_Code := 4002;
    L_Error_Text := 'PreOutput boiler command mismatch';
END_IF;

IF (NOT L_Block_IO) AND (GVL_COMMAND.G_Vent_Stop <> GVL_COMMAND_SHADOW.G_Vent_Stop) THEN
    L_Block_IO := TRUE;
    L_Error_Code := 4003;
    L_Error_Text := 'PreOutput vent command mismatch';
END_IF;

IF (NOT L_Block_IO) AND (GVL_COMMAND.G_Close_Valve_35 <> GVL_COMMAND_SHADOW.G_Close_Valve_35) THEN
    L_Block_IO := TRUE;
    L_Error_Code := 4004;
    L_Error_Text := 'PreOutput valve 35 command mismatch';
END_IF;

IF (NOT L_Block_IO) AND (GVL_COMMAND.G_Close_Valve_36 <> GVL_COMMAND_SHADOW.G_Close_Valve_36) THEN
    L_Block_IO := TRUE;
    L_Error_Code := 4005;
    L_Error_Text := 'PreOutput valve 36 command mismatch';
END_IF;

// GAS safety requires gas valve close command before IO projection.
IF (NOT L_Block_IO) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS) AND (NOT GVL_COMMAND_SHADOW.G_Gas_Valve_Close) THEN
    L_Block_IO := TRUE;
    L_Error_Code := 4010;
    L_Error_Text := 'PreOutput gas valve close missing';
END_IF;

// GAS safety requires non-zero ventilation intent/output before IO projection.
IF (NOT L_Block_IO) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS) THEN
    IF (GVL_VENT_OUTPUT.AO_Supply_Fans[1] = 0) AND (GVL_VENT_OUTPUT.AO_Exhaust_Fans[1] = 0) THEN
        L_Block_IO := TRUE;
        L_Error_Code := 4011;
        L_Error_Text := 'PreOutput gas ventilation inactive';
    END_IF;
END_IF;

// FIRE safety requires smoke exhaust output and no supply fan output.
IF (NOT L_Block_IO) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        IF GVL_VENT_OUTPUT.AO_Exhaust_Fans[L_i] = 0 THEN
            L_Block_IO := TRUE;
            L_Error_Code := 4020;
            L_Error_Text := 'PreOutput smoke exhaust inactive';
        END_IF;
    END_FOR;
END_IF;

IF (NOT L_Block_IO) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        IF GVL_VENT_OUTPUT.AO_Supply_Fans[L_i] <> 0 THEN
            L_Block_IO := TRUE;
            L_Error_Code := 4021;
            L_Error_Text := 'PreOutput supply active in fire';
        END_IF;
    END_FOR;
END_IF;

// WATER_LEAK safety requires close commands and close output intent before IO projection.
IF (NOT L_Block_IO) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = WATER_LEAK) THEN
    IF GVL_COMMAND_SHADOW.G_Close_Valve_35 AND (NOT GVL_WATER_OUTPUT.DO_Water_Valve_35_Close) THEN
        L_Block_IO := TRUE;
        L_Error_Code := 4030;
        L_Error_Text := 'PreOutput valve 35 close output missing';
    ELSIF GVL_COMMAND_SHADOW.G_Close_Valve_36 AND (NOT GVL_WATER_OUTPUT.DO_Water_Valve_36_Close) THEN
        L_Block_IO := TRUE;
        L_Error_Code := 4031;
        L_Error_Text := 'PreOutput valve 36 close output missing';
    END_IF;
END_IF;

// FREEZE protection must keep at least one circulation path available.
IF (NOT L_Block_IO) AND GVL_STATE.G_Safety_Freeze_Risk THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF GVL_HEATING_OUTPUT.DO_Manifold_Pumps[L_i] THEN
            L_Any_Manifold_Pump_On := TRUE;
        END_IF;
    END_FOR;

    IF (NOT L_Any_Manifold_Pump_On) AND (NOT GVL_HEATING_OUTPUT.DO_Backup_Circulation_Pump) THEN
        L_Block_IO := TRUE;
        L_Error_Code := 4040;
        L_Error_Text := 'PreOutput freeze circulation inactive';
    END_IF;
END_IF;

// Publish pre-output barrier status.
GVL_COMMAND_VERIFY.PreOutput_Barrier_OK := NOT L_Block_IO;
GVL_COMMAND_VERIFY.PreOutput_Block_IO := L_Block_IO;
GVL_COMMAND_VERIFY.PreOutput_Last_Error_Code := L_Error_Code;
GVL_COMMAND_VERIFY.PreOutput_Last_Error_Text := L_Error_Text;

IF L_Block_IO THEN
    GVL_COMMAND_VERIFY.PreOutput_Last_Error_Time_MS := L_Now_MS;

    // IO_Write consumes PreOutput_Block_IO as the hard-stop gate.
    // Command shadow remains owned by PRG_Command_Arbitration.
    // Runtime sanity diagnostics remain owned by PRG_Command_Verifier.
    IF NOT L_Prev_Block_IO THEN
        GVL_COMMAND_VERIFY.PreOutput_Block_Count := GVL_COMMAND_VERIFY.PreOutput_Block_Count + 1;
        fbLog(
            VI_Event_Type := 1002,
            VI_Timestamp := L_Now_MS,
            VI_Param1 := L_Error_Code,
            VI_Param2 := GVL_COMMAND_VERIFY.PreOutput_Block_Count
        );
    END_IF;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    L_Boiler_Modulation_REAL[L_i] := TO_REAL(GVL_IO.AI_Boiler_Modulation[L_i]);
END_FOR;

L_Current_Hour := TO_UINT(GVL_TIME_SERVICE.G_Time_Of_Day_MS / 3600000);

L_Heating_Emergency_Stop := GVL_COMMAND_SHADOW.G_Heating_Emergency_Stop;
L_Heating_Gas_Safety_Stop := GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop OR GVL_STATE.G_Safety_Gas_Latched;

L_Runtime_Context.Runtime_Enabled := TRUE;
L_Runtime_Context.Runtime_Ready := TRUE;
L_Runtime_Context.Runtime_Fault := FALSE;
L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_IDLE;

L_Runtime_Context.Allow_DHW_Phase := TRUE;
L_Runtime_Context.Allow_Heating_Phase := TRUE;
L_Runtime_Context.Allow_Service_Gating_Phase := TRUE;
L_Runtime_Context.Allow_State_Publication_Phase := TRUE;
L_Runtime_Context.Allow_Diagnostics_Phase := TRUE;
L_Runtime_Context.Allow_Output_Projection_Phase := TRUE;

L_Runtime_Context.DHW_Executed := FALSE;
L_Runtime_Context.Heating_Executed := FALSE;
L_Runtime_Context.Service_Gating_Executed := FALSE;
L_Runtime_Context.State_Publication_Executed := FALSE;
L_Runtime_Context.Diagnostics_Executed := FALSE;
L_Runtime_Context.Output_Projection_Executed := FALSE;

L_Runtime_Context.DHW_Before_Heating_Valid := TRUE;
L_Runtime_Context.State_Publication_Before_Diagnostics_Valid := TRUE;
L_Runtime_Context.Output_Projection_Last_Valid := TRUE;

L_Runtime_Context.Diagnostics_Isolation_Valid := TRUE;
L_Runtime_Context.Explainability_Isolation_Valid := TRUE;
L_Runtime_Context.Safety_Isolation_Valid := TRUE;
L_Runtime_Context.OpenTherm_Ownership_Valid := TRUE;
L_Runtime_Context.Cascade_Ownership_Valid := TRUE;

L_Runtime_Context.Runtime_Status_Code := 1;
L_Runtime_Context.Runtime_Status_Text := 'Heating runtime nominal';

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_IDLE;

fbObserverPhase(
    VI_Authorization_Stage := TRUE,
    VI_Finalization_Stage := FALSE,
    VI_Runtime_Context := L_Runtime_Context,
    VI_Diagnostics_Valid := TRUE
);

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_DHW;

fbDHWManager(
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_Current_TOD := GVL_STATUS.G_Current_TOD,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_Temp := GVL_STATE.G_DHW_Temp,
    VI_Pressure := GVL_STATE.G_DHW_Pressure,
    VI_Config := GVL_CONFIG.G_DHW_Config,
    VI_Current_Day_Of_Week := GVL_STATUS.G_Current_Day,
    VI_IO_Modules_Online := GVL_STATUS.G_IO_Modules_Online,
    VI_Reset_Errors := GVL_INTENT_USER.I_Reset_Errors,
    VI_Emergency_Stop := L_Heating_Emergency_Stop,
    VI_System_Mode := GVL_STATE.G_System_Mode,
    VO_Status => L_DHW_Status,
    VO_Heating_Pump => L_DHW_Heating_Pump,
    VO_Circ_Pump => L_DHW_Circ_Pump
);

L_Runtime_Context.DHW_Executed := TRUE;

IF L_Heating_Gas_Safety_Stop THEN
    L_DHW_Heating_Pump := FALSE;
    L_DHW_Status.Heating_Pump_On := FALSE;
END_IF;

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_HEATING;

fbHeatingManager(
    VI_System_Mode := GVL_STATE.G_System_Mode,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_Outdoor_Temp := GVL_STATE.G_Outdoor_Temp,
    VI_Config := GVL_CONFIG.G_Heating_Config,
    VI_Tariff := GVL_CONFIG.G_HMI_Tariff_Settings,
    VI_Current_Hour := L_Current_Hour,
    VI_DHW_Heating_Demand := L_DHW_Heating_Pump,
    VI_DHW_Target_Temp := GVL_CONFIG.G_DHW_Config.Target_Temp,
    VI_Emergency_Stop := L_Heating_Emergency_Stop,
    VI_Gas_Safety_Stop := L_Heating_Gas_Safety_Stop,
    VI_Boiler_Error_Status := GVL_STATE.G_Boiler_Error,
    VI_Boiler_OT_Online := GVL_STATE.G_Boiler_OT_Online,
    VI_Boiler_Modulation := L_Boiler_Modulation_REAL,
    VI_Floor_Temps := GVL_STATE.G_Floor_Temps,
    VI_Room_Temps := GVL_STATE.G_Room_Temps,
    VI_Manifold_Pressures := GVL_STATE.G_Manifold_Pressures,
    VI_Manifold_Currents := GVL_STATE.G_Manifold_Currents,
    VI_Manifold_Temps_Supply := GVL_STATE.G_Manifold_T_Supply,
    VI_Manifold_Temps_Return := GVL_STATE.G_Manifold_T_Return,
    VI_Boiler_Flame_Status := GVL_STATE.G_Boiler_Flame,
    VI_Zone_Configs := GVL_CONFIG.G_HMI_FloorHeating_Configs,
    VI_Rule_Actions := GVL_STATE.G_Rule_Actions,
    VI_IO_Modules_Online := GVL_STATUS.G_IO_Modules_Online,
    VI_Manifold_End_Switches := GVL_STATE.G_Manifold_End_Switches,
    VI_Valve_Test_Config := GVL_CONFIG.G_Valve_Test_Config,
    VO_Manifold_Valves => L_Manifold_Valves,
    VO_Manifold_Pumps => L_Manifold_Pumps,
    VO_Zone_Valves => L_Zone_Valves,
    VO_Boiler_OT_Enable => L_Boiler_OT_Enable,
    VO_Boiler_OT_Setpoint => L_Boiler_OT_Setpoint,
    VO_Backup_Circulation_Pump => L_Backup_Circulation_Pump,
    VO_Electric_Heater_Enable => L_Electric_Heater_Enable,
    VO_Freeze_Risk_Status => L_Freeze_Risk_Status,
    VO_Status => L_Manifold_Status,
    VO_Boiler_Status => L_Boiler_Status
);

L_Runtime_Context.Heating_Executed := TRUE;

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_SERVICE_GATING;

fbServiceGatingPhase(
    VI_Enable := TRUE,
    VIO_Manifold_Pumps := L_Manifold_Pumps,
    VIO_Backup_Circulation_Pump := L_Backup_Circulation_Pump,
    VIO_Electric_Heater_Enable := L_Electric_Heater_Enable,
    VIO_DHW_Heating_Pump := L_DHW_Heating_Pump,
    VIO_DHW_Circ_Pump := L_DHW_Circ_Pump,
    VIO_DHW_Status := L_DHW_Status,
    VIO_Freeze_Risk_Status := L_Freeze_Risk_Status
);

L_Runtime_Context.Service_Gating_Executed := fbServiceGatingPhase.VO_Executed;
L_Runtime_Context.Safety_Isolation_Valid := fbServiceGatingPhase.VO_Valid;

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_STATE_PUBLICATION;

fbStatePublicationPhase(
    VI_Enable := TRUE,
    VI_Zone_Valves := L_Zone_Valves,
    VI_Manifold_Pumps := L_Manifold_Pumps,
    VI_Manifold_Valves := L_Manifold_Valves,
    VI_Boiler_OT_Enable := L_Boiler_OT_Enable,
    VI_Boiler_OT_Setpoint := L_Boiler_OT_Setpoint,
    VI_Backup_Circulation_Pump := L_Backup_Circulation_Pump,
    VI_Electric_Heater_Enable := L_Electric_Heater_Enable,
    VI_Freeze_Risk_Status := L_Freeze_Risk_Status,
    VI_Manifold_Status := L_Manifold_Status,
    VI_Boiler_Status := L_Boiler_Status,
    VI_DHW_Heating_Pump := L_DHW_Heating_Pump,
    VI_DHW_Circ_Pump := L_DHW_Circ_Pump,
    VI_DHW_Status := L_DHW_Status
);

L_Runtime_Context.State_Publication_Executed := fbStatePublicationPhase.VO_Executed;
L_Runtime_Context.State_Publication_Before_Diagnostics_Valid := fbStatePublicationPhase.VO_Valid;

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_DIAGNOSTICS;

fbDiagnosticsPhase(
    VI_Enable := TRUE,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

L_Runtime_Context.Diagnostics_Executed := fbDiagnosticsPhase.VO_Executed;
L_Runtime_Context.Diagnostics_Isolation_Valid := fbDiagnosticsPhase.VO_Valid;

fbObserverPhase(
    VI_Authorization_Stage := FALSE,
    VI_Finalization_Stage := TRUE,
    VI_Runtime_Context := L_Runtime_Context,
    VI_Diagnostics_Valid := L_Runtime_Context.Diagnostics_Isolation_Valid
);

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_OUTPUT_PROJECTION;

fbOutputProjectionPhase(
    VI_Enable := TRUE,
    VI_Zone_Valves := L_Zone_Valves,
    VI_Manifold_Pumps := L_Manifold_Pumps,
    VI_Manifold_Valves := L_Manifold_Valves,
    VI_DHW_Heating_Pump := L_DHW_Heating_Pump,
    VI_DHW_Circ_Pump := L_DHW_Circ_Pump,
    VI_Backup_Circulation_Pump := L_Backup_Circulation_Pump,
    VI_Electric_Heater_Enable := L_Electric_Heater_Enable
);

L_Runtime_Context.Output_Projection_Executed := fbOutputProjectionPhase.VO_Executed;
L_Runtime_Context.Output_Projection_Last_Valid := fbOutputProjectionPhase.VO_Valid;

L_Runtime_Context.Current_Phase := E_Heating_Runtime_Phase.HRP_COMPLETE;

// >>> BULK_SYNC_ANCHOR: PRG_Heating <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;

// ======================================================
// OBSERVABILITY GOVERNOR
// ======================================================
// Pure downstream visibility aggregation layer.
//
// Observability does not:
// - own runtime authority;
// - arbitrate publication;
// - maintain synchronization barriers;
// - participate in quarantine governance.
// ======================================================

GVL_OBSERVABILITY_AUTHORITY.Runtime_Failure_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Output_Decay_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Transport_Failure_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Recovery_Failure_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Fencing_Failure_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Monotonic_Failure_Visible := FALSE;

GVL_OBSERVABILITY_AUTHORITY.Distributed_Failure_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Distributed_Quarantine_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Runtime_Stale_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Snapshot_Stale_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Boot_Mismatch_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Fencing_Conflict_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Semantic_Continuity_Lost_Visible := FALSE;

GVL_OBSERVABILITY_AUTHORITY.Distributed_Publication_Reconciliation_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Distributed_Publication_Freeze_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Distributed_Snapshot_Consistency_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Publication_Stale_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Publication_Divergence_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Publication_Reconciliation_Lost_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Snapshot_Not_Immutable_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Distributed_Immutable_Snapshot_Quarantine_Visible := FALSE;

GVL_OBSERVABILITY_AUTHORITY.Distributed_Commit_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Distributed_Commit_Quarantine_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Publication_Prepare_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Publication_Commit_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Ack_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Mismatch_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Replay_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Missing_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Commit_Lease_Expired_Visible := FALSE;

GVL_OBSERVABILITY_AUTHORITY.Unsafe_State_Published := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Emergency_Visibility_Required := FALSE;

IF NOT GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK THEN
    GVL_OBSERVABILITY_AUTHORITY.Runtime_Failure_Visible := TRUE;
    GVL_OBSERVABILITY_AUTHORITY.Emergency_Visibility_Required := TRUE;
END_IF;

IF GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay THEN
    GVL_OBSERVABILITY_AUTHORITY.Output_Decay_Visible := TRUE;
