GVL_INPUT.IN_Sensor_Fault := FALSE;

GVL_INPUT.IN_Min_Zone_Confidence := 1.0;
GVL_INPUT.IN_Worst_Zone := 0;

// ======================================================
// BASE ENVIRONMENT INPUT AGGREGATION
// ======================================================
GVL_INPUT.IN_Outdoor_Temp := GVL_STATE.G_Outdoor_Temp;
GVL_INPUT.IN_Preheat_Request := GVL_STATE.G_Preheat_Request;
GVL_INPUT.IN_Freeze_Request := GVL_STATE.G_Freeze_Request;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    GVL_INPUT.IN_Room_Temps[L_i] := GVL_STATE.G_Room_Temps[L_i];
    GVL_INPUT.IN_Room_Hum[L_i] := GVL_STATE.G_Room_Hum[L_i];
    GVL_INPUT.IN_Room_CO2[L_i] := GVL_STATE.G_Room_CO2[L_i];

    IF L_i <= GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS THEN
        GVL_INPUT.IN_Floor_Temps[L_i] := GVL_STATE.G_Floor_Temps[L_i];
    END_IF;

    // VALIDATION
    IF (GVL_INPUT.IN_Room_Temps[L_i] < GVL_INPUT_VALIDATION_CONFIG.G_Room_Temp_Min) OR
       (GVL_INPUT.IN_Room_Temps[L_i] > GVL_INPUT_VALIDATION_CONFIG.G_Room_Temp_Max) THEN
        GVL_INPUT.IN_Validation_Failed := TRUE;
        GVL_INPUT.IN_Input_Degraded := TRUE;
        GVL_INPUT.IN_Sensor_Fault := TRUE;
        GVL_INPUT.IN_Validation_Reason := 'Temp out of range';
        GVL_INPUT.IN_Last_Invalid_Zone := L_i;
    END_IF;

    IF (GVL_INPUT.IN_Room_Hum[L_i] < GVL_INPUT_VALIDATION_CONFIG.G_Room_Hum_Min) OR
       (GVL_INPUT.IN_Room_Hum[L_i] > GVL_INPUT_VALIDATION_CONFIG.G_Room_Hum_Max) THEN
        GVL_INPUT.IN_Validation_Failed := TRUE;
        GVL_INPUT.IN_Input_Degraded := TRUE;
        GVL_INPUT.IN_Sensor_Fault := TRUE;
        GVL_INPUT.IN_Validation_Reason := 'Hum out of range';
        GVL_INPUT.IN_Last_Invalid_Zone := L_i;
    END_IF;

    L_TempDelta := ABS(GVL_INPUT.IN_Room_Temps[L_i] - GVL_INPUT.IN_Room_Temp_Prev[L_i]);
    L_HumDelta := ABS(GVL_INPUT.IN_Room_Hum[L_i] - GVL_INPUT.IN_Room_Hum_Prev[L_i]);

    // INSTANT CONFIDENCE
    GVL_INPUT.IN_Room_Temp_Confidence[L_i] := GVL_INPUT_VALIDATION_CONFIG.G_Default_Confidence;
    GVL_INPUT.IN_Room_Hum_Confidence[L_i] := GVL_INPUT_VALIDATION_CONFIG.G_Default_Confidence;

    IF L_TempDelta > GVL_INPUT_VALIDATION_CONFIG.G_Room_Temp_Spike_Threshold THEN
        GVL_INPUT.IN_Room_Temp_Confidence[L_i] := GVL_INPUT_VALIDATION_CONFIG.G_Bad_Spike_Confidence;
        GVL_INPUT.IN_Anomaly_Detected := TRUE;
        GVL_INPUT.IN_Anomaly_Reason := 'Temp spike';
    END_IF;

    IF L_HumDelta > GVL_INPUT_VALIDATION_CONFIG.G_Room_Hum_Spike_Threshold THEN
        GVL_INPUT.IN_Room_Hum_Confidence[L_i] := GVL_INPUT_VALIDATION_CONFIG.G_Bad_Spike_Confidence;
        GVL_INPUT.IN_Anomaly_Detected := TRUE;
        GVL_INPUT.IN_Anomaly_Reason := 'Hum spike';
    END_IF;

    // REPUTATION
    IF GVL_INPUT_VALIDATION_CONFIG.G_Enable_Reputation_Learning THEN
        GVL_INPUT.IN_Room_Temp_Reputation[L_i] :=
            GVL_INPUT.IN_Room_Temp_Reputation[L_i] * (1.0 - GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate) +
            GVL_INPUT.IN_Room_Temp_Confidence[L_i] * GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate;

        GVL_INPUT.IN_Room_Hum_Reputation[L_i] :=
            GVL_INPUT.IN_Room_Hum_Reputation[L_i] * (1.0 - GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate) +
            GVL_INPUT.IN_Room_Hum_Confidence[L_i] * GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate;

        GVL_INPUT.IN_Room_Temp_Reputation[L_i] :=
            GVL_INPUT.IN_Room_Temp_Reputation[L_i] +
            (1.0 - GVL_INPUT.IN_Room_Temp_Reputation[L_i]) * GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Recovery_Decay;

        GVL_INPUT.IN_Room_Hum_Reputation[L_i] :=
            GVL_INPUT.IN_Room_Hum_Reputation[L_i] +
            (1.0 - GVL_INPUT.IN_Room_Hum_Reputation[L_i]) * GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Recovery_Decay;
    END_IF;

    IF GVL_INPUT.IN_Room_Temp_Reputation[L_i] < GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence THEN
        GVL_INPUT.IN_Room_Temp_Reputation[L_i] := GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence;
    END_IF;

    IF GVL_INPUT.IN_Room_Hum_Reputation[L_i] < GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence THEN
        GVL_INPUT.IN_Room_Hum_Reputation[L_i] := GVL_INPUT_VALIDATION_CONFIG.G_Min_Sensor_Confidence;
    END_IF;

    // FINAL
    GVL_INPUT.IN_Zone_Confidence[L_i] :=
        (GVL_INPUT.IN_Room_Temp_Confidence[L_i] * GVL_INPUT.IN_Room_Temp_Reputation[L_i] +
         GVL_INPUT.IN_Room_Hum_Confidence[L_i] * GVL_INPUT.IN_Room_Hum_Reputation[L_i]) / 2.0;

    IF GVL_INPUT.IN_Zone_Confidence[L_i] < GVL_INPUT.IN_Min_Zone_Confidence THEN
        GVL_INPUT.IN_Min_Zone_Confidence := GVL_INPUT.IN_Zone_Confidence[L_i];
        GVL_INPUT.IN_Worst_Zone := L_i;
    END_IF;

    GVL_INPUT.IN_Room_Temp_Prev[L_i] := GVL_INPUT.IN_Room_Temps[L_i];
    GVL_INPUT.IN_Room_Hum_Prev[L_i] := GVL_INPUT.IN_Room_Hum[L_i];
END_FOR;

// ======================================================
// SAFETY SENSOR INPUT AGGREGATION
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    GVL_INPUT.IN_Water_Sensors[L_i] := GVL_STATE.G_Water_Sensors[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SMOKE_SENSORS DO
    GVL_INPUT.IN_Smoke_Sensors[L_i] := GVL_STATE.G_Smoke_Sensors[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    GVL_INPUT.IN_Methane_Sensors[L_i] := GVL_STATE.G_Methane_Sensors[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_CO_SENSORS DO
    GVL_INPUT.IN_CO_Sensors[L_i] := GVL_STATE.G_CO_Sensors[L_i];
END_FOR;

// >>> BULK_SYNC_ANCHOR: PRG_Input_Processing <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO

    // ======================================================
    // HEARTBEAT VALIDATION
    // ======================================================
    IF GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Heartbeat <>
       GVL_OPENTHERM_ADAPTER.G_Status[L_i].Last_Heartbeat THEN

        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Last_Heartbeat :=
            GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Heartbeat;

        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Last_Heartbeat_MS := L_Now_MS;
    END_IF;

    L_Heartbeat_Age :=
        L_Now_MS - GVL_OPENTHERM_ADAPTER.G_Status[L_i].Last_Heartbeat_MS;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Heartbeat_Age_MS :=
        L_Heartbeat_Age;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Heartbeat_Timeout :=
        (L_Heartbeat_Age > GVL_CONFIG.G_OpenTherm_Heartbeat_Timeout_MS);

    // ======================================================
    // COMMAND ACK VALIDATION
    // ======================================================
    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Ack :=
        (GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Ack_Seq =
         GVL_OPENTHERM_ADAPTER.G_Command[L_i].Sequence);

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Last_Command_Ack_Seq :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Ack_Seq;

    L_Command_Age :=
        L_Now_MS - GVL_OPENTHERM_ADAPTER.G_Command[L_i].Last_Write_MS;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Age_MS :=
        L_Command_Age;

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Timeout :=
        (NOT GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Ack) AND
        (L_Command_Age > GVL_CONFIG.G_OpenTherm_Command_Ack_Timeout_MS);

    // ======================================================
    // FINAL ADAPTER STATE
    // ======================================================
    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Online :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Online AND
        (NOT GVL_OPENTHERM_ADAPTER.G_Status[L_i].Heartbeat_Timeout) AND
        (NOT GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Timeout);

    GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Error :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Error OR
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Timeout OR
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Heartbeat_Timeout;

    // ======================================================
    // ENUM STATES
    // ======================================================
    IF GVL_OPENTHERM_ADAPTER.G_Status[L_i].Heartbeat_Timeout THEN
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_State := OT_STATE_HEARTBEAT_TIMEOUT;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Error_State := OT_ERROR_HEARTBEAT_TIMEOUT;

    ELSIF GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Timeout THEN
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_State := OT_STATE_ACK_TIMEOUT;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Error_State := OT_ERROR_ACK_TIMEOUT;

    ELSIF GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Error THEN
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_State := OT_STATE_ADAPTER_ERROR;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Error_State := OT_ERROR_ADAPTER_FAULT;

    ELSIF GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Online THEN
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_State := OT_STATE_ONLINE;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Error_State := OT_ERROR_NONE;

    ELSE
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_State := OT_STATE_OFFLINE;
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Error_State := OT_ERROR_COMMUNICATION;
    END_IF;

    // ======================================================
    // PUBLISH TO SYSTEM STATE
    // ======================================================
    GVL_STATE.G_Boiler_OT_Online[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Online;

    GVL_STATE.G_Boiler_OT_Command_Ack[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Ack;

    GVL_STATE.G_Boiler_OT_Command_Timeout[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Timeout;

    GVL_STATE.G_Boiler_OT_Heartbeat_Timeout[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Heartbeat_Timeout;

    GVL_STATE.G_Boiler_OT_Adapter_Error[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Error;

    GVL_STATE.G_Boiler_OT_Heartbeat_Age_MS[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Heartbeat_Age_MS;

    GVL_STATE.G_Boiler_OT_Command_Age_MS[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Command_Age_MS;

    GVL_STATE.G_Boiler_OT_Adapter_State[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_State;

    GVL_STATE.G_Boiler_OT_Error_State[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Error_State;

    GVL_STATE.G_Boiler_Error[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Adapter_Error;

    GVL_STATE.G_Boiler_Flame[L_i] :=
        GVL_OPENTHERM_ADAPTER.G_Status[L_i].Raw_Flame;

END_FOR;

fbIO_Watchdog_1(VI_System_Time_MS := GVL_STATUS.G_System_Time_MS, VI_Module_ID := 1, VI_Heartbeat_Signal := GVL_IO.DI_Module_1_Heartbeat, VI_Timeout_MS := 2000);
fbIO_Watchdog_2(VI_System_Time_MS := GVL_STATUS.G_System_Time_MS, VI_Module_ID := 2, VI_Heartbeat_Signal := GVL_IO.DI_Module_2_Heartbeat, VI_Timeout_MS := 2000);

GVL_STATUS.G_IO_Modules_Online[1] := fbIO_Watchdog_1.VO_Module_Online;
GVL_STATUS.G_IO_Modules_Online[2] := fbIO_Watchdog_2.VO_Module_Online;

L_IO_Error_Active := fbIO_Watchdog_1.VO_Error_Active OR fbIO_Watchdog_2.VO_Error_Active;

fbDiagEventManager(
    VI_Code := 16#E001,
    VI_Severity := 4,
    VI_Active := NOT fbIO_Watchdog_1.VO_Module_Online,
    VI_Timestamp := GVL_STATUS.G_System_Time_MS,
    VI_Source := 1,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

fbDiagEventManager(
    VI_Code := 16#E002,
    VI_Severity := 4,
    VI_Active := NOT fbIO_Watchdog_2.VO_Module_Online,
    VI_Timestamp := GVL_STATUS.G_System_Time_MS,
    VI_Source := 2,
    VIO_Events := GVL_STATUS.G_Diagnostics_Events,
    VIO_Count := GVL_STATUS.G_Diagnostics_Count
);

IF L_IO_Error_Active THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        GVL_STATE.G_Manifold_Pumps[L_i] := FALSE;
    END_FOR;
END_IF;

// Lighting and motion are sized by C_MAX_LIGHT_ZONES.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    fbDebounce_Switches[L_i](IN := GVL_IO.DI_Lighting_Switches[L_i], PT := L_Debounce_Time, VI_System_Time_MS := GVL_STATUS.G_System_Time_MS);
    GVL_STATE.G_Physical_Switches[L_i] := fbDebounce_Switches[L_i].Q;

    fbDebounce_Motion[L_i](IN := GVL_IO.DI_Motion_Sensors[L_i], PT := L_Debounce_Time, VI_System_Time_MS := GVL_STATUS.G_System_Time_MS);
    GVL_STATE.G_Motion_Sensors[L_i] := fbDebounce_Motion[L_i].Q;
END_FOR;

// Socket hardware inputs are propagated instead of being forced to FALSE.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    GVL_STATE.G_Socket_Switches[L_i] := GVL_IO.DI_Socket_Switches[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SECURITY_SENSORS DO
    fbDebounce_Security_Open[L_i](IN := GVL_IO.DI_Security_Open[L_i], PT := L_Debounce_Time, VI_System_Time_MS := GVL_STATUS.G_System_Time_MS);
    fbDebounce_Security_Glass[L_i](IN := GVL_IO.DI_Security_Glass[L_i], PT := L_Debounce_Time, VI_System_Time_MS := GVL_STATUS.G_System_Time_MS);
END_FOR;

fbDebounce_Group_2F(IN := GVL_IO.DI_Security_2F_Group, PT := L_Debounce_Time, VI_System_Time_MS := GVL_STATUS.G_System_Time_MS);

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_DOOR_SENSORS DO
    IF GVL_CONFIG.G_Door_Map[L_i] > 0 AND GVL_CONFIG.G_Door_Map[L_i] <= GVL_CONSTANTS.C_MAX_SECURITY_SENSORS THEN
        GVL_STATE.G_Door_Sensors[L_i] := fbDebounce_Security_Open[GVL_CONFIG.G_Door_Map[L_i]].Q;
    END_IF;
END_FOR;

// Window/opening mapping is limited by C_MAX_ZONES and protected by bounds checks.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Map_Index := GVL_CONFIG.G_Window_Map[L_i];
    IF L_Map_Index > 0 THEN
        IF L_Map_Index <= GVL_CONSTANTS.C_MAX_SECURITY_SENSORS THEN
            GVL_STATE.G_Window_Sensors[L_i] := fbDebounce_Security_Open[L_Map_Index].Q;
        ELSE
            L_Glass_Index := L_Map_Index - GVL_CONSTANTS.C_MAX_SECURITY_SENSORS;
            IF (L_Glass_Index >= 1) AND (L_Glass_Index <= GVL_CONSTANTS.C_MAX_SECURITY_SENSORS) THEN
                GVL_STATE.G_Window_Sensors[L_i] := fbDebounce_Security_Glass[L_Glass_Index].Q;
            END_IF;
        END_IF;
    END_IF;
END_FOR;
GVL_STATE.G_Window_Sensors[16] := fbDebounce_Group_2F.Q;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    fbDebounce_Flood[L_i](IN := GVL_IO.DI_Flood_Sensors[L_i], PT := L_Debounce_Time, VI_System_Time_MS := GVL_STATUS.G_System_Time_MS);
    GVL_STATE.G_Water_Sensors[L_i] := fbDebounce_Flood[L_i].Q;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SMOKE_SENSORS DO
    fbDebounce_Smoke[L_i](IN := GVL_IO.DI_Smoke_Sensors[L_i], PT := L_Debounce_Time, VI_System_Time_MS := GVL_STATUS.G_System_Time_MS);
    GVL_STATE.G_Smoke_Sensors[L_i] := fbDebounce_Smoke[L_i].Q;
END_FOR;

fbCalib_Outdoor_Temp(
    VI_Raw_Value := GVL_IO.AI_Temp_Outdoor.rValue,
    VI_Record := GVL_CONFIG.G_Calib_Outdoor_Temp
);
GVL_STATE.G_Outdoor_Temp := fbCalib_Outdoor_Temp.VO_Calibrated_Value;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_TEMPS DO
    IF GVL_IO.AI_Supply_Temps[L_i].wStatus = 0 THEN
        fbCalib_Supply_Temps[L_i](
            VI_Raw_Value := GVL_IO.AI_Supply_Temps[L_i].rValue,
            VI_Record := GVL_CONFIG.G_Calib_Supply_Temps[L_i]
        );
        GVL_STATE.G_Supply_Temps[L_i] := fbCalib_Supply_Temps[L_i].VO_Calibrated_Value;
    END_IF;
END_FOR;

// Humidity and CO2 IO/state/calibration arrays are sized by C_MAX_ZONES.
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    fbCalib_Room_Hum[L_i](
        VI_Raw_Value := GVL_IO.AI_Room_Hum[L_i],
        VI_Record := GVL_CONFIG.G_Calib_Humidity[L_i]
    );
    GVL_STATE.G_Room_Hum[L_i] := fbCalib_Room_Hum[L_i].VO_Calibrated_Value;

    fbCalib_Room_CO2[L_i](
        VI_Raw_Value := GVL_IO.AI_Room_CO2[L_i],
        VI_Record := GVL_CONFIG.G_Calib_CO2[L_i]
    );
    GVL_STATE.G_Room_CO2[L_i] := fbCalib_Room_CO2[L_i].VO_Calibrated_Value;
END_FOR;

// Room temperature filtering and range validation
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    fbCalib_Room_Temps[L_i](
        VI_Raw_Value := GVL_IO.AI_Room_Temps[L_i],
        VI_Record := GVL_CONFIG.G_Calib_Room_Temps[L_i]
    );

    IF GVL_STATE.G_Last_Valid_Room_Temps[L_i] = 0.0 THEN
        L_Filtered_Room_Temp := fbCalib_Room_Temps[L_i].VO_Calibrated_Value;
    ELSE
        L_Filtered_Room_Temp := (GVL_STATE.G_Last_Valid_Room_Temps[L_i] * 0.9) + (fbCalib_Room_Temps[L_i].VO_Calibrated_Value * 0.1);
    END_IF;

    IF (L_Filtered_Room_Temp < -50.0) OR (L_Filtered_Room_Temp > 100.0) THEN
        GVL_STATE.G_Temp_Sensor_Fault[L_i] := TRUE;
        GVL_STATE.G_Room_Temps[L_i] := GVL_STATE.G_Last_Valid_Room_Temps[L_i];
        GVL_STATUS.G_Diagnostics.Sensor_Fault := TRUE;
    ELSE
        GVL_STATE.G_Temp_Sensor_Fault[L_i] := FALSE;
        GVL_STATE.G_Room_Temps[L_i] := L_Filtered_Room_Temp;
        GVL_STATE.G_Last_Valid_Room_Temps[L_i] := L_Filtered_Room_Temp;
    END_IF;
END_FOR;

// Floor temperature filtering and range validation
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF L_i <= GVL_CONSTANTS.C_MAX_ZONES THEN
        fbCalib_Floor_Temps[L_i](
            VI_Raw_Value := GVL_IO.AI_Floor_Temps[L_i],
            VI_Record := GVL_CONFIG.G_Calib_Floor_Temps[L_i]
        );

        IF GVL_STATE.G_Last_Valid_Floor_Temps[L_i] = 0.0 THEN
            L_Filtered_Floor_Temp := fbCalib_Floor_Temps[L_i].VO_Calibrated_Value;
        ELSE
            L_Filtered_Floor_Temp := (GVL_STATE.G_Last_Valid_Floor_Temps[L_i] * 0.9) + (fbCalib_Floor_Temps[L_i].VO_Calibrated_Value * 0.1);
        END_IF;

        IF (L_Filtered_Floor_Temp < -50.0) OR (L_Filtered_Floor_Temp > 100.0) THEN
            GVL_STATE.G_Floor_Temp_Sensor_Fault[L_i] := TRUE;
            GVL_STATE.G_Floor_Temps[L_i] := GVL_STATE.G_Last_Valid_Floor_Temps[L_i];
            GVL_STATUS.G_Diagnostics.Sensor_Fault := TRUE;
        ELSE
            GVL_STATE.G_Floor_Temp_Sensor_Fault[L_i] := FALSE;
            GVL_STATE.G_Floor_Temps[L_i] := L_Filtered_Floor_Temp;
            GVL_STATE.G_Last_Valid_Floor_Temps[L_i] := L_Filtered_Floor_Temp;
        END_IF;
    ELSE
        GVL_STATE.G_Floor_Temp_Sensor_Fault[L_i] := TRUE;
        GVL_STATE.G_Floor_Temps[L_i] := GVL_STATE.G_Last_Valid_Floor_Temps[L_i];
    END_IF;
END_FOR;

GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Active := FALSE;
GVL_STATUS.G_Diagnostics.Manifold_Pressure_First_Fault_Index := 0;
GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Active := FALSE;
GVL_STATUS.G_Diagnostics.Manifold_Current_First_Fault_Index := 0;
GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Text := '';
GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Text := '';

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF GVL_IO.AI_Manifold_Pressures[L_i] < 0 THEN
        L_Manifold_Pressure_Raw := 0;
    ELSE
        L_Manifold_Pressure_Raw := INT_TO_WORD(GVL_IO.AI_Manifold_Pressures[L_i]);
    END_IF;

    IF GVL_IO.AI_Manifold_Currents[L_i] < 0 THEN
        L_Manifold_Current_Raw := 0;
    ELSE
        L_Manifold_Current_Raw := INT_TO_WORD(GVL_IO.AI_Manifold_Currents[L_i]);
    END_IF;

    fbAnalog_Manifold_Pressure[L_i](
        VI_Raw_Value := L_Manifold_Pressure_Raw,
        VI_Sensor_Type := 0,
        VI_Min_Scale := 0.0,
        VI_Max_Scale := 10.0,
        VI_Offset := 0.0,
        VI_Multiplier := 1.0,
        VI_Filter_Time_MS := GVL_CONSTANTS.C_MS_IN_SECOND,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
        VI_Fallback_Mode := 0,
        VI_Default_Value := 0.0
    );
    GVL_STATE.G_Manifold_Pressures[L_i] := fbAnalog_Manifold_Pressure[L_i].VO_Value;
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault[L_i] := fbAnalog_Manifold_Pressure[L_i].VO_Error;
    GVL_STATUS.G_Diagnostics.Manifold_Pressure_Diag_Code[L_i] := fbAnalog_Manifold_Pressure[L_i].VO_Diag_Code;

    fbDiagEventManager(
        VI_Code := GVL_CONFIG.ERR_PRESSURE_OUT_OF_RANGE,
        VI_Severity := 3,
        VI_Active := fbAnalog_Manifold_Pressure[L_i].VO_Error,
        VI_Timestamp := GVL_STATUS.G_System_Time_MS,
        VI_Source := 100 + L_i,
        VIO_Events := GVL_STATUS.G_Diagnostics_Events,
        VIO_Count := GVL_STATUS.G_Diagnostics_Count
    );

    fbAnalog_Manifold_Current[L_i](
        VI_Raw_Value := L_Manifold_Current_Raw,
        VI_Sensor_Type := 0,
        VI_Min_Scale := 0.0,
        VI_Max_Scale := 16.0,
        VI_Offset := 0.0,
        VI_Multiplier := 1.0,
        VI_Filter_Time_MS := GVL_CONSTANTS.C_MS_IN_SECOND,
        VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
        VI_Fallback_Mode := 0,
        VI_Default_Value := 0.0
    );
    GVL_STATE.G_Manifold_Currents[L_i] := fbAnalog_Manifold_Current[L_i].VO_Value;
    GVL_STATUS.G_Diagnostics.Manifold_Current_Fault[L_i] := fbAnalog_Manifold_Current[L_i].VO_Error;
    GVL_STATUS.G_Diagnostics.Manifold_Current_Diag_Code[L_i] := fbAnalog_Manifold_Current[L_i].VO_Diag_Code;

    fbDiagEventManager(
        VI_Code := GVL_CONFIG.ERR_PUMP_UNDERCURRENT,
        VI_Severity := 3,
        VI_Active := fbAnalog_Manifold_Current[L_i].VO_Error,
        VI_Timestamp := GVL_STATUS.G_System_Time_MS,
        VI_Source := 200 + L_i,
        VIO_Events := GVL_STATUS.G_Diagnostics_Events,
        VIO_Count := GVL_STATUS.G_Diagnostics_Count
    );

    IF GVL_IO.AI_Manifold_Temps_Supply[L_i].wStatus = 0 THEN
        fbCalib_Manifold_T_Supply[L_i](
            VI_Raw_Value := GVL_IO.AI_Manifold_Temps_Supply[L_i].rValue,
            VI_Record := GVL_CONFIG.G_Calib_Manifold_T_Supply[L_i]
        );
        GVL_STATE.G_Manifold_T_Supply[L_i] := fbCalib_Manifold_T_Supply[L_i].VO_Calibrated_Value;
    END_IF;

    fbCalib_Manifold_T_Return[L_i](
        VI_Raw_Value := INT_TO_REAL(GVL_IO.AI_Manifold_Temps_Return[L_i]) / 10.0,
        VI_Record := GVL_CONFIG.G_Calib_Manifold_T_Return[L_i]
    );
    GVL_STATE.G_Manifold_T_Return[L_i] := fbCalib_Manifold_T_Return[L_i].VO_Calibrated_Value;
    GVL_STATE.G_Manifold_End_Switches[L_i] := GVL_IO.DI_Manifold_End_Switches[L_i];

    IF GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault[L_i] OR GVL_STATUS.G_Diagnostics.Manifold_Current_Fault[L_i] THEN
        GVL_STATUS.G_Diagnostics.Sensor_Fault := TRUE;
        GVL_STATUS.G_Diagnostics.Subsystem_Degraded := TRUE;
    END_IF;

    IF GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault[L_i] AND GVL_STATUS.G_Diagnostics.Manifold_Current_Fault[L_i] THEN
        GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Text := 'Correlated pressure/current fault detected';
        GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Text := 'Correlated pressure/current fault detected';
    ELSIF GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault[L_i] AND (GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Text = '') THEN
        GVL_STATUS.G_Diagnostics.Manifold_Pressure_Fault_Text := 'Pressure sensor fault detected';
    ELSIF GVL_STATUS.G_Diagnostics.Manifold_Current_Fault[L_i] AND (GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Text = '') THEN
        GVL_STATUS.G_Diagnostics.Manifold_Current_Fault_Text := 'Current sensor fault detected';
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    IF GVL_IO.AI_Methane_LEL[L_i].wStatus = 0 THEN
        fbCalib_Methane[L_i](
            VI_Raw_Value := GVL_IO.AI_Methane_LEL[L_i].rValue,
            VI_Record := GVL_CONFIG.G_Calib_Methane[L_i]
        );
        GVL_STATE.G_Methane_Sensors[L_i] := fbCalib_Methane[L_i].VO_Calibrated_Value;
    END_IF;

    fbDiagEventManager(
        VI_Code := 16#E003,
        VI_Severity := 3,
        VI_Active := GVL_IO.AI_Methane_LEL[L_i].wStatus <> 0,
        VI_Timestamp := GVL_STATUS.G_System_Time_MS,
        VI_Source := 300 + L_i,
        VIO_Events := GVL_STATUS.G_Diagnostics_Events,
        VIO_Count := GVL_STATUS.G_Diagnostics_Count
    );
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_CO_SENSORS DO
    fbCalib_CO[L_i](
        VI_Raw_Value := GVL_IO.AI_CO_PPM[L_i],
        VI_Record := GVL_CONFIG.G_Calib_CO[L_i]
    );
    GVL_STATE.G_CO_Sensors[L_i] := fbCalib_CO[L_i].VO_Calibrated_Value;
END_FOR;

GVL_STATE.G_Boiler_Flame := GVL_IO.AI_Boiler_Flame_Status;
GVL_STATE.G_Boiler_Error := GVL_IO.DI_Boiler_Error;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    GVL_STATE.G_Boiler_OT_Online[L_i] := FALSE;
END_FOR;

GVL_STATE.G_DHW_Temp := GVL_IO.AI_DHW_Temp;
GVL_STATE.G_DHW_Pressure := GVL_IO.AI_DHW_Pressure;

GVL_STATE.G_Water_Zone_Open_FB := GVL_IO.DI_Water_Zone_Open_FB;
GVL_STATE.G_Water_Zone_Close_FB := GVL_IO.DI_Water_Zone_Close_FB;

// >>> BULK_SYNC_ANCHOR: PRG_IO_Read <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Authority_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// PLC FENCING GOVERNOR
// ======================================================
// Governs distributed PLC ownership semantics.
// Prevents stale-owner resurrection and split-brain.
// ======================================================

GVL_PLC_FENCING.PLC_Split_Brain_Detected := FALSE;
GVL_PLC_FENCING.PLC_Stale_Owner_Detected := FALSE;
GVL_PLC_FENCING.PLC_Asymmetric_Partition_Detected := FALSE;
GVL_PLC_FENCING.PLC_Forced_Safe_Quarantine := FALSE;

// Active PLC ownership validation.
IF L_Authority_Valid AND (NOT GVL_STATUS.G_Is_Active_PLC) THEN
    L_Authority_Valid := FALSE;
    L_Error_Code := 7001;
    L_Error_Text := 'PLC ownership inactive';
END_IF;

// Lease freshness validation.
L_Delta_MS := L_Now_MS - GVL_PLC_FENCING.PLC_Last_Lease_Refresh_MS;

IF L_Authority_Valid AND GVL_PLC_FENCING.PLC_Lease_Active THEN
    IF L_Delta_MS > GVL_PLC_FENCING.PLC_Lease_Timeout_MS THEN
        L_Authority_Valid := FALSE;
        L_Error_Code := 7002;
        L_Error_Text := 'PLC lease expired';
    END_IF;
END_IF;

// Heartbeat-only ownership is unsafe.
IF L_Authority_Valid AND GVL_PLC_FENCING.PLC_Heartbeat_Only_Mode THEN
    L_Authority_Valid := FALSE;
    L_Error_Code := 7003;
    L_Error_Text := 'Heartbeat-only ownership rejected';
END_IF;

// Publish authoritative fencing state.
IF L_Authority_Valid THEN
    GVL_PLC_FENCING.PLC_Ownership_Epoch := GVL_PLC_FENCING.PLC_Ownership_Epoch + 1;
    GVL_PLC_FENCING.PLC_Fencing_Token := GVL_PLC_FENCING.PLC_Ownership_Epoch;

    GVL_PLC_FENCING.PLC_Ownership_Valid := TRUE;
    GVL_PLC_FENCING.PLC_Semantic_Authority_Valid := TRUE;

    GVL_PLC_FENCING.PLC_Lease_Active := TRUE;
    GVL_PLC_FENCING.PLC_Lease_Expired := FALSE;

    GVL_PLC_FENCING.PLC_Last_Lease_Refresh_MS := L_Now_MS;
    GVL_PLC_FENCING.PLC_Last_Authority_Validation_MS := L_Now_MS;

    GVL_PLC_FENCING.PLC_Last_Error_Code := 0;
    GVL_PLC_FENCING.PLC_Last_Error_Text := '';
ELSE
    GVL_PLC_FENCING.PLC_Ownership_Valid := FALSE;
    GVL_PLC_FENCING.PLC_Semantic_Authority_Valid := FALSE;

    GVL_PLC_FENCING.PLC_Lease_Expired := TRUE;
    GVL_PLC_FENCING.PLC_Forced_Safe_Quarantine := TRUE;

    GVL_PLC_FENCING.PLC_Last_Error_Code := L_Error_Code;
    GVL_PLC_FENCING.PLC_Last_Error_Text := L_Error_Text;

    IF L_Error_Code = 7002 THEN
        GVL_PLC_FENCING.PLC_Stale_Owner_Detected := TRUE;
    END_IF;

    IF L_Error_Code = 7003 THEN
        GVL_PLC_FENCING.PLC_Split_Brain_Detected := TRUE;
        GVL_PLC_FENCING.PLC_Asymmetric_Partition_Detected := TRUE;
    END_IF;

    GVL_PLC_FENCING.PLC_Fencing_Invalidation_Count := GVL_PLC_FENCING.PLC_Fencing_Invalidation_Count + 1;
END_IF;

// Centralized tuning profile controller.
// This block enforces consistent adaptive behavior settings.

CASE GVL_BEHAVIOR_ADAPT.G_Adapt_Profile OF

    ADAPT_PROFILE_STABLE:
        GVL_BEHAVIOR_ADAPT.G_Adapt_Learning_Rate := 0.03;
        GVL_BEHAVIOR_ADAPT.G_Confidence_Learning_Rate := 0.03;
        GVL_BEHAVIOR_ADAPT.G_Decay_Factor := 0.998;
        GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold := 7;

        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Comfort := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Night := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Preheat := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_VentBoost := 0.9;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_AccessSecure := 1.0;

    ADAPT_PROFILE_BALANCED:
        GVL_BEHAVIOR_ADAPT.G_Adapt_Learning_Rate := 0.05;
        GVL_BEHAVIOR_ADAPT.G_Confidence_Learning_Rate := 0.05;
        GVL_BEHAVIOR_ADAPT.G_Decay_Factor := 0.995;
        GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold := 5;

        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Comfort := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Night := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Preheat := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_VentBoost := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_AccessSecure := 1.0;

    ADAPT_PROFILE_AGGRESSIVE:
        GVL_BEHAVIOR_ADAPT.G_Adapt_Learning_Rate := 0.08;
        GVL_BEHAVIOR_ADAPT.G_Confidence_Learning_Rate := 0.08;
        GVL_BEHAVIOR_ADAPT.G_Decay_Factor := 0.990;
        GVL_BEHAVIOR_ADAPT.G_Adapt_Update_Threshold := 3;

        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Comfort := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Night := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Preheat := 1.0;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_VentBoost := 1.1;
        GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_AccessSecure := 1.0;

ELSE
        // No fallback required
END_CASE;

// >>> BULK_SYNC_ANCHOR: PRG_Behavior_Adapt_Profile <<<

L_BB_Record.Timestamp := GVL_TIME_SERVICE.G_Now_MS;
L_BB_Record.PLC_Active_ID := GVL_STATUS.G_PLC_ID;
L_BB_Record.Gas_Methane_LEL := GVL_STATE.G_Methane_Sensors[1];
L_BB_Record.Gas_CO_PPM := GVL_STATE.G_CO_Sensors[1];
L_BB_Record.Flood_Active := GVL_ALARM.G_Flood_Alarm_Active;
L_BB_Record.Fire_Active := GVL_ALARM.G_Fire_Alarm_Active;

L_BB_Record.System_Mode := TO_BYTE(TO_INT(GVL_STATE.G_System_Mode));
L_BB_Record.First_Fault_Type := TO_BYTE(GVL_SYSTEM_HEALTH.G_First_Fault_Type);
L_BB_Record.First_Fault_Source := TO_BYTE(GVL_SYSTEM_HEALTH.G_First_Fault_Source);
L_BB_Record.First_Fault_Active := GVL_SYSTEM_HEALTH.G_First_Fault_Active;
L_BB_Record.System_Severity := TO_BYTE(GVL_SYSTEM_HEALTH.G_System_Severity);
L_BB_Record.Root_Cause := TO_BYTE(GVL_SYSTEM_HEALTH.G_Root_Cause);
L_BB_Record.Watchdog_Fault := GVL_SYSTEM_HEALTH.G_Watchdog_Fault;

L_BB_Freeze := GVL_ALARM.G_Gas_Alarm_Active OR GVL_ALARM.G_Fire_Alarm_Active OR GVL_ALARM.G_Flood_Alarm_Active OR GVL_SYSTEM_HEALTH.G_First_Fault_Active;

fbBlackBox(
    VI_Current_Data := L_BB_Record,
    VI_Freeze := L_BB_Freeze
);

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Transport_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// TRANSPORT FRESHNESS GOVERNOR
// ======================================================
// Governs transport freshness semantics.
// Prevents stale transport semantic publication.
//
// Transport freshness is upstream of runtime barrier in MAIN.
// It must not consume runtime barrier or downstream recovery
// governance state, because runtime barrier consumes transport
// freshness state later in the same scan-cycle.
// ======================================================

GVL_TRANSPORT_FRESHNESS.Transport_Stale_Frame_Detected := FALSE;
GVL_TRANSPORT_FRESHNESS.Transport_Transaction_Mismatch := FALSE;
GVL_TRANSPORT_FRESHNESS.Transport_Snapshot_Invalid := FALSE;

// Monotonic authority linkage.
IF L_Transport_Valid AND (NOT GVL_TIME_MONOTONIC.Monotonic_Time_Valid) THEN
    L_Transport_Valid := FALSE;
    L_Error_Code := 10001;
    L_Error_Text := 'Transport monotonic authority invalid';
END_IF;

// Transport reconnect quarantine.
IF GVL_TRANSPORT_FRESHNESS.Transport_Reconnect_Stabilizing THEN
    GVL_TRANSPORT_FRESHNESS.Transport_Quarantine_Active := TRUE;

    L_Transport_Valid := FALSE;

    IF L_Error_Code = 0 THEN
        L_Error_Code := 10003;
        L_Error_Text := 'Transport reconnect stabilization active';
    END_IF;
END_IF;

// Lease freshness validation.
L_Delta_MS := L_Now_MS - GVL_TRANSPORT_FRESHNESS.Transport_Last_Refresh_MS;

IF L_Transport_Valid AND GVL_TRANSPORT_FRESHNESS.Transport_Lease_Valid THEN
    IF L_Delta_MS > GVL_TRANSPORT_FRESHNESS.Transport_Lease_Timeout_MS THEN
        L_Transport_Valid := FALSE;
        L_Error_Code := 10004;
        L_Error_Text := 'Transport lease expired';

        GVL_TRANSPORT_FRESHNESS.Transport_Lease_Expired := TRUE;
    END_IF;
END_IF;

// Publish authoritative transport freshness state.
IF L_Transport_Valid THEN
    GVL_TRANSPORT_FRESHNESS.Transport_Epoch := GVL_TRANSPORT_FRESHNESS.Transport_Epoch + 1;
    GVL_TRANSPORT_FRESHNESS.Transport_Publication_Epoch := GVL_TRANSPORT_FRESHNESS.Transport_Publication_Epoch + 1;

    GVL_TRANSPORT_FRESHNESS.Transport_Freshness_Valid := TRUE;
    GVL_TRANSPORT_FRESHNESS.Transport_Publication_Allowed := TRUE;

    GVL_TRANSPORT_FRESHNESS.Transport_Lease_Valid := TRUE;
    GVL_TRANSPORT_FRESHNESS.Transport_Lease_Expired := FALSE;

    GVL_TRANSPORT_FRESHNESS.Transport_Quarantine_Active := FALSE;

    GVL_TRANSPORT_FRESHNESS.Transport_Last_Refresh_MS := L_Now_MS;
    GVL_TRANSPORT_FRESHNESS.Transport_Last_Publication_MS := L_Now_MS;

    GVL_TRANSPORT_FRESHNESS.Transport_Last_Error_Code := 0;
    GVL_TRANSPORT_FRESHNESS.Transport_Last_Error_Text := '';
ELSE
    GVL_TRANSPORT_FRESHNESS.Transport_Freshness_Valid := FALSE;
    GVL_TRANSPORT_FRESHNESS.Transport_Publication_Allowed := FALSE;

    GVL_TRANSPORT_FRESHNESS.Transport_Snapshot_Invalid := TRUE;

    GVL_TRANSPORT_FRESHNESS.Transport_Last_Error_Code := L_Error_Code;
    GVL_TRANSPORT_FRESHNESS.Transport_Last_Error_Text := L_Error_Text;

    GVL_TRANSPORT_FRESHNESS.Transport_Invalidation_Count := GVL_TRANSPORT_FRESHNESS.Transport_Invalidation_Count + 1;
END_IF;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Semantic_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// SEMANTIC PROGRESS GOVERNOR
// ======================================================
// Governs semantic execution continuity foundation.
// Visibility/publication continuity only.
// Does not invalidate runtime barrier,
// PLC fencing, immutable snapshots or IO authority.
// ======================================================

GVL_SEMANTIC_PROGRESS.Semantic_Stagnation_Detected := FALSE;
GVL_SEMANTIC_PROGRESS.Semantic_Replay_Suspected := FALSE;
GVL_SEMANTIC_PROGRESS.Semantic_Livelock_Suspected := FALSE;
GVL_SEMANTIC_PROGRESS.Semantic_Deadlock_Suspected := FALSE;
GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired := FALSE;

// ------------------------------------------------------
// Semantic execution continuity projection.
// ------------------------------------------------------

GVL_SEMANTIC_PROGRESS.Semantic_Execution_Counter :=
    GVL_SEMANTIC_PROGRESS.Semantic_Execution_Counter + 1;

// ------------------------------------------------------
// Replay suspicion foundation.
// ------------------------------------------------------

IF GVL_SEMANTIC_PROGRESS.Semantic_Execution_Counter
<= GVL_SEMANTIC_PROGRESS.Semantic_Last_Execution_Counter THEN
    GVL_SEMANTIC_PROGRESS.Semantic_Replay_Suspected := TRUE;

    L_Semantic_Valid := FALSE;
    L_Error_Code := 17000;
    L_Error_Text := 'Semantic replay suspected';
END_IF;

// ------------------------------------------------------
// Lease freshness validation.
// ------------------------------------------------------

L_Delta_MS :=
    L_Now_MS - GVL_SEMANTIC_PROGRESS.Semantic_Progress_Last_Update_MS;

IF L_Semantic_Valid
AND GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Active THEN
    IF L_Delta_MS > GVL_SEMANTIC_PROGRESS.Semantic_Progress_Timeout_MS THEN
        GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired := TRUE;
        GVL_SEMANTIC_PROGRESS.Semantic_Deadlock_Suspected := TRUE;

        L_Semantic_Valid := FALSE;
        L_Error_Code := 17001;
        L_Error_Text := 'Semantic progress lease expired';
    END_IF;
END_IF;

// ------------------------------------------------------
// Semantic stagnation detection foundation.
// ------------------------------------------------------

IF L_Semantic_Valid THEN
    IF GVL_SEMANTIC_PROGRESS.Semantic_Execution_Counter
    = GVL_SEMANTIC_PROGRESS.Semantic_Last_Execution_Counter THEN
        GVL_SEMANTIC_PROGRESS.Semantic_Stagnation_Detected := TRUE;
        GVL_SEMANTIC_PROGRESS.Semantic_Livelock_Suspected := TRUE;

        L_Semantic_Valid := FALSE;
        L_Error_Code := 17002;
        L_Error_Text := 'Semantic execution stagnation detected';
    END_IF;
END_IF;

// ------------------------------------------------------
// Publish semantic continuity foundation.
// ------------------------------------------------------

IF L_Semantic_Valid THEN
    GVL_SEMANTIC_PROGRESS.Semantic_Progress_Epoch :=
        GVL_SEMANTIC_PROGRESS.Semantic_Progress_Epoch + 1;

    GVL_SEMANTIC_PROGRESS.Semantic_Continuity_Epoch :=
        GVL_SEMANTIC_PROGRESS.Semantic_Continuity_Epoch + 1;

    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid := TRUE;
    GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK := TRUE;

    GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Active := TRUE;
    GVL_SEMANTIC_PROGRESS.Semantic_Progress_Lease_Expired := FALSE;
    GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active := FALSE;

    GVL_SEMANTIC_PROGRESS.Semantic_Last_Execution_Counter :=
        GVL_SEMANTIC_PROGRESS.Semantic_Execution_Counter;

    GVL_SEMANTIC_PROGRESS.Semantic_Progress_Last_Update_MS := L_Now_MS;

    GVL_SEMANTIC_PROGRESS.Semantic_Last_Error_Code := 0;
    GVL_SEMANTIC_PROGRESS.Semantic_Last_Error_Text := '';
ELSE
    GVL_SEMANTIC_PROGRESS.Semantic_Forward_Progress_Valid := FALSE;
    GVL_SEMANTIC_PROGRESS.Semantic_Execution_Continuity_OK := FALSE;

    GVL_SEMANTIC_PROGRESS.Semantic_Progress_Quarantine_Active := TRUE;

    GVL_SEMANTIC_PROGRESS.Semantic_Last_Error_Code := L_Error_Code;
    GVL_SEMANTIC_PROGRESS.Semantic_Last_Error_Text := L_Error_Text;

    GVL_SEMANTIC_PROGRESS.Semantic_Invalidation_Count :=
        GVL_SEMANTIC_PROGRESS.Semantic_Invalidation_Count + 1;
END_IF;

// ======================================================
// HEATING CONFIDENCE
// ======================================================
GVL_HMI.G_HMI_Heating_Confidence := GVL_STATE.G_Heating_Confidence;
GVL_HMI.G_HMI_Heating_Confidence_Percent := REAL_TO_INT(GVL_STATE.G_Heating_Confidence * 100.0);

// ======================================================
// HEATING ROOT CAUSE
// ======================================================
GVL_HMI.G_HMI_Heating_Reason_Code := GVL_STATE.G_Heating_Confidence_Reason_Code;
GVL_HMI.G_HMI_Heating_Status_Text := GVL_STATE.G_Heating_Confidence_Reason_Text;

// ======================================================
// HEATING STATUS LEVEL
// ======================================================
IF GVL_STATE.G_Heating_Confidence > 0.8 THEN
    GVL_HMI.G_HMI_Heating_Status_Level := 0;
ELSIF GVL_STATE.G_Heating_Confidence > 0.5 THEN
    GVL_HMI.G_HMI_Heating_Status_Level := 1;
ELSE
    GVL_HMI.G_HMI_Heating_Status_Level := 2;
END_IF;

// ======================================================
// CASCADE SEMANTIC STATE
// ======================================================
GVL_HMI.G_HMI_Heating_Cascade_Available :=
    GVL_STATE.G_Heating_Cascade_Available;

GVL_HMI.G_HMI_Heating_Cascade_Degraded :=
    GVL_STATE.G_Heating_Cascade_Degraded;

GVL_HMI.G_HMI_Heating_Cascade_Partial_Capacity :=
    GVL_STATE.G_Heating_Cascade_Partial_Capacity;

GVL_HMI.G_HMI_Heating_Cascade_No_Flame :=
    GVL_STATE.G_Heating_Cascade_No_Flame;

GVL_HMI.G_HMI_Heating_Cascade_Transport_Degraded :=
    GVL_STATE.G_Heating_Cascade_Transport_Degraded;

GVL_HMI.G_HMI_Heating_Cascade_Ignition_Timeout :=
    GVL_STATE.G_Heating_Cascade_Ignition_Timeout;

GVL_HMI.G_HMI_Heating_Cascade_Active_Boilers :=
    GVL_STATE.G_Heating_Cascade_Active_Boilers;

GVL_HMI.G_HMI_Heating_Cascade_Available_Boilers :=
    GVL_STATE.G_Heating_Cascade_Available_Boilers;

// ======================================================
// OPENTHERM SEMANTIC STATE
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO

    GVL_HMI.G_HMI_Boiler_OT_Online[L_i] :=
        GVL_STATE.G_Boiler_OT_Online[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Command_Ack[L_i] :=
        GVL_STATE.G_Boiler_OT_Command_Ack[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Command_Timeout[L_i] :=
        GVL_STATE.G_Boiler_OT_Command_Timeout[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Heartbeat_Timeout[L_i] :=
        GVL_STATE.G_Boiler_OT_Heartbeat_Timeout[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Adapter_Error[L_i] :=
        GVL_STATE.G_Boiler_OT_Adapter_Error[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Heartbeat_Age_MS[L_i] :=
        GVL_STATE.G_Boiler_OT_Heartbeat_Age_MS[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Command_Age_MS[L_i] :=
        GVL_STATE.G_Boiler_OT_Command_Age_MS[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Adapter_State[L_i] :=
        GVL_STATE.G_Boiler_OT_Adapter_State[L_i];

    GVL_HMI.G_HMI_Boiler_OT_Error_State[L_i] :=
        GVL_STATE.G_Boiler_OT_Error_State[L_i];

END_FOR;

// ======================================================
// PREDICTIVE FLAGS
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    GVL_HMI.G_HMI_Heating_Predictive_Pressure_Drop[L_i] :=
        GVL_STATE.G_Predictive_Pump_Pressure_Drop[L_i];

    GVL_HMI.G_HMI_Heating_Predictive_Current_Rise[L_i] :=
        GVL_STATE.G_Predictive_Pump_Current_Rise[L_i];
END_FOR;

// Central time update point.
// Must run before PRG_IO_Read and all consumers of GVL_TIME_SERVICE.
fbTimebase();
fbTime();

// Step 4.2 compatibility bridge.
// Legacy consumers of GVL_STATUS.G_System_Time_MS receive the same canonical time.
GVL_STATUS.G_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS;
GVL_STATUS.G_Current_TOD := GVL_TIME_SERVICE.G_Current_TOD;
GVL_STATUS.G_Current_Day := TO_UINT(GVL_TIME_SERVICE.G_Day_Of_Week);

// ======================================================
// DISTRIBUTED PEER INGESTION
// ======================================================
// Bounded peer-session ingestion layer.
//
// Purpose:
// normalize remote PLC liveness/session visibility into
// distributed peer-input fields consumed by distributed governors.
//
// This layer does NOT:
// - perform reconciliation/quarantine decisions
// - perform split-brain detection
// - validate peer publication correctness
// - mutate local runtime authority
//
// Current implementation status:
// peer epoch/token values are projected from currently available
// remote PLC runtime visibility until a richer transport/session
// contract is implemented.
// ======================================================

L_Now_MS := GVL_STATUS.G_System_Time_MS;

// ------------------------------------------------------
// Peer session freshness projection.
// ------------------------------------------------------

GVL_DISTRIBUTED_EPOCH.Peer_Last_Refresh_MS :=
    GVL_STATUS.G_Remote_PLC_Last_Seen_MS;

GVL_DISTRIBUTED_EPOCH.Peer_Lease_Active :=
    GVL_STATUS.G_Remote_PLC_Alive;

// ------------------------------------------------------
// Peer runtime visibility projection.
// ------------------------------------------------------

IF GVL_STATUS.G_Remote_PLC_Alive THEN
    // Transitional projection model:
    // until explicit remote epoch transport exists,
    // peer visibility mirrors current known remote-active session.

    GVL_DISTRIBUTED_EPOCH.Peer_Runtime_Epoch :=
        GVL_RUNTIME_EPOCH.Runtime_Epoch;

    GVL_DISTRIBUTED_EPOCH.Peer_Snapshot_Epoch :=
        GVL_RUNTIME_SNAPSHOT.Runtime_Snapshot_Epoch;

    GVL_DISTRIBUTED_EPOCH.Peer_Boot_Generation :=
        GVL_STATUS.G_Active_PLC_ID;

    // Transitional fencing projection.
    // Explicit remote fencing-token exchange is not yet implemented.
    GVL_DISTRIBUTED_EPOCH.Peer_Fencing_Token :=
        GVL_STATUS.G_Active_PLC_ID;
ELSE
    GVL_DISTRIBUTED_EPOCH.Peer_Lease_Active := FALSE;
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Distributed_Peer_Ingestion <<<

// Centralized Health execution (Phase 5)
fbSystemHealthOrchestrator(
    VO_First_Fault_Active => GVL_SYSTEM_HEALTH.G_First_Fault_Active,
    VO_First_Fault_Type => GVL_SYSTEM_HEALTH.G_First_Fault_Type,
    VO_First_Fault_Source => GVL_SYSTEM_HEALTH.G_First_Fault_Source,
    VO_System_Severity => GVL_SYSTEM_HEALTH.G_System_Severity,
    VO_Root_Cause => GVL_SYSTEM_HEALTH.G_Root_Cause,
    VO_Watchdog_Fault => GVL_SYSTEM_HEALTH.G_Watchdog_Fault
);

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Runtime_OK := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// AUTHORITATIVE RUNTIME BARRIER
// ======================================================
// Creates authoritative runtime publication semantics.
// Rejects impossible runtime states before physical publication.
//
// Runtime authority remains:
// - monotonic-time authoritative;
// - PLC fencing authoritative;
// - transport freshness authoritative.
//
// Recovery cleanup, command verification and observability
// remain downstream-oriented. Diagnostics/explainability
// synchronization must not become upstream runtime authority.
// ======================================================

GVL_RUNTIME_EPOCH.Runtime_Cycle_Start_MS := L_Now_MS;
GVL_RUNTIME_EPOCH.Runtime_Snapshot_Published := FALSE;
GVL_RUNTIME_EPOCH.Runtime_Impossible_State_Detected := FALSE;
GVL_RUNTIME_EPOCH.Runtime_IO_Publication_Allowed := FALSE;

// ------------------------------------------------------
// Monotonic time authority validation.
// ------------------------------------------------------

IF NOT GVL_TIME_MONOTONIC.Monotonic_Time_Initialized THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4900;
    L_Error_Text := 'Monotonic time not initialized';
END_IF;

IF L_Runtime_OK AND (NOT GVL_TIME_MONOTONIC.Monotonic_Time_Valid) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4901;
    L_Error_Text := 'Monotonic time invalid';
END_IF;

IF L_Runtime_OK AND GVL_TIME_MONOTONIC.Startup_Quarantine_Active THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4902;
    L_Error_Text := 'Startup quarantine active';
END_IF;

IF L_Runtime_OK AND GVL_TIME_MONOTONIC.Time_Rollback_Detected THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4903;
    L_Error_Text := 'Monotonic rollback detected';
END_IF;

IF L_Runtime_OK AND GVL_TIME_MONOTONIC.Retained_Time_Invalid THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4904;
    L_Error_Text := 'Retained monotonic time invalid';
END_IF;

IF L_Runtime_OK AND (GVL_TIME_MONOTONIC.Boot_Generation_ID = 0) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 4905;
    L_Error_Text := 'Boot generation missing';
END_IF;

// ------------------------------------------------------
// Base PLC/runtime authority validation.
// ------------------------------------------------------

IF L_Runtime_OK AND (NOT GVL_STATUS.G_Is_Active_PLC) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5000;
    L_Error_Text := 'Runtime barrier inactive PLC';
END_IF;

// ------------------------------------------------------
// PLC fencing authority validation.
// ------------------------------------------------------

IF L_Runtime_OK AND (NOT GVL_PLC_FENCING.PLC_Ownership_Valid) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5010;
    L_Error_Text := 'PLC ownership invalid';
END_IF;

IF L_Runtime_OK AND (NOT GVL_PLC_FENCING.PLC_Semantic_Authority_Valid) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5011;
    L_Error_Text := 'PLC semantic authority invalid';
END_IF;

IF L_Runtime_OK AND GVL_PLC_FENCING.PLC_Forced_Safe_Quarantine THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5012;
    L_Error_Text := 'PLC fencing quarantine active';
END_IF;

IF L_Runtime_OK AND GVL_PLC_FENCING.PLC_Lease_Expired THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5013;
    L_Error_Text := 'PLC authority lease expired';
END_IF;

IF L_Runtime_OK AND (GVL_PLC_FENCING.PLC_Fencing_Token = 0) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5014;
    L_Error_Text := 'PLC fencing token missing';
END_IF;

// ------------------------------------------------------
// Transport freshness validation.
// ------------------------------------------------------

IF L_Runtime_OK AND (NOT GVL_TRANSPORT_FRESHNESS.Transport_Freshness_Valid) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5200;
    L_Error_Text := 'Transport freshness invalid';
END_IF;

IF L_Runtime_OK AND (NOT GVL_TRANSPORT_FRESHNESS.Transport_Publication_Allowed) THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5201;
    L_Error_Text := 'Transport publication blocked';
END_IF;

IF L_Runtime_OK AND GVL_TRANSPORT_FRESHNESS.Transport_Quarantine_Active THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5202;
    L_Error_Text := 'Transport quarantine active';
END_IF;

IF L_Runtime_OK AND GVL_TRANSPORT_FRESHNESS.Transport_Lease_Expired THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5203;
    L_Error_Text := 'Transport lease expired';
END_IF;

IF L_Runtime_OK AND GVL_TRANSPORT_FRESHNESS.Transport_Snapshot_Invalid THEN
    L_Runtime_OK := FALSE;
    L_Error_Code := 5204;
    L_Error_Text := 'Transport snapshot invalid';
END_IF;

// ------------------------------------------------------
// Impossible-state rejection.
// ------------------------------------------------------

IF L_Runtime_OK THEN
    IF (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE)
    AND (GVL_COMMAND_SHADOW.G_Vent_Stop)
    THEN
        L_Runtime_OK := FALSE;
        L_Error_Code := 5003;
        L_Error_Text := 'Impossible fire ventilation state';
    END_IF;
END_IF;

IF L_Runtime_OK THEN
    IF (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS)
    AND (NOT GVL_COMMAND_SHADOW.G_Gas_Valve_Close)
    THEN
        L_Runtime_OK := FALSE;
        L_Error_Code := 5004;
        L_Error_Text := 'Impossible gas valve state';
    END_IF;
END_IF;

// ------------------------------------------------------
// Authoritative runtime publication.
// ------------------------------------------------------

GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK := L_Runtime_OK;
GVL_RUNTIME_EPOCH.Runtime_Snapshot_Valid := L_Runtime_OK;
GVL_RUNTIME_EPOCH.Runtime_PLC_Authority_Valid :=
    GVL_STATUS.G_Is_Active_PLC
    AND GVL_PLC_FENCING.PLC_Semantic_Authority_Valid
    AND GVL_PLC_FENCING.PLC_Ownership_Valid
    AND GVL_TIME_MONOTONIC.Monotonic_Time_Valid
    AND GVL_TRANSPORT_FRESHNESS.Transport_Freshness_Valid;

GVL_RUNTIME_EPOCH.Runtime_Last_Validation_Time_MS := L_Now_MS;

IF L_Runtime_OK THEN
    GVL_RUNTIME_EPOCH.Runtime_Epoch := GVL_RUNTIME_EPOCH.Runtime_Epoch + 1;
    GVL_RUNTIME_EPOCH.Runtime_IO_Publication_Allowed := TRUE;
    GVL_RUNTIME_EPOCH.Runtime_Snapshot_Published := TRUE;
    GVL_RUNTIME_EPOCH.Runtime_Last_Error_Code := 0;
    GVL_RUNTIME_EPOCH.Runtime_Last_Error_Text := '';
ELSE
    GVL_RUNTIME_EPOCH.Runtime_Impossible_State_Detected := TRUE;
    GVL_RUNTIME_EPOCH.Runtime_Last_Error_Code := L_Error_Code;
    GVL_RUNTIME_EPOCH.Runtime_Last_Error_Text := L_Error_Text;
    GVL_RUNTIME_EPOCH.Runtime_Barrier_Block_Count := GVL_RUNTIME_EPOCH.Runtime_Barrier_Block_Count + 1;
END_IF;

GVL_RUNTIME_EPOCH.Runtime_Cycle_End_MS := L_Now_MS;

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Commit_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// DISTRIBUTED PUBLICATION COMMIT GOVERNOR
// ======================================================
// Governs deterministic peer publication commit continuity.
// Publication-authoritative only.
// Does not invalidate runtime barrier,
// PLC fencing or immutable snapshot authority.
//
// Current implementation mode:
// peer-optional foundation mode.
//
// Missing peer topology is NOT treated as divergence.
// Peer validation activates only after real peer
// synchronization state exists.
// ======================================================

GVL_DISTRIBUTED_COMMIT.Peer_Commit_Ack_Expired := FALSE;
GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch := FALSE;
GVL_DISTRIBUTED_COMMIT.Peer_Commit_Replay_Detected := FALSE;
GVL_DISTRIBUTED_COMMIT.Peer_Commit_Missing := FALSE;
GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired := FALSE;

// ------------------------------------------------------
// Local publication projection.
// ------------------------------------------------------
// Distributed commit is upstream of output freshness in MAIN.
// Therefore local commit baseline must not read GVL_OUTPUT_EPOCH.
// It uses the already-prepared distributed snapshot epoch instead.
// ------------------------------------------------------

GVL_DISTRIBUTED_COMMIT.Local_Publication_Commit_Epoch := GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Epoch;
GVL_DISTRIBUTED_COMMIT.Local_Prepare_Epoch := GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Epoch;

// ------------------------------------------------------
// Immutable publication preparation validation.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Reconciled
AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Publication_Freeze_Valid
AND GVL_DISTRIBUTED_SNAPSHOT.Distributed_Snapshot_Consistent
THEN
    GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Active := TRUE;
    GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid := TRUE;
ELSE
    GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Active := FALSE;
    GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Valid := FALSE;

    L_Commit_Valid := FALSE;
    L_Error_Code := 15000;
    L_Error_Text := 'Distributed immutable publication prepare invalid';
END_IF;

// ------------------------------------------------------
// Peer session detection.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_COMMIT.Peer_Publication_Commit_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Peer_Prepare_Epoch > 0 THEN
    L_Peer_Session_Active := TRUE;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Peer_Commit_Ack_Valid THEN
    L_Peer_Session_Active := TRUE;
END_IF;

// ------------------------------------------------------
// Commit lease freshness validation.
// ------------------------------------------------------

IF L_Commit_Valid AND L_Peer_Session_Active THEN
    L_Delta_MS := L_Now_MS - GVL_DISTRIBUTED_COMMIT.Peer_Commit_Last_Refresh_MS;

    IF GVL_DISTRIBUTED_COMMIT.Commit_Lease_Active THEN
        IF L_Delta_MS > GVL_DISTRIBUTED_COMMIT.Commit_Timeout_MS THEN
            GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired := TRUE;

            L_Commit_Valid := FALSE;
            L_Error_Code := 15001;
            L_Error_Text := 'Distributed commit lease expired';
        END_IF;
    END_IF;
END_IF;

// ------------------------------------------------------
// Peer commit acknowledgement validation.
// ------------------------------------------------------

IF L_Commit_Valid AND L_Peer_Session_Active THEN
    IF NOT GVL_DISTRIBUTED_COMMIT.Peer_Commit_Ack_Valid THEN
        GVL_DISTRIBUTED_COMMIT.Peer_Commit_Missing := TRUE;

        L_Commit_Valid := FALSE;
        L_Error_Code := 15002;
        L_Error_Text := 'Peer commit acknowledgement missing';
    END_IF;
END_IF;

// ------------------------------------------------------
// Deterministic commit epoch continuity.
// ------------------------------------------------------

IF L_Commit_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_COMMIT.Peer_Publication_Commit_Epoch < GVL_DISTRIBUTED_COMMIT.Local_Publication_Commit_Epoch THEN
        GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch := TRUE;

        L_Commit_Valid := FALSE;
        L_Error_Code := 15003;
        L_Error_Text := 'Peer commit epoch mismatch';
    END_IF;
END_IF;

// ------------------------------------------------------
// Replay protection foundation.
// ------------------------------------------------------

IF L_Commit_Valid AND L_Peer_Session_Active THEN
    IF GVL_DISTRIBUTED_COMMIT.Peer_Prepare_Epoch < GVL_DISTRIBUTED_COMMIT.Local_Prepare_Epoch THEN
        GVL_DISTRIBUTED_COMMIT.Peer_Commit_Replay_Detected := TRUE;

        L_Commit_Valid := FALSE;
        L_Error_Code := 15004;
        L_Error_Text := 'Peer commit replay detected';
    END_IF;
END_IF;

// ------------------------------------------------------
// Publish deterministic distributed commit state.
// ------------------------------------------------------

IF L_Commit_Valid THEN
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Epoch := GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Epoch + 1;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Reconciliation_Epoch := GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Reconciliation_Epoch + 1;

    GVL_DISTRIBUTED_COMMIT.Publication_Commit_Requested := TRUE;

    IF L_Peer_Session_Active THEN
        GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed := TRUE;
        GVL_DISTRIBUTED_COMMIT.Commit_Lease_Active := TRUE;
    ELSE
        GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed := FALSE;
        GVL_DISTRIBUTED_COMMIT.Commit_Lease_Active := FALSE;
    END_IF;

    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid := TRUE;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Quarantine_Active := FALSE;

    GVL_DISTRIBUTED_COMMIT.Commit_Last_Reconciliation_MS := L_Now_MS;

    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Last_Error_Code := 0;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Last_Error_Text := '';
ELSE
    GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed := FALSE;

    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid := FALSE;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Quarantine_Active := TRUE;

    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Last_Error_Code := L_Error_Code;
    GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Last_Error_Text := L_Error_Text;
END_IF;

L_Error := FALSE;
GVL_CONFIG_VALIDATION.G_Config_Auto_Corrected := FALSE;
GVL_CONFIG_CONTROL.G_Apply_Done := FALSE;
GVL_CONFIG_CONTROL.G_Rollback_Done := FALSE;

IF NOT GVL_CONFIG_SIMULATION.G_Simulation_Result_OK THEN
    GVL_CONFIG_CONTROL.G_Apply_Request := FALSE;
END_IF;

// ===== SIZE VALIDATION =====
IF GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits < 1 OR GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits > GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS THEN
    GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits := GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS;
    L_Error := TRUE;
END_IF;

IF GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones < 1 OR GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones > GVL_CONSTANTS.C_MAX_WATER_ZONES THEN
    GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones := GVL_CONSTANTS.C_MAX_WATER_ZONES;
    L_Error := TRUE;
END_IF;

IF GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones < 1 OR GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones > GVL_CONSTANTS.C_MAX_LIGHT_ZONES THEN
    GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones := GVL_CONSTANTS.C_MAX_LIGHT_ZONES;
    L_Error := TRUE;
END_IF;

// ===== EXISTING VALIDATION =====
IF GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate < 0.0 OR GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate > 1.0 THEN
    GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate := 0.05;
    L_Error := TRUE;
END_IF;

// ===== APPLY (unchanged) =====
IF GVL_CONFIG_CONTROL.G_Apply_Request AND GVL_CONFIG_CONTROL.G_Apply_Confirm THEN
    GVL_CONFIG_CONTROL.BCK_Reputation_Learning_Rate := GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate;
    GVL_INPUT_VALIDATION_CONFIG.G_Reputation_Learning_Rate := GVL_CONFIG_CONTROL.STG_Reputation_Learning_Rate;

    GVL_CONFIG_CONTROL.G_Config_Version := GVL_CONFIG_CONTROL.G_Config_Version + 1;

    L_Index := GVL_CONFIG_HISTORY.G_History_Index;
    GVL_CONFIG_HISTORY.G_History_Version[L_Index] := GVL_CONFIG_CONTROL.G_Config_Version;
    GVL_CONFIG_HISTORY.G_History_Time_MS[L_Index] := GVL_TIME_SERVICE.G_Now_MS;
    GVL_CONFIG_HISTORY.G_History_Action[L_Index] := 'APPLY';

    L_Index := L_Index + 1;
    IF L_Index > 5 THEN L_Index := 1; END_IF;
    GVL_CONFIG_HISTORY.G_History_Index := L_Index;

    GVL_CONFIG_CONTROL.G_Backup_Valid := TRUE;
    GVL_CONFIG_CONTROL.G_Apply_Done := TRUE;
END_IF;

GVL_CONFIG_VALIDATION.G_Config_Valid := NOT L_Error;
GVL_CONFIG_VALIDATION.G_Config_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

// >>> BULK_SYNC_ANCHOR: PRG_Config_Manager <<<

L_Now := GVL_TIME_SERVICE.G_Now_MS;
L_Last := GVL_DIAGNOSTICS_EXT.G_Last_Update_Time;

// ===============================
// CYCLE INTERVAL MEASUREMENT
// ===============================
IF L_Last = 0 THEN
    L_Cycle_MS := GVL_DIAGNOSTICS_EXT.G_Cycle_Expected_MS;
ELSE
    IF L_Now >= L_Last THEN
        L_Cycle_MS := L_Now - L_Last;
    ELSE
        L_Cycle_MS := (4294967295 - L_Last) + L_Now + 1;
    END_IF;
END_IF;

GVL_DIAGNOSTICS_EXT.G_Last_Update_Time := L_Now;
GVL_DIAGNOSTICS_EXT.G_Cycle_Last_MS := L_Cycle_MS;

// min/max
IF (GVL_DIAGNOSTICS_EXT.G_Cycle_Min_MS = 0) OR (L_Cycle_MS < GVL_DIAGNOSTICS_EXT.G_Cycle_Min_MS) THEN
    GVL_DIAGNOSTICS_EXT.G_Cycle_Min_MS := L_Cycle_MS;
END_IF;

IF L_Cycle_MS > GVL_DIAGNOSTICS_EXT.G_Cycle_Max_MS THEN
    GVL_DIAGNOSTICS_EXT.G_Cycle_Max_MS := L_Cycle_MS;
END_IF;

// average (incremental)
GVL_DIAGNOSTICS_EXT.G_Cycle_Sample_Count := GVL_DIAGNOSTICS_EXT.G_Cycle_Sample_Count + 1;
GVL_DIAGNOSTICS_EXT.G_Cycle_Avg_MS :=
    GVL_DIAGNOSTICS_EXT.G_Cycle_Avg_MS +
    (UDINT_TO_REAL(L_Cycle_MS) - GVL_DIAGNOSTICS_EXT.G_Cycle_Avg_MS) /
    UDINT_TO_REAL(GVL_DIAGNOSTICS_EXT.G_Cycle_Sample_Count);

// ===============================
// OVERRUN / CRITICAL DETECTION
// ===============================
GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Active := (L_Cycle_MS > GVL_DIAGNOSTICS_EXT.G_Cycle_Warning_MS);
GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Active := (L_Cycle_MS > GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_MS);

IF GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Active THEN
    GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Count := GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Count + 1;
    GVL_DIAGNOSTICS_EXT.G_Cycle_Last_Overrun_MS := L_Cycle_MS;
    GVL_DIAGNOSTICS_EXT.G_Cycle_Last_Overrun_Time_MS := L_Now;
END_IF;

IF GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Active THEN
    GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Count := GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Count + 1;
END_IF;

// edge logging
IF GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Active AND NOT L_Prev_Overrun THEN
    fbLog(
        VI_Event_Type := 2001,
        VI_Timestamp := L_Now,
        VI_Param1 := L_Cycle_MS,
        VI_Param2 := GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Count
    );
END_IF;

IF GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Active AND NOT L_Prev_Critical THEN
    fbLog(
        VI_Event_Type := 2002,
        VI_Timestamp := L_Now,
        VI_Param1 := L_Cycle_MS,
        VI_Param2 := GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Count
    );
END_IF;

L_Prev_Overrun := GVL_DIAGNOSTICS_EXT.G_Cycle_Overrun_Active;
L_Prev_Critical := GVL_DIAGNOSTICS_EXT.G_Cycle_Critical_Active;

// ===============================
// EXISTING HEALTH LOGIC
// ===============================
IF L_Last = 0 THEN
    L_Delta_Time := 0.1;
ELSE
    L_Delta_Time := UDINT_TO_REAL(L_Cycle_MS) / 1000.0;
END_IF;

L_Error_Heating := GVL_STATE.G_Heating_Subsystem_Degraded;
L_Error_Safety := GVL_STATE.G_Safety_Gas_Alarm OR GVL_STATE.G_Safety_Leak_Alarm OR GVL_STATE.G_Safety_Smoke_Alarm;
L_Error_IO := GVL_STATE.G_Heating_IO_Fault;

IF L_Error_Heating THEN
    GVL_DIAGNOSTICS_EXT.G_Error_Count_Heating := GVL_DIAGNOSTICS_EXT.G_Error_Count_Heating + 1;
    GVL_DIAGNOSTICS_EXT.G_Last_Error_Time_Heating := L_Now;
    GVL_DIAGNOSTICS_EXT.G_Health_Heating := GVL_DIAGNOSTICS_EXT.G_Health_Heating - (0.5 * L_Delta_Time);
ELSE
    GVL_DIAGNOSTICS_EXT.G_Health_Heating := GVL_DIAGNOSTICS_EXT.G_Health_Heating + (0.1 * L_Delta_Time);
END_IF;

IF L_Error_Safety THEN
    GVL_DIAGNOSTICS_EXT.G_Error_Count_Safety := GVL_DIAGNOSTICS_EXT.G_Error_Count_Safety + 1;
    GVL_DIAGNOSTICS_EXT.G_Last_Error_Time_Safety := L_Now;
    GVL_DIAGNOSTICS_EXT.G_Health_Safety := GVL_DIAGNOSTICS_EXT.G_Health_Safety - (1.0 * L_Delta_Time);
ELSE
    GVL_DIAGNOSTICS_EXT.G_Health_Safety := GVL_DIAGNOSTICS_EXT.G_Health_Safety + (0.2 * L_Delta_Time);
END_IF;

IF L_Error_IO THEN
    GVL_DIAGNOSTICS_EXT.G_Error_Count_IO := GVL_DIAGNOSTICS_EXT.G_Error_Count_IO + 1;
    GVL_DIAGNOSTICS_EXT.G_Last_Error_Time_IO := L_Now;
    GVL_DIAGNOSTICS_EXT.G_Health_IO := GVL_DIAGNOSTICS_EXT.G_Health_IO - (0.5 * L_Delta_Time);
ELSE
    GVL_DIAGNOSTICS_EXT.G_Health_IO := GVL_DIAGNOSTICS_EXT.G_Health_IO + (0.1 * L_Delta_Time);
END_IF;

// clamp
IF GVL_DIAGNOSTICS_EXT.G_Health_Heating < 0.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_Heating := 0.0; END_IF;
IF GVL_DIAGNOSTICS_EXT.G_Health_Heating > 1.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_Heating := 1.0; END_IF;

IF GVL_DIAGNOSTICS_EXT.G_Health_Safety < 0.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_Safety := 0.0; END_IF;
IF GVL_DIAGNOSTICS_EXT.G_Health_Safety > 1.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_Safety := 1.0; END_IF;

IF GVL_DIAGNOSTICS_EXT.G_Health_IO < 0.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_IO := 0.0; END_IF;
IF GVL_DIAGNOSTICS_EXT.G_Health_IO > 1.0 THEN GVL_DIAGNOSTICS_EXT.G_Health_IO := 1.0; END_IF;

fbSystemInit(
    VIO_Local_State := L_Local_State,
    VIO_Remote_State := L_Remote_State
);

fbSystemRecovery(
    VIO_Recovery_Done := L_Recovery_Done
);

fbSystemPersist(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VIO_Persist_Buffer := L_Persist_Buffer,
    VIO_Last_Written_Persist_Buffer := L_Last_Written_Persist_Buffer,
    VIO_Persist_Buffer_Changed := L_Persist_Buffer_Changed,
    VIO_Last_Persist_Write_MS := L_Last_Persist_Write_MS,
    VIO_NVRAM_Cmd := L_NVRAM_Cmd,
    VIO_NVRAM_Offset := L_NVRAM_Offset,
    VIO_NVRAM_Done := L_NVRAM_Done,
    VIO_NVRAM_Err := L_NVRAM_Err,
    VIO_NVRAM_ErrID := L_NVRAM_ErrID
);

fbSystemRedundancy(
    VIO_Local_State := L_Local_State,
    VIO_Remote_State := L_Remote_State
);

L_History_Write_Event := FALSE;
L_History_Event.timestamp_ms := GVL_TIME_SERVICE.G_Now_MS;
L_History_Event.event_code := 0;
L_History_Event.event_value := 0.0;
L_History_Event.unit := 0;
L_History_Event.zone_id := 0;
L_History_Event.operator_id := 'SYSTEM';
L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;

IF GVL_STATE.G_System_Mode <> L_Last_System_Mode THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := 1101;
    L_History_Event.event_value := TO_REAL(TO_INT(GVL_STATE.G_System_Mode));
    L_History_Event.unit := 1;
    L_History_Event.zone_id := 0;
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Last_System_Mode := GVL_STATE.G_System_Mode;

ELSIF GVL_SYSTEM_HEALTH.G_Root_Cause <> L_Last_Root_Cause THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := 1102;
    L_History_Event.event_value := TO_REAL(TO_INT(GVL_SYSTEM_HEALTH.G_Root_Cause));
    L_History_Event.unit := 2;
    L_History_Event.zone_id := TO_BYTE(GVL_SYSTEM_HEALTH.G_First_Fault_Source);
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Last_Root_Cause := GVL_SYSTEM_HEALTH.G_Root_Cause;

ELSIF GVL_SYSTEM_HEALTH.G_First_Fault_Source <> L_Last_First_Fault_Source THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := 1103;
    L_History_Event.event_value := TO_REAL(GVL_SYSTEM_HEALTH.G_First_Fault_Source);
    L_History_Event.unit := 3;
    L_History_Event.zone_id := TO_BYTE(GVL_SYSTEM_HEALTH.G_First_Fault_Source);
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Last_First_Fault_Source := GVL_SYSTEM_HEALTH.G_First_Fault_Source;

ELSIF GVL_STATUS.G_Current_Scenario <> GVL_STATUS.G_Previous_Scenario THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := 1001;
    L_History_Event.event_value := TO_REAL(GVL_STATUS.G_Current_Scenario);
    L_History_Event.unit := 4;
    L_History_Event.zone_id := 0;
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    GVL_STATUS.G_Previous_Scenario := GVL_STATUS.G_Current_Scenario;

ELSIF GVL_STATUS.G_Diagnostics.Alarm_Event_Pulse THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := TO_WORD(GVL_STATUS.G_Diagnostics.Alarm_Event_Code);
    L_History_Event.event_value := GVL_STATUS.G_Diagnostics.Alarm_Event_Value;
    L_History_Event.unit := 10;
    L_History_Event.zone_id := 0;
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;

ELSIF GVL_STATUS.G_Diagnostics.Operator_Journal_Event_Seq <> L_Last_Operator_Journal_Seq THEN
    L_History_Write_Event := TRUE;
    L_History_Event.event_code := 1301;
    L_History_Event.event_value := TO_REAL(GVL_STATUS.G_Diagnostics.Operator_Journal_Event_Seq);
    L_History_Event.unit := 20;
    L_History_Event.zone_id := 0;
    L_History_Event.priority := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Last_Operator_Journal_Seq := GVL_STATUS.G_Diagnostics.Operator_Journal_Event_Seq;
END_IF;

IF L_History_Write_Event THEN
    IF (L_History_Event.event_code = L_Last_Event_Code)
       AND (ABS(L_History_Event.event_value - L_Last_Event_Value) < 0.001)
       AND (GVL_TIME_SERVICE.G_Now_MS - L_Last_Event_Time_MS < 5000) THEN
        L_History_Write_Event := FALSE;
    ELSE
        L_Last_Event_Code := L_History_Event.event_code;
        L_Last_Event_Value := L_History_Event.event_value;
        L_Last_Event_Time_MS := GVL_TIME_SERVICE.G_Now_MS;
    END_IF;
END_IF;

fbHistoryManager(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Write_Event := L_History_Write_Event,
    VI_Event := L_History_Event
);

// ======================================================
// MODBUS RTU DRIVER EXECUTION
// ======================================================
// Runtime execution wrapper for the RTU driver FB.
//
// Driver_Attached is a configuration/HMI decision and must not depend
// on runtime bridge state.
// ======================================================

FB_RTU_Driver(
    VI_Enable := GVL_CONFIG.G_OpenTherm_Enabled,
    VI_Driver_Attached := GVL_CONFIG.G_Modbus_RTU_Driver_Attached,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

L_Mode_Active := GVL_SAFETY_SHUTDOWN.G_Safety_Active;
L_Phase := GVL_SAFETY_RECOVERY.G_Recovery_Phase;

CASE L_Phase OF

    IDLE:
        IF NOT L_Mode_Active AND GVL_SAFETY_RECOVERY.G_Recovery_Requested THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := STABILIZING;
            GVL_SAFETY_RECOVERY.G_Recovery_Active := TRUE;
            GVL_SAFETY_RECOVERY.G_Recovery_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
        END_IF;

    STABILIZING:
        IF L_Mode_Active THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := ABORTED;
            GVL_SAFETY_RECOVERY.G_Recovery_Abort_Reason := 1;
        ELSIF (GVL_TIME_SERVICE.G_Now_MS - GVL_SAFETY_RECOVERY.G_Recovery_Start_MS) > GVL_SAFETY_RECOVERY_CONFIG.G_Stabilization_Delay_MS THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := WAIT_MANUAL_CONFIRM;
            GVL_SAFETY_RECOVERY.G_Recovery_Stable_Since_MS := GVL_TIME_SERVICE.G_Now_MS;
        END_IF;

    WAIT_MANUAL_CONFIRM:
        IF L_Mode_Active THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := ABORTED;
            GVL_SAFETY_RECOVERY.G_Recovery_Abort_Reason := 1;
        ELSIF GVL_SAFETY_RECOVERY.G_Recovery_Manual_Confirm THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := RECOVERING;
        END_IF;

    RECOVERING:
        IF L_Mode_Active THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := ABORTED;
            GVL_SAFETY_RECOVERY.G_Recovery_Abort_Reason := 1;
        ELSE
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := COOLDOWN;
            GVL_SAFETY_RECOVERY.G_Recovery_Cooldown_Start_MS := GVL_TIME_SERVICE.G_Now_MS;
        END_IF;

    COOLDOWN:
        IF L_Mode_Active THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := ABORTED;
            GVL_SAFETY_RECOVERY.G_Recovery_Abort_Reason := 1;
        ELSE
            L_Time_OK := (GVL_TIME_SERVICE.G_Now_MS - GVL_SAFETY_RECOVERY.G_Recovery_Cooldown_Start_MS) > GVL_SAFETY_RECOVERY_CONFIG.G_Cooldown_Time_MS;

            IF L_Time_OK THEN
                GVL_SAFETY_RECOVERY.G_Recovery_Phase := IDLE;
                GVL_SAFETY_RECOVERY.G_Recovery_Active := FALSE;
                GVL_SAFETY_RECOVERY.G_Recovery_Requested := FALSE;
                GVL_SAFETY_RECOVERY.G_Recovery_Manual_Confirm := FALSE;
            END_IF;
        END_IF;

    ABORTED:
        GVL_SAFETY_RECOVERY.G_Recovery_Active := FALSE;
        IF NOT L_Mode_Active THEN
            GVL_SAFETY_RECOVERY.G_Recovery_Phase := IDLE;
        END_IF;

END_CASE;

// >>> BULK_SYNC_ANCHOR: PRG_Safety_Recovery <<<

fbPresence(
    VI_Motion_Sensors := GVL_STATE.G_Motion_Sensors,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

GVL_PRESENCE.G_Any_Motion := fbPresence.VO_Any_Motion;
GVL_PRESENCE.G_Occupied := fbPresence.VO_Occupied;
GVL_PRESENCE.G_Auto_Away_Request := fbPresence.VO_Auto_Away;
GVL_PRESENCE.G_Last_Motion_TS := fbPresence.VO_Last_Motion_TS;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    IF GVL_STATE.G_Motion_Sensors[L_i] THEN
        GVL_PRESENCE.G_Zone_Occupied[L_i] := TRUE;
        GVL_PRESENCE.G_Zone_Last_Motion_TS[L_i] := GVL_STATUS.G_System_Time_MS;
    END_IF;

    IF (GVL_STATUS.G_System_Time_MS - GVL_PRESENCE.G_Zone_Last_Motion_TS[L_i]) > 900000 THEN
        GVL_PRESENCE.G_Zone_Occupied[L_i] := FALSE;
    END_IF;
END_FOR;

// Detect config error from validation layer
L_Config_Error := GVL_STATUS.G_Diagnostics.Sensor_Fault OR GVL_STATUS.G_Diagnostics.Subsystem_Degraded;

// --- Save snapshot when system is healthy ---
IF NOT L_Config_Error THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        GVL_CONFIG_BACKUP.G_Backup_FloorHeating_Configs[L_i] := GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i];
    END_FOR;

    GVL_CONFIG_BACKUP.G_Backup_Max_Active_Manifolds := GVL_CONFIG.G_Max_Active_Manifolds;
    GVL_CONFIG_BACKUP.G_Backup_Max_Thermal_Budget := GVL_CONFIG.G_Max_Thermal_Budget;

    GVL_CONFIG_BACKUP.G_Backup_Valid := TRUE;
END_IF;

// --- Rollback if config invalid ---
IF L_Config_Error THEN

    // Freeze system via command layer
    GVL_COMMAND_SHADOW.G_Heating_Block := TRUE;
    GVL_COMMAND_SHADOW.G_Boiler_Stop := TRUE;

    // Restore snapshot only if valid
    IF GVL_CONFIG_BACKUP.G_Backup_Valid THEN
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
            GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i] := GVL_CONFIG_BACKUP.G_Backup_FloorHeating_Configs[L_i];
        END_FOR;

        GVL_CONFIG.G_Max_Active_Manifolds := GVL_CONFIG_BACKUP.G_Backup_Max_Active_Manifolds;
        GVL_CONFIG.G_Max_Thermal_Budget := GVL_CONFIG_BACKUP.G_Backup_Max_Thermal_Budget;

        GVL_STATUS.G_System_Mode_Text := 'CONFIG ROLLBACK';
    ELSE
        GVL_STATUS.G_System_Mode_Text := 'CONFIG INVALID - NO BACKUP';
    END_IF;
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Config_Versioning <<<

L_Maintenance_Apply_Intent := FALSE;

// Dangerous action request
IF GVL_COMMAND.CMD_Dangerous_Action_Request AND (GVL_COMMAND.CMD_User_Access_Level >= 2) THEN
    IF NOT L_Dangerous_Action_Armed THEN
        fbLogEvent(
            VI_Event_Type := 8,
            VI_Timestamp := GVL_TIME_SERVICE.G_Now_MS,
            VI_Param1 := TO_UDINT(GVL_COMMAND.CMD_User_Access_Level),
            VI_Param2 := 1
        );
    END_IF;

    L_Dangerous_Action_Armed := TRUE;
    L_Dangerous_Action_Deadline_MS := GVL_TIME_SERVICE.G_Now_MS + 15000;

    GVL_STATUS.G_Diagnostics.Dangerous_Action_Pending_Confirm := TRUE;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Confirm_Deadline_MS := L_Dangerous_Action_Deadline_MS;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Confirm_Text := 'Подтвердите опасное действие в течение 15 секунд';
END_IF;

// Timeout
IF L_Dangerous_Action_Armed AND (GVL_TIME_SERVICE.G_Now_MS > L_Dangerous_Action_Deadline_MS) THEN
    L_Dangerous_Action_Armed := FALSE;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Pending_Confirm := FALSE;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Confirm_Text := 'Окно подтверждения истекло';
END_IF;

// Confirm
IF GVL_COMMAND.CMD_Dangerous_Action_Confirm AND
   L_Dangerous_Action_Armed AND
   (GVL_COMMAND.CMD_User_Access_Level >= 2) THEN

    L_Maintenance_Apply_Intent := TRUE;

    fbLogEvent(
        VI_Event_Type := 9,
        VI_Timestamp := GVL_TIME_SERVICE.G_Now_MS,
        VI_Param1 := TO_UDINT(GVL_COMMAND.CMD_User_Access_Level),
        VI_Param2 := 1
    );

    L_Dangerous_Action_Armed := FALSE;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Pending_Confirm := FALSE;
    GVL_STATUS.G_Diagnostics.Dangerous_Action_Confirm_Text := 'Опасное действие подтверждено оператором';
END_IF;

// Apply maintenance
IF L_Maintenance_Apply_Intent THEN
    GVL_CONFIG.G_DHW_Heating_Pump_In_Service := GVL_COMMAND.CMD_Set_DHW_Heating_Pump_In_Service;
    GVL_CONFIG.G_DHW_Circ_Pump_In_Service := GVL_COMMAND.CMD_Set_DHW_Circ_Pump_In_Service;
END_IF;

// Access enforcement
GVL_STATUS.G_Diagnostics.User_Access_Level_Active := GVL_COMMAND.CMD_User_Access_Level;
GVL_STATUS.G_Diagnostics.User_Access_Denied := FALSE;

IF GVL_COMMAND.CMD_Dangerous_Action_Request OR GVL_COMMAND.CMD_Dangerous_Action_Confirm THEN
    IF GVL_COMMAND.CMD_User_Access_Level < 2 THEN
        IF NOT L_User_Access_Denied_Prev THEN
            fbLogEvent(
                VI_Event_Type := 10,
                VI_Timestamp := GVL_TIME_SERVICE.G_Now_MS,
                VI_Param1 := TO_UDINT(GVL_COMMAND.CMD_User_Access_Level),
                VI_Param2 := 2
            );
        END_IF;

        GVL_STATUS.G_Diagnostics.User_Access_Denied := TRUE;
        GVL_STATUS.G_Diagnostics.Operator_Action_Blocked := TRUE;
    END_IF;
END_IF;

L_User_Access_Denied_Prev := GVL_STATUS.G_Diagnostics.User_Access_Denied;

L_Scenario_Config := GVL_CONFIG.G_HMI_Scenario_Configs[TO_INT(GVL_STATUS.G_Current_Scenario)];

fbSimulation(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_Scenario := GVL_STATUS.G_Current_Scenario,
    VI_Config := L_Scenario_Config
);

fbPlayback(
    VI_Mode_Record := FALSE,
    VI_Time_Index := GVL_TIME_SERVICE.G_Now_MS,
    VI_Light_Inputs := L_Playback_Lights
);

// Reset outputs
GVL_SIMULATION.G_Sim_Heating_Sensor_Fault := FALSE;
GVL_SIMULATION.G_Sim_IO_Fault := FALSE;
GVL_SIMULATION.G_Sim_Low_Pressure := FALSE;
GVL_SIMULATION.G_Sim_Predictive_Pump_Fault := FALSE;
GVL_SIMULATION.G_Sim_Gas_Alarm := FALSE;
GVL_SIMULATION.G_Sim_Leak_Alarm := FALSE;
GVL_SIMULATION.G_Sim_Smoke_Alarm := FALSE;
GVL_SIMULATION.G_Sim_Dual_PLC_Active := FALSE;

IF NOT GVL_SIMULATION.G_Simulation_Enable THEN
    GVL_SIMULATION.G_Test_Running := FALSE;
    GVL_SIMULATION.G_Test_Scenario_Active := FALSE;
    RETURN;
END_IF;

// Start scenario
IF GVL_SIMULATION.G_Test_Start THEN
    GVL_SIMULATION.G_Test_Scenario_Active := TRUE;
    GVL_SIMULATION.G_Test_Started_MS := GVL_TIME_SERVICE.G_Now_MS;
END_IF;

// Stop scenario
IF GVL_SIMULATION.G_Test_Stop THEN
    GVL_SIMULATION.G_Test_Scenario_Active := FALSE;
END_IF;

GVL_SIMULATION.G_Test_Running := GVL_SIMULATION.G_Test_Scenario_Active;

IF NOT GVL_SIMULATION.G_Test_Scenario_Active THEN
    RETURN;
END_IF;

// Scenario execution
CASE GVL_SIMULATION.G_Test_Scenario_ID OF

    1: // Gas safety
        GVL_SIMULATION.G_Sim_Gas_Alarm := TRUE;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 1;

    2: // Leak + pressure
        GVL_SIMULATION.G_Sim_Leak_Alarm := TRUE;
        GVL_SIMULATION.G_Sim_Low_Pressure := TRUE;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 2;

    3: // Sensor + predictive
        GVL_SIMULATION.G_Sim_Heating_Sensor_Fault := TRUE;
        GVL_SIMULATION.G_Sim_Predictive_Pump_Fault := TRUE;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 2;

    4: // Dual PLC
        GVL_SIMULATION.G_Sim_Dual_PLC_Active := TRUE;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 3;

    5: // Full stress
        GVL_SIMULATION.G_Sim_Gas_Alarm := TRUE;
        GVL_SIMULATION.G_Sim_Leak_Alarm := TRUE;
        GVL_SIMULATION.G_Sim_Smoke_Alarm := TRUE;
        GVL_SIMULATION.G_Sim_Low_Pressure := TRUE;
        GVL_SIMULATION.G_Sim_Predictive_Pump_Fault := TRUE;
        GVL_SIMULATION.G_Test_Expected_Result_Code := 4;

ELSE
        // No fallback required
END_CASE;

// Auto stop by time
IF (GVL_TIME_SERVICE.G_Now_MS - GVL_SIMULATION.G_Test_Started_MS) > GVL_SIMULATION.G_Test_Duration_MS THEN
    GVL_SIMULATION.G_Test_Scenario_Active := FALSE;
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_System_Simulation <<<

// ======================================================
// PRIORITY 1: PLC ROLE VALIDATION (ABSOLUTE)
// ======================================================
IF GVL_STATUS.G_Is_Active_PLC AND GVL_STATUS.G_Other_PLC_Is_Active THEN
    GVL_HEALTH_BRIDGE.G_Role_Conflict_Error := TRUE;

    GVL_COMMAND_SHADOW.G_Gas_Valve_Close := TRUE;
    GVL_COMMAND_SHADOW.G_Boiler_Stop := TRUE;
    GVL_COMMAND_SHADOW.G_Supply_100_Req := FALSE;
    GVL_COMMAND_SHADOW.G_Supply_80_Req := FALSE;
    GVL_COMMAND_SHADOW.G_Vent_PV3_Boost := FALSE;
    GVL_COMMAND_SHADOW.G_Exhaust_100_Req := FALSE;
    GVL_COMMAND_SHADOW.G_Vent_Stop := TRUE;
    GVL_COMMAND_SHADOW.G_Vent_Block := TRUE;
    GVL_COMMAND_SHADOW.G_Vent_Smoke_Exhaust := FALSE;

    GVL_COMMAND_SHADOW.G_Heating_Block := TRUE;
    GVL_COMMAND_SHADOW.G_Heating_Emergency_Stop := TRUE;
    GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop := TRUE;

    GVL_COMMAND_SHADOW.G_Water_Block := TRUE;
    GVL_COMMAND_SHADOW.G_Water_Emergency_Stop := TRUE;
    GVL_COMMAND_SHADOW.G_Close_Valve_35 := TRUE;
    GVL_COMMAND_SHADOW.G_Close_Valve_36 := TRUE;

    GVL_COMMAND_SHADOW.G_Lock_1_Open := FALSE;
    GVL_COMMAND_SHADOW.G_Lock_1_Close := FALSE;
    GVL_COMMAND_SHADOW.G_Lock_2_Open := FALSE;
    GVL_COMMAND_SHADOW.G_Lock_2_Close := FALSE;
    GVL_COMMAND_SHADOW.G_Gate_Open := FALSE;
    GVL_COMMAND_SHADOW.G_Wicket_Open := FALSE;
    RETURN;
END_IF;

// ======================================================
// PRIORITY 2: PLC INACTIVE
// ======================================================
IF NOT GVL_STATUS.G_Is_Active_PLC THEN
    GVL_COMMAND_SHADOW.G_Gas_Valve_Close := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Close_Gas;
    GVL_COMMAND_SHADOW.G_Boiler_Stop := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Boiler;
    GVL_COMMAND_SHADOW.G_Supply_100_Req := FALSE;
    GVL_COMMAND_SHADOW.G_Supply_80_Req := FALSE;
    GVL_COMMAND_SHADOW.G_Vent_PV3_Boost := FALSE;
    GVL_COMMAND_SHADOW.G_Exhaust_100_Req := FALSE;
    GVL_COMMAND_SHADOW.G_Vent_Stop := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Stop_Vent;
    GVL_COMMAND_SHADOW.G_Vent_Block := FALSE;
    GVL_COMMAND_SHADOW.G_Vent_Smoke_Exhaust := FALSE;

    GVL_COMMAND_SHADOW.G_Heating_Block := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Heating;
    GVL_COMMAND_SHADOW.G_Heating_Emergency_Stop := FALSE;
    GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop := FALSE;

    GVL_COMMAND_SHADOW.G_Water_Block := GVL_COMMAND_POLICY_CONFIG.G_PLC_Inactive_Block_Water;
    GVL_COMMAND_SHADOW.G_Water_Emergency_Stop := FALSE;
    GVL_COMMAND_SHADOW.G_Close_Valve_35 := FALSE;
    GVL_COMMAND_SHADOW.G_Close_Valve_36 := FALSE;

    GVL_COMMAND_SHADOW.G_Lock_1_Open := FALSE;
    GVL_COMMAND_SHADOW.G_Lock_1_Close := FALSE;
    GVL_COMMAND_SHADOW.G_Lock_2_Open := FALSE;
    GVL_COMMAND_SHADOW.G_Lock_2_Close := FALSE;
    GVL_COMMAND_SHADOW.G_Gate_Open := FALSE;
    GVL_COMMAND_SHADOW.G_Wicket_Open := FALSE;
    RETURN;
END_IF;

// ======================================================
// RESET LOCAL BUFFER
// ======================================================
L_Gas_Valve_Close := FALSE;
L_Boiler_Stop := FALSE;
L_Supply_100_Req := FALSE;
L_Supply_80_Req := FALSE;
L_Vent_PV3_Boost := FALSE;
L_Exhaust_100_Req := FALSE;
L_Vent_Stop := FALSE;
L_Vent_Block := FALSE;
L_Vent_Smoke_Exhaust := FALSE;

L_Heating_Block := FALSE;
L_Heating_Emergency_Stop := FALSE;
L_Heating_Gas_Safety_Stop := FALSE;

L_Water_Block := FALSE;
L_Water_Emergency_Stop := FALSE;
L_Close_Valve_35 := FALSE;
L_Close_Valve_36 := FALSE;

L_Lock_1_Open := FALSE;
L_Lock_1_Close := FALSE;
L_Lock_2_Open := FALSE;
L_Lock_2_Close := FALSE;
L_Gate_Open := FALSE;
L_Wicket_Open := FALSE;

// ======================================================
// PRIORITY 3: SAFETY MODE
// ======================================================
L_Mode := GVL_SAFETY_SHUTDOWN.G_Safety_Mode;
L_Safety_Active := FALSE;

CASE L_Mode OF

    NORMAL:
        L_Safety_Active := FALSE;

    FIRE:
        L_Safety_Active := TRUE;
        L_Heating_Block := GVL_COMMAND_POLICY_CONFIG.G_Fire_Block_Heating;
        L_Boiler_Stop := GVL_COMMAND_POLICY_CONFIG.G_Fire_Stop_Boiler;
        L_Vent_Stop := FALSE;
        L_Vent_PV3_Boost := FALSE;
        L_Exhaust_100_Req := FALSE;
        L_Vent_Smoke_Exhaust := TRUE;
        L_Heating_Emergency_Stop := GVL_COMMAND_POLICY_CONFIG.G_Fire_Block_Heating;
        L_Lock_1_Open := GVL_COMMAND_POLICY_CONFIG.G_Fire_Open_Lock_1;
        L_Lock_2_Open := GVL_COMMAND_POLICY_CONFIG.G_Fire_Open_Lock_2;
        L_Gate_Open := GVL_COMMAND_POLICY_CONFIG.G_Fire_Open_Gate;
        L_Wicket_Open := GVL_COMMAND_POLICY_CONFIG.G_Fire_Open_Wicket;

    GAS:
        L_Safety_Active := TRUE;
        L_Gas_Valve_Close := GVL_COMMAND_POLICY_CONFIG.G_Gas_Close_Gas;
        L_Boiler_Stop := GVL_COMMAND_POLICY_CONFIG.G_Gas_Stop_Boiler;
        L_Heating_Block := GVL_COMMAND_POLICY_CONFIG.G_Gas_Block_Heating;
        L_Heating_Gas_Safety_Stop := GVL_COMMAND_POLICY_CONFIG.G_Gas_Block_Heating;
        L_Vent_PV3_Boost := TRUE;
        L_Vent_Smoke_Exhaust := FALSE;
        L_Gate_Open := GVL_COMMAND_POLICY_CONFIG.G_Gas_Open_Gate;
        L_Wicket_Open := GVL_COMMAND_POLICY_CONFIG.G_Gas_Open_Wicket;
        L_Lock_1_Open := GVL_COMMAND_POLICY_CONFIG.G_Gas_Open_Lock_1;
        L_Lock_2_Open := GVL_COMMAND_POLICY_CONFIG.G_Gas_Open_Lock_2;

    WATER_LEAK:
        L_Safety_Active := TRUE;
        L_Water_Block := GVL_COMMAND_POLICY_CONFIG.G_Water_Block_Water;
        L_Water_Emergency_Stop := GVL_COMMAND_POLICY_CONFIG.G_Water_Block_Water;
        L_Close_Valve_35 := GVL_COMMAND_POLICY_CONFIG.G_Water_Block_Water;
        L_Close_Valve_36 := GVL_COMMAND_POLICY_CONFIG.G_Water_Block_Water;

    GLOBAL_STOP:
        L_Safety_Active := TRUE;
        L_Heating_Block := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Heating;
        L_Heating_Emergency_Stop := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Heating;
        L_Boiler_Stop := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Stop_Boiler;
        L_Vent_Stop := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Stop_Vent;
        L_Water_Block := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Water;
        L_Water_Emergency_Stop := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Water;
        L_Close_Valve_35 := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Water;
        L_Close_Valve_36 := GVL_COMMAND_POLICY_CONFIG.G_GlobalStop_Block_Water;

ELSE
        L_Safety_Active := TRUE;
        L_Gas_Valve_Close := TRUE;
        L_Boiler_Stop := TRUE;
        L_Heating_Block := TRUE;
        L_Heating_Emergency_Stop := TRUE;
        L_Vent_Stop := TRUE;
        L_Water_Block := TRUE;
        L_Water_Emergency_Stop := TRUE;
        L_Close_Valve_35 := TRUE;
        L_Close_Valve_36 := TRUE;
END_CASE;

// ======================================================
// PRIORITY 4: USER INTENT (ONLY WHEN SAFETY IS NOT ACTIVE)
// ======================================================
L_User_Access_OK := GVL_INTENT_USER.I_Source_Valid AND (GVL_INTENT_USER.I_User_Access_Level >= 1);

IF (NOT L_Safety_Active) AND L_User_Access_OK THEN
    IF GVL_INTENT_USER.I_Lock_1_Open_Request THEN
        L_Lock_1_Open := TRUE;
        L_Lock_1_Close := FALSE;
    ELSIF GVL_INTENT_USER.I_Lock_1_Close_Request THEN
        L_Lock_1_Open := FALSE;
        L_Lock_1_Close := TRUE;
    END_IF;

    IF GVL_INTENT_USER.I_Lock_2_Open_Request THEN
        L_Lock_2_Open := TRUE;
        L_Lock_2_Close := FALSE;
    ELSIF GVL_INTENT_USER.I_Lock_2_Close_Request THEN
        L_Lock_2_Open := FALSE;
        L_Lock_2_Close := TRUE;
    END_IF;

    IF GVL_INTENT_USER.I_Gate_Open_Request THEN
        L_Gate_Open := TRUE;
    END_IF;

    IF GVL_INTENT_USER.I_Wicket_Open_Request THEN
        L_Wicket_Open := TRUE;
    END_IF;
END_IF;

// Dangerous user actions require explicit confirmation and elevated access.
IF (NOT L_Safety_Active) AND
   GVL_INTENT_USER.I_Source_Valid AND
   GVL_INTENT_USER.I_Dangerous_Action_Request AND
   GVL_INTENT_USER.I_Dangerous_Action_Confirm AND
   (GVL_INTENT_USER.I_User_Access_Level >= 2) THEN
    // Reserved for future high-risk manual actions.
    // No direct safety override is allowed here.
END_IF;

// ======================================================
// PRIORITY 5: AUTOMATION RULES (ONLY SAFE COMMAND-LEVEL ACTIONS)
// ======================================================
IF NOT L_Safety_Active THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF GVL_STATE.G_Rule_Actions[L_i].Active AND GVL_STATE.G_Rule_Actions[L_i].Triggered THEN
            CASE GVL_STATE.G_Rule_Actions[L_i].Action_Type OF

                ACTION_SET_FLOOR_HEATING:
                    IF GVL_STATE.G_Rule_Actions[L_i].Value <= 0.0 THEN
                        L_Heating_Block := TRUE;
                        L_Boiler_Stop := TRUE;
                    END_IF;

                ACTION_SET_VENTILATION:
                    IF GVL_STATE.G_Rule_Actions[L_i].Value <= 0.0 THEN
                        L_Vent_Stop := TRUE;
                    END_IF;

            ELSE
                // Non command-level actions are handled by their own subsystem.
            END_CASE;
        END_IF;
    END_FOR;
END_IF;

// ======================================================
// POST-PROCESS CONFLICT RESOLUTION
// ======================================================
IF (L_Mode = FIRE) AND GVL_COMMAND_POLICY_CONFIG.G_Fire_Block_Lock_Close THEN
    L_Lock_1_Close := FALSE;
    L_Lock_2_Close := FALSE;
END_IF;

IF GVL_COMMAND_POLICY_CONFIG.G_Block_Close_When_Open_Commanded THEN
    IF L_Lock_1_Open AND L_Lock_1_Close THEN
        L_Lock_1_Close := FALSE;
    END_IF;

    IF L_Lock_2_Open AND L_Lock_2_Close THEN
        L_Lock_2_Close := FALSE;
    END_IF;
END_IF;

// ======================================================
// SINGLE POINT WRITE (DETERMINISTIC)
// ======================================================
GVL_COMMAND_SHADOW.G_Gas_Valve_Close := L_Gas_Valve_Close;
GVL_COMMAND_SHADOW.G_Boiler_Stop := L_Boiler_Stop;
GVL_COMMAND_SHADOW.G_Supply_100_Req := L_Supply_100_Req;
GVL_COMMAND_SHADOW.G_Supply_80_Req := L_Supply_80_Req;
GVL_COMMAND_SHADOW.G_Vent_PV3_Boost := L_Vent_PV3_Boost;
GVL_COMMAND_SHADOW.G_Exhaust_100_Req := L_Exhaust_100_Req;
GVL_COMMAND_SHADOW.G_Vent_Stop := L_Vent_Stop;
GVL_COMMAND_SHADOW.G_Vent_Block := L_Vent_Block;
GVL_COMMAND_SHADOW.G_Vent_Smoke_Exhaust := L_Vent_Smoke_Exhaust;

GVL_COMMAND_SHADOW.G_Heating_Block := L_Heating_Block;
GVL_COMMAND_SHADOW.G_Heating_Emergency_Stop := L_Heating_Emergency_Stop;
GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop := L_Heating_Gas_Safety_Stop;

GVL_COMMAND_SHADOW.G_Water_Block := L_Water_Block;
GVL_COMMAND_SHADOW.G_Water_Emergency_Stop := L_Water_Emergency_Stop;
GVL_COMMAND_SHADOW.G_Close_Valve_35 := L_Close_Valve_35;
GVL_COMMAND_SHADOW.G_Close_Valve_36 := L_Close_Valve_36;

GVL_COMMAND_SHADOW.G_Lock_1_Open := L_Lock_1_Open;
GVL_COMMAND_SHADOW.G_Lock_1_Close := L_Lock_1_Close;
GVL_COMMAND_SHADOW.G_Lock_2_Open := L_Lock_2_Open;
GVL_COMMAND_SHADOW.G_Lock_2_Close := L_Lock_2_Close;
GVL_COMMAND_SHADOW.G_Gate_Open := L_Gate_Open;
GVL_COMMAND_SHADOW.G_Wicket_Open := L_Wicket_Open;

// >>> BULK_SYNC_ANCHOR: PRG_Command_Arbitration <<<

// ======================================================
// PEER HEARTBEAT INGESTION
// ======================================================
// Bounded transport/heartbeat ingestion bridge.
//
// Purpose:
// map physical partner heartbeat inputs into runtime-visible
// remote PLC liveness state consumed by arbitration layers.
//
// This layer does NOT:
// - perform distributed epoch reconciliation
// - publish peer fencing tokens
// - mutate distributed authority state
// - participate in runtime/output hard-stop governance
//
// Ownership:
// physical partner inputs  -> GVL_IO
// heartbeat ingestion      -> this PRG
// arbitration/governance   -> downstream consumers only
// ======================================================

L_Now_MS := GVL_STATUS.G_System_Time_MS;

// ------------------------------------------------------
// Physical heartbeat ingestion.
// ------------------------------------------------------

GVL_STATUS.G_Remote_PLC_Pulse := GVL_IO.DI_Partner_Pulse;

// ------------------------------------------------------
// Partner active visibility projection.
// ------------------------------------------------------

IF GVL_IO.DI_Partner_Active THEN
    GVL_STATUS.G_Remote_PLC_Last_Seen_MS := L_Now_MS;
END_IF;

// ------------------------------------------------------
// Optional pulse freshness refresh.
// ------------------------------------------------------

IF GVL_IO.DI_Partner_Pulse THEN
    GVL_STATUS.G_Remote_PLC_Last_Seen_MS := L_Now_MS;
END_IF;

// ------------------------------------------------------
// Remote liveness projection.
// ------------------------------------------------------

GVL_STATUS.G_Remote_PLC_Alive :=
    (L_Now_MS - GVL_STATUS.G_Remote_PLC_Last_Seen_MS) < 3000;

// >>> BULK_SYNC_ANCHOR: PRG_Peer_Heartbeat_Ingestion <<<

L_PreOutput_Block_IO := GVL_COMMAND_VERIFY.PreOutput_Block_IO;
L_Output_Freshness_Block := GVL_OUTPUT_EPOCH.Output_Forced_Safe_Decay;
L_Snapshot_Block := (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen) OR (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed) OR (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid) OR (NOT GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid) OR GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected;
L_Global_Hard_Stop := GVL_COMMAND_SHADOW.G_Heating_Emergency_Stop OR L_PreOutput_Block_IO OR L_Output_Freshness_Block OR L_Snapshot_Block;
L_Gas_Safety_Stop := GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop OR GVL_COMMAND_SHADOW.G_Boiler_Stop;
L_Freeze_Active := GVL_STATE.G_Safety_Freeze_Risk;
L_Gas_Fire_Siren_Enable := GVL_ALARM.G_Gas_Fire_Siren OR GVL_ALARM.G_Global_Siren OR GVL_ALARM.G_Global_Critical;

// ======================================================
// AUTHORITATIVE IO HARD-STOP GATE
// ======================================================
// Physical IO publication must never continue when:
//   - PLC authority is lost;
//   - emergency stop is active;
//   - pre-output barrier rejected current-cycle runtime projection;
//   - output freshness governor invalidated publication;
//   - immutable snapshot authority invalidated publication;
//   - snapshot mutation was detected.
// ======================================================

IF NOT GVL_STATUS.G_Is_Active_PLC OR L_Global_Hard_Stop THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        GVL_IO.DO_Zone_Valves[L_i] := FALSE;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        GVL_IO.DO_Manifold_Pumps[L_i] := FALSE;
        GVL_IO.AO_Manifold_Valves[L_i] := 0;
    END_FOR;

    GVL_IO.DO_DHW_Heating_Pump := FALSE;
    GVL_IO.DO_DHW_Circ_Pump := FALSE;
    GVL_IO.DO_Backup_Circulation_Pump := FALSE;
    GVL_IO.DO_Electric_Heater_Enable := FALSE;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        GVL_IO.AO_Supply_Fans[L_i] := 0;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        GVL_IO.AO_Exhaust_Fans[L_i] := 0;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WATER_ZONES DO
        GVL_IO.DO_Water_Zone_Enable[L_i] := FALSE;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
        GVL_IO.AO_Lighting_Levels[L_i] := 0;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
        GVL_IO.AO_Blinds_Positions[L_i] := 1000;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
        GVL_IO.DO_Sockets[L_i] := FALSE;
    END_FOR;

    GVL_IO.DO_Gate_Open := FALSE;
    GVL_IO.DO_Wicket_Open := FALSE;
    GVL_IO.DO_Lock_1_Open := FALSE;
    GVL_IO.DO_Lock_1_Close := FALSE;
    GVL_IO.DO_Lock_2_Open := FALSE;
    GVL_IO.DO_Lock_2_Close := FALSE;
    GVL_IO.DO_Gas_Siren := L_Gas_Fire_Siren_Enable AND GVL_ALARM.G_Gas_Alarm_Active;
    GVL_IO.DO_Fire_Siren := L_Gas_Fire_Siren_Enable AND GVL_ALARM.G_Fire_Alarm_Active;
    GVL_IO.DO_Security_Siren := GVL_ALARM.G_Security_Siren OR (GVL_ALARM.G_Global_Siren AND GVL_ALARM.G_Security_Alarm);
    GVL_IO.DO_Gas_Valve_Close := TRUE;

    IF L_PreOutput_Block_IO THEN
        fbTrace(iLayer := TRACE_IO,iSource := SRC_IO,iReason := REASON_SAFETY_BLOCK,iValueBool := TRUE,iValueReal := REAL(GVL_COMMAND_VERIFY.PreOutput_Last_Error_Code),iText := 'IO blocked by pre-output barrier');
    END_IF;

    IF L_Output_Freshness_Block THEN
        fbTrace(iLayer := TRACE_IO,iSource := SRC_IO,iReason := REASON_SAFETY_BLOCK,iValueBool := TRUE,iValueReal := REAL(GVL_OUTPUT_EPOCH.Output_Last_Error_Code),iText := 'IO forced safe by output freshness decay');
    END_IF;

    IF L_Snapshot_Block THEN
        fbTrace(iLayer := TRACE_IO,iSource := SRC_IO,iReason := REASON_SAFETY_BLOCK,iValueBool := TRUE,iValueReal := REAL(GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Error_Code),iText := 'IO blocked by immutable snapshot authority');
    END_IF;

    RETURN;
END_IF;

L_Heating_Forced_Off := GVL_COMMAND_SHADOW.G_Heating_Block;
L_Vent_Forced_Off := GVL_COMMAND_SHADOW.G_Vent_Stop OR GVL_COMMAND_SHADOW.G_Vent_Block;
L_Water_Forced_Off := GVL_COMMAND_SHADOW.G_Water_Block OR GVL_COMMAND_SHADOW.G_Water_Emergency_Stop;

L_Access_Safety_Override := (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE) OR (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS);
L_Access_Forced_Off := GVL_SAFETY_RECOVERY.G_Recovery_Active AND NOT L_Access_Safety_Override;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF (L_i > GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits) OR L_Heating_Forced_Off THEN
        GVL_IO.DO_Zone_Valves[L_i] := FALSE;
    ELSE
        GVL_IO.DO_Zone_Valves[L_i] := GVL_HEATING_OUTPUT.DO_Zone_Valves[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF L_Heating_Forced_Off AND NOT (L_Gas_Safety_Stop AND L_Freeze_Active) THEN
        GVL_IO.DO_Manifold_Pumps[L_i] := FALSE;
        GVL_IO.AO_Manifold_Valves[L_i] := 0;
    ELSE
        GVL_IO.DO_Manifold_Pumps[L_i] := GVL_HEATING_OUTPUT.DO_Manifold_Pumps[L_i];
        GVL_IO.AO_Manifold_Valves[L_i] := GVL_HEATING_OUTPUT.AO_Manifold_Valves[L_i];
    END_IF;
END_FOR;

IF L_Heating_Forced_Off AND NOT (L_Gas_Safety_Stop AND L_Freeze_Active) THEN
    GVL_IO.DO_DHW_Heating_Pump := FALSE;
    GVL_IO.DO_DHW_Circ_Pump := FALSE;
    GVL_IO.DO_Backup_Circulation_Pump := FALSE;
    GVL_IO.DO_Electric_Heater_Enable := FALSE;
ELSE
    GVL_IO.DO_DHW_Heating_Pump := GVL_HEATING_OUTPUT.DO_DHW_Heating_Pump;
    GVL_IO.DO_DHW_Circ_Pump := GVL_HEATING_OUTPUT.DO_DHW_Circ_Pump;
    GVL_IO.DO_Backup_Circulation_Pump := GVL_HEATING_OUTPUT.DO_Backup_Circulation_Pump;
    GVL_IO.DO_Electric_Heater_Enable := GVL_HEATING_OUTPUT.DO_Electric_Heater_Enable;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    IF L_Vent_Forced_Off THEN
        GVL_IO.AO_Supply_Fans[L_i] := 0;
    ELSE
        GVL_IO.AO_Supply_Fans[L_i] := GVL_VENT_OUTPUT.AO_Supply_Fans[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    IF L_Vent_Forced_Off THEN
        GVL_IO.AO_Exhaust_Fans[L_i] := 0;
    ELSE
        GVL_IO.AO_Exhaust_Fans[L_i] := GVL_VENT_OUTPUT.AO_Exhaust_Fans[L_i];
    END_IF;
END_FOR;

GVL_IO.DO_Water_Valve_35_Close := GVL_WATER_OUTPUT.DO_Water_Valve_35_Close;
GVL_IO.DO_Water_Valve_36_Close := GVL_WATER_OUTPUT.DO_Water_Valve_36_Close;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WATER_ZONES DO
    IF (L_i > GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones) OR L_Water_Forced_Off THEN
        GVL_IO.DO_Water_Zone_Enable[L_i] := FALSE;
    ELSE
        GVL_IO.DO_Water_Zone_Enable[L_i] := GVL_WATER_OUTPUT.DO_Water_Zone_Enable[L_i];
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_LIGHT_ZONES DO
    GVL_IO.AO_Lighting_Levels[L_i] := GVL_LIGHTING_OUTPUT.AO_Lighting_Levels[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
    GVL_IO.AO_Blinds_Positions[L_i] := GVL_LIGHTING_OUTPUT.AO_Blinds_Positions[L_i];
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    GVL_IO.DO_Sockets[L_i] := GVL_LIGHTING_OUTPUT.DO_Sockets[L_i];
END_FOR;

IF L_Access_Forced_Off THEN
    GVL_IO.DO_Gate_Open := FALSE;
    GVL_IO.DO_Wicket_Open := FALSE;
    GVL_IO.DO_Lock_1_Open := FALSE;
    GVL_IO.DO_Lock_1_Close := FALSE;
    GVL_IO.DO_Lock_2_Open := FALSE;
    GVL_IO.DO_Lock_2_Close := FALSE;
ELSE
    GVL_IO.DO_Gate_Open := GVL_ACCESS_OUTPUT.DO_Gate_Open;
    GVL_IO.DO_Wicket_Open := GVL_ACCESS_OUTPUT.DO_Wicket_Open;
    GVL_IO.DO_Lock_1_Open := GVL_ACCESS_OUTPUT.DO_Lock_1_Open;
    GVL_IO.DO_Lock_1_Close := GVL_ACCESS_OUTPUT.DO_Lock_1_Close;
    GVL_IO.DO_Lock_2_Open := GVL_ACCESS_OUTPUT.DO_Lock_2_Open;
    GVL_IO.DO_Lock_2_Close := GVL_ACCESS_OUTPUT.DO_Lock_2_Close;
END_IF;

GVL_IO.DO_Gas_Siren := L_Gas_Fire_Siren_Enable AND GVL_ALARM.G_Gas_Alarm_Active;
GVL_IO.DO_Fire_Siren := L_Gas_Fire_Siren_Enable AND GVL_ALARM.G_Fire_Alarm_Active;
GVL_IO.DO_Security_Siren := GVL_ALARM.G_Security_Siren OR (GVL_ALARM.G_Global_Siren AND GVL_ALARM.G_Security_Alarm);
GVL_IO.DO_Gas_Valve_Close := GVL_COMMAND_SHADOW.G_Gas_Valve_Close;

fbTrace(iLayer := TRACE_IO,iSource := SRC_IO,iReason := REASON_DOMAIN_PROJECTION,iValueBool := TRUE,iValueReal := 0.0,iText := 'IO write projection executed');

// ======================================================
// MODBUS RTU SYSCOM TRANSPORT EXECUTION
// ======================================================
// Byte-level transport boundary execution.
// ======================================================

FB_SysCom_Transport(
    VI_Enable := GVL_CONFIG.G_OpenTherm_Enabled,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

L_Now_MS := GVL_STATUS.G_System_Time_MS;
L_Snapshot_Valid := TRUE;
L_Error_Code := 0;
L_Error_Text := '';

// ======================================================
// IMMUTABLE RUNTIME SNAPSHOT GOVERNOR
// ======================================================
// Governs immutable publication snapshot semantics.
// Prevents mutable runtime publication leakage.
//
// Runtime snapshot is upstream of output freshness.
// It must not depend on downstream output decay state.
// ======================================================

GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected := FALSE;
GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed := FALSE;
GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen := FALSE;

// ------------------------------------------------------
// Runtime authority linkage.
// ------------------------------------------------------

IF NOT GVL_RUNTIME_EPOCH.Runtime_Runtime_Barrier_OK THEN
    L_Snapshot_Valid := FALSE;
    L_Error_Code := 12000;
    L_Error_Text := 'Runtime authority invalid';
END_IF;

// ------------------------------------------------------
// Mutation detection foundation.
// ------------------------------------------------------

IF L_Snapshot_Valid
AND GVL_RUNTIME_EPOCH.Runtime_Impossible_State_Detected
THEN
    L_Snapshot_Valid := FALSE;
    L_Error_Code := 12003;
    L_Error_Text := 'Runtime mutation anomaly detected';

    GVL_RUNTIME_SNAPSHOT.Snapshot_Mutation_Detected := TRUE;
END_IF;

// ------------------------------------------------------
// Immutable snapshot freeze semantics.
// ------------------------------------------------------

IF L_Snapshot_Valid THEN
    GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen := TRUE;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed := TRUE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid := TRUE;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid := TRUE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Runtime_Authority_Valid := TRUE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Freeze_Start_MS := L_Now_MS;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Publication_MS := L_Now_MS;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Epoch := GVL_RUNTIME_SNAPSHOT.Snapshot_Epoch + 1;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Epoch := GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Epoch + 1;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Error_Code := 0;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Error_Text := '';
ELSE
    GVL_RUNTIME_SNAPSHOT.Snapshot_Frozen := FALSE;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Publication_Allowed := FALSE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Copy_Valid := FALSE;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Isolation_Valid := FALSE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Runtime_Authority_Valid := FALSE;

    GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Error_Code := L_Error_Code;
    GVL_RUNTIME_SNAPSHOT.Snapshot_Last_Error_Text := L_Error_Text;
END_IF;

// ======================================================
// CENTRAL CONFIGURATION VALIDATION
// ======================================================
// Diagnostic-only layer. It sets validation flags and degraded diagnostics,
// but does not write command/shadow/output structures.

L_Config_Error := FALSE;

// ======================================================
// ACTIVE SIZE CONFIGURATION
// ======================================================
IF (GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits < 1) OR
   (GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits > GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS) THEN
    L_Config_Error := TRUE;
END_IF;

IF (GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones < 1) OR
   (GVL_SYSTEM_SIZE_CONFIG.G_Active_Water_Zones > GVL_CONSTANTS.C_MAX_WATER_ZONES) THEN
    L_Config_Error := TRUE;
END_IF;

IF (GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones < 1) OR
   (GVL_SYSTEM_SIZE_CONFIG.G_Active_Light_Zones > GVL_CONSTANTS.C_MAX_LIGHT_ZONES) THEN
    L_Config_Error := TRUE;
END_IF;

IF (GVL_SYSTEM_SIZE_CONFIG.G_Active_Blinds < 0) OR
   (GVL_SYSTEM_SIZE_CONFIG.G_Active_Blinds > GVL_CONSTANTS.C_MAX_BLINDS) THEN
    L_Config_Error := TRUE;
END_IF;

IF (GVL_SYSTEM_SIZE_CONFIG.G_Active_Sockets < 0) OR
   (GVL_SYSTEM_SIZE_CONFIG.G_Active_Sockets > GVL_CONSTANTS.C_MAX_SOCKETS) THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// HEATING CIRCUIT CONFIGURATION
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    L_Zone := BYTE_TO_INT(GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].zone);
    L_Sensor := BYTE_TO_INT(GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].sensor_id);
    L_Manifold := BYTE_TO_INT(GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].manifold_id);

    IF (L_Zone < 1) OR (L_Zone > GVL_CONSTANTS.C_MAX_ZONES) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF (L_Sensor < 1) OR (L_Sensor > GVL_CONSTANTS.C_MAX_ZONES) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF (L_Manifold < 1) OR (L_Manifold > GVL_CONSTANTS.C_MAX_MANIFOLDS) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].min_temp > GVL_CONFIG.G_HMI_FloorHeating_Configs[L_i].max_temp THEN
        L_Config_Error := TRUE;
    END_IF;
END_FOR;

IF (GVL_CONFIG.G_Max_Active_Manifolds < 1) OR
   (GVL_CONFIG.G_Max_Active_Manifolds > GVL_CONSTANTS.C_MAX_MANIFOLDS) THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONFIG.G_Max_Thermal_Budget <= 0.0 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONFIG.G_Policy_Min_Hold_MS < 10000 THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// ACCESS / TIMING CONFIGURATION
// ======================================================
IF (GVL_CONFIG.G_Access_Pulse_MS < 100) OR (GVL_CONFIG.G_Access_Pulse_MS > 5000) THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// MAP CONFIGURATION
// ======================================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_DOOR_SENSORS DO
    L_Map_Index := GVL_CONFIG.G_Door_Map[L_i];
    IF (L_Map_Index < 1) OR (L_Map_Index > GVL_CONSTANTS.C_MAX_SECURITY_SENSORS) THEN
        L_Config_Error := TRUE;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Map_Index := GVL_CONFIG.G_Window_Map[L_i];
    IF L_Map_Index <> 0 THEN
        IF (L_Map_Index < 1) OR (L_Map_Index > (GVL_CONSTANTS.C_MAX_SECURITY_SENSORS * 2)) THEN
            L_Config_Error := TRUE;
        END_IF;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF (GVL_CONFIG.G_FloorTemp_Map[L_i] < 1) OR (GVL_CONFIG.G_FloorTemp_Map[L_i] > GVL_CONSTANTS.C_MAX_ZONES) THEN
        L_Config_Error := TRUE;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    IF (GVL_CONFIG.G_RoomTemp_Map[L_i] < 1) OR (GVL_CONFIG.G_RoomTemp_Map[L_i] > GVL_CONSTANTS.C_MAX_ZONES) THEN
        L_Config_Error := TRUE;
    END_IF;
END_FOR;

// ======================================================
// HARDWARE SERVICE / RETRY CONFIGURATION
// ======================================================
IF GVL_CONFIG.G_Freeze_Hardware_Retry_Count < 0 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONFIG.G_Freeze_Hardware_Retry_Delay_MS < 1000 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONFIG.G_Pump_Exercise_Enabled THEN
    IF GVL_CONFIG.G_Pump_Exercise_Interval_MS < GVL_CONSTANTS.C_MS_IN_MINUTE THEN
        L_Config_Error := TRUE;
    END_IF;
    IF GVL_CONFIG.G_Pump_Exercise_Duration_MS < 1000 THEN
        L_Config_Error := TRUE;
    END_IF;
END_IF;

IF GVL_CONFIG.G_Water_Valve_Exercise_Enabled THEN
    IF GVL_CONFIG.G_Water_Valve_Exercise_Interval_MS < GVL_CONSTANTS.C_MS_IN_MINUTE THEN
        L_Config_Error := TRUE;
    END_IF;
    IF GVL_CONFIG.G_Water_Valve_Exercise_Duration_MS < 1000 THEN
        L_Config_Error := TRUE;
    END_IF;
END_IF;

IF GVL_CONFIG.G_Water_Valve_Close_Retry_Count < 0 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONFIG.G_Water_Valve_Close_Retry_Delay_MS < 1000 THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// OPENTHERM / MODBUS RTU CONFIGURATION
// ======================================================
IF GVL_CONFIG.G_OpenTherm_Enabled THEN

    IF GVL_CONFIG.G_OpenTherm_Heartbeat_Timeout_MS < 1000 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_OpenTherm_Command_Ack_Timeout_MS < 500 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_Modbus_RTU_Baudrate < 1200 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG.G_Modbus_RTU_Parity > 2) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG.G_Modbus_RTU_Stop_Bits < 1) OR
       (GVL_CONFIG.G_Modbus_RTU_Stop_Bits > 2) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF (GVL_CONFIG.G_Modbus_RTU_Data_Bits < 7) OR
       (GVL_CONFIG.G_Modbus_RTU_Data_Bits > 8) THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_Modbus_RTU_Slave_ID = 0 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_Modbus_RTU_Poll_Interval_MS < 50 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_Modbus_RTU_Request_Timeout_MS < 50 THEN
        L_Config_Error := TRUE;
    END_IF;

    IF GVL_CONFIG.G_Modbus_RTU_Retry_Count < 0 THEN
        L_Config_Error := TRUE;
    END_IF;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        IF GVL_CONFIG.G_OpenTherm_Register_Map[L_i].Cmd_Enable_Offset = GVL_CONFIG.G_OpenTherm_Register_Map[L_i].Status_Word_Offset THEN
            L_Config_Error := TRUE;
        END_IF;

        IF GVL_CONFIG.G_OpenTherm_Register_Map[L_i].Cmd_Setpoint_x10_Offset = GVL_CONFIG.G_OpenTherm_Register_Map[L_i].Status_Word_Offset THEN
            L_Config_Error := TRUE;
        END_IF;
    END_FOR;
END_IF;

// ======================================================
// SENSOR COUNT SANITY
// ======================================================
IF GVL_CONSTANTS.C_MAX_METHANE_SENSORS < 2 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONSTANTS.C_MAX_SMOKE_SENSORS < 6 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONSTANTS.C_MAX_CO_SENSORS < 8 THEN
    L_Config_Error := TRUE;
END_IF;

IF GVL_CONSTANTS.C_MAX_FLOOD_SENSORS < 9 THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// CONFIG SIMULATION / COMMISSIONING VALIDATION
// ======================================================
fbConfigSimulation(
    VI_Enable := TRUE,
    VI_Request := GVL_CONFIG_SIMULATION.G_Simulation_Request,
    VI_Confirm := GVL_CONFIG_SIMULATION.G_Simulation_Confirm
);

IF fbConfigSimulation.VO_Executed AND NOT fbConfigSimulation.VO_Result_OK THEN
    L_Config_Error := TRUE;
END_IF;

// ======================================================
// STORE FLAGS
// ======================================================
GVL_CONFIG_VALIDATION.G_Config_Valid := NOT L_Config_Error;
GVL_CONFIG_VALIDATION.G_Config_Critical_Error := L_Config_Error;
GVL_CONFIG_VALIDATION.G_Config_Last_Update_MS := GVL_STATUS.G_System_Time_MS;

IF L_Config_Error THEN
    GVL_CONFIG_VALIDATION.G_Config_Last_Error_Text := 'CONFIG VALIDATION ERROR';
    GVL_STATUS.G_Diagnostics.Subsystem_Degraded := TRUE;
    GVL_STATUS.G_System_Mode_Text := 'CONFIG ERROR';
ELSE
    GVL_CONFIG_VALIDATION.G_Config_Last_Error_Text := '';
END_IF;

// Operator / test / recover workflow ownership.

fbSafetyWorkflow(
    VI_System_Time_MS := GVL_TIME_SERVICE.G_Now_MS,
    VI_Water_Selective_Recover := GVL_INTENT_USER.I_Water_Selective_Recover,
    VI_Gas_Selective_Recover := GVL_INTENT_USER.I_Gas_Selective_Recover,
    VI_Water_Valve_Test_Open := GVL_INTENT_USER.I_Water_Valve_Test_Open,
    VI_Water_Valve_Test_Close := GVL_INTENT_USER.I_Water_Valve_Test_Close,
    VI_Water_Valve_Test_Confirm := GVL_INTENT_USER.I_Water_Valve_Test_Confirm,
    VI_Gas_Valve_Test_Open := GVL_INTENT_USER.I_Gas_Valve_Test_Open,
    VI_Gas_Valve_Test_Close := GVL_INTENT_USER.I_Gas_Valve_Test_Close,
    VI_Gas_Valve_Test_Confirm := GVL_INTENT_USER.I_Gas_Valve_Test_Confirm
);

// propagate test timeout safety actions
IF fbSafetyWorkflow.VO_Water_Test_Timeout_Close_Required THEN
    GVL_INTENT_SAFETY.I_Test_Timeout_Water_Close := TRUE;
END_IF;

IF fbSafetyWorkflow.VO_Gas_Test_Timeout_Close_Required THEN
    GVL_INTENT_SAFETY.I_Test_Timeout_Gas_Close := TRUE;
END_IF;

// move recovery manual confirm here
IF GVL_INTENT_USER.I_Reset_Errors THEN
    GVL_SAFETY_RECOVERY.G_Recovery_Manual_Confirm := TRUE;
END_IF;

// >>> BULK_SYNC_ANCHOR: PRG_Safety_Operator <<<

// ======================================================
// DISTRIBUTED COMMIT OBSERVABILITY GOVERNOR
// ======================================================
// Isolated downstream observability projection layer.
// Publication visibility only.
// Does not invalidate runtime barrier,
// PLC fencing, immutable snapshots or IO directly.
//
// Visibility ownership rule:
// this layer publishes only dedicated distributed
// visibility fields.
//
// Global observability escalation ownership remains
// inside PRG_Observability_Governor.
// ======================================================

GVL_OBSERVABILITY_AUTHORITY.Distributed_Commit_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Distributed_Commit_Quarantine_Visible := FALSE;

GVL_OBSERVABILITY_AUTHORITY.Publication_Prepare_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Publication_Commit_Visible := FALSE;

GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Ack_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Mismatch_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Replay_Visible := FALSE;
GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Missing_Visible := FALSE;

GVL_OBSERVABILITY_AUTHORITY.Commit_Lease_Expired_Visible := FALSE;

// ------------------------------------------------------
// Distributed commit validity visibility.
// ------------------------------------------------------

IF NOT GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Valid THEN
    GVL_OBSERVABILITY_AUTHORITY.Distributed_Commit_Visible := TRUE;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Distributed_Commit_Quarantine_Active THEN
    GVL_OBSERVABILITY_AUTHORITY.Distributed_Commit_Quarantine_Visible := TRUE;
END_IF;

// ------------------------------------------------------
// Publication lifecycle visibility.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_COMMIT.Publication_Prepare_Active THEN
    GVL_OBSERVABILITY_AUTHORITY.Publication_Prepare_Visible := TRUE;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Publication_Commit_Confirmed THEN
    GVL_OBSERVABILITY_AUTHORITY.Publication_Commit_Visible := TRUE;
END_IF;

// ------------------------------------------------------
// Peer commit continuity visibility.
// ------------------------------------------------------

IF GVL_DISTRIBUTED_COMMIT.Peer_Commit_Ack_Valid THEN
    GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Ack_Visible := TRUE;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Peer_Commit_Mismatch THEN
    GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Mismatch_Visible := TRUE;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Peer_Commit_Replay_Detected THEN
    GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Replay_Visible := TRUE;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Peer_Commit_Missing THEN
    GVL_OBSERVABILITY_AUTHORITY.Peer_Commit_Missing_Visible := TRUE;
END_IF;

IF GVL_DISTRIBUTED_COMMIT.Commit_Lease_Expired THEN
    GVL_OBSERVABILITY_AUTHORITY.Commit_Lease_Expired_Visible := TRUE;
END_IF;

// Build weights from compile-safe scalar GVL fields
L_Weights.W_Comfort := GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Comfort;
L_Weights.W_Night := GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Night;
L_Weights.W_Preheat := GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_Preheat;
L_Weights.W_VentBoost := GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_VentBoost;
L_Weights.W_AccessSecure := GVL_BEHAVIOR_ADAPT.G_Behavior_Weight_AccessSecure;

L_Hour := TO_INT(GVL_TIME_SERVICE.G_Time_Of_Day_MS / 3600000);

// Reset
GVL_INTENT_BEHAVIOR.I_Request_Night_Mode := FALSE;
GVL_INTENT_BEHAVIOR.I_Request_Comfort_Mode := FALSE;
GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost := FALSE;
GVL_INTENT_BEHAVIOR.I_Request_Access_Secure_Mode := FALSE;

GVL_INTENT_BEHAVIOR.I_Score_Comfort := REAL_TO_INT(GVL_SCENARIO_CONFIG.G_Comfort_Base_Score * L_Weights.W_Comfort);
GVL_INTENT_BEHAVIOR.I_Score_Night := 0;
GVL_INTENT_BEHAVIOR.I_Score_Preheat := 0;
GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost := 0;
GVL_INTENT_BEHAVIOR.I_Score_Access_Secure := 0;

// Night
IF (L_Hour >= GVL_SCENARIO_CONFIG.G_Night_Start_Hour) OR (L_Hour < GVL_SCENARIO_CONFIG.G_Night_End_Hour) THEN
    GVL_INTENT_BEHAVIOR.I_Score_Night := REAL_TO_INT(GVL_SCENARIO_CONFIG.G_Night_Base_Score * L_Weights.W_Night);
END_IF;

// Preheat
IF GVL_INPUT.IN_Preheat_Request THEN
    GVL_INTENT_BEHAVIOR.I_Score_Preheat := REAL_TO_INT(GVL_SCENARIO_CONFIG.G_Preheat_Base_Score * L_Weights.W_Preheat);
END_IF;

// Vent boost
L_BestVentScore := 0.0;
L_BestVentZone := 0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Hum := GVL_INPUT.IN_Room_Hum[L_i];

    IF GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[L_i].Zone_Weight = 0.0 THEN
        L_ZoneWeight := GVL_BEHAVIOR_ADAPT.G_Adapt_Default_Zone_Weight;
    ELSE
        L_ZoneWeight := GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[L_i].Zone_Weight;
    END_IF;

    L_AdaptConfidence := GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[L_i].Confidence;
    IF L_AdaptConfidence <= 0.0 THEN
        L_AdaptConfidence := GVL_SCENARIO_CONFIG.G_Fallback_Adapt_Confidence;
    END_IF;

    L_InputConfidence := GVL_INPUT.IN_Zone_Confidence[L_i];
    IF L_InputConfidence <= 0.0 THEN
        L_InputConfidence := GVL_SCENARIO_CONFIG.G_Fallback_Input_Confidence;
    END_IF;

    L_ZoneConfidence := L_AdaptConfidence * L_InputConfidence;

    IF L_Hum > GVL_SCENARIO_CONFIG.G_VentBoost_Humidity_Threshold THEN
        L_ZoneScore := GVL_SCENARIO_CONFIG.G_VentBoost_Base_Score * L_Weights.W_VentBoost * L_ZoneWeight * L_ZoneConfidence;

        IF L_ZoneScore > L_BestVentScore THEN
            L_BestVentScore := L_ZoneScore;
            L_BestVentZone := L_i;
        END_IF;
    END_IF;
END_FOR;

GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost := REAL_TO_INT(L_BestVentScore);
GVL_INTENT_BEHAVIOR.I_Best_VentBoost_Zone := L_BestVentZone;

// Access secure
IF (L_Hour >= GVL_SCENARIO_CONFIG.G_Access_Secure_Start_Hour) OR (L_Hour < GVL_SCENARIO_CONFIG.G_Access_Secure_End_Hour) THEN
    GVL_INTENT_BEHAVIOR.I_Score_Access_Secure := REAL_TO_INT(GVL_SCENARIO_CONFIG.G_AccessSecure_Base_Score * L_Weights.W_AccessSecure);
END_IF;

// Activate flags
IF GVL_INTENT_BEHAVIOR.I_Score_Night >= GVL_SCENARIO_CONFIG.G_Night_Activation_Threshold THEN
    GVL_INTENT_BEHAVIOR.I_Request_Night_Mode := TRUE;
END_IF;

IF GVL_INTENT_BEHAVIOR.I_Score_Preheat >= GVL_SCENARIO_CONFIG.G_Comfort_Activation_Threshold THEN
    GVL_INTENT_BEHAVIOR.I_Request_Comfort_Mode := TRUE;
END_IF;

IF GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost >= GVL_SCENARIO_CONFIG.G_VentBoost_Activation_Threshold THEN
    GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost := TRUE;
END_IF;

IF GVL_INTENT_BEHAVIOR.I_Score_Access_Secure >= GVL_SCENARIO_CONFIG.G_AccessSecure_Activation_Threshold THEN
    GVL_INTENT_BEHAVIOR.I_Request_Access_Secure_Mode := TRUE;
END_IF;

// Multi-objective weights
GVL_INTENT_BEHAVIOR.I_Weight_Night := TO_REAL(GVL_INTENT_BEHAVIOR.I_Score_Night) / 100.0;
GVL_INTENT_BEHAVIOR.I_Weight_Comfort := TO_REAL(GVL_INTENT_BEHAVIOR.I_Score_Comfort) / 100.0;
GVL_INTENT_BEHAVIOR.I_Weight_Vent_Boost := TO_REAL(GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost) / 100.0;
GVL_INTENT_BEHAVIOR.I_Weight_Access_Secure := TO_REAL(GVL_INTENT_BEHAVIOR.I_Score_Access_Secure) / 100.0;

// Scenario text
IF GVL_INTENT_BEHAVIOR.I_Request_Night_Mode THEN
    GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text := 'Night mode';
ELSIF GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost THEN
    GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text := 'Vent Boost';
ELSIF GVL_INTENT_BEHAVIOR.I_Request_Comfort_Mode THEN
    GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text := 'Comfort';
ELSIF GVL_INTENT_BEHAVIOR.I_Request_Access_Secure_Mode THEN
    GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text := 'Access Secure';
ELSE
    GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text := 'Idle';
END_IF;

GVL_INTENT_BEHAVIOR.I_Reason_Text := GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text;
GVL_INTENT_BEHAVIOR.I_Last_Update_MS := GVL_TIME_SERVICE.G_Now_MS;

fbTrace(iLayer:=TRACE_SCENARIO,iSource:=SRC_SCENARIO,iReason:=REASON_SCENARIO_VENT_BOOST,iValueBool:=GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost,iValueReal:=TO_REAL(GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost),iText:=GVL_INTENT_BEHAVIOR.I_Selected_Scenario_Text);

// Wet-zone adapter
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WET_ZONES DO
    L_Wet_Zone_Active[L_i] := FALSE;
END_FOR;
IF GVL_STATUS.G_Wet_Zone_Light_Active THEN
    L_Wet_Zone_Active[1] := TRUE;
END_IF;

// === Ventilation Inputs (from arbitration only) ===
L_Vent_PV3_Boost_Req := GVL_COMMAND_SHADOW.G_Vent_PV3_Boost;
L_Supply_100_Req := GVL_COMMAND_SHADOW.G_Supply_100_Req;
L_Exhaust_100_Req := GVL_COMMAND_SHADOW.G_Exhaust_100_Req;
L_Supply_80_Req := GVL_COMMAND_SHADOW.G_Supply_80_Req;
L_Vent_Stop_Req := GVL_COMMAND_SHADOW.G_Vent_Stop;

// 11. Ventilation control (execution core)
fbVentilationManager(
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_IsActivePLC := GVL_STATUS.G_Is_Active_PLC,
    VI_Outdoor_Temp := GVL_STATE.G_Outdoor_Temp,
