GVL_DEBUG_VIEW.D_Score_Night := GVL_INTENT_BEHAVIOR.I_Score_Night;
GVL_DEBUG_VIEW.D_Score_Preheat := GVL_INTENT_BEHAVIOR.I_Score_Preheat;
GVL_DEBUG_VIEW.D_Score_VentBoost := GVL_INTENT_BEHAVIOR.I_Score_Vent_Boost;
GVL_DEBUG_VIEW.D_Score_AccessSecure := GVL_INTENT_BEHAVIOR.I_Score_Access_Secure;

GVL_DEBUG_VIEW.D_Intent_Night := GVL_INTENT_BEHAVIOR.I_Request_Night_Mode;
GVL_DEBUG_VIEW.D_Intent_Comfort := GVL_INTENT_BEHAVIOR.I_Request_Comfort_Mode;
GVL_DEBUG_VIEW.D_Intent_VentBoost := GVL_INTENT_BEHAVIOR.I_Request_Ventilation_Boost;
GVL_DEBUG_VIEW.D_Intent_AccessSecure := GVL_INTENT_BEHAVIOR.I_Request_Access_Secure_Mode;

GVL_DEBUG_VIEW.D_Heating_Block := GVL_COMMAND_SHADOW.G_Heating_Block;
GVL_DEBUG_VIEW.D_Vent_Stop := GVL_COMMAND_SHADOW.G_Vent_Stop;
GVL_DEBUG_VIEW.D_Water_Block := GVL_COMMAND_SHADOW.G_Water_Block;
GVL_DEBUG_VIEW.D_Access_Open_Active := GVL_COMMAND_SHADOW.G_Gate_Open OR GVL_COMMAND_SHADOW.G_Wicket_Open;

GVL_DEBUG_VIEW.D_Global_Reason := GVL_EXPLAINABILITY.G_Last_Global_Reason_Text;
GVL_DEBUG_VIEW.D_Behavior_Why_Active := GVL_EXPLAINABILITY.G_Behavior_Why_Active;
GVL_DEBUG_VIEW.D_Heating_Why_Blocked := GVL_EXPLAINABILITY.G_Heating_Why_Blocked;
GVL_DEBUG_VIEW.D_Vent_Why_Stopped := GVL_EXPLAINABILITY.G_Vent_Why_Stopped;
GVL_DEBUG_VIEW.D_Water_Why_Closed := GVL_EXPLAINABILITY.G_Water_Why_Closed;
GVL_DEBUG_VIEW.D_Access_Why_Opened := GVL_EXPLAINABILITY.G_Access_Why_Opened;

// SENSOR QUALITY → HMI
GVL_DEBUG_VIEW.D_Input_Source_Valid := GVL_INPUT.IN_Source_Valid;
GVL_DEBUG_VIEW.D_Input_Degraded := GVL_INPUT.IN_Input_Degraded;
GVL_DEBUG_VIEW.D_Sensor_Fault := GVL_INPUT.IN_Sensor_Fault;
GVL_DEBUG_VIEW.D_Validation_Failed := GVL_INPUT.IN_Validation_Failed;
GVL_DEBUG_VIEW.D_Anomaly_Detected := GVL_INPUT.IN_Anomaly_Detected;
GVL_DEBUG_VIEW.D_Validation_Reason := GVL_INPUT.IN_Validation_Reason;
GVL_DEBUG_VIEW.D_Anomaly_Reason := GVL_INPUT.IN_Anomaly_Reason;
GVL_DEBUG_VIEW.D_Last_Invalid_Zone := GVL_INPUT.IN_Last_Invalid_Zone;
GVL_DEBUG_VIEW.D_Min_Zone_Confidence := GVL_INPUT.IN_Min_Zone_Confidence;
GVL_DEBUG_VIEW.D_Worst_Zone := GVL_INPUT.IN_Worst_Zone;

GVL_DEBUG_VIEW.D_Adapt_Profile := GVL_BEHAVIOR_ADAPT.G_Adapt_Profile;

IF GVL_BEHAVIOR_ADAPT.G_Adapt_Profile = ADAPT_PROFILE_STABLE THEN
    GVL_DEBUG_VIEW.D_Adapt_Profile_Text := 'STABLE';
ELSIF GVL_BEHAVIOR_ADAPT.G_Adapt_Profile = ADAPT_PROFILE_BALANCED THEN
    GVL_DEBUG_VIEW.D_Adapt_Profile_Text := 'BALANCED';
ELSE
    GVL_DEBUG_VIEW.D_Adapt_Profile_Text := 'AGGRESSIVE';
END_IF;

L_MaxWeight := 0.0;
L_MinWeight := 9999.0;
GVL_DEBUG_VIEW.D_Main_VentBoost_Zone := 0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ZONES DO
    L_Weight := GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[L_i].Zone_Weight;
    IF L_Weight > L_MaxWeight THEN
        L_MaxWeight := L_Weight;
        GVL_DEBUG_VIEW.D_Main_VentBoost_Zone := L_i;
        GVL_DEBUG_VIEW.D_Main_VentBoost_Zone_Weight := L_Weight;
        GVL_DEBUG_VIEW.D_Main_VentBoost_Zone_Confidence :=
            GVL_BEHAVIOR_ADAPT.G_VentBoost_Zone_Adapt[L_i].Confidence;
    END_IF;
    IF L_Weight < L_MinWeight THEN
        L_MinWeight := L_Weight;
    END_IF;
END_FOR;

GVL_DEBUG_VIEW.D_Max_VentBoost_Zone_Weight := L_MaxWeight;
GVL_DEBUG_VIEW.D_Min_VentBoost_Zone_Weight := L_MinWeight;

L_Index := GVL_TRACE.G_Trace_Write_Index - 1;
IF L_Index < 1 THEN
    L_Index := 200;
END_IF;

GVL_DEBUG_VIEW.D_Last_Trace_Text := GVL_TRACE.G_Trace_Buffer[L_Index].Text;
GVL_DEBUG_VIEW.D_Last_Trace_Time_MS := GVL_TRACE.G_Trace_Buffer[L_Index].Timestamp_MS;
GVL_DEBUG_VIEW.D_Last_Trace_Reason := GVL_TRACE.G_Trace_Buffer[L_Index].Reason_Code;

IF L_Init_Done THEN
    RETURN;
END_IF;

L_Active_Zones_Count := GVL_SYSTEM_SIZE_CONFIG.G_Active_Heating_Circuits;

IF (L_Active_Zones_Count < 1) OR (L_Active_Zones_Count > GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS) THEN
    GVL_STATUS.G_Diagnostics.Sensor_Fault := TRUE;
    GVL_STATUS.G_System_Mode_Text := 'CONFIG ERROR: invalid active heating circuits';
    GVL_COMMAND_SHADOW.G_Heating_Block := TRUE;
    GVL_COMMAND_SHADOW.G_Boiler_Stop := TRUE;
    L_Active_Zones_Count := GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS;
END_IF;

FOR L_i := 1 TO L_Active_Zones_Count DO
    L_Zone_Index := GVL_CONFIG.G_Heating_Circuit_To_Zone[L_i];
    IF (L_Zone_Index < 1) OR (L_Zone_Index > GVL_CONSTANTS.C_MAX_ZONES) THEN
        GVL_STATUS.G_Diagnostics.Sensor_Fault := TRUE;
        GVL_STATUS.G_System_Mode_Text := CONCAT('CONFIG ERROR CIRCUIT ', INT_TO_STRING(L_i));
        GVL_COMMAND_SHADOW.G_Heating_Block := TRUE;
        GVL_COMMAND_SHADOW.G_Boiler_Stop := TRUE;
    END_IF;
END_FOR;

L_Init_Done := TRUE;

// >>> BULK_SYNC_ANCHOR: PRG_System_Init <<<

FB_Backend(
    VI_Enable := GVL_CONFIG.G_OpenTherm_Enabled,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS
);

// Вызов основной программы
PRG_System();
// >>> BULK_SYNC_ANCHOR: PRG_PLC_A <<<

L_Now_MS := GVL_STATUS.G_System_Time_MS;

// ===============================
// 1. COMMAND MISMATCH CHECK
// ===============================
L_Mismatch_Count := 0;

IF GVL_COMMAND.G_Gas_Valve_Close <> GVL_COMMAND_SHADOW.G_Gas_Valve_Close THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Boiler_Stop <> GVL_COMMAND_SHADOW.G_Boiler_Stop THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Vent_Stop <> GVL_COMMAND_SHADOW.G_Vent_Stop THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Supply_100_Req <> GVL_COMMAND_SHADOW.G_Supply_100_Req THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Supply_80_Req <> GVL_COMMAND_SHADOW.G_Supply_80_Req THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Vent_PV3_Boost <> GVL_COMMAND_SHADOW.G_Vent_PV3_Boost THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Close_Valve_35 <> GVL_COMMAND_SHADOW.G_Close_Valve_35 THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Close_Valve_36 <> GVL_COMMAND_SHADOW.G_Close_Valve_36 THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Lock_1_Open <> GVL_COMMAND_SHADOW.G_Lock_1_Open THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Lock_1_Close <> GVL_COMMAND_SHADOW.G_Lock_1_Close THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Lock_2_Open <> GVL_COMMAND_SHADOW.G_Lock_2_Open THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Lock_2_Close <> GVL_COMMAND_SHADOW.G_Lock_2_Close THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Gate_Open <> GVL_COMMAND_SHADOW.G_Gate_Open THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;
IF GVL_COMMAND.G_Wicket_Open <> GVL_COMMAND_SHADOW.G_Wicket_Open THEN L_Mismatch_Count := L_Mismatch_Count + 1; END_IF;

GVL_COMMAND_VERIFY.Command_Mismatch_Count := L_Mismatch_Count;
GVL_COMMAND_VERIFY.Command_Match_OK := (L_Mismatch_Count = 0);
GVL_COMMAND_VERIFY.Command_Mismatch_Active := (L_Mismatch_Count > 0);

// ===============================
// 2. RUNTIME SANITY CHECKS
// ===============================
L_Runtime_Error := FALSE;
L_Runtime_Error_Code := 0;
L_Runtime_Error_Text := '';
L_Any_Manifold_Pump_On := FALSE;

// PLC inactive: fail-safe outputs should be off/safe except alarm/gas close outputs.
IF (NOT L_Runtime_Error) AND (NOT GVL_STATUS.G_Is_Active_PLC) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        IF GVL_IO.DO_Zone_Valves[L_i] THEN
            L_Runtime_Error := TRUE;
            L_Runtime_Error_Code := 10;
            L_Runtime_Error_Text := 'PLC inactive zone valve on';
        END_IF;
    END_FOR;
END_IF;

IF (NOT L_Runtime_Error) AND (NOT GVL_STATUS.G_Is_Active_PLC) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF GVL_IO.DO_Manifold_Pumps[L_i] THEN
            L_Runtime_Error := TRUE;
            L_Runtime_Error_Code := 11;
            L_Runtime_Error_Text := 'PLC inactive pump on';
        END_IF;
    END_FOR;
END_IF;

// GAS: gas valve must be physically commanded closed.
IF (NOT L_Runtime_Error) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS) AND (NOT GVL_IO.DO_Gas_Valve_Close) THEN
    L_Runtime_Error := TRUE;
    L_Runtime_Error_Code := 1;
    L_Runtime_Error_Text := 'Gas valve not closed';
END_IF;

// GAS: ventilation must not be forced fully off by the IO layer.
IF (NOT L_Runtime_Error) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = GAS) THEN
    IF (GVL_IO.AO_Supply_Fans[1] = 0) AND (GVL_IO.AO_Exhaust_Fans[1] = 0) THEN
        L_Runtime_Error := TRUE;
        L_Runtime_Error_Code := 3;
        L_Runtime_Error_Text := 'Gas ventilation inactive';
    END_IF;
END_IF;

// FIRE: all exhaust fans should be commanded above zero in smoke exhaust mode.
IF (NOT L_Runtime_Error) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        IF GVL_IO.AO_Exhaust_Fans[L_i] = 0 THEN
            L_Runtime_Error := TRUE;
            L_Runtime_Error_Code := 2;
            L_Runtime_Error_Text := 'Smoke exhaust not active';
        END_IF;
    END_FOR;
END_IF;

// FIRE: supply fans should be off in smoke exhaust mode.
IF (NOT L_Runtime_Error) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = FIRE) THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        IF GVL_IO.AO_Supply_Fans[L_i] <> 0 THEN
            L_Runtime_Error := TRUE;
            L_Runtime_Error_Code := 4;
            L_Runtime_Error_Text := 'Supply fan active in fire';
        END_IF;
    END_FOR;
END_IF;

// WATER_LEAK: valve close commands must reach physical outputs.
IF (NOT L_Runtime_Error) AND (GVL_SAFETY_SHUTDOWN.G_Safety_Mode = WATER_LEAK) THEN
    IF GVL_COMMAND_SHADOW.G_Close_Valve_35 AND (NOT GVL_IO.DO_Water_Valve_35_Close) THEN
        L_Runtime_Error := TRUE;
        L_Runtime_Error_Code := 5;
        L_Runtime_Error_Text := 'Water valve 35 not closed';
    ELSIF GVL_COMMAND_SHADOW.G_Close_Valve_36 AND (NOT GVL_IO.DO_Water_Valve_36_Close) THEN
        L_Runtime_Error := TRUE;
        L_Runtime_Error_Code := 6;
        L_Runtime_Error_Text := 'Water valve 36 not closed';
    END_IF;
END_IF;

// FREEZE: when freeze-risk is active, heating circulation should not be fully dead.
IF (NOT L_Runtime_Error) AND GVL_STATE.G_Safety_Freeze_Risk THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF GVL_IO.DO_Manifold_Pumps[L_i] THEN
            L_Any_Manifold_Pump_On := TRUE;
        END_IF;
    END_FOR;

    IF (NOT L_Any_Manifold_Pump_On) AND (NOT GVL_IO.DO_Backup_Circulation_Pump) THEN
        L_Runtime_Error := TRUE;
        L_Runtime_Error_Code := 7;
        L_Runtime_Error_Text := 'Freeze circulation inactive';
    END_IF;
END_IF;

// GAS+FREEZE: electric backup may be used for anti-freeze, but DHW heating must remain off.
IF (NOT L_Runtime_Error) AND GVL_STATE.G_Safety_Freeze_Risk AND GVL_COMMAND_SHADOW.G_Heating_Gas_Safety_Stop THEN
    IF GVL_IO.DO_DHW_Heating_Pump THEN
        L_Runtime_Error := TRUE;
        L_Runtime_Error_Code := 8;
        L_Runtime_Error_Text := 'DHW heating active during gas freeze';
    END_IF;
END_IF;

// Apply result
IF L_Runtime_Error THEN
    GVL_COMMAND_VERIFY.Runtime_Sanity_OK := FALSE;
    GVL_COMMAND_VERIFY.Runtime_Last_Error_Code := L_Runtime_Error_Code;
    GVL_COMMAND_VERIFY.Runtime_Last_Error_Text := L_Runtime_Error_Text;
    GVL_COMMAND_VERIFY.Runtime_Last_Error_Time_MS := L_Now_MS;

    IF NOT L_Prev_Runtime_Error THEN
        GVL_COMMAND_VERIFY.Runtime_Sanity_Error_Count := GVL_COMMAND_VERIFY.Runtime_Sanity_Error_Count + 1;
        fbLog(
            VI_Event_Type := 1001,
            VI_Timestamp := L_Now_MS,
            VI_Param1 := L_Runtime_Error_Code,
            VI_Param2 := GVL_COMMAND_VERIFY.Runtime_Sanity_Error_Count
        );
    END_IF;
ELSE
    GVL_COMMAND_VERIFY.Runtime_Sanity_OK := TRUE;
END_IF;

L_Prev_Runtime_Error := L_Runtime_Error;

IF GVL_INTENT_USER.I_Set_Adapt_Profile_Req THEN

    // block if safety active
    IF (GVL_SAFETY_SHUTDOWN.G_Safety_Mode <> NORMAL) OR GVL_SAFETY_RECOVERY.G_Recovery_Active THEN

        fbTrace(
            iLayer := TRACE_USER,
            iSource := SRC_USER,
            iReason := REASON_SAFETY,
            iValueBool := FALSE,
            iValueReal := 0.0,
            iText := 'Profile change blocked: SAFETY ACTIVE'
        );

    ELSE

        IF (GVL_INTENT_USER.I_Set_Adapt_Profile_Confirm)
           AND (GVL_INTENT_USER.I_User_Access_Level >= 2) THEN

            GVL_BEHAVIOR_ADAPT.G_Adapt_Profile :=
                GVL_INTENT_USER.I_Adapt_Profile_Value;

            IF GVL_INTENT_USER.I_Adapt_Profile_Value = ADAPT_PROFILE_STABLE THEN
                L_Text := 'Adapt profile: STABLE';
            ELSIF GVL_INTENT_USER.I_Adapt_Profile_Value = ADAPT_PROFILE_BALANCED THEN
                L_Text := 'Adapt profile: BALANCED';
            ELSE
                L_Text := 'Adapt profile: AGGRESSIVE';
            END_IF;

            fbTrace(
                iLayer := TRACE_USER,
                iSource := SRC_USER,
                iReason := REASON_USER_REQUEST,
                iValueBool := TRUE,
                iValueReal := TO_REAL(GVL_INTENT_USER.I_User_Access_Level),
                iText := L_Text
            );

        END_IF;

    END_IF;

    GVL_INTENT_USER.I_Set_Adapt_Profile_Req := FALSE;
    GVL_INTENT_USER.I_Set_Adapt_Profile_Confirm := FALSE;

END_IF;

fbPolicy(
    VI_Zone_Occupied := GVL_PRESENCE.G_Zone_Occupied,
    VI_Zone_Last_Motion_TS := GVL_PRESENCE.G_Zone_Last_Motion_TS,
    VI_System_Time_MS := GVL_STATUS.G_System_Time_MS,
    VI_Zone_Permanent_Use := GVL_HEATING_POLICY.G_Zone_Permanent_Use,
    VI_Zone_Guest_Preheat := GVL_HEATING_POLICY.G_Zone_Guest_Preheat_Request,
    VI_Behavior_Mode := GVL_MODE.G_Current_Behavior_Mode
);

GVL_HEATING_POLICY.G_Zone_Empty_Duration_MS := fbPolicy.VO_Zone_Empty_Duration_MS;
GVL_HEATING_POLICY.G_Zone_Policy_Class := fbPolicy.VO_Zone_Policy_Class;
GVL_HEATING_POLICY.G_Zone_Target_Adjustment := fbPolicy.VO_Zone_Target_Adjustment;
GVL_HEATING_POLICY.G_Zone_Priority_Bias := fbPolicy.VO_Zone_Priority_Bias;

